 \For{each $reading$ in $\mathcal{D}_{filtered}$}{ \tcp{Map to calibrated distance $d_{gap}$}
    \If{$reading$ $<$ $threshold_{low}$}{
        $d_{gap}$ $\leftarrow$ $0$\; 
    }
    \ElseIf{$reading$ $>$ $threshold_{up}$}{
        $d_{gap}$ $\leftarrow$ MAX-DISTANCE\;
       } 
    \Else{
