\section{Plain Gr\"obner basis analysis over $\F_2$} \label{app: plainF2}

Let us define the Cauchy integrals 
\[
I_d(n)\eqdef \frac{1}{2\pi i}\oint \frac{1}{z^{d+1}}\frac{(1+(l-1)z)^w}{(1-z)(1+z^2)^m} dz
\]
for all non-negative integers $d$.
Each coefficient of the Hilbert series can be written as the corresponding integral
\[
\HF_{R/\mathcal{I}}(d)=I_d(n).
\]
We set $f(z)$ such that $e^{nf(z)}= \frac{1}{z^{d+1}}\frac{(1+(l-1)z)^w}{(1-z)(1+z^2)^m}$, i.e.
\[
f(z) \eqdef \frac{w}{n} \ln(1+(l-1)z)-\frac{m}{n}\ln(1+z^2)-\frac{1}{n}\ln(1-z)-\frac{d+1}{n}\ln(z).
\]
We compute the saddle points as
\begin{align*}
zf'(z)=&\frac{(l-1)w}{n}\frac{z}{1+(l-1)z}-\frac{2m}{n}\frac{z^2}{1+z^2}+\frac{1}{n}\frac{z}{1-z}-\frac{d+1}{n}\\
=&\frac{(l-1)}{l}\frac{z}{1+(l-1)z}-2\mu\frac{z^2}{1+z^2}+\frac{1}{n}\frac{z}{1-z}-\frac{d+1}{n}.
\end{align*}
We observe that the term $\frac{1}{n}\frac{z}{1-z}$ is negligible when $n\to \infty$. Hence, the computation leads to the condition
\[
\frac{(l-1)}{l} z(1+z^2)-2\mu z^2(1+(l-1)z)-\frac{d+1}{n}(1+z^2)(1+(l-1)z)=0
\]
and we want to find the value $\delta\eqdef\frac{d+1}{n}$ which provides the asymptotic of the relative degree of regularity. The cubic equation in $z$ above can be rewritten in the canonical form
\[
P(z)=p_3 z^3+p_2 z^2+p_1 z+p_0=0
\]
where
\[
\begin{cases}
    p_3 &= (l-1)\left(2\mu +\delta-\frac{1}{l}\right) \\
    p_2 &= 2\mu +\delta\\
    p_1 &= (l-1)\left(\delta -\frac{1}{l}\right) \\
    p_0 &= \delta.
\end{cases}
\]

We want to find coalescent saddle points, i.e. a root of multiplicity 2 for $P$. For cubic polynomials, this can be found by forcing the discriminant to vanish. The discriminant is defined as
\[
\Delta(P)=18 p_3 p_2 p_1 p_0-4 p_2^3 p_0 + p_2^2 p_1^2- 4 p_3 p_1^3 -27 p_3^2 p_0^2.
\]
Equating the discriminant to 0 (and dividing by -4) provides a quartic equation
\begin{equation} \label{eq: quarticF2}
r_4 \delta^4+ r_3 \delta^3+r_2\delta^2+r_1\delta +r_0=0
\end{equation}
in the variable $\delta$, whose coefficients are polynomial functions of $\mu$ and $l$:
\[
\begin{cases}
    r_4 &= ((l-1)^2+1)^2 \\
    r_3 &= 2\mu ((l-1)^2+1)((l-1)^2+3)-4\frac{(l-1)^2((l-1)^2+1)}{l}\\
    r_2 &= 4\mu^2 (2(l-1)^2+3)- 2\mu\frac{(l-1)^2(3(l-1)^2-1)}{l} +2\frac{(l-1)^2 (3 (l-1)^2 +1)}{l^2}\\
    r_1 &= 8 \mu^3+20\mu^2 \frac{(l-1)^2}{l} + 2\mu (l-1)^2 \frac{3(l-1)^2-5}{l^2 }-4 \frac{(l-1)^4}{l^3} \\
    r_0 &= -\mu^2 \frac{(l-1)^2}{l^2}-2\mu \frac{(l-1)^4}{l^3}+\frac{(l-1)^4}{l^4}.
\end{cases}
\]
The smallest positive root $\bar{\delta}$ of \eqref{eq: quarticF2} gives the good asymptotic for the relative degree of regularity.

\section{Plain Gr\"obner basis approach over $\F_q$} \label{app: plainFq}

We can write the Hilbert function at degree $d$ as
\[
\HF_{R/\mathcal{I}}(d)=I_d(n)
\]
for the Cauchy integrals 
\[
I_d(n)\eqdef \frac{1}{2\pi i}\oint \frac{1}{z^{d+1}}\frac{(1+(l-1)z)^w (1-z^2)^m}{(1-z)^{w+1}} dz.
\]

We set $f(z)$ such that $e^{nf(z)}=  \frac{1}{z^{d+1}}\frac{(1+(l-1)z)^w (1-z^2)^m}{(1-z)^{w+1}} $, i.e.
\[
f(z) \eqdef \frac{w}{n} \ln(1+(l-1)z)-\frac{m}{n}\ln(1-z^2)-\frac{w+1}{n}\ln(1-z)-\frac{d+1}{n}\ln(z).
\]
We compute the saddle points as
\begin{align*}
zf'(z)=&\frac{(l-1)w}{n}\frac{z}{1+(l-1)z}-\frac{2m}{n}\frac{z^2}{1-z^2}+\frac{w+1}{n}\frac{z}{1-z}-\frac{d+1}{n}\\
=&\frac{(l-1)}{l}\frac{z}{1+(l-1)z}-2\mu\frac{z^2}{1-z^2}+\frac{1}{l}\frac{z}{1-z}+\frac{1}{n}\frac{z}{1-z}-\frac{d+1}{n}.
\end{align*}
We observe that the term $\frac{1}{n}\frac{z}{1-z}$ is negligible when $n\to \infty$. Hence, the computation leads to the condition
\[
\frac{(l-1)}{l} z(1-z^2)-2\mu z^2(1+(l-1)z)+\frac{1}{l}z(1+z)(1+(l-1)z)-\frac{d+1}{n}(1-z^2)(1+(l-1)z)=0
\]
and we want to find the value $\delta\eqdef\frac{d+1}{n}$ which provides the asymptotic of the relative degree of regularity. The cubic equation in $z$ above can be rewritten in the canonical form
\[
P(z)=p_3 z^3+p_2 z^2+p_1 z+p_0=0
\]
where
\[
\begin{cases}
    p_3 &= (l-1)\left(2\mu -\delta\right) \\
    p_2 &= 2\mu -\delta-1\\
    p_1 &= \delta(l-1)-1 \\
    p_0 &= \delta.
\end{cases}
\]

We want to find coalescent saddle points, i.e. a root of multiplicity 2 for $P$. For cubic polynomials, this can be found by forcing the discriminant to vanish. The discriminant is defined as
\[
\Delta(P)=18 p_3 p_2 p_1 p_0-4 p_2^3 p_0 + p_2^2 p_1^2- 4 p_3 p_1^3 -27 p_3^2 p_0^2.
\]
Equating the discriminant to 0 provides a quartic equation
\begin{equation} \label{eq: quarticFq}
r_4 \delta^4+ r_3 \delta^3+r_2\delta^2+r_1\delta +r_0=0
\end{equation}
in the variable $\delta$, whose coefficients are polynomial functions of $\mu$ and $l$:
\[
\begin{cases}
    r_4 &= 4l^2(2l+1)^2 \\
    r_3 &= -8\mu (l^3-4l^2-2l+4)-4(3l^2-8l+8)(l-2)\\
    r_2 &= -16\mu^2 (2l^2-4l-1)+ 8\mu(3l^3-14l^2+29l-24)+13l^2-48l+48\\
    r_1 &= -32\mu^3-16\mu^2 (5l-8) -4\mu (6l^2-23+24) -6(l-2) \\
    r_0 &= 4\mu^2 +4\mu(2l-3)+1.
\end{cases}
\]
The smallest positive root $\bar{\delta}$ of \eqref{eq: quarticFq} gives the good asymptotic for the relative degree of regularity.

