\begin{document}


\maketitle


\begin{abstract}
The problem of computing optimal orthogonal approximation to a given matrix has attracted growing interest in machine learning. Notable applications include the recent Muon optimizer or Riemannian optimization on the Stiefel manifold. Among existing approaches, the Newton-Schulz iteration has emerged as a particularly effective solution, as it relies solely on matrix multiplications and thus achieves high computational efficiency on GPU hardware. Despite its efficiency, the method has inherent limitations—its coefficients are fixed and thus not optimized for a given matrix. In this paper we address this issue by proposing a Chebyshev-optimized version of Newton-Schulz (CANS). Based on the Chebyshev's alternance theorem, we theoretically derive optimal coefficients for the 3-rd order Newton-Schulz iteration and apply a Remez algorithm to compute optimal higher-degree polynomials. 
We leverage these polynomials to construct controlled approximate orthogonalization schemes, which is of interest in deep learning applications. 
Practically, we demonstrate the method's effectiveness in two key applications: orthogonalization in the Muon optimizer, and providing an efficient retraction alternative for Riemannian optimization on the Stiefel manifold. 


\end{abstract}


\section{Introduction}
Polar decomposition of a matrix $X\in\mathbb{R}^{m\times n}, m\geq n$ is a factorization $X=WH$, where $W \in\mathbb{R}^{m\times n}$ has orthonormal columns and $H \in\mathbb{R}^{n\times n}$ is a positive semidefinite symmetric matrix (or Hermitian in the complex case). 
An important application of the polar decomposition is the orthogonal Procrustes problem:
\[\min_{Q: \, Q^TQ=I}\|Q-X\|_F,\]
with the solution being $Q=W$ the polar factor of $X$. For generalization of this problem, see~\cite{schonemann1966generalized}.


Polar decomposition can be computed directly using the singular value decomposition $X=USV^T$, which immediately leads to $W=UV^T, H=VSV^T$. However, calculating the SVD can be costly for many applications. There are several iterative methods available, including Newton \cite{kenney1992scaling} and Halley's methods \cite{nakatsukasa2010optimizing}, which require matrix inversion. In this work, we consider the Newton-Schulz iteration \cite{bjorck1971iterative, kovarik1970some, higham2008functions}, which only requires matrix multiplication:
\begin{equation}
\label{eq:classical_ns}
X_{k+1}=\frac{3}{2}X_k-\frac{1}{2}X_kX_k^TX_k, \quad X_1 = X.\end{equation}
This iteration converges to the orthogonal factor of the polar decomposition if $\sigma_1(X)<\sqrt{3}$ and $\sigma_n(X)>0$. Classical Newton-Schulz iteration can be also extended to higher degrees \cite{bernstein2024modular}:
\[X_{k+1}=\alpha_1^kX_k+\alpha_3^kX_kX_k^TX_k +\alpha_5^kX_k(X_k^TX_k)^2+\dots + \alpha_{2t+1}^kX_k(X_k^TX_k)^T,\]
which can be rewritten using SVD of $X_k = US_k V^T$ as follows:
\[X_{k+1} = U(\alpha^k_1S_k+\alpha^k_3S^3_k+\alpha^k_5S^5_k+\dots+\alpha^k_{2d+1}S^{2d+1}_k)V^T=U p_k(S_k)V^T.\]
In order for these iterations to converge to the orthogonal polar factor, the composition of polynomials $p_k(p_{k-1}(\dots p_1(x)))$ should converge to the unity function $f \equiv 1$ on the segment $[\sigma_n(X), \sigma_1(X)]$. Indeed,  the desired property is:
\begin{equation} \label{eq:polybound}
\begin{split}
    \|X_{k+1} - UV^T\|_2 
    &= \|U(p_k(S_k) - I)V^T\|_2 = \|p_k(S_k) - I\|_2 \\
    &= \|p_k(p_{k-1}(\dots p_1(S)))  - I\|_2  \\
    &=\max_i |p_k(p_{k-1}(\dots p_1(s_i))) - 1| \\
    &\leq \max_{s\in[\sigma_n, \sigma_1]} |p_k(p_{k-1}(\dots p_1(s))) - 1| \to 0, \quad k\to \infty,
\end{split}
\end{equation}
 where we used orthogonal invariance of the spectral norm.
 However, in some applications (e.g., Muon optimizer), high orthogonalization accuracy may not be necessary and finding an approximation of $f\equiv 1$ with an error $\varepsilon$ is sufficient. This allows to balance between accuracy and efficiency when selecting polynomials.

In this work, we propose algorithms for optimizing the coefficients of the classical Newton-Schulz method, based on the Chebyshev alternation theorem. This framework, which we call \emph{Chebyshev-accelerated Newton-Schulz (CANS)}, enables us to obtain polynomials with the desired properties and accelerated convergence. Our main contributions are:
\begin{itemize}
\item We derive theory for finding odd polynomials that optimally approximate the unity function on a given segment $[a, b]$ (Section~\ref{sec:optimalodd}). This leads us to explicit formulas when $p_k$ are of degree 3 and Remez algorithm for larger degrees. Given the bounds on the largest and smallest singular values, these polynomials lead to methods that outperform Newton-Schulz (Section~\ref{sec:CANS}). 
\item We develop new polynomials that are confined within the interval $[1-\delta, 1+\delta]$ with a user-specified $\delta$ (inexact orthogonalization), while maximizing the polynomial derivative in the vicinity of zero (Section~\ref{sec:maxderiv}). This is motivated by the needs of the orthogonalization procedure of the \emph{Muon} optimizer~\cite{jordan2024muon}.  For the same target $\delta$, our polynomials achieve a larger derivative compared to original Muon polynomial and those from~\cite{jiacheng}, and yield faster convergence of the optimizer when training the NanoGPT network  (Section \ref{sec:muon}).
\item We further demonstrate that by maximizing the derivative at the origin, our inexact orthogonalization polynomials can serve as an effective preprocessing step for an iterative method of choice. This is particularly useful when information about the smallest singular value is not available. We also show that the largest singular value can be accurately approximated via Gelfand's formula with negligible computational overhead (Section~\ref{sec:gelfand}).
\item In Section \ref{sec:riemannian}, we demonstrate the application of our method for building an efficient retraction on the Stiefel manifold, which shows a speedup in training Wide ResNet with orthogonal constraints.
\end{itemize}

\section{Related work}
\textbf{Iterative methods.} The works \cite{bjorck1971iterative, kovarik1970some} are credited with being the first to propose the Taylor series-based iterative algorithm for calculating the orthogonal polar factor. In \cite{higham1990fast} this result is used for deriving an algorithm, which balances between inversion (Newton iteration) and matrix multiplication. The analysis of backward stability and convergence of classical Newton-Schulz and other iterative methods is given in \cite{nakatsukasa2012backward}. 
There are also several works that explore the scaling of Newton-Schulz iteration for the computation of matrix sign function \cite{chen2014stable, chen2014newton} for third-degree polynomials. The idea of empirically tuning the coefficients was also proposed in \cite{bernstein2024modular}.

\textbf{Deep learning.} In neural networks, Newton-Schulz iteration is applied for enforcing orthonormality of the weight matrices \cite{anil2019sorting}. Its computational efficiency has made it particularly valuable for optimizers requiring approximate orthogonalization, including Muon \cite{jordan2024muon, bernstein2024modular} and Scion \cite{pethick2025training}. Related approaches have employed Newton iteration for computing matrix p-th roots in other optimizers \cite{anil2020scalable}. 


\textbf{Riemannian optimization.} In Riemannian optimization on the Stiefel manifold, polar decomposition is one of the possible retractions \cite{absil2009optimization} to the manifold, alongside Cayley transform \cite{li2020efficient, zhu2017riemannian, gao2021riemannian} and QR.


\section{Optimal odd polynomials and Newton-Schulz iterations}

\subsection{Optimal odd polynomials} \label{sec:optimalodd}
As stated in~\eqref{eq:polybound}, our goal is to find an odd polynomial that best approximates the unity function $f\equiv1$ on a given segment $[a,b]$, in which the singular values of the matrix fall $[\sigma_n(X), \sigma_1(X)] \in [a, b]$.


By $L_n$ we shall denote the space of odd polynomials of degree $2n-1$, that is, \[L_n = \{\alpha_1x + \alpha_3 x^3 + \dots + \alpha_{2n-1}x^{2n-1}: \alpha_1,\alpha_3,\dots, \alpha_{2n-1} \in \mathbb R\}.\] Note that $\dim L_n = n$. Now fix $0 < a < b$ and $n \in \mathbb N$. For a function $f \in C[a,b]$ we consider the problem of finding $p \in L_n$ such that $\|f - p\|_{C[a,b]} = \min \{\|f - q\|_{C[a,b]}: q \in L_n\}$. A polynomial $p$ with the foregoing property we shall call {\it{the best uniform odd polynomial approximation}} of $f$ {\it{of degree}} $2n-1$. Since we do not consider approximations in any other sense, we shall use a shorter term {\it{best odd polynomial approximation}} omitting the explicit mention of the degree, if it is clear from the context. The powerful method of studying best polynomial approximations is provided by the Chebyshev equioscillation theorem (see~\cite[Section~10]{Trefethen2020} for classical formulation, and~\cite[Theorem~5]{Hormander2018} for the general version). In our case it reduces to the following fact.

\begin{theorem}\label{th:Chebyshev}
    Let $0 < a < b$, $n \in \mathbb N$, and $f \in C[a,b]$. Then the following statements hold.
    \begin{enumerate}[label=(\roman*)]
        \item\label{th:Chebyshevi} The best odd polynomial approximation of $f$ is unique.
        \item\label{th:Chebyshevii} $p \in L_n$ is the best odd polynomial approximation of $f$ of degree $2n-1$ if and only if there exist points $x_0 < x_1 < \dots < x_n$ on the interval $[a,b]$ such that $|p(x_j)-f(x_j)| = \|p - f\|_{C[a,b]}$ for all $j = 0, \dots, n$ and $p(x_j) - f(x_j) = -(p(x_{j-1}) - f(x_{j-1}))$ for all $j = 1, \dots, n$.
    \end{enumerate}
\end{theorem}

The points $x_0, \dots, x_n$ from Theorem~\ref{th:Chebyshev} are said to form the {\it{Chebyshev alternance for}} $p - f$. 

We shall need further properties of the best odd polynomial approximation of the unity function $f \equiv 1$. Given $0 < a < b$ and $n \in \mathbb N$ we denote by $p_{n,a,b}$ the best degree $2n-1$ odd polynomial approximation of the unity on the interval $[a,b]$ and by $\varepsilon(n,a,b)$ we denote the value $\|p_{n,a,b} - 1\|_{C[a,b]}$. The following proposition contains basic properties of $p_{n,a,b}$.

\begin{proposition}\label{prop:properties}
    Let $0 < a < b$ and let $n \in \mathbb N$. Then the following statements hold.
    \begin{enumerate}[label=(\roman*)]
        \item\label{prop:propertiesi} If $x_0 <  \dots< x_n$ are the points of the Chebyshev alternance for $p_{n,a,b} - 1$, then $x_0 = a$ and $x_n = b$.
        \item\label{prop:propertiesii} If $\varepsilon = \|p_{n,a,b} - 1\|_{C[a,b]}$, then $p_{n,a,b}(x_j) = 1 - (-1)^j \varepsilon$  for all $j = 0, \dots, n$.
        \item\label{prop:propertiesiii} The derivative $p_{n,a,b}^{\prime}(x)$ attains a local maximum at $x = 0$ and decreases on the interval $[0, x_1]$. Moreover, $p_{n,a,b}^{\prime}(0) \ge (1-\varepsilon)/a$.
        \item\label{prop:propertiesiv} For any $t > 0$ we have $\varepsilon(n, ta, tb) = \varepsilon(n,a,b)$ and $p_{n,ta,tb}(tx) = p_{n,a,b}(x)$.
    \end{enumerate}
\end{proposition}
\begin{proof} See Appendix \ref{apx:chebyshev_properties}.
\end{proof}


Using the foregoing proposition it is easy to find a closed-form expression for $p_{2,a,b}$.

\begin{proposition}\label{prop:explicit}  Let $0<a<b$.
Then
\[p_{2,a,b}=\frac{2}{2\left(\frac{a^{2}+a b+b^{2}}{3}\right)^{3 / 2}+a^{2} b+b^{2} a}\left(\left(a^{2}+a b+b^{2}\right) x-x^{3}\right) .\]
Moreover, this polynomial attains its maximum on $[a, b]$ at $x=e=\sqrt{\left(a^{2}+a b+b^{2}\right) / 3}$. Finally,
\begin{equation}
\label{eq:appr_error}
\varepsilon(2,a,b)=\|p_{2,a,b}-1\|_{C[a, b]}=\frac{2\left(\frac{a^{2}+a b+b^{2}}{3}\right)^{3 / 2}-a^{2} b-b^{2} a}{2\left(\frac{a^{2}+a b+b^{2}}{3}\right)^{3 / 2}+a^{2} b+b^{2} a} .
\end{equation}
\end{proposition}
\begin{proof}
see Appendix \ref{apx:explicit}.
\end{proof}

For the polynomials of higher degree, finding explicit formulas by the method of~Proposition~\ref{prop:explicit} seems to be unrealistic, as the problem reduces to finding roots of polynomials of degree more than 4. Also we were not able to construct any transcendental formula for $p_{n,a,b}$. However, we can use an adaptation of the well-known Remez algorithm (see, e.g.~\cite[Section 10]{Trefethen2020}) for finding coefficients of the optimal polynomials of higher degrees. Let us describe the main idea of the Remez algorithm. Assume that we are given a set $\{x_1, \dots, x_{n-1}\}$ of distinct points on the open interval $(a,b)$. The points $x_0 = a, x_1, \dots, x_{n-1}, x_n = b$ serve as a guess for the Chebyshev alternance points for $p_{n,a,b} - 1$. It is easy to see that there is a unique pair $(p, \varepsilon)$ such that  $p \in L_n$ (that is, $p$ is odd and has degree $\le 2n-1$), $\varepsilon \in \mathbb R$, and $p(x_j) = 1 - (-1)^j\varepsilon$ for all $j = 0, 1, \dots, n$. The equations $p(x_j) = 1 - (-1)^j\varepsilon$ for $j = 0, \dots, n$ form a nonsingular system of linear equations in $n+1$ unknowns, namely, $\varepsilon$ and coefficients of $p$. Thus, $p$ and $\varepsilon$ are, indeed, uniquely determined by the above conditions. Unfortunately, $x_0, \dots, x_n$ may not constitute a Chebyshev alternance for $p - 1$, as $p$ is not guaranteed to satisfy $p([a,b]) \subset [1 - \varepsilon, 1 + \varepsilon]$. However, it is clear that $p$ has exactly $n-1$ distinct extremal points $\{y_1, \dots, y_{n-1}\}$ in the open interval $(a,b)$. The collection of points $y_0 = a, y_1, \dots, y_{n-1}, y_n = b$ (consisting of boundaries of the interval and extremal points of $p$) serves as a new guess for the Chebyshev alternance points for $p_{n,a,b} - 1$, and this guess is better than the previous. By repeating the above construction with points $y_1, \dots, y_{n-1}$ instead of $x_1, \dots, x_{n-1}$, we obtain a new pair $(q, \delta)$ with similar properties. By a fairly straightforward argument one can show that $\delta \ge \varepsilon$ and $\|q - 1\|_{C[a,b]} \le \|p - 1\|_{C[a,b]}$. Iterating this process yields a sequence of polynomials that is guaranteed to converge to $p_{n,a,b}$. 

It should be noted that Remez algorithm is notorious for its instability when dealing with polynomials of sufficiently high degree. However, we have not observed an improvement of our methods when using polynomials of degrees higher than $5$. 

\subsection{Newton-Schulz iterations based on optimal odd polynomials} \label{sec:CANS}

We outline several reasonable choices of polynomials for Newton-Schulz iterations of a matrix $X$.

At first we consider the case when we are given a priori estimates on the singular values of $X$, i.e. $a \le \sigma_k(X) \le b$ for all $k = 1, \dots, n$. In this case it is natural to consider an integer $d_0 \in \mathbb N$ and an optimal odd polynomial $p_{d_0,a,b} = \sum_{k = 1}^{d_0} \alpha_{2k-1}x^{2k-1}$. All singular values of the matrix $X_1 = \sum_{k = 1}^{d_0} \alpha_{2k-1}X(X^TX)^{k-1}$ are contained in the interval $[a_1, b_1] = [1 - \varepsilon(d_0,a,b), 1 + \varepsilon(d_0,a,b)]$. Thus, we can again choose an integer $d_1$ (possibly distinct from $d_0$) and repeat this process with $p_{d_1, a_1, b_1}$ and matrix $X_1$. If $d_0, d_1,\dots$ are chosen to be greater or equal than $2$, then this process converges to the orthogonal factor $UV^T$ of $X$ in its polar decomposition. 
We present analysis of the convergence of these iterations in case of polynomials of degree $3$ (i.e. $d_1 = d_2 = \dots = 2$).


Let $0 < a < b$ and consider the following recursion (see also Algorithm \ref{alg:cans}):
\begin{equation}
\label{eq:explicit3}
\begin{gathered}
a_{0}=a,\quad  b_{0}=b,\quad 0<a<b \\
a_{n+1}=1-\varepsilon\left(2, a_{n}, b_{n}\right), \quad b_{n+1}=1+\varepsilon\left(2, a_{n}, b_{n}\right) .
\end{gathered}
\end{equation}
We also have $\varepsilon(d_k,a,b)=\|X_k-UV^T\|_2$.
\begin{proposition}\label{prop:convergence}
With the definition above, the error of approximation $\varepsilon_{n+1}=\varepsilon(2, a_n, b_n)$ converges to zero quadratically. More precisely,
\[
\varepsilon_{n+1} \leq \varepsilon_{n}^2 \quad \text{and} \quad \lim_{n \to \infty} \frac{\varepsilon_{n+1}}{\varepsilon_{n}^{2}}=\frac{3}{4}.
\]
\end{proposition} 
\begin{proof}See Appendix \ref{apx:convergence_proof}. \end{proof}
\begin{corollary} \label{prop:num_steps} For the starting segment $[a_0, b_0]$, where $0<a_0<1$ and $b_0=1$, the number of iterations necessary to achieve the desired error of approximation $\varepsilon$ in the spectral norm is as follows:\[n\geq \left\lceil \log_2\left(\frac{\ln\varepsilon}{\ln(1-a_0)}\right) \right\rceil.\]\end{corollary}\begin{proof}See Appendix \ref{apx:num_steps_proof}.\end{proof}
Note that one can efficiently ensure that $b_0\leqslant 1$ together with $b_0\approx 1$, as is discussed in Section~\ref{sec:gelfand}.



\subsection{Polynomials with large derivatives at $x=0$} \label{sec:maxderiv}

Now we assume that we are given a number $\delta \in (0, 1)$. Consider odd polynomials that satisfy the following property: there exists $a \in (0, 1 - \delta)$ such that $p(a) = 1 - \delta$, $p([a, 1 + \delta]) \subset [1 - \delta, 1 + \delta]$, and $p([0,a]) \subset [0, 1-\delta]$. We denote the set of all polynomials of degree $2d-1$ satisfying this property by $\mathcal P_{d,\delta}$. If $p \in \mathcal P_{d,\delta}$ and, in addition, it satisfies $p(x) \ge cx$ for all $x \in [0, a]$ and some $c > 1$, then for all $x \in (0, 1+ \delta]$ the sequence $x_1 = p(x), x_2 = p(p(x)), \dots$ monotonically increases until it falls into $[1-\delta, 1+\delta]$, after which it does not escape this interval. Newton-Schulz iterations with such a polynomial $p$ may not converge, but the singular values of the matrix lie in the interval $[1-\delta, 1+\delta]$ after a sufficiently large number of iterations. The problem is to optimize the rate of the ``convergence'' of these iterations for small singular values, or, in other words, to construct such polynomials with the largest possible derivative at $x = 0$.

We propose a following recipe to construct a polynomial in $\mathcal P_{d,\delta}$ (that also satisfies the inequality $p(x) \ge cx$ for all $x \in [0, a]$ and some $c > 1$). Let $d \in \mathbb N$ and consider the function $E(t) = \varepsilon(d,t,1 + \delta)$. It is easy to see that $E$ monotonically decreases on the interval $t \in (0, 1+\delta)$ and satisfies $E(t) \to 1$ as $t \to 0$, and $E(t) \to 0$ as $t \to 1 + \delta$. Thus, there exists a unique $a(d,\delta) \in (0, 1 + \delta)$ such that $E(a) = \delta$. Let us denote the corresponding polynomial $p_{d,a(d,\delta),1+\delta}$ by $q_{d, \delta}$. The fact that $q_{d,\delta}$ belongs to $\mathcal P_{d,\delta}$ follows immediately from Proposition~\ref{prop:properties}. Moreover, $q_{d,\delta}(x) \ge cx$ for all $x \in [0, a(d, \delta)]$ with $c = (1-\delta)/a(d,\delta)$.

\begin{proposition}\label{prop:kellerjordantype}
    Let $\delta \in (0,1)$ and $d \in \mathbb N$. For $p \in \mathcal P_{d, \delta}$ let $\mathfrak a(p) = \inf\{x \in [0, 1 + \delta]: p(x) \ge 1 - \delta\}$. Then the following statements hold.
    \begin{enumerate}[label=(\roman*)]
        \item\label{prop:kellerjordantypei} $\mathfrak a(q_{d,\delta}) = a(d, \delta)$ and for all $p \in \mathcal P_{d, \delta}$ the inequality $\mathfrak a(p) \ge a(d, \delta)$ holds. In other words, $q_{d, \delta}$ minimizes the function $\mathfrak a$ on the set $\mathcal P_{d, \delta}$.
        \item\label{prop:kellerjordantypeii} Assume that $d = 2$ (i.e. the degree of polynomials in consideration is $3$). Then $q_{2, \delta}^\prime(0) \ge p^\prime(0)$ for all $p \in \mathcal P_{d, \delta}$.
    \end{enumerate}
\end{proposition}
\begin{proof}
   See Appendix \ref{apx:kellerjordantype}.
\end{proof}
\begin{remark}\leavevmode
    \begin{enumerate}
        \item It is easy to obtain classical Newton-Schulz iterations from the polynomials $q_{d,\delta}$. Indeed, consider $d = 2$ and then pass to the limit $\delta \to 0$. Clearly, the polynomial $q_{2, \delta}(x)$ converges to $p(x)$ such that $p(1) = 1$ and $p^\prime(1) = 0$. There is only one odd polynomial of degree three satisfying these properties, namely, $p(x) = 3x/2 - x^3/2$, which is used in the classical Newton-Schulz iterations.
        \item It seems plausible that $q_{d,\delta}$ maximizes the derivative at $0$ on the set $\mathcal P_{d, \delta}$ for all $d$ (not only $d = 2$). We were not able to prove this statement, but it is supported by numerical experiments, as all alternative approaches that we are aware of yield polynomials with smaller derivative at zero.
    \end{enumerate}
\end{remark}


\begin{figure}
  \centering
   \includegraphics[width=0.8\linewidth]{imgs/illustration.pdf} 
  \caption{\label{fig:high_derivative} Illustration of the selection of a polynomial with a high derivative at zero. The green polynomial falls into $[1-\delta, 1+\delta]$, but has insufficient derivative. The blue polynomial $q_{d, \delta}$ has the highest possible derivative among polynomials from $\mathcal{P}_{d, \delta}$. The purple polynomial is not part of  $\mathcal{P}_{d, \delta}$, and its derivative is too large. }
\end{figure}

Finally, we observe that it is not necessary to iterate a single polynomial in order to push singular values into a given interval $[1-\delta, 1 + \delta]$. If we allow usage of distinct polynomials on each iteration, we can achieve more rapid ``convergence''. Again consider arbitrary $\delta \in (0,1)$. Choose a number $d_1 \in \mathbb N$ and find $\delta_1$ such that $\varepsilon(d_1, 1-\delta_1,1+\delta_1) = \delta$. After that one may choose yet another $d_2 \in \mathbb N$ and find $\delta_2$ such that $\varepsilon(d_2, 1 - \delta_2, 1 + \delta_2) = \delta_1$. Consider the corresponding polynomials $p_k = p_{d_k, 1 - \delta_k, 1 + \delta_k}$. It is easy to see that the composition $f(x) = p_1(p_2(\dots p_l(x) \dots))$ maps the interval $[1 - \delta_l, 1 + \delta_l]$ into $[1 - \delta,1 + \delta]$. Moreover, $f$ monotonically increases on $[0, 1-\delta_l]$ and satisfies $f(x) > x$ for all $x \in [0, 1 - \delta_l]$. After rescaling the argument by multiplying with $(1 + \delta)/(1 + \delta_l)$ we obtain a function $g(x) = f\left(x(1 + \delta_l)/(1 + \delta)\right)$ that has similar properties to an iteration of $q_{d, \delta}$. Moreover, if $d_1 = d_2 = \dots = d_l = d$, then $g^\prime(0) \ge \left(q^\prime_{d, \delta}(0)\right)^l$. Thus, allowing distinct polynomials on each iteration leads to faster convergence.
\begin{remark}\leavevmode
    \begin{enumerate}
        \item If $d_1 = d_2 = \dots = 2$, then the problem of finding $\delta_{j+1}$ such that $\varepsilon(2, 1 - \delta_{j+1},  1 + \delta_{j+1}) = \delta_j$ using formulae from Proposition~\ref{prop:explicit} can be reduced to finding roots of a degree three polynomial. For $d > 2$ we use Remez algorithm to determine $\varepsilon(d, a, b)$ numerically and solve the equation $\varepsilon(d, 1 - \delta_{j+1},  1 + \delta_{j+1}) = \delta_j$ using binary search.
        \item Even though choosing distinct polynomials can further maximize the derivative at $0$, it should be noted that the number $l$ of required iterations and degrees $d_1, \dots, d_l$ are to be chosen prior to computation. Therefore, in order to guarantee the desired inequalities on the singular values of the matrix after Newton-Schulz iterations, one has to impose a priori assumptions on $X$.
    \end{enumerate}
\end{remark}


Such polynomials with high derivatives at zero can be applied to matrices with rapidly decreasing singular values before orthogonalization (see Algorithms \ref{alg:cans}, \ref{alg:preprocessing}). This helps to speed up the orthogonalization of such matrices (see Figure \ref{fig:random}).

\begin{minipage}[t]{0.49\textwidth}
\begin{algorithm}[H]
\begin{algorithmic}
\caption{\label{alg:cans} Orthogonalization with CANS.}
\State \textbf{Input} Normalized matrix $X \in \mathbb{R}^{n\times p}, p\leq n$; $[a, b]$ where singular values of $X$ lie; number of iterations $s$; polynomials' degrees $2d_i-1$.
\State
\If {a is unknown}
\State $X, a, b = \texttt{$\delta$-orthogonalization}(X)$
\EndIf
\For {i \textbf{in} $\,\, 0 \dots \texttt{s}$}
\State $p_i, \varepsilon = \texttt{remez}(a, b, 2d_i-1)$
\State $\triangleright$ If $d_i=2,$ use formulas \ref{prop:explicit}, not $\texttt{remez}$.
\State $a, b = 1-\varepsilon, 1+\varepsilon$
\EndFor
\State $X=p_s(p_{s-1}(\dots p_1(p_0(X))))$
\State \textbf{Return} $X$
\end{algorithmic}
\end{algorithm}
\end{minipage}
\hfill
\begin{minipage}[t]{0.49\textwidth} 
\begin{algorithm}[H]
\begin{algorithmic}
\caption{\label{alg:preprocessing} $\delta$-orthogonalization.}
\State \textbf{Input} Normalized matrix $X \in \mathbb{R}^{n\times p}, p\leq n$; degrees $2d_i-1, i=0\dots s$; desired $\delta$; right boundary $B=1+\delta$; $eps=1e\text{-}7$.
\State $A_l, A_r = 0, B$
\While{ $|\delta-\varepsilon|>eps$} 
\State $a, b = (A_l + A_r) / 2, B$
\For{i \textbf{in} $\,\, 0 \dots s$}
\State $p, \varepsilon=\texttt{remez}(a, b, 2d_i-1)$
\State $a, b = 1 - \varepsilon, 1 + \varepsilon$
\EndFor
\If {$\varepsilon < \delta$}:
\State $A_r = (A_r + A_l) / 2$
\Else
\State$A_l = (A_l + A_r) / 2$
\EndIf
\EndWhile
\State $a, b=1-\delta, 1+\delta$
\State $X=p_s(p_{s-1}(\dots p_1(p_0(X))))$
\State \textbf{Return} $X, a, b$
\end{algorithmic}
\end{algorithm}
