		\subsection{Characterization of best responses}\label{ss:char}	

		Our next result establishes that, in $\nexp$-PAB auction games, best response supply functions have an affine dependence on the price, up to the market-clearing price $p^*$. 

		\begin{lemma}\label{lemmma:affine}
			Consider the $\nexp$-PAB auction game with set of producers $\mathcal N$, production cost functions $C_i$ for every $i$ in $\mc N$, and  demand function $D$. 
			Then, for  every strategy profile $S$ in $\mc S=(\nexp)^{\mc N}$ and every producer $i$ in $\mc N$, there exists an activation price $x_i$ in $[0,\hat p]$ such that the non-expansive supply function $\tilde{S}_i(p)=[p-x_i]_+$ satisfies
			\be\label{same-clearing}p^*(\tilde S_i,S_{-i}^*)=p^*(S_i,S_{-i}^*)\,,\ee
			and
			\be\label{eq1}u_i(\tilde S_i,S_{-i}^*)\ge u(S_i,S_{-i}^*)\,,\ee 
			with equality if and only if 
			\begin{equation}\label{eq:br_form}
				S_i(p) =[p-x_i]_+\,,\qquad\forall p\in [0, p^*]\,.%\begin{cases} 
			\end{equation}
		\end{lemma}
		\begin{proof}
			Consider a strategy profile $S$ in $\mc S$ and let $p^*=p^*(S)$ denote the associated market-clearing price. 
			For a producer $i$ in $\mc N$, consider the activation price
			$$x_i := {\sum_{j\neq i}S_j(p^*)- D(p^*)}+p^*\,,$$
			and define the supply function
			$\tilde{S}_i(p)=[p-x_i]_+$. 
			(C.f.~Figure \ref{fig:Klip_sf}.) 
			Clearly, $\tilde{S}_i\in\nexp$. 
			Notice that 
			$$\tilde S_i(p^*)=p^*-x_i=D(p^*)-\sum_{j\neq i}S_j(p^*)\,,$$
			so that \eqref{same-clearing} holds true and $\tilde S_i(p^*)=S_i(p^*)$. 
			Moreover, 
			$$S_i(p)\geq 0=\tilde{S}_i(p)\,,\qquad \forall p\in[0, x_i]\,.$$ 
			On the other hand, for every $p$ in $(x_i, p^*]$, we have that 
			$$
			\ba{rcl}
			S_i (p^*) - S_i (p) 
			&=&|S_i (p^*) - S_i (p)|
			\le|p^*-p| \\[7pt]
			%&=& K(p^*-p) \\
			%	 \\[7pt]	&=& 
			&=& p^*-x_i-(p-x_i) 
			= \tilde{S}_i(p^*)-\tilde{S}_i(p)%\\[7pt] 
			%&=& 
			=S_i(p^*)-\tilde{S}_i(p)	\,,
			\ea
			$$
			where the inequality follows from the fact that $S_i\in\nexp$. Hence, we have that  
			$$S_i(p)\geq \tilde{S}_i(p)\,,\qquad \forall p\in[0, p^*]\,,\qquad  S_i(p^*)=\tilde{S}_i(p^*)\,.$$ 
			Therefore, %We now want to show that playing the strategy $\tilde{S}_i$ gives a greater or equal utility than $S_i$, that is,
			$$
			\ba{rcl}
			u_i(S_i, S_{-i}) &= & p^*S_i(p^*)- \int_0^{p^*}S_i(p)dp -C_i(S_i(p^*))\\
			&\leq & p^*\tilde{S}_i(p^*)- \int_0^{p^*}\tilde{S}_i(p)dp -C_i(\tilde{S}_i(p^*))\\&= &u_i(\tilde{S}_i, S_{-i})\,,
			\ea
			$$
			thus proving \eqref{eq1}. 
			%Notice that, as $S_i(p^*)=\tilde{S}_i(p^*)$, the previous inequality holds true if and only if
			%\begin{equation}\label{eq:integral}
			%	\int_0^{p^*}S_i(p)\dd p\geq \int_0^{p^*}\tilde{S}_i(p)\dd p\,.
			%\end{equation}
			We remark that %since the inequality is satisfied punctually, 
			$$\int_0^{p^*}S_i(p)\dd p= \int_0^{p^*}\tilde{S}_i(p)\dd p \qquad \Leftrightarrow\qquad  S_i(p)=\tilde{S}_i(p) \,,\quad \forall p \in[0, p^*]\,,$$
			which implies that $u_i(S_i, S_{-i})=u_i(\tilde{S}_i, S_{-i})$ if and only if $S_i(p)=\tilde{S}_i(p)$ for every $p$ in $[0, p^*]$. Otherwise, $u_i(S_i, S_{-i})<u_i(\tilde{S}_i, S_{-i})$.
			This concludes the proof.
		\end{proof}

		\begin{proposition}[Affine best-response]\label{pr:br_form}
			Consider the $\nexp$-PAB auction game with set of producers $\mathcal N$, production cost functions $C_i$ for every $i$ in $\mc N$, and  demand function $D$. 
			For  every strategy profile $S$ in $\mc S=(\nexp)^{\mc N}$, if $S_i \in \mathcal B_i(S_{-i})$ is a best response of a producer $i$ in $\mc N$, then  there exists an activation price $x_i$ in $[0, \hat{p}]$ such that 	\eqref{eq:br_form} holds true. 
			%		\begin{equation}\label{eq:br_form}
				%S_i(p) =[p-x_i]_+\,,\qquad\forall p\in [0, p^*]\,,%\begin{cases} 
				%		\end{equation}
			%	where $p^*=p^*(S)$ is the market-clearing price.
		\end{proposition}
		\begin{proof}
			The claim is a direct consequence of Lemma \ref{lemmma:affine}. 
		\end{proof}

