			Then:
			\begin{enumerate}
				\item[(i)] for every Nash equilibrium $x^*$ of the activation price game, the strategy profile $S^*$ with supply functions 
				\be\label{Si=p-x}S_i^*(p)=[p-x_i^*]_+\,,\qquad\forall p\in[0,\hat p]\,,\ee for every  $i$ in $\mc N$ is a Nash equilibrium of the $\nexp$-PAB auction game; 
				\item[(ii)] for every Nash equilibrium $S^*$ of the $\nexp$-PAB auction game, there exists a Nash equilibrium $x^*$ of the activation price game such that 
				\be\label{p=p}p^*(S^*)=\ov p(x^*)\,,\ee
				and 
				\be\label{Si=p-xi}S_i^*(p)=[p-x_i^*]_+\,,\qquad \forall p\in[0,p^*(S^*)]\,,\ee
				for every $i$ in $\mc N$. 
			\end{enumerate}
		\end{proposition}
		\begin{proof} (i) Let $x^*$ in $\mc X$ be a Nash equilibrium of the activation price game and let $S^*$ in $\mc S$ be a strategy profile with supply functions as in \eqref{Si=p-x} for every producer $i$ in $\mc N$. Observe that 
			\be\label{eq0}p^*(S^*)=\ov p(x^*)\,,\qquad u_i(S^*)=\ov u_i(x^*)\,.\ee
			For every supply function $S_i$ in $\nexp$, Lemma \ref{lemmma:affine} implies there exists an activation price $x_i$ in $[0,\hat p]$ such that the supply function $\tilde S_i(p)=[p-x_i]_+$ satisfies \eqref{same-clearing} and \eqref{eq1}. 
			Now, observe that 
			\be\label{eq2} %\begin{array}{l}
			p^*(\tilde S_i,S_{-i}^*)=\ov p(x_i,x^*_{-i})\,,\;u_i(\tilde S_i,S_{-i}^*)=\ov u_i(x_i,x^*_{-i})\,.%\end{array}
			\ee
			Since $x^*$ is a Nash equilibrium of the activation price game, we have that 
			\be\label{eq3}\ov u_i(x^*)\ge\ov u_i(x_i,x^*_{-i})\,.\ee
			Equations \eqref{eq0}, \eqref{eq3}, \eqref{eq2}, and \eqref{eq1} imply that 
			$$
			u_i(S^*)=\ov u_i(x^*)\ge\ov u_i(x_i,x^*_{-i})=u_i(\tilde S_i,S_{-i}^*)\ge u(S_i,S_{-i}^*)\,.
			$$
			Since the above holds true for every producer $i$ in $\mc N$ and every supply functions $S_i$ in $\nexp$, we have that $S^*$ is a Nash equilibrium of the $\nexp$-PAB auction game. 

			(ii) Let $S^*$ be a Nash equilibrium of the $\nexp$-PAB auction game. Then, Proposition \ref{pr:br_form}, implies that, for every producer $i$ in $\mc N$, there exists an activation price $x_i^*$ in $[0,\hat p]$ such that \eqref{Si=p-xi} holds true. Observe that \eqref{eq0} holds true. Now, fix $x_i$ in $[0,\hat p]$ and let $S_i(p)=[p-x_i]_+$. Then, we have that 
			\be\label{eq4}p^*(S_i,S_{-i}^*)=\ov p(x_i,x^*_{-i})\,,\; u_i(S_i,S_{-i}^*)=\ov u_i(x_i,x^*_{-i})\,.\ee
