Example \ref{ex:3_lin} leads to a discussion on the value of $K$. %Indeed, our model requires $K$ to be fixed, but for any $K$ we obtain different equilibrium outcomes.  Recall that, according to Proposition \ref{pr:no_br} and the following remark, best responses would exist in the general setting if one could use step functions. Also, as $K$ increases, we are enlarging the strategy space. Therefore, a fundamental example that requires a deeper study is the case when $K$ approaches infinity. 
In the following result, we compute explicitly the resulting market-clearing price when $K$ goes to infinity. This limit permits a comparison with equilibrium outcome in standard oligopoly models, such as Cournot and Bertrand, and in the Supply Function equilibrium. 

\begin{proposition}\label{pr:limit}
Consider a set of producers $\mathcal N$, quadratic production cost functions as in \eqref{eq:quad_c} for every $i$ in $\mc N$, and affine demand function \eqref{eq:aff_dem}. 
For $K>0$, let $x_i^{(K)}$, for $i$ in $\mc N$ and $p^*_K$ be the activation prices and, respectively, the clearing price of any Nash equilibrium $S^{(K)}$ of the $\lip$-PAB auction game. Then, for every producer $i$ in $\mc N$, 
\be\label{eqlimxip}\lim_{K\to+\infty}x_i^{(K)}=\lim_{K\to+\infty}p^*_K=\frac{\hat p\gamma+b\sum_{j=1}^{n}1/c_j}{\gamma+\sum_{j=1}^{n}1/c_j}.\ee
Moreover, the asymptotic quantity of good sold by a producer $i$ in $\mc N$ is
\be\label{eqlimSK}\lim_{K\to+\infty}S_i^{(K)}(p^*_K)=\frac{\gamma/c_i}{\gamma+\sum_{j=1}^{n}1/c_j}[\hat p-b]_+\,,\ee
while its asymptotic profit is given 
\be\label{eqlimuiK}\lim_{K\to+\infty}u_i^{(K)}(p^*_K)=\frac{\gamma^2}{c_i(\gamma+\sum_{j=1}^{n}1/c_j)^2}[\hat p-b]^2_+\,.\ee
\end{proposition}
\begin{proof}
Let $a_i$, $d_i$, and $\Delta$ be defined as in \eqref{eq:quadr_coeff}, \eqref{eq:quadr_coeff2}, and \eqref{Delta-def}, respectively. Then, 
\be\label{limKai}%\label{limKdi}\label{limKDelta}
%\begin{aligned}
\lim_{K\to+\infty}a_i=%\\&=\lim_{K\to+\infty}\frac{Kc_i(n-1)+c_i\gamma+1}{(n+\gamma/K)(Kc_i(n-1)+c_i\gamma+n+\gamma/K)}
\frac1n\,,\;\; \lim_{K\to+\infty}	d_{i} =\frac1{c_i}\,,\;\; \lim_{K\to+\infty}\Delta=\sum_{i\in\mc N}\frac1{c_i}\,,
%\end{aligned}
\ee
%\be\label{limKdi}\lim_{K\to+\infty}	d_{i} =\lim_{K\to+\infty}\frac{K(n-1)+\gamma }{Kc_i(n-1)+c_i\gamma+n+\gamma/K}
%=\frac1{c_i}\,,\ee
%for every producer $i$ in $\mc N$, so that
%\be\label{limKDelta}\lim_{K\to+\infty}\Delta=\lim_{K\to+\infty}\sum_{i\in\mc N}d_i=\sum_{i\in\mc N}\frac1{c_i}\,.\ee
It then follows from \eqref{eq:ne_lin} and \eqref{limKDelta} that 
$$\lim_{K\to+\infty}x_i^{(K)} = \lim_{K\to+\infty}\left(n+\frac{\gamma}{K}\right)\frac{\hat p\gamma+b\Delta}{\gamma+\Delta}a_i+\frac bKd_i=\frac{\hat p\gamma+b\sum_{j=1}^{n}1/c_j}{\gamma+\sum_{j=1}^{n}1/c_j}\,,$$
for every producer $i$ in $\mc N$, while \eqref{eq:ep_ne_lin} and \eqref{limKDelta} imply that
$$\lim_{K\to+\infty}p^*_K=\lim_{K\to+\infty}\frac{\hat p\gamma+b\Delta}{\gamma+\Delta}=\frac{\hat p\gamma+b\sum_{j=1}^{n}1/c_j}{\gamma+\sum_{j=1}^{n}1/c_j} \,,$$
thus proving \eqref{eqlimxip}. Moreover, observe that from \eqref{eq:quadr_coeff} we get that
\be\label{limK}
\begin{aligned}
\lim_{K\to+\infty}&K\left(1-\left(n+\frac\gamma{K}\right)a_i\right)=\\=&\lim_{K\to+\infty}\frac{K(n-1)+\gamma}{Kc_i(n-1)+c_i\gamma+n+\gamma/K}=\frac1{c_i}\,,
\end{aligned}\ee
for every producer $i$ in $\mc N$, so that
$$\ba{rcl}\ds\lim_{K\to+\infty}S^{(K)}(p^*_K)
&=&\ds\lim_{K\to+\infty}K[p^*_K-x_i^{(K)}]_+\\
&=&\ds\lim_{K\to+\infty}\left[\frac{\hat p\gamma+b\Delta}{\gamma+\Delta}K\left(1-\left(n+\frac\gamma{K}\right)a_i\right)-bd_i\right]_+\\
&=&\ds\left[\frac{\hat p\gamma+b\sum_{j=1}^{n}1/c_j}{\gamma+\sum_{j=1}^{n}1/c_j}-b\right]_+\frac1{c_i}\\
&=&\ds\frac{\gamma/c_i}{\gamma+\sum_{j=1}^{n}1/c_j}[\hat p-b]_+
\ea$$
where the second equality follows from \eqref{eq:ep_ne_lin} and \eqref{eq:ne_lin} and the third one from \eqref{limK} and \eqref{limKdi}.  
Hence, we have proved \eqref{eqlimSK}. Finally, by \eqref{eq:utility_pab}, 
$$\ba{rcl}	\ds u_i^{(K)}(p^*_K)
&=&\ds p^*_KS_i^{(K)}(p^*_K)-\int_0^{p^*_K}S _i^{(K)}(p)\dd p - C^{(K)}_i(S_i^{(K)}(p^*_K))\\
&=&\ds p^*_KS_i^{(K)}(p^*_K)-K\int_{x_i^{(K)}}^{p^*_K}(p-x_i^{(K)})\dd p -C^{(K)}_i(S_i^{(K)}(p^*_K))\\
%&=&\ds p^*_KS_i^{(K)}(p^*_K)-\frac K2(p^*_K-x_i^{(K)})^2 -C^{(K)}_i(S_i^{(K)}(p^*_K))\\
&=&\ds p^*_KS_i^{(K)}(p^*_K)-\frac {1}{2K}(S_i^{(K)}(p^*_K))^2 -\frac{c_i}{2} \left(S_i^{(K)}(p^*_K)\right)^2-bS_i^{(K)}(p^*_K)\,.
\ea$$
Therefore,
$$\ba{rcl}\ds\lim_{K\to+\infty}u_i^{(K)}(p^*_K)
%&=&\ds\left(\frac{\hat p\gamma+b\sum_{j=1}^{n}1/c_j}{\gamma+\sum_{j=1}^{n}1/c_j}-b\right)\frac{\gamma/c_i}{\gamma+\sum_{j=1}^{n}1/c_j}[\hat p-b]_+\\&&
%\ds-\frac{c_i}{2}\frac{\gamma^2/c_i^2}{(\gamma+\sum_{j=1}^{n}1/c_j)^2}[\hat p-b]^2_+\\
&=&\ds\frac{\gamma^2(\hat{p}-b)}{c_i(\gamma+\sum_{j=1}^{n}1/c_j)^2}[\hat p-b]_+-\frac{\gamma^2}{2c_i(\gamma+\sum_{j=1}^{n}1/c_j)^2}[\hat p-b]^2_+
\\
&=&\ds\frac{\gamma^2}{2c_i(\gamma+\sum_{j=1}^{n}1/c_j)^2}[\hat p-b]^2_+
\,,\ea$$
where the fifth equality follows from \eqref{eqlimxip} and \eqref{eqlimSK}.
\end{proof}

We  conclude this section with the following fundamental remark, showing that, according to Proposition \ref{pr:limit}, in the limit, we obtain \emph{perfect competition} at the Nash equilibrium.
\begin{remark}
According to Proposition \ref{pr:limit}, for $K\rightarrow \infty$, we have that $\lim_{K\rightarrow \infty} x_i^{(K)}=\lim_{K\rightarrow \infty} p^*_K=p^*_{\infty}$ for all agents $i$ in $\mathcal N$. %, where $x^*$ is the unique equilibrium of the activation price  game. 
This observation implies that, as $K$ approaches infinity, %we are approximating 
the set of Nash equilibria of the $\lip$-PAB auction game converges to a set of \emph{step functions} that are zero up to the market-clearing price $p^*_{\infty}$.  This was also observed in Example \ref{ex:3_lin}. Therefore, by increasing the value of $K$, we are estimating the behavior of the PAB auction game with strategy space $\mathcal A=\cmon$ %, %, by converging to the step function best responses 
%that we observed at the begin of the chapter in the
(recall the proof of Proposition \ref{pr:no_br} and Remark \ref{rem:step_f}).
%			\end{remark}
%			\begin{remark}\color{red}
%	perfect competition with efficient distribution of quantities
Furthermore, in this setting, marginal costs are given by $C'_i(q_i) = c_i q_i+b$ and, for $\hat p\geq b$, we find
$$
\ba{rclclcl}
\ds\lim_{K\to+\infty}C_i'\left(S_i^{(K)}(p^*_K)\right)
&=&\ds C_i'\left(\frac{\gamma/c_i}{\gamma+\sum_{j=1}^{n}1/c_j}[\hat p-b]_+\right)\\[10pt]
&=&\ds C_i'\left(\frac1c_i\left(\frac{\hat p\gamma+b\sum_{j=1}^{n}1/c_j}{\gamma+\sum_{j=1}^{n}1/c_j}-b\right)\right)
&=&\ds C_i'\left(\frac{p^*_\infty-b}{c_i}\right)&=&\ds p^*_\infty
%				\\[10pt]
%				&=&\ds p^*_\infty
\,,\ea$$
for every $i$ in $\mathcal N$. 
Therefore, in the limit, we obtain \emph{perfect competition} (i.e., the price is equal to the marginal costs). As we shall see in the next section, when the costs are quadratic and homogeneous,  the unique equilibrium of the activation price game corresponds, in the limit, to the "best" Nash equilibrium of the Bertrand competition, that is, the one corresponding to perfect competition. Furthermore, we remark that we obtain  \emph{efficient allocation} also when the costs are heterogeneous.
%Furthermore, since $q_{i,\infty}\propto 1/c_i$ we also have \emph{efficient allocation}.
%In Proposition \ref{pr:limit}, we find that, as $K$ goes to infinity, the total sold quantity at Nash equilibrium in the $\lip$-PAB auction game is given by $$q^*_{i, {\infty}}:= \lim_{K\to+\infty}S_i^{(K)}(p^*_K)=\frac{\gamma/c_i}{\gamma+\sum_{j=1}^{n}1/c_j}[\hat p-b]_+=\frac1c_i(\frac{\hat p\gamma+b\sum_{j=1}^{n}1/c_j}{\gamma+\sum_{j=1}^{n}1/c_j}-b)$$, for all $i$ in $\mathcal N$.	Notice that we find the same sold quantity if we consider uniform-price remuneration and supply bids $S_i(p)=\frac{1}{c_i}(p-b)$ for all $i$ in $\mathcal N$. If we combine all these remarks, we find that we observe the same outcome as truthful bidding in uniform-price auctions.		
\end{remark}




