\title{VeriFlow: Modeling Distributions for Neural Network Verification}

\author{Faried Abu Zaid \inst{1}  \and Daniel Neider  \inst{2}\inst{3} \and Mustafa Yal\c{c}{\i}ner \inst{2}\inst{3}}
