\section{Detailed proofs}\label{app:proofs}
\subsection{Proof of Lemma~\ref{lemma: UHU<0}}\label{proof of lemma: UHU<0}
\begin{proof} 
	It follows from (\ref{Galerkin equation}) that
	\begin{equation}
		\label{UHU<0}
		\begin{aligned}
			&	\frac{\mathrm{d}    }{\mathrm{d}  t} \left(U^{(m)}(t)\right)^\top \mathcal{H}U^{(m)}(t)
			\\=& -\left( \mathcal{P}_m\nabla_GE(U^{(m)}(t))\right)^\top \mathcal{H}U^{(m)}(t) - \left(U^{(m)}(t)\right)^\top \mathcal{H} \mathcal{P}_m\nabla_GE(U^{(m)}(t))
			\\=& -2 \left(U^{(m)}(t) \right)^\top \mathcal{H}^2U^{(m)}(t) +2\left( \left(U^{(m)}(t)\right)^\top \mathcal{H}U^{(m)}(t)\right)^2
			\\ \leqslant &2\left( \left(U^{(m)}(t)\right)^\top \mathcal{H}U^{(m)}(t)\right)^2.
		\end{aligned}
	\end{equation}

	Fixed $t\geqslant0$, for any eigenvalue $\lambda(t)$ of the matrix $\left(U^{(m)}(t)\right)^\top \mathcal{H}U^{(m)}(t):=A_m(t)$, there corresponds a normalized eigenvector $y(t)\in \mathbb{R}^N$ such that
	\begin{equation*}
		\begin{aligned}
			A_m(t)y(t) = \lambda(t)y(t) \text{ with } y(t)^\top y(t) = 1.
		\end{aligned}
	\end{equation*}
	and thus
	\begin{equation*}
		\begin{aligned}
			y(t)^\top A_m(t) y(t) = \lambda(t).
		\end{aligned}
	\end{equation*}
	Taking the derivative of both sides with respect to $t$ yields
	\begin{equation*}
		\begin{aligned}
			\frac{\mathrm{d}   }{\mathrm{d}  t} \lambda(t)  =& \frac{\mathrm{d}    }{\mathrm{d}  t} \left(y(t)^\top A_m(t) y(t)\right) 
			\\ =& \left(\frac{\mathrm{d}   y(t) }{\mathrm{d}  t}\right)^\top A_m(t)y(t) +y(t)^\top \frac{\mathrm{d}  A_m(t) }{\mathrm{d}  t}  y(t)+y(t)^\top A_m(t) \frac{\mathrm{d} y(t)}{\mathrm{d}  t} 
			\\ = &\lambda(t)\left(\frac{\mathrm{d}   y(t) }{\mathrm{d}  t}\right)^\top y(t) +y(t)^\top \frac{\mathrm{d} A_m(t) }{\mathrm{d}  t}  y(t)+ \lambda(t) y(t)^\top \frac{\mathrm{d}  y(t)  }{\mathrm{d}  t} .
		\end{aligned}
	\end{equation*}
	We note that the normalization condition $y(t)^\top y(t) = 1$ implies
	\begin{equation*}
		\begin{aligned}
			0=	\frac{\mathrm{d}    }{\mathrm{d}  t} \left(y(t)^\top y(t)\right) = \left(\frac{\mathrm{d}   y(t) }{\mathrm{d}  t}\right)^\top y(t) +y(t)^\top \frac{\mathrm{d}  y(t)  }{\mathrm{d}  t} .
		\end{aligned}
	\end{equation*}

	Therefore, we can rewrite (\ref{UHU<0}) as
	\begin{equation*}
		\begin{aligned}
			\frac{\mathrm{d}   }{\mathrm{d}  t} \lambda(t) = y(t)^\top \frac{\mathrm{d}  A_m(t)  }{\mathrm{d}  t}  y(t) 
			\leqslant 2y(t)^\top\left( A_m(t) \right)^2 y(t)  = 2\left(\lambda(t) \right)^2.
		\end{aligned}
	\end{equation*}
	It follows that
	\begin{equation*}
		\begin{aligned}
			\lambda(t)\leqslant \frac{\lambda(0)}{1-2t\lambda(0)} = -\frac{|\lambda(0)|}{1+2t|\lambda(0)|} \leqslant0,
		\end{aligned}
	\end{equation*}
	which implies $A_m(t) \leqslant0$, that is $ \left(U^{(m)}(t)\right)^\top \mathcal{H}U^{(m)}(t)\leqslant0$ for all $t\geqslant0$.
\end{proof}


\subsection{Proof of Lemma~\ref{negative condition of initial value}}\label{proof of lemma: negative condition of initial value}
\begin{proof}
	For any $a\in \mathbb{R}^N$ and $a \neq 0$, denote $v = U_0 a$, then there exists a series $\{\alpha_j\}_{j=1}^{\infty}$ such that
	\begin{equation*}
		\begin{aligned}
			v = \sum\limits_{j=1}^{\infty} \alpha_j v_j,
		\end{aligned}
	\end{equation*}
	and thus
	\begin{equation*}
		\begin{aligned}
			a^\top \left(U_0^\top \exp(-k\mathcal{H}t) U_0\right)a = v^\top \exp(-k\mathcal{H}t) v =  \sum\limits_{j=1}^{\infty} \exp(-k\lambda_j t) |\alpha_j|^2. 
		\end{aligned}
	\end{equation*}
	Since the function $\exp(-k\lambda t)$ is convex with respect to $\lambda$, it is obtained by Jensen's inequality that
	\begin{equation*}
		\begin{aligned}
			\exp\left( -k\frac{v^\top \mathcal{H}v}{\|v\|^2} t\right)  =& \exp\left( -k \frac{\sum_{j=1}^{\infty}|\alpha_j|^2\lambda_j }{\sum_{j=1}^{\infty}|\alpha_j|^2}t\right)
			\\\leqslant&  \frac{\sum_{j=1}^{\infty}|\alpha_j|^2\exp\left(-k\lambda_j t\right) }{\sum_{j=1}^{\infty}|\alpha_j|^2}= \frac{ v^\top \exp(-k\mathcal{H}t) v}{\|v\|^2}.
		\end{aligned}
	\end{equation*}
	For $U_0^\top \mathcal{H} U_0\leqslant 0$, there exists a constant $h_0 \leqslant0$ that 
	\begin{equation*}
		\begin{aligned}
			\frac{v^\top \mathcal{H}v}{\|v\|^2}  \leqslant \sup\limits_{a\in \mathbb{R}^N \backslash \{0\}}\frac{a^\top \left(U_0^\top \mathcal{H}U_0\right)a}{\|U_0 a\|^2} \stackrel{\Delta}{=}h_0 .  
		\end{aligned}
	\end{equation*}
	It follows that
	\begin{equation*}
		\begin{aligned}
			v^\top \exp(-k\mathcal{H}t) v \geqslant \|U_0a\|^2 \exp(-kch_0t)\geqslant \|U_0 a\|^2 ,\quad \forall t\geqslant0.
		\end{aligned}
	\end{equation*}
	Thus we have
	\begin{equation*}
		\begin{aligned}
			U_0^\top \exp(-k\mathcal{H}t) U_0 \geqslant U_0^\top U_0 ,\quad \forall t\geqslant0.
		\end{aligned}
	\end{equation*}
	The proof is now complete.
\end{proof}

\subsection{Proof of Lemma~\ref{expression of Glaerkin solution}}\label{proof of lemma: expression of Glaerkin solution}

\begin{proof}
	For any $U^{(m)}(t) \in (\mathcal{V}_m)^N$, 
	$$U^{(m)}(t) = \sum\limits_{i=1}^{m} \sum\limits_{p=1}^N \alpha_{ip}^{(m)}(t) V_{ip} =V_m  \alpha^{(m)}(t), $$
	where
	$$\alpha^{(m)}(t)  =\begin{pmatrix}
		\alpha_{11}^{(m)}(t)& \alpha_{12}^{(m)}(t)&\cdots& \alpha_{1N}^{(m)}(t) \\
		\alpha_{21}^{(m)}(t)& \alpha_{22}^{(m)}(t)&\cdots& \alpha_{2N}^{(m)}(t)\\
		\vdots &\vdots& &\vdots\\
		\alpha_{m1}^{(m)}(t)& \alpha_{m2}^{(m)}(t)&\cdots& \alpha_{mN}^{(m)}(t)
	\end{pmatrix} \in \mathbb{R}^{m\times N}$$
	and $V_m = (v_1, \cdots, v_m)$. Thus $\mathcal{H}_mV_m = V_m\Lambda_m \text{ with } \Lambda_m = \operatorname{diag}\left(\lambda_1,\cdots, \lambda_m\right)$. Furthermore, $V_m$ satisfies $V_m^\top V_m = I_m$ and $V_m V_m^\top = \sum\limits_{i=1}^m v_i v_i^\top$, which is, in fact, the projection operator $\mathcal{P}_m$.


	Thus the first equation of (\ref{finite dimension of operator}) can be rewritten as
	\begin{equation*}
		\begin{aligned}
			V_m  \frac{\mathrm{d}    }{\mathrm{d}  t} \alpha^{(m)}(t)
			=&   \frac{\mathrm{d}    }{\mathrm{d}  t}U^{(m)}  
			\\=& -\mathcal{H}_m  V_m  \alpha^{(m)}(t) +   V_m  \alpha^{(m)}(t) \left(\alpha^{(m)}(t)\right)^\top  V_m^\top  \mathcal{H}_m V_m  \alpha^{(m)}(t) 
			\\=&- V_m  \left(\Lambda_m \alpha^{(m)}(t) -\alpha^{(m)}(t) \left(\alpha^{(m)}(t)\right)^\top \Lambda_m  \alpha^{(m)}(t)  \right).
		\end{aligned}
	\end{equation*}

	We obtain from \cite{yan1994global}] that the solution of
	\begin{equation*}
		\label{oja eqaution}
		\begin{aligned}
			\frac{\mathrm{d}    }{\mathrm{d}  t} \alpha^{(m)}(t) 
			=	-  \left(  \Lambda_m  \alpha^{(m)}(t) -\alpha^{(m)}(t)  \left(\alpha^{(m)}(t)\right)^\top   \Lambda_m  \alpha^{(m)}(t)  \right) 
		\end{aligned}
	\end{equation*}
	can be expressed as
	\begin{equation}
		\label{expression of solution for oja equation }
		\begin{aligned}
			\alpha^{(m)}(t) =&\exp(-\Lambda_m t) \alpha^{(m)}(0) \left[ I_N-\left(\alpha^{(m)}(0) \right)^\top   \alpha^{(m)}(0) \right.
			\\&\qquad\qquad\left. +\left(\alpha^{(m)}(0) \right)^\top   \exp (-2 \Lambda_m t)  \alpha^{(m)}(0) \right]^{-1 / 2} Q^{(m)}(t),
		\end{aligned}
	\end{equation}
	where $Q^{(m)}(t)\in \mathcal{O}^N$ depends on $t$ only.
	We obtain from Lemma \ref{negative condition of initial value} that 
	\begin{equation*}
		\begin{aligned}
			U_0^\top \exp(-2\mathcal{H}t) U_0 \geqslant U_0^\top U_0, \quad \forall t\geqslant0,
		\end{aligned}
	\end{equation*}
	and thus
	\begin{equation*}
		\begin{aligned}
			I_N-\left(\alpha^{(m)}(0) \right)^\top   \alpha^{(m)}(0)  +\left(\alpha^{(m)}(0) \right)^\top   \exp (-2 \Lambda_m t)  \alpha^{(m)}(0)\geqslant I_N,
		\end{aligned}
	\end{equation*}
	which implies that (\ref{expression of solution for oja equation }) holds for all $t\geqslant0$. Therefore, 
	\begin{equation*}
		\begin{aligned}
			U^{(m)}(t) 	=& \exp (-\mathcal{H}_m t) U^{(m)}(0)\left[ I_N-\left(U^{(m)}(0)\right)^\top U^{(m)}(0)\right.
			\\&\qquad \qquad \quad  \qquad \left. +\left(U^{(m)}(0)\right)^\top \exp (-2 \mathcal{H}_m t) U^{(m)}(0)\right]^{-1 / 2} Q^{(m)}(t).
		\end{aligned}
	\end{equation*}
	The proof is now complete.
\end{proof}

\subsection{Proof of Lemma~\ref{solution of linear evolution problem}}\label{proof of lemma:solution of linear evolution problem}
\begin{proof}
	Since the operator \(\mathcal{H}\) is bounded and satisfies the G\aa rding inequality, it follows that \(\mathcal{H}\) is closed. Consequently, the shifted operator
	\begin{equation*}
		\begin{aligned}
			\mathcal{H}_{\lambda_1} := -(\mathcal{H}-\lambda_1\mathcal{I})
		\end{aligned}
	\end{equation*}
	is also closed. Moreover, since $\mathcal{D}(\mathcal{H}_{\lambda_1}) = \mathcal{D}(\mathcal{H})$, we have
	\begin{equation*}
		\begin{aligned}
			\overline{\mathcal{D}(\mathcal{H}_{\lambda_1})} = \bigl(H_0^1(\Omega)\bigr)^N.
		\end{aligned}
	\end{equation*}

	Observing that $\lambda_{\max}\bigl(\mathcal{H}_{\lambda_1}\bigr) = 0$, we deduce that for any $\lambda>0$ the operator $\lambda\mathcal{I} - \mathcal{H}_{\lambda_1}$ is invertible and its inverse satisfies the bound
	\[
	\bigl(\lambda\mathcal{I}-\mathcal{H}_{\lambda_1}\bigr)^{-1}  \leqslant \frac{1}{\lambda}\mathcal{I}.
	\]
	By the Hille–Yosida theorem, it then follows that \(\mathcal{H}_{\lambda_1}\) is the infinitesimal generator of a \(C_0\) semigroup of contractions.

	Furthermore, by Theorem 3.1.1 in \cite{pazy1983semigroups}, the operator \(-\mathcal{H}\) is also the infinitesimal generator of a \(C_0\) semigroup. Hence, Theorem 1.2.4 in \cite{pazy1983semigroups} ensures that for every $U_0 \in \bigl(\mathcal{D}(\mathcal{H})\bigr)^N$,
	the linear evolution problem \eqref{linear evolution problem} has a unique solution given by
	\begin{equation*}
		\begin{aligned}
			W(t) = \exp\bigl(-k\,\mathcal{H}t\bigr)U_0 \in\left(\mathcal{D}(\mathcal{H})\right)^N .
		\end{aligned}
	\end{equation*}
	Moreover, Theorem 4.1.3 in \cite{pazy1983semigroups} guarantees that \(W(t)\) is continuously differentiable on $[0,+\infty)$; that is,
	\begin{equation*}
		\begin{aligned}
			W \in C^{1}\left([0,+\infty);\,\left(\mathcal{D}(\mathcal{H})\right)^N\right).
		\end{aligned}
	\end{equation*}
\end{proof}


\subsection{Proof of Lemma~\ref{singular values of soltion}}\label{proof of lemma: singular values of soltion}

\begin{proof}
	We see from the proof of Lemma~\ref{negative condition of initial value} that there holds for all constant $k>0$
	\begin{equation*}
		\begin{aligned}
			a^\top \left(U_0^\top \exp(-k\mathcal{H}t) U_0\right)a \geqslant \lambda_{\min}\left(U_0^\top U_0\right) \exp(k|h_0|t)\|a\|^2, \quad \forall a \in \mathbb{R}^N,
		\end{aligned}
	\end{equation*}
	that is,
	\begin{equation*}
		\begin{aligned}
			\lambda_{\min}\left(U_0^\top \exp(-k\mathcal{H}t) U_0 \right) \geqslant \lambda_{\min}\left(U_0^\top U_0\right) \exp(k|h_0|t).
		\end{aligned}
	\end{equation*}
	Under the initial condition $U_0^\top \mathcal{H}U_0<0$, the constant $h_0$ is strictly negative. Therefore, 
	\begin{equation*}
		\begin{aligned}
			\lambda_{\max}\left( \left(U_0^\top \exp(-k\mathcal{H}t) U_0\right)^{-1} \right) \leqslant \frac{1}{\lambda_{\min}\left(U_0^\top U_0\right) }\exp(-k|h_0|t).
		\end{aligned}
	\end{equation*}
	As $t$ goes to $\infty$, the right-hand side tends to 0, ensuring that 
	\begin{equation}
		\label{inverse of U0exp(-Ht)U0 goes to 0}
		\begin{aligned}
			\left(U_0^\top \exp(-k\mathcal{H}t) U_0\right)^{-1}\rightarrow 0 \text{ as } t \rightarrow \infty.
		\end{aligned}
	\end{equation}

	We obtain from Theorem \ref{expression of solution(linear operator)} that
	\begin{equation}
		\label{U UT expression}
		\begin{aligned}
			U(t)U(t)^\top  
			=& \exp (-\mathcal{H} t) U_0 \left[I_N -U_0^\top U_0  + U_0^\top\exp (-2 \mathcal{H} t) U_0 \right]^{-1 }U_0^\top \exp (-\mathcal{H} t).
		\end{aligned}
	\end{equation} 
	Moreover, it follows from the proof of Theorem \ref{expression of solution(linear operator)} that for each fixed $t\geqslant0$ we have
	$$
	U(t) \in \bigl(\mathcal{D}(\mathcal{H})\bigr)^N.
	$$
	Hence, the operator $U(t)U(t)^\top$ is well defined as a linear mapping from $\bigl(L^2(\Omega)\bigr)^N$ into $\bigl(\mathcal{D}(\mathcal{H})\bigr)^N$.

	It is clear that $	U(t)U(t)^\top $ has the same nonzero eigenvalues as
	\begin{equation*}
		\begin{aligned}
			&U_0^\top \exp (-2\mathcal{H} t) U_0 \left[I_N -U_0^\top U_0  + U_0^\top\exp (-2 \mathcal{H} t) U_0 \right]^{-1 }
			\\=&\left[\left(I_N -U_0^\top U_0\right)\left(U_0^\top \exp (-2 \mathcal{H} t) U_0\right)^{-1} +I_N \right]^{-1},
		\end{aligned}
	\end{equation*}
	which approaches to $I_N$ as $t\rightarrow \infty$ since the result $\lim\limits_{t\rightarrow\infty} \left(U_0^\top \exp (-2 \mathcal{H} t) U_0\right)^{-1} = 0$ indicated in (\ref{inverse of U0exp(-Ht)U0 goes to 0}).

	As a consequence, there exist $N$ nonzero eigenvalues of $U(t)U(t)^\top$ that approach 1, and thus $U(t)^\top U(t)$ also has $N$ nonzero eigenvalues that approach 1.

	Let $\{\eta_i(t)\}_{i =1}^N $  be the eigenvalues of $\left(I_N -U_0^\top U_0\right)\left(U_0^\top \exp (-2 \mathcal{H} t) U_0\right)^{-1} $, then the nonzero eigenvalues $\{\tilde{\sigma}_i(t)\}_{i =1}^N $ of $U(t)U(t)^\top $ can be written as 
	$$\tilde{\sigma}_i(t) = \left(\eta_i(t)+1\right)^{-1}, i =1, 2, \cdots, N.$$

	Note that $ \left(U_0^\top \exp (-2 \mathcal{H} t) U_0\right)^{-1}$ is monotonically decreasing with respect to $t\geqslant 0$.  If $\sigma_i(0) \leqslant 1$ for $1 \leqslant i \leqslant N$, that is $U_0^\top U_0 \leqslant I_N$, then the matrix 
	$$\left(I_N -U_0^\top U_0\right)^{\frac{1}{2}}\left(U_0^\top \exp (-2 \mathcal{H} t) U_0\right)^{-1} \left(I_N -U_0^\top U_0\right)^{\frac{1}{2}}$$
	is positive semidefinite and monotonically nonincreasing with respect to $t\geqslant 0$. Thus $\eta_i(t)\geqslant 0$ and is nonincreasing for $i=1, 2, \cdots,N$.
	Therefore, $0<\tilde{\sigma}_i(t)\leqslant1$ and $\tilde{\sigma}_i(t)$ is nondecreasing, so is $\sigma_i(t)$.
	Similarly, we can prove (3).

	With the condition $\beta = \min\{ 1, \sigma_1(0)\}$, we see that 
	\begin{equation*}
		\begin{aligned}
			&	\left(U_0^\top \exp (-2 \mathcal{H} t) U_0\right)^{-\frac{1}{2}}\left(I_N -U_0^\top U_0\right)\left(U_0^\top \exp (-2 \mathcal{H} t) U_0\right)^{-\frac{1}{2}}
			\\	\leqslant &\left(U_0^\top \exp (-2 \mathcal{H} t) U_0\right)^{-\frac{1}{2}}(I_N - \beta I_N)\left(U_0^\top \exp (-2 \mathcal{H} t) U_0\right)^{-\frac{1}{2}}
			\\ =& (1-\beta)\left(U_0^\top \exp (-2 \mathcal{H} t) U_0\right)^{-1} \leqslant (1-\beta)(U_0^\top U_0)^{-1}
			\leqslant (\frac{1}{\beta}-1)I_N,
		\end{aligned}
	\end{equation*}
	and thus $\eta_i(t)\leqslant\frac{1}{\beta}-1$, which indicates that $\sigma_i(t)\geqslant \beta$. We can then conclude that $\sigma_i(t)\geqslant \beta , \forall  i=1,2, \cdots,N$. The lemma is now fully proved.
\end{proof}


\subsection{Proof of Lemma~\ref{Bound of UHU}}\label{proof of lemma: Bound of UHU}

\begin{proof}
	We see from (\ref{operator of gradient flow based model}) that
	\begin{equation*}
		\begin{aligned}
			\frac{\mathrm{d}    }{\mathrm{d}  t} \left(U(t)\right)^\top \mathcal{H}U(t)
			=& -\left( \nabla_GE(U(t))\right)^\top \mathcal{H}U(t) - \left(U(t)\right)^\top \mathcal{H} \nabla_GE(U(t))
			\\=& -2 \left(U(t) \right)^\top \mathcal{H}^2U(t) +2\left( \left(U(t)\right)^\top \mathcal{H}U(t)\right)^2
			\\ \leqslant &2\left( \left(U(t)\right)^\top \mathcal{H}U(t)\right)^2.
		\end{aligned}
	\end{equation*}
	Similar to the proof of Lemma \ref{lemma: UHU<0}, under the initial condition $U_0^\top\mathcal{H}U_0<0$, we have $ \left(U(t)\right)^\top \mathcal{H}U(t)<0$ for all $t\geqslant0$.	

	Since Lemma \ref{singular values of soltion} implies that 
	\begin{equation*}
		\begin{aligned}
			U(t)^\top U(t) \geqslant \beta I_N, \quad \forall t\geqslant0,
		\end{aligned}
	\end{equation*}
	we have
	\begin{equation*}
		\begin{aligned}
			U(t)^\top \mathcal{H}U(t)  = &	U(t)^\top \left(\mathcal{P}_{\operatorname{span}\{U(t)\}}\mathcal{H}	\mathcal{P}_{\operatorname{span}\{U(t)\}}\right)U(t)
			\\ \leqslant& \lambda_{\max}\left\{\mathcal{P}_{\operatorname{span}\{U(t)\}}\mathcal{H}	\mathcal{P}_{\operatorname{span}\{U(t)\}}\right\} U(t)^\top U(t)
			\\\leqslant & \lambda_{\max}\left\{\mathcal{P}_{\operatorname{span}\{U(t)\}} \mathcal{H}\mathcal{P}_{\operatorname{span}\{U(t)\}}\right\}\beta I_N,
		\end{aligned}
	\end{equation*}
	where $	\mathcal{P}_{\operatorname{span}\{U(t)\}}$ is the orthogonal projection onto the subspace $\operatorname{span}\{U(t)\}$.
	We see that $	\mathcal{P}_{\operatorname{span}\{U(t)\}}\mathcal{H} 	\mathcal{P}_{\operatorname{span}\{U(t)\}}$ has the same nonzero (negative) eigenvalues as 
	\begin{equation*}
		\begin{aligned}
			\mathcal{P}_{\operatorname{span}\{U(t)\}}^2\mathcal{H}=&	\mathcal{P}_{\operatorname{span}\{U(t)\}}\mathcal{H} 
			\\=  &U(t)  \left( U(t)^\top  U(t)  \right)^{-1}  U(t)^\top \mathcal{H} 
			\\=&\exp\left(-\mathcal{H}t\right)U_0 \left[U_0^\top \exp\left(-2\mathcal{H}t\right)U_0 \right]^{-1} U_0^\top \exp\left(-2\mathcal{H}t\right)\mathcal{H}.
		\end{aligned}
	\end{equation*}
	Similarly, $	\mathcal{P}_{\operatorname{span}\{U(t)\}}\mathcal{H} $ has the same nonzero (negative) eigenvalues as 
	\begin{equation*}
		\begin{aligned}
			U_0^\top \exp\left(-2\mathcal{H}t\right)\mathcal{H}U_0 \cdot \left(	U_0^\top \exp\left(-2\mathcal{H}t\right)U_0\right)^{-1}.
		\end{aligned}
	\end{equation*}
	Consider the Rayleigh quotient of the above matrix, we get that
	\begin{equation*}
		\begin{aligned}
			R(t,a) = \frac{a^\top U_0^\top \exp\left(-2\mathcal{H}t\right)\mathcal{H}U_0a }{a^\top U_0^\top \exp\left(-2\mathcal{H}t\right)U_0a}, \quad \forall a\in \mathbb{R}^N\backslash\{0\}.
		\end{aligned}
	\end{equation*}
	Denote $v = U_0a$, then 
	\begin{equation*}
		\begin{aligned}
			R(t,a)  = \frac{v^\top \exp\left(-2\mathcal{H}t\right)\mathcal{H}v}{v^\top \exp\left(-2\mathcal{H}t\right)v}  \stackrel{\Delta}{=} R(t,v),
		\end{aligned}
	\end{equation*}
	which is equivalent to 
	\begin{equation*}
		\begin{aligned}
			R(t,v)=\frac{v^\top \exp\left(-2\mathcal{H}t\right)\mathcal{H}v}{v^\top \exp\left(-2\mathcal{H}t\right)v}, \text{ where } v\in \left\{v\in \operatorname{span}\left\{U_0\right\}:\|v\| = 1\right\}.
		\end{aligned}
	\end{equation*}

	For any $v\in  \left\{v\in \operatorname{span}\left\{U_0\right\}:\|v\| = 1\right\}$, there exists a sequence $\left\{\alpha_j\right\}_{j=1}^{\infty}$ such that $v = \sum_{j=1}^{\infty}\alpha_j v_j$ and $\sum_{j=1}^{\infty}\alpha_j ^2 = 1$. Therefore, we can rewrite $R(t,v)$ as
	\begin{equation*}
		\begin{aligned}
			R(t,v) = \frac{\sum_{j=1}^{\infty}\lambda_j \exp(-2\lambda_j t)\alpha_j ^2}{\sum_{j=1}^{\infty} \exp(-2\lambda_j t)\alpha_j ^2}.   
		\end{aligned}
	\end{equation*}

	Denote the index set $\mathrm{I}(v) = \left\{j\in \mathbb{N}_{+}: \alpha_j \neq 0\text{ and } \lambda_j<0\right\}$. Since $v^\top \mathcal{H}v<0, \forall v\in \operatorname{span}\{U_0\}$, $\mathrm{I}(v)$ is not empty. Let $|\lambda_{j^*}| = \max\left\{|\lambda_j|: j\in \mathrm{I}(v)\right\}$, and denote $\mathrm{I}_{\max} = \left\{ j: \lambda_j = \lambda_{j^*}\text{ and } \alpha_j \neq0\right\}$, then
	\begin{equation*}
		\begin{aligned}
			R(t,v) = \frac{ \sum_{j\in \mathrm{I}_{\max}}\lambda_j \alpha_j^2 +\sum_{j\notin \mathrm{I}_{\max}}\lambda_j \exp\left(-2\left(\lambda_j+|\lambda_{j^*}|\right) t\right)\alpha_j ^2}{ \sum_{j\in \mathrm{I}_{\max}} \alpha_j^2 +\sum_{j\notin \mathrm{I}_{\max}} \exp\left(-2\left(\lambda_j+|\lambda_{j^*}|\right) t\right)\alpha_j ^2},
		\end{aligned}
	\end{equation*}
	and thus
	\begin{equation*}
		\begin{aligned}
			\lim\limits_{t\rightarrow\infty}R(t,v)  = \lambda_{j^*}.
		\end{aligned}
	\end{equation*}

	Due to the continuity of the linear operator $\mathcal{H}$ in the finite dimensional space $\operatorname{span}\left\{U_0\right\}$, there exists a $T_{*}>0$ such that for all $t\geqslant T_{*}$
	\begin{equation*}
		\begin{aligned}
			R(t,v)\leqslant -\frac{ |\lambda_{j^*}|}{2}, \quad \forall v\in  \left\{v\in \operatorname{span}\left\{U_0\right\}:\|v\| = 1\right\}
		\end{aligned}
	\end{equation*}

	For the fixed time interval $[0, T_{*}]$, since $[0, T_{*}]\times   \left\{v\in \operatorname{span}\left\{U_0\right\}:\|v\| = 1\right\}$ is compact set, the continuous function $R(t,v)$ has a maximum value, denote as
	\begin{equation*}
		\begin{aligned}
			C_{*} = \max_{\substack{  t\in [0, T_{*}], \\v\in  \left\{v\in \operatorname{span}\left\{U_0\right\}:\|v\| = 1\right\}}} R(t,v) <0.
		\end{aligned}
	\end{equation*}

	Then we arrive at
	\begin{equation*}
		\begin{aligned}
			R(t,v) \leqslant \max\left\{C_{*},-\frac{ |\lambda_{j^*}|}{2}\right\}, \quad \forall t\geqslant0, v\in  \left\{v\in \operatorname{span}\left\{U_0\right\}:\|v\| = 1\right\},
		\end{aligned}
	\end{equation*}
	which leads to, 
	\begin{equation*}
		\begin{aligned}
			\lambda_{\max}\left\{\mathcal{P}_{\operatorname{span}\{U(t)\}} \mathcal{H} 	\mathcal{P}_{\operatorname{span}}\right\}
			\leqslant & \max\limits_{a\in \mathbb{R}^N \backslash \{0\} } R(t,a)  
			\\=& \max\limits_{v\in  \left\{v\in \operatorname{span}\left\{U_0\right\}:\|v\| = 1\right\}} R(t,v) 
			\\ \leqslant & \max\left\{C_{*},-\frac{ |\lambda_{j^*}|}{2}\right\}.
		\end{aligned}
	\end{equation*}

	Denote $c_0 =-\beta \max\left\{C_{*},-\frac{ |\lambda_{j^*}|}{2}\right\}$, we come to the conclusion that
	\begin{equation*}
		\begin{aligned}
			U(t)^\top \mathcal{H}U(t)   \leqslant -c_0 I_N.
		\end{aligned}
	\end{equation*}
	where $c_0$ only depends on the initial value $U_0$.
\end{proof}

\subsection{Proof of Lemma~\ref	{converge to operator equation}}\label{proof of lemma: converge to operator equation}

\begin{proof}
	Similar with the proof in \ref{proof of lemma: expression of Glaerkin solution}, we have $U_0 = \sum\limits_{i=1}^{\infty} \sum\limits_{p=1}^N \alpha_{ip}^{(0)}(t) V_{ip} $. Thus, for any $k\geqslant0$, we have
	\begin{equation*}
		\begin{aligned}
			&	\exp(-k\mathcal{H}t ) U_0= \sum\limits_{i=1}^{\infty}\sum\limits_{p=1}^N  \alpha_{ip}^{(0)} \exp( -k\lambda_i t) V_{ip}, 
			\\&U_0^\top U_0 =  \sum\limits_{i=1}^{\infty} \sum\limits_{p=1}^N \left(  \alpha_{ip}^{(0)}\right)^2 V_{ip}^\top  V_{ip}.
		\end{aligned}
	\end{equation*}
	We see from (\ref{U UT expression}) that
	\begin{equation*}
		\begin{aligned}
			\mathcal{Z}(t)
			=& \exp (-\mathcal{H} t) U_0 \left[I_N -U_0^\top U_0  + U_0^\top\exp (-2 \mathcal{H} t) U_0 \right]^{-1 }U_0^\top \exp (-\mathcal{H} t).
		\end{aligned}
	\end{equation*} 
	Therefore, we can rewrite $\mathcal{Z}(t)$ as
	\begin{equation*}
		\label{element expression}
		\begin{aligned}
			\sum\limits_{j=1}^{\infty}	\sum\limits_{k=1}^{\infty}	\sum\limits_{p=1}^N 	\alpha_{jkp}(t)  V_{jp} V_{kp}^\top,
		\end{aligned}
	\end{equation*} 
	where $\alpha_{jkp}(t)$ ($\forall j,k =1, 2,\cdots$ and $p = 1, 2, \cdots, N$) has the form $\frac{\sum_{i=1}^{\infty} a_i \exp \left(\gamma_i  t\right)}{\sum_{i=1}^{\infty} b_i \exp \left(\beta_i t\right)}$, and $\gamma_1 \geqslant\gamma_2\geqslant\cdots \geqslant 0, \beta_1 \geqslant\beta_2 \geqslant\cdots \geqslant 0$, $a_1, b_1 \neq 0$. 

	Note that $U(t)$ is bounded for $t\geqslant 0$, all the elements $\alpha_{jkp}(t)$ of $\mathcal{Z}(t)$ are also bounded, which indicates that $\gamma_1 \leqslant \beta_1$ for all $j, k =1, 2, \cdots$.

	It follows that $\mathcal{Z}(t)$ exponentially converges as $t\rightarrow \infty$, which indicates 
	\begin{equation*}
		\begin{aligned}
			0 =  \lim\limits_{t\rightarrow\infty} \frac{\mathrm{d}    }{\mathrm{d}  t} \mathcal{Z}(t)= -  \lim\limits_{t\rightarrow\infty}\left( \mathcal{H}\mathcal{Z}(t) +\mathcal{Z}(t)\mathcal{H} - 2\mathcal{Z}(t) \mathcal{H}\mathcal{Z}(t) \right).
		\end{aligned}
	\end{equation*}
	Denote $ \lim\limits_{t\rightarrow \infty}\mathcal{Z}(t) = \mathcal{Z}_{\infty}$, then $ \mathcal{Z}_{\infty}$ is the solution to the following equation
	\begin{equation*}
		\begin{aligned}
			\mathcal{H} \mathcal{Z}_{\infty}+\mathcal{Z}_{\infty}\mathcal{H} = 2\mathcal{Z}_{\infty} \mathcal{H} \mathcal{Z}_{\infty}.
		\end{aligned}
	\end{equation*}
	Since all the nonzero eigenvalues of $\lim\limits_{t\rightarrow \infty}\mathcal{Z}(t) $ are equal to 1, we obtain
	$$\lim\limits_{t\rightarrow \infty}\mathcal{Z}^2(t) = \lim\limits_{t\rightarrow \infty}\mathcal{Z}(t),$$
	thus, $ \mathcal{Z}_{\infty}$ also satisfies
	\begin{equation*}
		\begin{aligned}
			\mathcal{Z}_{\infty}^2  = \mathcal{Z}_{\infty}.
		\end{aligned}
	\end{equation*}
	This completes the proof.
\end{proof}

\subsection{Proof of Lemma~\ref{meaning of initial condition}}\label{proof of lemma: meaning of initial condition} 

\begin{proof}
	For $U \in B([V^{(*)}], \delta)$, there exists a $\tilde{U} \in [V^{(*)}]$, such that $\|\tilde{U}-V^{(*)}\|_1 = \operatorname{dist}_{H_0^1}([U], [V^{(*)}])\leqslant \delta$. For simplicity, we still use $U$ to denote $\tilde{U} $. 
	Since 
	\begin{equation*}
		\begin{aligned}
			\delta\geqslant \|U - V^{(*)}\|_1 =\left(  \sum_{j=1}^N \|u_j - v_j\|_1^2 \right)^{\frac{1}{2}} \geqslant \| u_{j}- v_{j}\| ,\quad \forall j = 1,2 ,\cdots, N,
		\end{aligned}
	\end{equation*} 
	and there exists a series of constants $\{ \alpha_{kj}\}_{k=1}^{\infty}$, such that $u_{j}  = \sum\limits_{k=1}^{\infty} \alpha_{kj}v_k, \forall j = 1,2 ,\cdots, N$, we have
	\begin{equation*}
		\begin{aligned}
			\delta\geqslant \left\|  \sum\limits_{k=1}^{\infty} \alpha_{kj}v_k- v_{j}  \right\| = \left(\sum\limits_{k=1, k\neq j}^{\infty} \alpha_{kj}^2 +(\alpha_{jj}-1)^2 \right)^{\frac{1}{2}}.
		\end{aligned}
	\end{equation*}
	It implies that $0<1-\delta\leqslant \alpha_{jj}\leqslant 1+\delta$, $\forall j = 1,2 ,\cdots, N$. This means that $U$ contains the component of all the eigenvectors corresponding to the $N$ smallest eigenvalues, thereby establishing the result.
\end{proof}



