\section{Collection of frequently used bounds}

The first two results are a Poincaré inequality and a trace inequality, both stated with explicit constants.
\begin{lemma}[Poincare inequality]\label{lem:poincare}
		For all $T \in \mathcal T_h$ and any $v\in H^1(T)$ with $\int_T v\dx=0$, it holds that
	\begin{equation*}
		\|v\|_{L^2(T)} \leq \pi^{-1}h_T \|\nabla v\|_{L^2(T)}
	\end{equation*}
	with $\pi>0$ denoting the circle constant.
\end{lemma}
\begin{proof}
The proof can be found, for example, in~\cite{Bebendorf2003}.
\end{proof}
\begin{lemma}[Trace inequality]\label{lem:trace_theo}
	For all $T \in \mathcal T_h$ and any $v\in H^1(T)$ satisfying ${\int_T v\dx=0}$, it holds that
	\begin{equation*}
		\sum_{F \in \mathcal F_{\partial T}}\ell_{T,F}^{-1}\|u\|_{L^2({F})}^2 \leq C_{\mathrm{tr}} \|\nabla u\|_{L^2(T)}^2
	\end{equation*}
	with the constant $C_{\mathrm{tr}} = 1/\pi^2+2/(d\pi)>0$.
\end{lemma}
\begin{proof}
The result and its corresponding proof can be found in \cite[Lem.~3.1]{Tran2024}, which, in turn, is based on \cite[Lem.~7.2]{Gal23}.
\end{proof}

Next, we present several results relevant to the analysis of the HHO method.

\begin{lemma}[Discrete Sobolev embeddings]\label{prop:discrete:sobolev:embed}
	Let $d \in \{2,3\}$ and $q$ satisfy $1 \leq q < \infty$ if $d=2$, and $1 \leq q \leq 6$ if $d=3$. Then, for all $\hat{v}_h = (v_{\mathcal{T}_h}, v_{\mathcal{F}_h}) \in \hat{U}_h$, it holds~that
	\[
	\|v_{\mathcal{T}_h}\|_{L^q} \lesssim \|\hat{v}_h\|_{a_h}
	\]
	with hidden constant depending only on the domain, mesh regularity, $q$, $k$, and~$\sigma$.
\end{lemma}

\begin{proof}
	The proof of this result can be deduced by combining \cite[Prop.~5.4]{Pietro2017} and \cite[Lem.~2.18]{Pietro2020}.
\end{proof}
\begin{lemma}[Moment-preserving smoothing operator]\label{prop:prese_inter}
	There exists a linear operator $\mathcal{J}_h  \colon \allowbreak \hat{U}_h \to H_0^1(\Omega)$ satisfying, for all $\hat{v}_h \in \hat{U}_h$, that
	\begin{equation*}
		\mathcal I_h\circ \mathcal J_h\hat{v}_h = \hat{v}_h,
	\end{equation*}
	which implies the following orthogonality relations:
	\[
	v_{\mathcal{T}_h} - \mathcal{J}_h \hat{v}_h \perp_{L^2} \mathcal{P}^{k+1}(\mathcal{T}_h), 
	\quad 
	\nabla_h(\mathcal{J}_h \hat{v}_h - \mathcal{R}_h \hat{v}_h) \perp_{L^2} \nabla_h \mathcal{P}^{k+1}(\mathcal{T}_h).
	\]
Moreover, the operator satisfies, for all $ \hat v_h \in \hat U_h$, the stability estimate
	\begin{equation*}
		\|\mathcal J_h\hat{v}_h\|_{H^1}\lesssim \|\hat{v}_h\|_{a_h},
	\end{equation*}
	and, for any $v \in H^2(\Omega)\cap H^1_0(\Omega)$, the following approximation properties hold:
	\begin{equation*}
		\|\nabla(\mathcal J_h\mathcal I_hv-v)\|_{L^2}\lesssim h \|v\|_{H^2},\quad \|\mathcal J_h\mathcal I_hv-v\|_{L^2}\lesssim h^2 \|v\|_{H^2},
	\end{equation*}
	where hidden constants depend only on the domain, mesh regularity, $k$, and~$\sigma$.
\end{lemma}

\begin{proof}
	For the construction of such an operator and the corresponding analysis, we refer, for example, to 	\cite[Sec.~4.3]{ErnZanotti2020}. The proof of the stability and approximation properties uses similar arguments as \cite[Lem. 3.5]{LiangNgoc2025}.
\end{proof}

\begin{lemma}[Discrete $L^{\infty}$-bound]\label{lem:linf_bound}
	Assume that $V \in H^1(\mathcal T_h)$. Then, for any discrete ground state $\hat{u}_h = (u_{\mathcal{T}_h}, u_{\mathcal{F}_h})$ of \cref{eq:hhoapprox}, both $\|\mathcal{J}_h \hat{u}_h\|_{L^\infty}$ and $\|u_{\mathcal{T}_h}\|_{L^\infty}$ are uniformly bounded. 
	%
	The same holds for the modified HHO approximation $\hat{u}_h^0 = (u_{\mathcal{T}_h}^0, u_{\mathcal{F}_h}^0)$ of \cref{eq:hhoapprox0} and its smoothed version $\mathcal{J}_h \hat{u}_h^0$.
\end{lemma}

\begin{proof}
	We proceed as in the proof of \cref{theo:plain_conver}, observing that \(\hat{u}_h\) can be interpreted as the HHO approximation of the solution \(u_h^c \in H^2(\Omega) \cap H_0^1(\Omega)\) to the auxiliary Poisson problem \cref{eq:ustar}. Recall that the \(H^2\)-norm of \(u_h^c\) is uniformly bounded.  
The improved \(L^2\)-error estimate for the HHO method, as established for example in \cite[Thm.~2.32 \&~2.33]{Pietro2020}, then implies that
	\begin{equation*}
		\|\mathcal{R}_h\hat{u}_h-u_h^c\|_{L^2} + \|\Pi_{\mathcal{T}_h}^{k+1}u_h^c - u_{\mathcal{T}_h}\|_{L^2}\lesssim h^2.
	\end{equation*}
Using a comparison between the discrete \( L^2 \)- and \( L^\infty \)-norms, the stability of the \( L^2 \)-projection, and the uniform \( L^\infty \)-bound for \( u_h^c \), we obtain for any \( T \in \mathcal{T}_h \) that
	\begin{align*}
		\|u_{\mathcal{T}_h}\|_{L^{\infty}(T)} &\leq \|\Pi_{\mathcal{T}_h}^{k+1}u_h^c - u_{\mathcal{T}_h}\|_{L^{\infty}(T)} + \|\Pi_{\mathcal{T}_h}^{k+1}u_h^c\|_{L^{\infty}(T)}\\
		&\lesssim h_T^{-d/2}\|\Pi_{\mathcal{T}_h}^{k+1}u_h^c - u_{\mathcal{T}_h}\|_{L^2(T)} + h_T^{-d/2}\|u_h^c\|_{L^{2}(T)}\\ &\lesssim h_T^{(4-d)/2} + \|u_h^c\|_{L^{\infty}(T)}\lesssim 1.
	\end{align*}
	Similarly arguments also show that  $\mathcal{R}_h\hat{u}_h$ is uniformly $L^{\infty}$-bounded.

Next, we show that $\mathcal J_h \hat{u}_h$ is uniformly $L^{\infty}$-bounded. Using again the comparison result between discrete norms, we obtain for any \(T \in \mathcal{T}_h\) that
	\begin{align*}
		\|\mathcal J_h\hat{u}_h\|_{L^{\infty}(T)} & \lesssim h_T^{-d/2} \|\mathcal J_h\hat{u}_h\|_{L^{2}(T)}\\
		&\lesssim h_T^{-d/2} \sum_{T'\cap T\neq \emptyset} \Big\{\|\mathcal{R}_h\hat{u}_h \|_{L^2(T')} + \|\mathcal{R}_h\hat{u}_h-u_{\mathcal{T}_h} \|_{L^2(T')} \\[-1.5ex]
		 & \ \ \ \ \ \ \ \qquad \quad \qquad \ \ +\sum_{F\in\mathcal{F}_{\partial T'}}h_F^{1/2}\|\Pi_{F}^k(\mathcal{R}_h\hat{u}_h-u_{\mathcal{F}_h})\|_{L^2(F)}\Big\}\\
		&\lesssim \|\mathcal{R}_h\hat{u}_h \|_{L^{\infty}} + \|\mathcal{R}_h\hat{u}_h-u_{\mathcal{T}_h} \|_{L^{\infty}} + h^{-(d-2)/2}|\hat{u}_h|_{s_h} \lesssim 1,
	\end{align*}
	where the second inequality follows from the specific construction of \( \mathcal{J}_h \) in \cite[Sec.~4.3]{ErnZanotti2020}, and arguments similar to those in \cite[Lem.~3.5]{LiangNgoc2025}. To derive the last inequality, we use that \( |\hat{u}_h|_{s_h} \lesssim h \|u_h^c\|_{H^2} \) (see \cref{theo:err_est} or \cite[Thm.~2.28]{Pietro2020}). This leads the uniform \( L^{\infty} \)-bound for \( \mathcal{J}_h \hat{u}_h \). The corresponding proof for the modified HHO approximation \( \hat{u}_h^0 \) is analogous and is therefore omitted for brevity.
\end{proof}

\begin{proposition}\label{eq:JhIh_linf}
For any \(v \in H^2(\Omega) \cap H_0^1(\Omega)\), it holds that
	\begin{align*}
		\|\mathcal J_h\mathcal{I}_hv\|_{L^{\infty}} 
		\lesssim \|\mathcal{R}_h\mathcal{I}_hv \|_{L^{\infty}} + \|\mathcal{R}_h\mathcal{I}_hv-\Pi_{\mathcal{T}_h}^{k+1}v \|_{L^{\infty}} + h^{-(d-2)/2}|\mathcal{I}_hv|_{s_h} \lesssim \|v\|_{H^2}.
	\end{align*}
\end{proposition}

\begin{lemma}[Quadrature error]\label{lem:modi_1}
For any \(\hat{v}_h = (v_{\mathcal{T}_h}, v_{\mathcal{F}_h})\), \(\hat{w}_h = (w_{\mathcal{T}_h}, w_{\mathcal{F}_h}) \in \hat{U}_h\), we have the following two estimates:
	\begin{align}\label{eq:quaderror1}
		\begin{split}
				&|((\Pi_{\mathcal{T}_h}^0{v}_{\mathcal{T}_h})^2 -v_{\mathcal{T}_h}^2 , v_{\mathcal{T}_h}w_{\mathcal{T}_h})_{L^2}|\\&\; \lesssim  h^2\|v_{\mathcal{T}_h}\|_{L^{\infty}}\|\nabla \mathcal J_h\hat{v}_h\|_{L^2} \big(\|v_{\mathcal{T}_h}\|_{L^{\infty}}\|\nabla \mathcal J_h\hat{w}_h\|_{L^2} + \|\nabla \mathcal J_h\hat{v}_h\|_{L^{2}}\|\mathcal J_h\hat{w}_h\|_{L^{\infty}}\\ & \qquad \qquad \quad  \quad  \qquad  \quad  \ \ \ \ + \|\mathcal J_h\hat{v}_h\|_{L^{\infty}}\|\nabla \mathcal J_h\hat{w}_h\|_{L^2}+ \|w_{\mathcal{T}_h}\|_{L^{\infty}}\|\nabla \mathcal J_h\hat{v}_h\|_{L^2}\big),
		\end{split}
	\end{align}\vspace{-.5ex}
		\begin{align}\label{eq:quaderror2}
			\begin{split}
					&| ( v_{\mathcal{T}_h}^2, v_{\mathcal{T}_h}w_{\mathcal{T}_h}- \Pi_{\mathcal{T}_h}^0v_{\mathcal{T}_h} \Pi_{\mathcal{T}_h}^0w_{\mathcal{T}_h})_{L^2}|\\
				&\quad \lesssim h^2\big(\|v_{\mathcal{T}_h}\|_{L^{\infty}}\|\nabla \mathcal J_h\hat{v}_h\|_{L^2}+\|\mathcal J_h\hat{v}_h\|_{L^{\infty}}\|\nabla \mathcal J_h\hat{v}_h\|_{L^2} \big)\\
				&\qquad \quad \qquad \times \big(\|v_{\mathcal{T}_h}\|_{L^{\infty}}\|\nabla \mathcal J_h\hat{w}_h\|_{L^2} 
				+ \|w_{\mathcal{T}_h}\|_{L^{\infty}}\|\nabla \mathcal J_h\hat{v}_h\|_{L^2}\big),
			\end{split}
	\end{align}
	where hidden constants depend only on the domain, mesh regularity, $k$, and~$\sigma$.
\end{lemma}
\begin{proof}
	We begin the proof by establishing three auxiliary estimates that will be used later. The first one, which holds for any \( \hat{v}_h = (v_{\mathcal{T}_h}, v_{\mathcal{F}_h}) \in \hat{U}_h \), reads
	\begin{align}\label{eq:appendix:auxi_1}
		\|v_{\mathcal{T}_h} - \Pi_{\mathcal{T}_h}^0 v_{\mathcal{T}_h}\|_{L^2} 
		&\leq \|v_{\mathcal{T}_h} - \mathcal{J}_h \hat{v}_h\|_{L^2} + \|\mathcal{J}_h \hat{v}_h - \Pi_{\mathcal{T}_h}^0 v_{\mathcal{T}_h}\|_{L^2} \lesssim h \|\nabla \mathcal{J}_h \hat{v}_h\|_{L^2}.
	\end{align}
This follows from \( \Pi_{\mathcal{T}_h}^{k+1} \mathcal{J}_h \hat{v}_h = v_{\mathcal{T}_h} \) and the approximation properties of the $L^2$-projection.
%
To derive the second estimate, we apply the triangle inequality along with the first estimate, which gives, for any \( \hat{v}_h, \hat{w}_h \in \hat{U}_h \), that
	\begin{equation}\label{eq:appendix:auxi_2}
		\begin{aligned}
			\|v_{\mathcal{T}_h}w_{\mathcal{T}_h}-\mathcal J_h\hat{v}_h\mathcal J_h\hat{w}_h\|_{L^2}&\leq \|v_{\mathcal{T}_h}w_{\mathcal{T}_h}-v_{\mathcal{T}_h} \mathcal J_h\hat{w}_h\|_{L^2} + \|v_{\mathcal{T}_h} \mathcal J_h\hat{w}_h-\mathcal J_h\hat{v}_h\mathcal J_h\hat{w}_h\|_{L^2}\\
			&\lesssim h\|v_{\mathcal{T}_h}\|_{L^{\infty}}\|\nabla\mathcal J_h\hat{w}_h\|_{L^2} + h\|\mathcal J_h\hat{w}_h\|_{L^{\infty}}\|\nabla\mathcal J_h\hat{v}_h\|_{L^2}.
		\end{aligned}
	\end{equation}
To prove the third estimate, we use the triangle inequality, the approximation properties of the \( L^2 \)-projection, and the product rule, which yields that
	\begin{equation}\label{eq:appendix:auxi_3}
		\begin{aligned}
			&\|v_{\mathcal{T}_h}w_{\mathcal{T}_h}- \Pi_{\mathcal{T}_h}^0(v_{\mathcal{T}_h}w_{\mathcal{T}_h})\|_{L^2}\\
			 &\quad \leq \|v_{\mathcal{T}_h}w_{\mathcal{T}_h}-\mathcal J_h\hat{v}_h\mathcal J_h\hat{w}_h\|_{L^2}  + \|\mathcal J_h\hat{v}_h\mathcal J_h\hat{w}_h -\Pi_{\mathcal{T}_h}^0(\mathcal J_h\hat{v}_h\mathcal J_h\hat{w}_h)\|_{L^2}\\ & \ \ \ \ \ \quad \quad   + \|\Pi_{\mathcal{T}_h}^0(v_{\mathcal{T}_h}w_{\mathcal{T}_h})-\Pi_{\mathcal{T}_h}^0(\mathcal J_h\hat{v}_h\mathcal J_h\hat{w}_h)\|_{L^2}\\
			&\quad \lesssim h\big(\|v_{\mathcal{T}_h}\|_{L^{\infty}}\|\nabla \mathcal J_h\hat{w}_h\|_{L^2} + \|\nabla \mathcal J_h\hat{v}_h\|_{L^{2}}\|\mathcal J_h\hat{w}_h\|_{L^{\infty}}
			%\\ & \ \ \ \ \ 
			+ \|\mathcal J_h\hat{v}_h\|_{L^{\infty}}\|\nabla \mathcal J_h\hat{w}_h\|_{L^2}\big).
		\end{aligned}
	\end{equation}
We now have the tools to prove \cref{eq:quaderror1}. Applying the triangle inequality yields
	\begin{multline*}
		|((\Pi_{\mathcal{T}_h}^0{v}_{\mathcal{T}_h})^2 -v_{\mathcal{T}_h}^2 , v_{\mathcal{T}_h}w_{\mathcal{T}_h})_{L^2}|  \leq \underbrace{|((\Pi_{\mathcal{T}_h}^0{v}_{\mathcal{T}_h})^2 -v_{\mathcal{T}_h}^2 , \Pi_{\mathcal{T}_h}^0(v_{\mathcal{T}_h}w_{\mathcal{T}_h}))_{L^2}|}_{\eqqcolon \Xi_1}\\+ 
		\underbrace{|((\Pi_{\mathcal{T}_h}^0{v}_{\mathcal{T}_h})^2 -v_{\mathcal{T}_h}^2 , v_{\mathcal{T}_h}w_{\mathcal{T}_h}-\Pi_{\mathcal{T}_h}^0(v_{\mathcal{T}_h}w_{\mathcal{T}_h}) )_{L^2}|}_{\eqqcolon \Xi_2},
%		\\		& = \Xi_1+\Xi_2
	\end{multline*}
	where the term $\Xi_1$ can be estimated as
	\begin{align}\label{eq:xi1}
		\Xi_1 & \leq \sum_{T \in \mathcal{T}_h}|\Pi_{T}^0(v_{T}w_{T})|\int_{T}(v_T-\Pi_{T}^0{v}_{T})^2\mathrm{d}x
%		&\leq C\|v_{\mathcal{T}_h} - \Pi_{\mathcal{T}_h}^0{v}_{\mathcal{T}_h}\|_{L^2}^2\|v_{\mathcal{T}_h}\|_{L^{\infty}}\|w_{\mathcal{T}_h}\|_{L^{\infty}}
		 \lesssim h^2\|v_{\mathcal{T}_h}\|_{L^{\infty}}\|w_{\mathcal{T}_h}\|_{L^{\infty}}\|\nabla \mathcal J_h\hat{v}_h\|_{L^2}^2.
	\end{align}
Here, the first inequality follows from elementary algebraic manipulations, using \( \Pi_T^0 v = |T|^{-1} \int_T v \, \mathrm{d}x \), while the second follows from \( \|\Pi_T^0 v\|_{L^\infty(T)} \leq \|v\|_{L^\infty(T)} \) and~\cref{eq:appendix:auxi_1}. The term $\Xi_2$ can be estimated as
	\begin{align*}
		\Xi_2 &\lesssim h\|v_{\mathcal{T}_h}\|_{L^{\infty}}\|\nabla \mathcal J_h\hat{v}_h\|_{L^2}\|v_{\mathcal{T}_h}w_{\mathcal{T}_h}- \Pi_{\mathcal{T}_h}^0(v_{\mathcal{T}_h}w_{\mathcal{T}_h})\|_{L^2},
%		&\leq Ch^2\|v_{\mathcal{T}_h}\|_{L^{\infty}}\|\nabla \mathcal J_h\hat{v}_h\|_{L^2} (\|v_{\mathcal{T}_h}\|_{L^{\infty}}\|\nabla \mathcal J_h\hat{w}_h\|_{L^2} + \|\nabla \mathcal J_h\hat{v}_h\|_{L^{2}}\|\mathcal J_h\hat{w}_h\|_{L^{\infty}}\\ & \ \ \ \ \ + \|\mathcal J_h\hat{v}_h\|_{L^{\infty}}\|\nabla \mathcal J_h\hat{w}_h\|_{L^2})
	\end{align*}
	where we again use the $L^{\infty}$-bound of $\Pi_T^0$ and \cref{eq:appendix:auxi_1}. Applying \cref{eq:appendix:auxi_3} to estimate the last term on the right-hand side yields the desired bound for \(\Xi_2\). Combining the previous estimates then establishes \cref{eq:quaderror1}.

Next, we prove estimate \cref{eq:quaderror2}. Applying the triangle inequality, we obtain that
\begin{multline*}
	| ( v_{\mathcal{T}_h}^2, v_{\mathcal{T}_h}w_{\mathcal{T}_h}- \Pi_{\mathcal{T}_h}^0v_{\mathcal{T}_h} \Pi_{\mathcal{T}_h}^0w_{\mathcal{T}_h})_{L^2}|  \leq 
	\underbrace{| ( \Pi_{\mathcal{T}_h}^0(v_{\mathcal{T}_h}^2), v_{\mathcal{T}_h}w_{\mathcal{T}_h}- \Pi_{\mathcal{T}_h}^0v_{\mathcal{T}_h} \Pi_{\mathcal{T}_h}^0w_{\mathcal{T}_h})_{L^2}|}_{\eqqcolon \xi_1}\\
	+ \underbrace{| ( v_{\mathcal{T}_h}^2 - \Pi_{\mathcal{T}_h}^0(v_{\mathcal{T}_h}^2), v_{\mathcal{T}_h}w_{\mathcal{T}_h}- \Pi_{\mathcal{T}_h}^0v_{\mathcal{T}_h} \Pi_{\mathcal{T}_h}^0w_{\mathcal{T}_h})_{L^2}|}_{\eqqcolon \xi_2}.
\end{multline*}
To estimate the term \(\Xi_1\), we apply algebraic manipulations similar to those in the proof of \cref{eq:xi1}, as well as the \(L^\infty\)-bound of \(\Pi_T^0\) and \cref{eq:appendix:auxi_1}, which gives
\begin{align*}
	\xi_1 &\leq 
%	\sum_{T \in \mathcal{T}_h}|\Pi_{T}^0(v_{T}^2)||\int_{T}v_{T}w_{T}- \Pi_{T}^0v_{T} \Pi_{T}^0w_{T}\mathrm{d}x|\\
%	& = 
	\sum_{T \in \mathcal{T}_h}|\Pi_{T}^0(v_{T}^2)||\int_{T}(v_{T}- \Pi_{T}^0v_{T})(w_{T}- \Pi_{T}^0w_{T}) \mathrm{d}x|\\
	&\lesssim h^2\|v_{\mathcal{T}_h}\|_{L^{\infty}}^2\|\nabla \mathcal J_h\hat{v}_h\|_{L^2}\|\nabla \mathcal J_h\hat{w}_h\|_{L^2}.
\end{align*}
The term \(\xi_2\) can be estimated by applying \cref{eq:appendix:auxi_3} with \(\hat{v}_h = \hat{w}_h\), proceeding similarly to the proof of \cref{eq:appendix:auxi_2}. Combining these estimates yields \cref{eq:quaderror2}.
\end{proof}

