\subsection{Rank \texorpdfstring{$m$}{m} Covariance Matrix Update}
\label{rank_m_update}
Let $\mathbf{X} \in \mathbb{R}^{D\times n}$ be the data set of interest and $\hat{\mathbf{X}} = \begin{bmatrix} \mathbf{X} & \mathbf{C} \end{bmatrix}$ with $\mathbf{C}\in \mathbb{R}^{D\times m}$. The covariance matrix of $\hat{\mathbf{X}}$ is

\begin{align*}
  \cov(\hat{\mathbf{X}}) &= 
  \frac{1}{(n+m-1)}\hat{\mathbf{X}}
  \left(\mathbf{I} - \frac{1}{(n+m)}
  \mathbf{1}_{n+m}\mathbf{1}_{n+m}^\top\right)
  \hat{\mathbf{X}}^\top \\
    &= \frac{1}{(n+m-1)}\begin{bmatrix} \mathbf{X} & \mathbf{C} \end{bmatrix}
    \left(\mathbf{I} - \frac{1}{(n+m)}\mathbf{1}_{n+m}\mathbf{1}_{n+m}^\top\right) \begin{bmatrix} 
    \mathbf{X} & \mathbf{C} \end{bmatrix}^\top 
 \end{align*}
 Multiplying both sides by $(n+m-1)$ for convenience,
 \begin{align*}
    (n+m-1)\cov(\hat{\mathbf{X}}) 
    &=
    \begin{bmatrix} 
    \mathbf{X} & \mathbf{C} 
    \end{bmatrix}
    \begin{bmatrix} 
      \mathbf{X}^\top \\ 
      \mathbf{C}^\top 
    \end{bmatrix} \\ &- 
    \frac{1}{n+m}
    \begin{bmatrix} 
    \mathbf{X} & \mathbf{C} 
    \end{bmatrix}
    \begin{bmatrix}
      \mathbf{1}_n \\
      \mathbf{1}_m
    \end{bmatrix}
    \begin{bmatrix}
      \mathbf{1}_n^\top & 
      \mathbf{1}_m^\top
    \end{bmatrix}
    \begin{bmatrix} 
      \mathbf{X}^\top \\ 
      \mathbf{C}^\top 
    \end{bmatrix} \\
     &=\mathbf{X}\,\mathbf{X}^\top + \mathbf{C}\,\mathbf{C}^\top
     - \frac{1}{n+m}\left( n\,\bar{\mathbf{x}} + m\,\bar{\mathbf{c}} \right) \left( n\,\bar{\mathbf{x}} + m\,\bar{\mathbf{c}} \right)^\top \\
     &= \mathbf{X}\,\mathbf{X}^\top + \mathbf{C}\,\mathbf{C}^\top- 
     \frac{1}{(n+m)}\left(n^2\bar{\mathbf{x}}\,\bar{\mathbf{x}}^\top + n\,m\,\bar{\mathbf{x}}\,\bar{\mathbf{c}}^\top+
     n\,m\,\bar{\mathbf{c}}\,\bar{\mathbf{x}}^\top
     +m^2\bar{\mathbf{c}}\,\bar{\mathbf{c}}^\top\right) 
     \end{align*}
     % Using a similar trick as demonstrated in \cref{sec:proof_rank_one}, 
     \begin{align*}
    \frac{(n+m-1)}{(n-1)}\cov(\hat{\mathbf{X}}) &=  \left(\frac{1}{(n-1)}
    \mathbf{X}\,\mathbf{X}^\top -
    \frac{n}{(n-1)}
    \bar{\mathbf{x}}\,\bar{\mathbf{x}}^\top\right) + 
    \frac{(n+m)\,n}{(n-1)(n+m)}
    \bar{\mathbf{x}}\,\bar{\mathbf{x}}^\top \\
      &\phantom{=} \qquad  -\frac{n^2}{(n-1)(n+m)}
    \bar{\mathbf{x}}\,\bar{\mathbf{x}}^\top + 
     \frac{1}{(n-1)}\mathbf{C}\,\mathbf{C}^\top \\ 
    &\phantom{=} \qquad 
    -\frac{1}{(n+m)(n-1)} \left(n\,m\,\bar{\mathbf{x}}\,\bar{\mathbf{c}}^\top
    +n\,m\,\bar{\mathbf{c}}\,\bar{\mathbf{x}}^\top +m^2\bar{\mathbf{c}}\,\bar{\mathbf{c}}^\top\right). 
\end{align*}
With some algebraic manipulation,
\begin{align*}
  \frac{(n+m-1)}{(n-1)}\cov(\hat{\mathbf{X}})
    &=\cov(\mathbf{X})+\frac{n\,m}{(n-1)(n+m)}\left(\bar{\mathbf{x}}\,\bar{\mathbf{x}}^\top -\bar{\mathbf{x}}\,\bar{\mathbf{c}}^\top-\bar{\mathbf{c}}\,\bar{\mathbf{x}}^\top\right)\\
    &\phantom{=}\qquad
    +\frac{1}{(n-1)}\mathbf{C}\,\mathbf{C}^\top-
    \frac{m^2}{(n+m)(n-1)}\bar{\mathbf{c}}\,\bar{\mathbf{c}}^\top \\
    &=\cov(\mathbf{X})+\frac{n\,m}{(n-1)(n+m)}\left(\bar{\mathbf{x}}\,\bar{\mathbf{x}}^\top -\bar{\mathbf{x}}\,\bar{\mathbf{c}}^\top-\bar{\mathbf{c}}\,\bar{\mathbf{x}}^\top+
    \bar{\mathbf{c}}\,\bar{\mathbf{c}}^\top\right)\\
    &\phantom{=}\qquad 
     -\frac{n\,m}{(n-1)(n+m)} \bar{\mathbf{c}}\,\bar{\mathbf{c}}^\top
   +\frac{1}{(n-1)}\mathbf{C}\,\mathbf{C}^\top\\
   &\phantom{=}\qquad
    -\frac{m^2}{(n+m)(n-1)}\bar{\mathbf{c}}\bar{\mathbf{c}}^\top \\
  &=\cov(\mathbf{X})+\frac{n\,m}{(n-1)(n+m)}(\bar{\mathbf{x}}-\bar{\mathbf{c}})(\bar{\mathbf{x}}-\bar{\mathbf{c}})^\top\\
    &\phantom{=}\qquad +
    \frac{1}{(n-1)}
    \mathbf{C}\,\mathbf{C}^\top-
    \frac{m(n+m)}{(n-1)(n+m)}
    \bar{\mathbf{c}}\,\bar{\mathbf{c}}^\top \\
 &=\cov(\mathbf{X})+\frac{n\,m}{(n-1)(n+m)}(\bar{\mathbf{x}}-\bar{\mathbf{c}})(\bar{\mathbf{x}}-\bar{\mathbf{c}})^\top
+   \frac{(m-1)}{(n-1)} \cov{(\mathbf{C})}
\end{align*}
Multiplying both sides by $\displaystyle \frac{(n-1)}{(n+m-1)}$ yields the desired result,
\begin{align*}
    \cov(\hat{\mathbf{X}})&=\frac{(n-1)}{(n+m-1)}\cov(\mathbf{X})+\frac{nm}{(n+m-1)(n+m)}(\bar{\mathbf{x}}-\bar{\mathbf{c}})(\bar{\mathbf{x}}-\bar{\mathbf{c}})^\top\\
    &\phantom{=} \qquad
    +\frac{(m-1)}{(n+m-1)}\cov(\mathbf{C}) 
\end{align*}
where 
\begin{align*}
    \cov(\mathbf{C}) &= \frac{1}{(m-1)}\sum_{i = n+1}^{n+m}({\mathbf{x}_i-\bar{\mathbf{c}}})({\mathbf{x}_i-\bar{\mathbf{c}}})^\top \\
    \mathbf{X} &=[\mathbf{x}_1,\, \mathbf{x}_2,\cdots,\mathbf{x}_n] \\
    \hat{\mathbf{X}} &=[\mathbf{x}_1,\, \mathbf{x}_2,\cdots,\mathbf{x}_{n+m}]
\end{align*}
