\subsection{Proof of Lemma 1}
\label{appendix:lemma1_proof}
\begin{proof}
Let $\mathbf{C} = \mathbf{C}^\top \in\mathbb{R}^{D\times D}$. For convenience, with a slight abuse of notation, we will ignore the multiplication by the constants $a$ and $b$ and assume that $\mathbf{C}$ and $\mathbf{B}\,\mathbf{B}^\top$ have been already multiplied by them. 

We wish to bound
\begin{align}
\left\|
\sigma_i \left( \mathbf{C} + \mathbf{B}\,\mathbf{B}^\top \right) - 
\sigma_i \left(\mathbf{C}_d + \mathbf{B}\,\mathbf{B}^\top \right)  
\right\|
\label{eqn:goal1}
\end{align}
where $d<D$.

The Courant--Fisher Theorem (1905),Theorem 8.1.5 \cite{MR1417720} gives us useful inequalities to compare the singular values of \cref{eqn:Rd1,eqn:Rd2}.
\begin{align}
\label{eqn:CF_1}
\sigma_i(\mathbf{C}) + \sigma_D(\mathbf{B}\,\mathbf{B}^\top)
&\le \sigma_i(\mathbf{C} + \mathbf{B}\,\mathbf{B}^\top)
\le \sigma_i(\mathbf{C}) + \sigma_1(\mathbf{B}\,\mathbf{B}^\top) \\
%
\label{eqn:CF_2}
\sigma_i(\mathbf{C}_d) + \sigma_D(\mathbf{B}\,\mathbf{B}^\top)
&\le \sigma_i(\mathbf{C}_d + \mathbf{B}\,\mathbf{B}^\top)
\le \sigma_i(\mathbf{C}_d) + \sigma_1(\mathbf{B}\,\mathbf{B}^\top) \\
%
\label{eqn:CF_3}
\sigma_i(\mathbf{B}\,\mathbf{B}^\top) + \sigma_D(\mathbf{C})
&\le \sigma_i(\mathbf{C} + \mathbf{B}\,\mathbf{B}^\top)
\le \sigma_i(\mathbf{B}\,\mathbf{B}^\top) + \sigma_1(\mathbf{C}) \\
%
\label{eqn:CF_4}
\sigma_i(\mathbf{B}\,\mathbf{B}^\top) + \sigma_D(\mathbf{C}_d)
&\le \sigma_i(\mathbf{C}_d + \mathbf{B}\,\mathbf{B}^\top)
\le \sigma_i(\mathbf{B}\,\mathbf{B}^\top) + \sigma_1(\mathbf{C}_d). 
\end{align}
We can simplify these inequalities slightly using
$\sigma_i(\mathbf{B}\,\mathbf{B}^\top) = \sigma_i^2(\mathbf{B})$, $\sigma_D(\mathbf{C}_d) = 0$ and $\sigma_1(\mathbf{C}) = \sigma_1(\mathbf{C}_d)$. Although there are four variations of inequalities, \cref{eqn:CF_1,eqn:CF_2} are the ones we need to consider. 
%\vspace{-0.4cm}
\begin{align}
\label{eqn:d8}
\sigma_i(\mathbf{C}) + \sigma_D^2(\mathbf{B})
&\le \sigma_i(\mathbf{C} + \mathbf{B}\,\mathbf{B}^\top)
\le \sigma_i(\mathbf{C}) + \sigma_1^2(\mathbf{B}) \\
%
\label{eqn:d9}
\sigma_i(\mathbf{C}_d) + \sigma_D^2(\mathbf{B})
&\le \sigma_i(\mathbf{C}_d + \mathbf{B}\,\mathbf{B}^\top)
\le \sigma_i(\mathbf{C}_d) + \sigma_1^2(\mathbf{B}) 
\end{align}
\Cref{eqn:goal1} is equivalent to maximizing
\begin{align}
\left| \sigma_i(\mathbf{C} + \mathbf{B}\,\mathbf{B}^\top) - \sigma_i(\mathbf{C}_d + \mathbf{B}\,\mathbf{B}^\top)\right|
\label{eqn:goal2}
\end{align}
for some (unknown) index $i$. 
First, consider the case when 
\begin{align}
\sigma_i(\mathbf{C} + \mathbf{B}\,\mathbf{B}^\top) > \sigma_i(\mathbf{C}_d + \mathbf{B}\,\mathbf{B}^\top).
\end{align}
To maximize the difference, we want $\sigma_i(\mathbf{C} + \mathbf{B}\,\mathbf{B}^\top)$ to be as large as possible (upper bound), and 
$\sigma_i(\mathbf{C}_d + \mathbf{B}\,\mathbf{B}^\top)$ to be as small as possible (lower bound). 

Upper bound in \cref{eqn:d8} and lower bound in \cref{eqn:d9} gives the following bound
\begin{align}
\left| \sigma_i(\mathbf{C} + \mathbf{B}\,\mathbf{B}^\top) - \sigma_i(\mathbf{C}_d + \mathbf{B}\,\mathbf{B}^\top)\right| &\le 
\sigma_i(\mathbf{C}) + \sigma_1^2(\mathbf{B}) 
- \sigma_i(\mathbf{C}_d) - \sigma_D^2(\mathbf{B}) 
\end{align}
Notice that $\sigma_i(\mathbf{C}) = \sigma_i(\mathbf{C}_d)$ for $i \le d$ and $\sigma_i(\mathbf{C}) - 
\sigma_i(\mathbf{C}_d) \leq \sigma_{d+1}(\mathbf{C})$ for $i>d$. 

Furthermore, if $n<D$ then $\sigma_D^2(\mathbf{B}) = 0$. Therefore, we get
\begin{align}
\label{eqn:bound1}
\left| \sigma_i(\mathbf{C} + \mathbf{B}\,\mathbf{B}^\top) - \sigma_i(\mathbf{C}_d + \mathbf{B}\,\mathbf{B}^\top)\right| &\le 
\sigma_{d+1}(\mathbf{C}) + \sigma_1^2(\mathbf{B}) 
\end{align}
In the second case 
\begin{align}
\sigma_i(\mathbf{C} + \mathbf{B}\,\mathbf{B}^\top) < \sigma_i(\mathbf{C}_d + \mathbf{B}\,\mathbf{B}^\top).
\end{align}
we want $\sigma_i(\mathbf{C} + B\,B^\top)$ to be as small as possible (lower bound), and 
$\sigma_i(\mathbf{C}_d + \mathbf{B}\,\mathbf{B}^\top)$ to be as large as possible (lower bound).

Lower bound in \cref{eqn:d8} and upper bound in \cref{eqn:d9} gives the following bound
\begin{align}
\label{eqn:bound2}
\left| \sigma_i(\mathbf{C} + \mathbf{B}\,\mathbf{B}^\top) - \sigma_i(\mathbf{C}_d + \mathbf{B}\,\mathbf{B}^\top)\right| & =  
\left| \sigma_i(\mathbf{C}) + \sigma_D^2(\mathbf{B}) 
- \sigma_i(\mathbf{C}_d) - \sigma_1^2(\mathbf{B}) \right | \\
&\le \sigma_1^2(\mathbf{B}) - \sigma_{d+1}(\mathbf{C}) 
\end{align}
\Cref{eqn:bound1,eqn:bound2} imply that 
\begin{align}
%\label{eqn:bound3}
\left| \sigma_i(\mathbf{C} + \mathbf{B}\,\mathbf{B}^\top) - \sigma_i(\mathbf{C}_d + \mathbf{B}\,\mathbf{B}^\top)\right|
&\le \sigma_{d+1}(\mathbf{C}) +\sigma_1^2(\mathbf{B})
\end{align}
\end{proof}

\subsection{Proof of Lemma 2}
\begin{proof}
Let $ \mathbf{A}_1 := a\,\mathbf{C} + b\,\mathbf{B}\,\mathbf{B}^\top$,
$ \mathbf{A}_2 := a\,\mathbf{C}_d + b\,\mathbf{B}\,\mathbf{B}^\top$,  $\Sigma = diag(\lambda_1,\ldots, \lambda_D)$ where $a = \frac{n-1}{(n+m-1)}$, $b = \frac{1}{(n+m-1)}$.
\begin{align*}
\mathbf{A}_1 &= \mathbf{A}_2 + a\,\sum_{i= d+1}^D\lambda_i\,u_i\,u_i^\top \\
 &= a\,\mathbf{C}_d + b\,\mathbf{B}\,\mathbf{B}^\top + a\,\sum_{i= d+1}^D\lambda_i\,u_i\,u_i^\top 
\end{align*}

Therefore, using Theorem 3 \cite{zwald2005convergence} we can write
% \cref{theorem:angles} we can write 
\begin{align}
    \label{proof:angle_proof_step1}
    \|\tilde{\mathbf{R}}_d\,\tilde{\mathbf{R}}_d^\top - 
    {\mathbf{R}}_d\,{\mathbf{R}}_d^\top\|_2 \leq 
    \frac{\|a\,\sum_{i= d+1}^D\lambda_i\,u_i\,u_i^\top\|_2}
    {\delta_d}
\end{align}
where $\delta_d = 0.5\left(\sigma_d(a\,\mathbf{C}_d+b\,\mathbf{B}\,\mathbf{B}^\top)
- \sigma_{d+1}(a\,\mathbf{C}_d+b\,\mathbf{B}\,\mathbf{B}^\top)
\right)$.
We want this eigengap to be large. Therefore, we need 
$\sigma_d(a\,\mathbf{C}_d+b\,\mathbf{B}\,\mathbf{B}^\top)$ large as much as possible and
$\sigma_{d+1}(a\,\mathbf{C}_d+b\,\mathbf{B}\,\mathbf{B}^\top)$ smaller as much as possible.

For convenience, with a slight abuse of notation, we will ignore the multiplication by the constants $a$ and $b$ and assume that $\mathbf{C}_d$ and $\mathbf{B}\,\mathbf{B}^\top$ have been already multiplied by them.  
Using \cref{eqn:CF_2,eqn:CF_4} with setting $i=d$ and $i=d+1$ we get the following inequalities.
\begin{align}
    \label{eqn:thm_p1}
    \sigma_d(\mathbf{C}_d) + \sigma_D(\mathbf{B}\,\mathbf{B}^\top)
    &\le \sigma_d(\mathbf{C}_d + \mathbf{B}\,\mathbf{B}^\top)
    \le \sigma_d(\mathbf{C}_d) + \sigma_1(\mathbf{B}\,\mathbf{B}^\top) \\
    %
    \label{eqn:thm_p2}
    \sigma_d(\mathbf{B}\,\mathbf{B}^\top) + \sigma_D(\mathbf{C}_d)
    &\le \sigma_d(\mathbf{C}_d + \mathbf{B}\,\mathbf{B}^\top)
    \le \sigma_d(\mathbf{B}\,\mathbf{B}^\top) + \sigma_1(\mathbf{C}_d). \\
    %
    \label{eqn:thm_p3}
    \sigma_{d+1}(\mathbf{C}_d) + \sigma_D(\mathbf{B}\,\mathbf{B}^\top)
    &\le \sigma_{d+1}(\mathbf{C}_d + \mathbf{B}\,\mathbf{B}^\top)
    \le \sigma_{d+1}(\mathbf{C}_d) + \sigma_1(\mathbf{B}\,\mathbf{B}^\top) \\
    %
    \label{eqn:thm_p4}
    \sigma_{d+1}(\mathbf{B}\,\mathbf{B}^\top) + \sigma_D(\mathbf{C}_d)
    &\le \sigma_{d+1}(\mathbf{C}_d + \mathbf{B}\,\mathbf{B}^\top)
    \le \sigma_{d+1}(\mathbf{B}\,\mathbf{B}^\top) + \sigma_1(\mathbf{C}_d). 
\end{align}
We want to make the upper bound depend on the largest singular value of the $\mathbf{B}$. Therefore, we consider the largest value from \cref{eqn:thm_p1} and the smallest value from \cref{eqn:thm_p3}. Notice that 
$\sigma_{d+1}(\mathbf{C}_d)$ and $\sigma_D(\mathbf{B}\,\mathbf{B}^\top)$ are both zero. So we get,
\begin{align*}
   \sigma_d(\mathbf{C}_d+\mathbf{B}\,\mathbf{B}^\top)
- \sigma_{d+1}(\mathbf{C}_d+\mathbf{B}\,\mathbf{B}^\top) &=
\sigma_d(\mathbf{C}_d) + \sigma_1^2(\mathbf{B})
% \frac{1}{\sigma_d(\mathbf{C}_d+\mathbf{B}\,\mathbf{B}^\top)
% - \sigma_{d+1}(\mathbf{C}_d+\mathbf{B}\,\mathbf{B}^\top)} &\leq
% \frac{1}{\sigma_1^2(\mathbf{B})}
\end{align*}
Therefore we can rewrite \Cref{proof:angle_proof_step1},
\begin{align}
    \|\tilde{\mathbf{R}}_d\,\tilde{\mathbf{R}}_d^\top - 
    {\mathbf{R}}_d\,{\mathbf{R}}_d^\top\|_2 &\leq 
    \frac{\|a\,\,\sum_{i= d+1}^D\lambda_i\,u_i\,u_i^\top\|_2}
    {b\,\delta_d}
    \leq 
    \frac{2\,a\,\sigma_{d+1}(\mathbf{C})}{a\,\sigma_d(\mathbf{C}_d) + b\,\sigma_1^2(\mathbf{B}))}
\end{align}
\end{proof}

