\begin{figure}[t]
    \centering
    \begin{subfigure}[b]{0.7\columnwidth}
        \centering
        \includegraphics[width=\linewidth]{images/automated_usage_X.png}
        \caption{Use of automation.}
        \label{fig:X_automation}
    \end{subfigure}\\
    \vspace{1em}
    \begin{subfigure}[b]{0.85\columnwidth}
        \centering
        \includegraphics[width=\linewidth]{images/moderated_content.png}
        \caption{Type of moderated content.}
