  \includegraphics[width=12.5cm]{couplingKSAT.pdf}
  \caption{Example of a coupling between derivative terms in \eqref{eqtypeContr2}--\eqref{eqtypeContr2N}. 
    For vector $r$ and type $t\in \{\rAllKid, \rPureP, \rPureM\}$, we pair the term $\diffr^{t}(z, r; +1)$ in \eqref{eqtypeContr2} with
    the term $\diffr^{t}(z, \mathfrak{p}_t(r); -1)$ in \eqref{eqtypeContr2N}.}
  \label{fig_coupling}  
\end{figure}

\begin{proof}[Proof of \Thm~\ref{thm_uniq}]
  From the triangle inequality, and \Lem~\ref{lem:ExtremalBnd}, it is immediate to obtain \Thm~\ref{thm_uniq} from \Prop~\ref{prop:condMarg}.
\end{proof}

\subsection{Discussion}\label{sec_discussion}
The location of the random 2-SAT satisfiability threshold was pinpointed already in the 1990s~\cite{CR,Goerdt} essentially because the threshold coincides with the giant component phase transition of a directed random graph whose edges correspond to the clauses.
This argument also implies that both the pure literal algorithm and another efficient algorithm called unit clause propagation find satisfying assignments up to the satisfiability threshold \whp\
By contrast, in the case of random $k$-SAT with $k\geq3$ the satisfiability threshold is known only for~$k$ exceeding an undetermined (but large) constant $k_0$~\cite{DSS3}.
The proof is based on a sophisticated, physics-inspired second moment argument that significantly extends ideas from earlier work~\cite{nae,yuval,KostaSAT}.
Asymptotically in the limit of large $k$ the satisfiabiliy threshold reads
\begin{align}\label{eqdsat}
  \dsat(k)&=k\brk{2^k\log 2-\frac{1+\log 2}2}+\eps_k,&&\mbox{where }\lim_{k\to\infty}\eps_k=0.
\end{align}
Even though~\cite{nae,yuval,DSS3,KostaSAT} rely on the second moment method, they do not yield asymptotically tight estimates of the number of satisfying assignments for any regime of $d$.
This is because the second moment method is applied not to the number of satisfying assignments, but to another, exponentially smaller random variable.
The assumption that $k$ exceeds a large constant is used critically in~\cite{KostaSAT,DSS3} to ensure certain concentration and expansion properties.

For $3\leq k<k_0$ even the {\em existence} of a uniform satisfiability threshold remains an open problem, although a sharp threshold sequence that may vary with $n$ is known to exist~\cite{Friedgut}.
That said, an upper bound on the satisfiability threshold (sequence) that matches the so-called `1-step replica symmetry breaking' prediction from statistical physics can be verified using the interpolation method from mathematical physics~\cite{FranzLeone,MMZ,MPZ,PanchenkoTalagrand}.
However, the currently known lower bounds for small $k$ (say, $k=3,4,5$) fall short of this upper bound~\cite{yuval,Greg,KKL}.
For example, in the case $k=3$ the best current lower bound is $\dsat(3)\geq10.56$, while $\dsat(3)\approx12.801$ according to physics predictions~\cite{MMZ,MPZ}.

Thus, the satisfiability of random formulas continues to pose a substantial challenge for `small' $3\leq k<k_0$.
In light of this, a particularly satisfactory aspect of the present results is that they apply and are meaningful for all $k\geq3$.
In fact, comparing the asymptotic bounds~\eqref{eqpureasymptotic} and~\eqref{eqdsat}, we see that the Gibbs uniqueness threshold $\duniq(k)$ is much smaller than $\dsat(k)$ for large $k$	.
Thus, \Thm s~\ref{thm_main} and~\ref{thm_uniq} cover larger shares of the satisfiable regime of $d$ for smaller values of $k$; cf.~Table~\ref{tab_main}.

The best current lower bounds on the satisfiability thresholds for $k\geq4$ are non-constructive.
With respect to the algorithmic problem of finding a satisfying assignment of a random $k$-CNF the best current results for `small' $k$ are based on simple combinatorial algorithms, analysed via the method of differential equations~\cite{FriezeSuen,Greg,KKL}.
Asymptotically for large $k$ the best known efficient algorithm~\cite{better} succeeds up to
\begin{align}\label{eqdalg}
  \dalg(k)&=(1-\eps_k)2^k\log k&&\mbox{where }\lim_{k\to\infty}\eps_k=0,
\end{align}
about a factor of $\log(k)/k$ below~\eqref{eqdsat}.
There is evidence that certain types of algorithms do not succeed for much larger values of $d$, at least for enough large $k$~\cite{Barriers,Bresler,bpdec,Hetterich}.
Apart from the task of finding a satisfying assignment, an important line of work deals with the problem of counting and sampling satisfying assignments of random $k$-CNFs for large $k$~\cite{CGGGHPMM,Zongchen,HWY}.
The best current result~\cite{Zongchen} covers the regime $d\leq 2^k/k^c$ for an undetermined (large enough) constant $c>0$.
Since for large $k$ the bound $2^k/k^c$ significantly exceeds the pure literal threshold~\eqref{eqpureasymptotic}, it might be an interesting question whether ideas from~\cite{CGGGHPMM,Zongchen,HWY} can be used to verify the replica symmetric solution~\eqref{eqBFE} for $d$ beyond the Gibbs uniqueness threshold for large $k$.

Most of the prior work on the rigorous verification of the replica symmetric solution focuses on a soft version of random $k$-SAT, the so-called random $k$-SAT model at {\em inverse termperature} $\beta>0$~\cite{PanchenkoBook}.
The partition function $Z_\beta(\PHI)$ of this model, its the key quantity of interest, is defined as follows.
For a clause $a$ of the random formula $\PHI$ and a truth assignment $\sigma$ write $\sigma\models a$ if $\sigma$ satisfies clause $a$.
Then
\begin{align}\label{eqZbeta}
  Z_\beta(\PHI)&=\sum_{\sigma\in\PM^n}\exp\bc{-\beta\sum_{i=1}^{\vm}\vecone\{\sigma\not\models a_i\}}.
\end{align}
Thus, each assignment $\sigma$ contributes a summand equal to $\exp(-\beta)$ raised to the power of the number of clauses that $\sigma$ fails to satisfy.
In effect,
\begin{align}\label{eqZbetainfty}
  Z(\PHI)&=\lim_{\beta\to\infty}Z_\beta(\PHI).
\end{align}
A line of prior work~\cite{Biswas,Panchenko2,Talagrand} deals with the derivation of the `thermodynamic limit'
\begin{align}\label{eqthermo}
  \lim_{n\to\infty}\frac1n\ex\brk{\log Z_\beta(\PHI)}
\end{align}
for small $d$ and/or small $\beta$.
Specifically, these works verify that~\eqref{eqthermo} is given by the replica symmetric solution at inverse temperature $\beta$ from~\cite{MZ,MZ2} under the assumption
\begin{align}\label{eqBiswas}
  d(k-1)\min\cbc{1,6\beta\exp(4\beta)}&<1.
\end{align}
We observe that for large $\beta$ the bound \eqref{eqBiswas} holds only up to the giant component threshold $d=1/(k-1)$, where the replica symmetric solution trivially follows from the fact that Belief Propagation is exact on acyclic graphical models~\cite[Theorem 4.1]{MM}.
That said, a technique called the interpolation method shows that the replica symmetric solution yields an upper bound on~\eqref{eqthermo} for all $d,\beta>0$~\cite{FranzLeone,PanchenkoTalagrand}.
In particular, we will combine the interpolation method with a concentration argument in order to prove \Cor~\ref{cor_interpolation}.

According to physics predictions the `replica symmetric solution' from~\cite{MZ,MZ2} yields the correct value of both $\lim_{n\to\infty}n^{-1}\log Z_\beta(\PHI)$ for all $\beta>0$ and of $\lim_{n\to\infty}n^{-1}\log Z(\PHI)$ for all $d$ up to a threshold $\drsb(k)$ close to but strictly below the satisfiability threshold $\dsat(k)$ for all $k\geq3$~\cite{pnas}.
The threshold $\drsb(k)$ is known as the `1-step replica symmetry breaking phase transition' in physics jargon; its asymptotic value is predicted as
\begin{align}\label{eqdrsb}
  \drsb(k)&=k\brk{2^k\log 2-2\log 2}+\eps_k,&&\mbox{where }\lim_{k\to\infty}\eps_k=0.
\end{align}
Indeed, the interpolation method can be used to verify that the replica symmetric solution ceases to be correct for $\drsb(k)+\eps_k<d<\dsat(k)$ with $\eps_k\to0$.
Conversely, the replica symmetric solution is known to be correct for all $d$ and $\beta>0$ where a certain correlation decay condition is satisfied~\cite{COMR}, provided that $k$ is large enough.
Physics methods predict that this condition holds for all $\beta>0$ and all $d<\drsb(k)$~\cite{pnas}.

The aforementioned work of Montanari and Shah~\cite{MS} also deals with the soft variant of random $k$-SAT~\eqref{eqZbeta}, but allows for an inverse temperature $\beta=\beta(n)$ that tends to infinity slowly as $n\to\infty$.
Specifically, considering a small power $\beta=n^\delta$ enables Montanari and Shah to estimate the number of assignments that violate all but $o(n)$ clauses.
The proof combines an interpolation on $0\leq\beta\leq n^\delta$ with a contraction argument that improves over the previous contraction estimates from~\cite{Biswas,Panchenko2,Talagrand}.
Instead of the interpolation on $\beta$, in order to prove \Thm~\ref{thm_main} we use the Aizenman-Sims-Starr scheme.
Because we count actual satisfying assignments, this requires the careful combinatorial analysis of tail events, which is where the \pulp\ algorithm and its analysis come in.
Additionally, towards the proof of \Thm~\ref{thm_uniq} we devise an improved version of the contraction argument from~\cite{MS}.
Following Montanari and Shah, we also take advantage of the impact of pure literals on the Belief Propagation operator.
But we develop an improved coupling scheme that yields a better range of $d$ for which contraction occurs.
Additionally, once again because we deal with actual satisfying assignments, the proof of the Gibbs uniqueness property involves the analysis of the \pulp\ algorithm on a Galton-Watson tree in order to cope with unlikely events.

By comparison to the `soft' random $k$-SAT model~\eqref{eqZbeta}, few prior contributions deal with the actual number $Z(\PHI)$ of satisfying assignments.
A result of Abbe and Montanari~\cite{AM}  implies that a deterministic limit (in probability)
\begin{align}\label{eqAM}
  \lim_{n\to\infty}\frac1n\log Z(\PHI)
\end{align}
exists for Lesbegue-almost all $0<d<\dpure(k)$ for all $k\geq2$.
However, the proof, which is based on the interpolation method, does not reveal the value of~\eqref{eqAM}.
In fact, prior to the present work the limit \eqref{eqAM} was known only in two cases.
First, in the trivial regime $d<1/(k-1)$ below the giant component threshold.
Second, in the case $k=2$ for $0<d<\dsat(2)=2$~\cite{2sat}.
In both cases the limit \eqref{eqAM} coincides with the replica symmetric solution from~\cite{MZ}.
Beyond the convergence in probability, $\log Z(\PHI)$ is known to satisfy a central limit theorem in the case $k=2$~\cite{CCOMRRZZ}.

To compute the limit~\eqref{eqAM} in the case $k=2$ the contribution~\cite{2sat} employs the Aizenman-Sims-Starr scheme.
The couplings that we use towards the proofs of \Prop~\ref{lem_PHI''}--\ref{lem_PHI'''} generalise the argument from~\cite{2sat} to $k\geq3$.
The main technical novelty lies in the way that moderately unlikely events are treated.
Specifically, in the case $k=2$ the simple Unit Clause propagation algorithm, which essentially boils down to directed reachability, was sufficient to derive a tail bound similar to (and actually stronger than)~\eqref{eq_prop_bad}.
By contrast, since in the case $k\geq3$ the clauses ``branch out'', the analysis of tail events and, accordingly, the derivation of \eqref{eq_prop_bad} is far more delicate.
The core of this derivation is the detailed analysis of the \pulp\ algorithm right up to $\dpure(k)$.

Finally, by contrast to random $k$-SAT the validity of the replica symmetric solution is known for the optimal parameter range for several other random constraint satisfaction problems that enjoy certain symmetry properties.
Examples include random graph colouring or random $k$-NAESAT~\cite{cond,CKPZ}.
Due to the symmetry property
\footnote{A formal definition of `symmetry' could be that the uniform distribution on spins is a fixed point of the Belief Propagation operator on the respective Galton-Watson tree.}
the replica symmetric solution simply coincides with the first moment of the number of solutions.
In effect, in many symmetric problems it is even possible to precisely determine the limiting distribution of the number of solutions, which superconcentrates on the first moment~\cite{CKM}.
By contrast, in random $k$-SAT the first moment overshoots the typical number of satisfying assignments by an exponential factor~\cite{nae}, which is why random $k$-SAT is so much more delicate than symmetric problems.
That said, there is a regular variant of random $k$-SAT (where every variable appears an equal number of times positively and negatively) where symmetry and superconcentration are recovered~\cite{COW}.



\subsection{Organisation}\label{sec_org}
In the remaining sections we work our way through the proofs of \Thm s~\ref{thm_main} and \ref{thm_uniq}. Specifically, in
\Sec~\ref{sec_pulp_pr} we analyse the \pulp\ algorithm introduced in \Sec~\ref{sec_pulp}, proving \Lem s~\ref{lem_Ichi}-\ref{lem_EIchi},
which facilitates many of the subsequent results.

In \Sec~\ref{sec_prop_arnab} we establish \Prop~\ref{prop_arnab}, verifying that the quantities appearing in \Thm~\ref{thm_main} are well-defined.
The proof of \Cor~\ref{cor_interpolation} follows in  \Sec~\ref{sec_prop_interpolation}.
\Sec~\ref{sec_prop_aizenman} is devoted to the Aizenman-Sims-Starr scheme, and in particular the proof of \Prop~\ref{prop_aizenman}.
There we also complete the proof of \Thm~\ref{thm_main}.

Our final \Sec~\ref{sec_prop:condMarg}, deals with the remaining proofs toward establishing \Thm~\ref{thm_uniq}. We begin by proving \Lem~\ref{lem_SmallOnTop},
showing that
the log-likelihood ratios of the random Galton-Watson formula close to the root are bounded \whp. This enables us to
compare the output distribution of the non-random operator introduced in \Sec~\ref{sec_uniq_outline} with that of actual ratios on the random tree.
We then proceed with the proof of \Prop~\ref{prop_BPPureLit}, and conclude with the proof of \eqref{eqstrangeconv}, completing the proof of \Thm~\ref{thm_uniq}.


\section{Analysis of {\pulp}}\label{sec_pulp_pr}

\noindent
This section is concerned with the analysis of \pulp\ from \Sec~\ref{sec_pulp}.
In particular, we prove \Lem~\ref{lem_EIchi}.
But let us get the proof of \Lem~\ref{lem_Ichi} out of the way first.


\subsection{Proof of \Lem~\ref{lem_Ichi}}
Suppose that $\bar\cL \supseteq \cL$ satisfies {\bf PULP1}--{\bf PULP2}.
Let $U=\{|l|:l\in\bar\cL\}$  be the set of variables underlying the literals $\bar\cL$.
Moreover, let $\chi: U \to \PM$ be the truth assignments under which all literals of $l\in\bar\cL$ evaluate to `true'.
Due to {\bf PULP2}, the assignment $\chi$ is well defined.
Moreover, since $\cL\subseteq\bar\cL$, under $\chi$ all literals $l\in\cL$ evaluate to `true'.
Hence, for a satisfying assignment $\sigma\in S(\Phi)$ define an assignment $\sigma'$ by letting 
\begin{align*}
  \sigma'(x)=\vecone\{x\in U\}\chi(x)+\vecone\{x\not\in U\}\sigma(x) \enspace.
\end{align*}
Because $\bar\cL$ satisfies condition {\bf PULP1}, we have $\sigma'\in S(\Phi,\cL)$.
Finally, because for a satisfying assignment $\tau'\in S(\Phi,\cL)$ there are no more than $2^{|U|}=2^{|\bar\cL|}$ satisfying assignments $\tau\in S(\Phi)$ such that $\tau(x)=\tau'(x)$ for all $x \not\in U$, we obtain the desired bound $Z(\Phi)\leq 2^{|\bar\cL|}Z(\Phi,\cL)$.



\subsection{Turning a tree to \pulp}\label{sec_treepulp}
While the ultimate goal of this section is to study the \pulp\ algorithm on the random formula $\PHI'$ to prove \Lem~\ref{lem_EIchi}, a necessary preparation is to investigate the algorithm on the random Galton-Watson tree $\TT=\TT_{d,k}$.
Of course, since $\TT$ may be infinite we should formally confine ourselves to the finite trees $\TT^{(\ell)}$ truncated at the $2\ell$-th level from the root $\root$.
Hence, recalling~\eqref{eqheightdef}, we aim to estimate the height $\fn_\root(s,\TT^{(\ell)})$ for finite $\ell$.
That said, since these random variables are monotonically increasing in $\ell$, it makes sense to define
\begin{align}\label{eqhTT}
  \fn_\root(s,\TT)&=\lim_{\ell\to\infty}\fn_\root(s,\TT^{(\ell)})\in[0,\infty].
\end{align}
We point out that for $d<\dpure(k)$ the tails of $\fn_\root(s,\TT)$ decay at a doubly exponential rate.

\begin{lemma}\label{lem:Peeling_on_Trees}
  For any $d<\dpure(k)$ there exist $c_1=c_1(d,k),c_2=c_2(d,k)>0$ such that
  \begin{align*}
    \Pr \brk{ \fn_{\root}(\pm1,\TT) \geq h } &\leq c_1 \cdot \exp\bc{-\exp\bc{c_2 \cdot h}} && \text{ for every } h \ge 1 \enspace.
  \end{align*}
\end{lemma}
\begin{proof}
  By symmetry it suffices to consider $\fn_{\root}(1,\TT)$.
  Thus, let $p_{h, \ell} = \Pr \brk{ \fn_{\root} (1,\TT^{(\ell)})\geq h}$.
  All variables at distance $2\ell$ from $\root$ are leaves and therefore pure in the tree $\TT^{(\ell)}$.
  Consequently, pure literal elimination removes all clauses of $\TT^{(\ell)}$ within at most $\ell$ rounds.
  Hence, $p_{h,\ell}=0$ for $h>\ell$.
  Furthermore, we claim that
  \begin{align}\label{eqlem:Peeling_on_Trees_1}
    p_{h,\ell}&=\varphi_{d,k}(p_{h-1,\ell-1}),\qquad\mbox{where}\quad\varphi_{d,k}(z)=1-\exp\bc{-\frac d2z^{k-1}}&&(1\leq h\leq\ell).
  \end{align}
  Indeed, if $\fn_{\root} (1,\TT^{(\ell)})\geq h\geq1$ then  by~\eqref{eqheightdef} there exists a clause $a\in\partial_{\TT} r$ with $\sign(\root,a)=-1$ such that $\fn_a(\TT^{(\ell)}[\root\mapsto 1])\geq h-1$.
  In other words, pure literal elimination on the sub-tree $\TT^{(\ell)}[a]$ of $\TT^{(\ell)}$ rooted at clause $a$ and with variable $\root$ removed takes at least $h-1$ rounds to remove clause $a$.
  Consequently, pure literal elimination on $\TT^{(\ell)}[a]$ takes at least $h-1$ rounds to remove one of the variables $x\in\partial_\TT a\setminus\{\root\}$.
  In other words, the sub-tree $\TT^{(\ell)}[x]$ comprising $x$ and its successors satisfies
  \begin{align}\label{eqlem:Peeling_on_Trees_2}
    \fn_x(\sign(x,a),\TT^{(\ell)}[x])&\geq h-1&&\mbox{for every }x\in\partial_\TT a\setminus\{\root\}.
  \end{align}
  But since $\TT$ is a Galton-Watson tree, the sub-tree $\TT^{(\ell)}[x]$ has the same distribution as the random tree $\TT^{(\ell-1)}$.
  Hence, \eqref{eqlem:Peeling_on_Trees_2} implies that for every $a\in\partial_{\TT}\root$ with $\sign(x,a)=-1$,
  \begin{align}\label{eqlem:Peeling_on_Trees_3}
    \pr\brk{\fn_a(\TT^{(\ell)}[\root\mapsto 1])\geq h-1\mid\TT^{(1)}}&=p_{h-1,\ell-1}^{k-1}.
  \end{align}
  Finally, the construction of $\TT$ ensures that the number of $a\in\partial_{\TT}\root$ with $\sign(x,a)=-1$ has distribution $\Po(d/2)$.
  Therefore, \eqref{eqlem:Peeling_on_Trees_3} shows that
  \begin{align*}
    p_{h,\ell}&=\sum_{i=0}^{\infty}\pr\brk{\Po(d/2)=i}\bc{1-\bc{1-p_{h-1,\ell-1}^{k-1}}^i}=1-\exp\bc{-\frac d2p_{h-1,\ell-1}^{k-1}},
  \end{align*}
  which completes the proof of~\eqref{eqlem:Peeling_on_Trees_1}.

  Since the sequences $(p_{h,\ell})_{\ell}$ are non-decreasing, the limits $p_h=\lim_{\ell\to\infty}p_{h,\ell}$ exist.
  Moreover, \eqref{eqlem:Peeling_on_Trees_1} shows that
  \begin{align}\label{eqlem:Peeling_on_Trees_4}
    p_h&=\varphi_{d,k}(p_{h-1})&&(h\geq1).
  \end{align}
  Hence, recalling the definition~\eqref{eqpure} of $\dpure(k)$, we find
  \begin{align*}
    \left(\frac{p_{h+1}}{p_{h}}\right)^{k-1} = \left(\frac{\varphi_{d,k}(p_h)} {p_h} \right)^{k-1} = d\cdot \frac{\left( 1 - \exp\left(-dp_h^{k-1}/2\right)\right)^{k-1}} {d p^{k-1}_h} \le \frac{d}{\dpure}<1 \enspace.
  \end{align*}
  Consequently,
  \begin{align}\label{eqlem:Peeling_on_Trees_5}
    \lim_{h\to\infty}p_h&=0.
  \end{align}

  To complete the proof we expand $\varphi_{d,k}(z)$ around $z=0$:
  \begin{align}\label{eqlem:Peeling_on_Trees_6}
    \varphi_{d,k}(z) &= \frac{d}{2}z^{k-1} +O(z^{2k-2})&&\mbox{ as }z\to 0.
  \end{align}
  Thus, %since $k\geq3$ %we obtain
  the function $\varphi_{d,k}(z)$ is well approximated by a $(k-1)$-th power. %$cz^q$ with $q\geq2$ as $z\to0$.
  Since $k\geq3$, combining \eqref{eqlem:Peeling_on_Trees_4}--\eqref{eqlem:Peeling_on_Trees_6}, we conclude that for sufficiently large $h$ we have $p_h\leq(d/2+1)p_{h-1}^{k-1}$.
  Consequently, $p_h\leq c_1 \cdot \exp\bc{-\exp\bc{c_2 \cdot h}}$ for suitable $c_1=c_1(d,k)$ and $c_2=c_2(d,k)$.
\end{proof}

We remind ourselves that %$\bar\cL(\pm1\cdot\root,\TT^{(\ell)})$ 
$\overline{\{\pm1\cdot\root\}}_{\TT^{(\ell)}}$ signifies the output of \pulp\ run on the formula $\TT^{(\ell)}$ with initial literal set $\{\pm1\cdot\root\}$.
We extend the definition of the closure to the (possibly infinite) tree $\TT$ by letting
\begin{align*}
  \overline{\{\pm1\cdot\root\}}_{\TT}&=\bigcap_{\ell_0\geq1}\bigcup_{\ell\geq\ell_0}\overline{\{\pm1\cdot\root\}}_{\TT^{(\ell)}}.
\end{align*}
This definition ensures that if the height $\fn_{\root}(\pm1,\TT)$ from~\eqref{eqhTT} is finite, then
\begin{align*}
  \overline{\{\pm1\cdot\root\}}_{\TT}=\overline{\{\pm1\cdot\root\}}_{\TT^{(\ell)}}\qquad\mbox{ for all }\ell\geq\fn_{\root}(\pm1,\TT).
\end{align*}
In order to estimate the size of this set, we combine \Lem~\ref{lem:Peeling_on_Trees} with a crude bound on the total number of variable nodes of the Galton-Watson tree $\TT^{(\ell)}$.
Recall that $V(\TT^{(\ell)})$ signifies the set of variable nodes of $\TT^{(\ell)}$.

\begin{lemma}\label{lem_crude}
  Let $d>0$.
  For any $\ell\geq1$ and any $t>100(1+d(k-1))^2$ we have
  \begin{align*}
    \pr\brk{|V(\TT^{(\ell)})|>t^\ell}&\leq \ell\exp(-t^{\ell/2}/4).
  \end{align*}
\end{lemma}
\begin{proof}
  Let $\vN_\ell=|V(\TT^{(\ell)})|$ for brevity, set $g=10(1+d(k-1))$ and notice that $t>g^2$.
  The construction of the Galton-Watson tree $\TT$ ensures that $\vN_0=1$ and that for $\ell\geq1$ given $\vN_{\ell-1}$ we have $\vN_\ell\disteq(k-1)\cdot\Po(d\vN_{\ell-1}).$
  Therefore, Bennett's inequality shows that
  \begin{align}\label{eqcrude1}
    \pr\brk{\vN_h>g^{h-\ell}t^\ell\mid\vN_{h-1}\leq g^{h-1-\ell}t^\ell}&\leq
    \exp\bc{-\frac{t^\ell}{4g^{\ell-h}}}\leq\exp(-t^{\ell/2}/4)&&(1\leq h\leq\ell).
  \end{align}
  Furthermore, if $\vN_\ell>t^\ell$ then there exists $1\leq h\leq\ell$ such that $\vN_h>g^{h-\ell}t^\ell$ while $\vN_{h-1}\leq g^{h-1-\ell}t^\ell$.
  Hence, combining~\eqref{eqcrude1} with the union bound completes the proof.
\end{proof}

\begin{corollary}\label{lem:SMSizeGivenHeight}
  For any $d<\dpure(k)$ there exists $c_3=c_3(d,k)>0$ such that
  \begin{align*}
    \pr[|\overline{\{\pm1\cdot\root\}}_{\TT}|>t]&\leq c_3\exp(-t^{1/c_3})&&\mbox{ for all }t>0.
  \end{align*}
\end{corollary}
\begin{proof}
  By symmetry it suffices to consider $\vN=|\overline{\{\root\}}_{\TT}|$.
  Since \Lem~\ref{lem:Peeling_on_Trees} shows that $\pr[\fn_{\root}(1,\TT)<\infty]=1$, we may assume from now on that indeed $\fn_{\root}(1,\TT)<\infty$.
  Moreover, picking $c_3=c_3(d,k)>0$ large enough, we may assume that $t>t_0$ for a large $t_0=t_0(d,k)$.
  Let $\vN_\ell=|V(\TT^{(\ell)})|$, $p_h=\pr\brk{\fn_\root(1,\TT)=h}$ and $g=10(1+d(k-1))$.
  It is an immediate consequence of the way that \pulp\ proceeds that for all $l\in\overline{\{\root\}}_{\TT}$ we have $|l|\in V(\TT^{(\fn_\root(1,\TT))})$.
  Hence, $\vN\leq\vN_{\fn_\root(1,\TT)}$.
  Therefore, by the law of total probability,
  \begin{align}\label{eqlem:SMSizeGivenHeight_1}
    \pr\brk{\vN>t}&\leq\sum_{h\geq0}S_h,&&\mbox{where }S_h=\pr\brk{\fn_\root(1,\TT)=h}\pr\brk{\vN_h>t\mid\fn_\root(1,\TT)=h}.
  \end{align}
  Depending on the value of $t$ in relation to $h$, we use either \Lem~\ref{lem:Peeling_on_Trees} or \Lem~\ref{lem_crude} to bound $S_h$.
  \begin{description}
    \item[Case 1: $t_0<t\leq g^{2h}$] \Lem~\ref{lem:Peeling_on_Trees} shows that for certain $c_1,c_2>0$ we have
    \begin{align}\label{eqlem:SMSizeGivenHeight_2}
      S_h&\leq \pr\brk{\fn_\root(1,\TT)=h} \leq c_1\exp(-\exp(c_2h))\leq c_12^{-h}\exp(-t^{1/c_3}),
    \end{align}
    provided $c_3$ is chosen large enough.
    \item[Case 2: $t>g^{2h}$] we apply \Lem~\ref{lem_crude} to obtain
    \begin{align}\label{eqlem:SMSizeGivenHeight_3}
      S_h&\leq \pr\brk{\vN_h>t} \leq h\exp(-\sqrt t/4)\leq h2^{-h}\exp(-t^{1/3}),
    \end{align}
    provided that $t>t_0$ is sufficiently large.
  \end{description}
  Combining the bounds~\eqref{eqlem:SMSizeGivenHeight_1}--\eqref{eqlem:SMSizeGivenHeight_3} completes the proof.
\end{proof}


\begin{corollary}\label{cor_c3}
  For any $d<\dpure(k)$ we have $\ex[|\overline{\{\pm1\cdot\root\}}_{\TT}|^2]<\infty.$
\end{corollary}
\begin{proof}
  This is an immediate consequence of \Cor~\ref{lem:SMSizeGivenHeight}.
\end{proof}


\subsection{Proof of \Lem~\ref{lem_EIchi}}\label{sec_lem_EIchi}
Because the distribution of $\PHI'$ is invariant under variable permutations and inversions, we may assume the initial set $\cL$ of literals passed to \pulp\ is just $\cL=\{x_1,\ldots,x_L\}$ for an integer $L=\tilde O(1)$.
For an integer $\ell\geq1$ let $\vec\phi_{\ell,L}'$ be the sub-formula of $\PHI'$ comprising all clauses and variables at distance at most $2\ell$ from $\cL$.
We recall that this formula has a bipartite graph representation $G(\vec\phi_{\ell,L}')$ with variable nodes $V(\vec\phi_{\ell,L}')$, clause nodes $F(\vec\phi_{\ell,L}')$ and edges $E(\vec\phi_{\ell,L}')$.
The {\em excess} of $\vec\phi_{\ell,L}'$ is defined as
\begin{align*}
  \vX_{\ell,L}&=|E(\vec\phi_{\ell,L}')|-|V(\vec\phi_{\ell,L}')|-|F(\vec\phi_{\ell,L}')|.
\end{align*}
Thus, $\vX_{\ell,L}=-L$  iff $G(\vec\phi'_{\ell,L})$ consists of $L$ acyclic components.

\begin{lemma}\label{lem_excess}
  Let $d>0$, $c>0$ and assume that $L\leq\log^cn$ and $\ell\leq c\log\log n$.
  Then
  \begin{align}\label{eqlem_excess1}
    \pr\brk{\vX_{\ell,L}>-L}&= \tilde O(n^{-1}),&\pr\brk{\vX_{\ell,L}>1-L}&= \tilde O(n^{-2}).
  \end{align}
  Furthermore, there exists $c_4=c_4(c,d,k)>0$ such that
  \begin{align}\label{eqlem_excess2}
    \pr\brk{|V(\vec\phi'_{\ell,L})|+|F(\vec\phi'_{\ell,L})|>\log^{c_4}n}&= O(n^{-2}).
  \end{align}
\end{lemma}
\begin{proof}
  We study breadth first search (`BFS') on the graph $G(\PHI')$ from the start vertices $\cL$ by means of a routine deferred decisions argument.
  Throughout the execution of BFS each variable node is in one of three possible states: unexplored, active, or finished.

  Towards the proof of~\eqref{eqlem_excess2} we study a `parallel' version of BFS.
  More precisely, let $\cA_0=\cL$ be the set of initially active variables, let $\cU_0=\{x_1,\ldots,x_n\}\setminus\cL$ comprise the initially unexplored variables and let $\cF_0=\emptyset$.
  Further, for $t\geq0$ define $\cA_{t+1},\cU_{t+1},\cF_{t+1}$ as follows.
  If $\cA_t=\emptyset$ then the process has stopped and we let $\cA_{t+1}=\cA_t=\emptyset,\cU_{t+1}=\cU_t,\cF_{t+1}=\cF_t$.
  Otherwise let $\cA_{t+1}$ be the set of all variable nodes $y\in\cU_{t}$ such that there exist an active variable node $x\in\cA_t$ and a clause $a$ that contains $x$ and $y$; in symbols, $x,y\in\partial_{\PHI'}a$.
  Further, let $\cF_{t+1}=\cF_t\cup\cA_t$ and $\cU_{t+1}=\cU_t\setminus\cA_{t+1}$.
  The BFS exploration occurs `in parallel' in the sense that all active vertices activate their previously unexplored second neighbours simultaneously.

  Let $\fF_t$ be the $\sigma$-algebra generated by the first $t$ rounds of parallel exploring.
  Then the distribution of $|\cA_{t+1}|$ given $\fF_t$ is stochastically dominated by a random variable with distribution $(k-1)\Po(d|\cA_t|)$.
  This is because by the construction of the formula $\PHI'$ the total number of clauses containing a given variable node has distribution $\Po(d(1-(k-1)/n))$.
  Hence, for any $u>0$ we have
  \begin{align}\label{eqlem_excess3}
    \pr\brk{|\cA_{t+1}|>u\mid\fF_t}&\leq\pr\brk{(k-1)\Po(d|\cA_t|)>u}.
  \end{align}

  To complete the proof of \eqref{eqlem_excess2} we mimic the argument from the proof of \Lem~\ref{lem_crude}.
  Thus, let $u=\log^{c_4-3}n$ for a large enough $c_4=c_4(c,d,k)$ and set $g=10(1+d(k-1))$.
  Since $\ell\leq c\log\log n$, the bound \eqref{eqlem_excess3} and Bennett's inequality show that
  \begin{align*}
    \pr\brk{|\cA_{t+1}|>g^{t+1-\ell}u\mid|\cA_t|\leq g^{t-\ell}u}&\leq\exp\bc{-\frac{u}{4g^{\ell-t+1}}}\leq\exp(-\sqrt u/4)=O(n^{-3})&&(0\leq t<\ell).
  \end{align*}
  Hence, taking a union bound on $0\leq t<\ell$ and observing that $|V(\vec\phi'_{\ell,L})|\subset\cA_0\cup\cdots\cup\cA_\ell$, we obtain
  \begin{align}\label{eqlem_excess4}
    \pr\brk{|V(\vec\phi'_{\ell,L})|>u\log n}&=\tilde O(n^{-3}).
  \end{align}
  Finally, another application of Bennett's inequality demonstrates that with probability $1-O(n^{-2})$ no variable of $\PHI'$ appears in more than $\log n$ clauses.
  Thus, $|F(\vec\phi'_{\ell,L})|\leq|V(\vec\phi'_{\ell,L})|\log n$.
  Hence, \eqref{eqlem_excess4} implies~\eqref{eqlem_excess2}.

  We are left to establish~\eqref{eqlem_excess1}.
  The way we set up the BFS process implies that there are only two ways in which excess edges can come about.
  First, there may be clauses $a$ with $\partial_{\PHI'}a\subset\cA_t\cup\cA_{t+1}$ such that $|\partial_{\PHI'}a\cap\cA_t|\geq2$.
  Given that $|\cA_t\cup\cA_{t+1}|\leq\log^{c_4}n$, the number of such $a$ with $|\partial_{\PHI'}a\cap\cA_t|=2$ has distribution $\Po(\tilde O(1/n))$, and the number of $a$ with $|\partial_{\PHI'}a\cap\cA_t|>2$ has distribution $\Po(\tilde O(1/n^2))$.
  The second possibility is that for a variable $x\in\cA_{t+1}$ there exist clauses $a,b\in\partial_{\PHI'}x$ with $\partial_{\PHI'}a,\partial_{\PHI'}b\subset\cA_t\cup\cA_{t+1}$.
  Once again the number of such clauses has distribution $\Po(\tilde O(1/n))$ given $|\cA_t\cup\cA_{t+1}|\leq\log^{c_4}n$.
  Furthermore, excess inducing clauses occur independently at different rounds $t$ of the BFS process.
  Thus, \eqref{eqlem_excess1} follows from~\eqref{eqlem_excess2}.
\end{proof}

We proceed to derive bounds on $|\bar\cL|=|\bar\cL_{\PHI'}|$ depending on the value of the excess.
To deal with the case of excess $-L$, let $\Lambda=\Theta(\log\log n)$ and let $(\TT[i])_{i\geq1}$ be a sequence of independent copies of the random tree $\TT$.
In the case that the excess $\vX_{\Lambda,L}$ equals $-L$, the bound on $|\bar\cL|$ follows from the fact that the Galton-Watson tree $\TT$ captures the local structure of the graph $G(\PHI')$ in combination with the bound from \Cor~\ref{lem:SMSizeGivenHeight}.
More precisely, the following is true.

\begin{lemma}\label{lem_noexcess}
  For any $0<d<\duniq(k)$ and $c>0$ there exists $\zeta=\zeta(c,d,k)>0$ such that with $\Lambda=\lceil\zeta\log\log n\rceil$ uniformly for all $1\leq L\leq\log^cn$ and all $u>0$ we have
  \begin{align*}
    \pr\brk{\vecone\{\vX_{\Lambda,L}=-L\}|\bar\cL|>u}&\leq\pr\brk{\sum_{i=1}^L|\overline{\{r\}}_{\TT[i]}|>u}+O(n^{-2}).
  \end{align*}
\end{lemma}
\begin{proof}
  We begin by coupling the random formula $\vec\phi'_{\ell,1}$ with the Galton-Watson tree $\TT^{(\ell)}[1]$ for $0\leq\ell\leq\Lambda$.
  The coupling operates in accordance with the iterations of the BFS process from the proof of
  \Lem~\ref{lem_excess}.
  Under the coupling some of the variable and clause nodes of $\vec\phi'_{\ell,1}$ and of the tree $\TT^{(\ell)}[1]$ are identical, but both $\TT^{(\ell)}[1]$ and $\vec\phi'_{\ell,1}$ may contain additional clauses or variables.
  These additional clauses/variables result from excess edges of $G(\vec\phi_{\ell,1}')$, i.e., edges that close cycles or merge different components in the course of the BFS process.

  For $\ell=0$ we just identify the start variable $x_1$ with the root $\root$ of the Galton-Watson tree $\TT[1]$.
  Going from $\ell$ to $\ell+1$, we remember the sets $\cA_\ell,\cA_{\ell+1}$ from the proof of \Lem~\ref{lem_excess}.
  For each variable $x\in\cA_\ell$ let $\cC_x$ be the set of clauses $a\in\partial_{\PHI'}x$ such that $|\partial_{\PHI'}a\cap\cA_{\ell+1}|=k-1$ and such that none of the variables $y\in\cA_{\ell+1}\cap\partial_{\PHI'}a$ appear in another clause $b\neq a$ with $\partial_{\PHI'}b\subset\cA_\ell\cup\cA_{\ell+1}$.
  In other words, $\cC_x$ contains all clauses $a\in\partial_{\PHI'}x$ that do not induce excess edges.
  Let $\vd_x=|\cC_x|$ be the number of such clauses.
  As we pointed out in the proof of \Lem~\ref{lem_excess}, $\vd_x$ is stochastically dominated by a $\Po(d)$ variable.
  Hence, there is a random variable $\vd_x'$ such that $\vd_x+\vd_x'\disteq\Po(d)$.

  For any variable $x\in\cA_\ell$ that is also a variable node of $\TT^{(\ell)}[1]$ we add all clauses $a\in\cC_x$ and the $k-1$ variables $y\in\partial_{\PHI'}a\cap\cA_{\ell+1}$ to $\TT^{(\ell+1)}[1]$.
  Additionally, $\TT^{(\ell+1)}[1]$ contains $\vd_x'$ independent random clauses that contain $x$ and $k-1$ new variable nodes without a counterpart in $\vec\phi'_{\ell+1,1}$.
  Finally, to complete $\TT^{(\ell+1)}[1]$ every variable $y$ of $\TT^{(\ell)}[1]$ at distance precisely $2\ell$ from $r$ such that $y\not\in V(\vec\phi_{\ell,1}')$ independently begets $\Po(d)$ offspring clause nodes, each containing $k-1$ new variable nodes that do not belong to $V(\vec\phi_{\ell+1,1}')$.

  The coupling ensures that $\vec\phi_{\Lambda,1}'$ is a sub-formula of $\TT^{(\Lambda)}[1]$ unless $\vX_{\Lambda,1}>-L$.
  The extension of this coupling to $\cL=\{x_1,\ldots,x_L\}$ is straightforward.
  We simply perform BFS exploration from the start variables $x_1,\ldots,x_L$ one after the other.
  Given that $\vX_{\Lambda,L}=-L$, we thus couple the sub-formula of $\PHI'$ explored from each $x_i$ with $\TT^{(\Lambda)}[i]$ for $1\leq i\leq L$ such that $\vec\phi'_{\Lambda,L}$ is contained in the union of $\TT^{(\Lambda)}[1],\ldots,\TT^{(\Lambda)}[L]$.
  Finally, we obtain independent copies $\TT[1],\ldots,\TT[L]$ of the (possibly infinite) tree $\TT$ by continuing the Galton-Watson processes $\TT^{(\Lambda)}[i]$ independently for depths $\ell>\Lambda$.

  The remaining task is to compare $|\bar\cL|$ with $\sum_{i=1}^L|\overline{\{r\}}_{\TT[i]}|$.
  If $\vX_{\Lambda,L}=-L$ and if $\fn_\root(1,\TT[i])<\Lambda$ for all $1\leq i\leq L$, then the coupling ensures that all clauses and variables of $\vec\phi_{\Lambda,L}'$ are contained in the disjoint union of the trees $\TT[1],\ldots,\TT[L]$, and thus $|\bar\cL|\leq\sum_{i=1}^L|\overline{\{r\}}_{\TT[i]}|$.
  Therefore, for any $u>0$ we have
  \begin{align}\label{eq_lem_noexcess1}
    \pr\brk{\vecone\cbc{\vX_{\Lambda,L}=-L,\,\max_{1\leq i\leq L}\fn_\root(1,\TT[i])<\Lambda}|\bar\cL|>u}&\leq\pr\brk{\sum_{i=1}^L|\overline{\{r\}}_{\TT[i]}|>u}.
  \end{align}
  Furthermore, since $\Lambda\geq\zeta\log\log n$ for a large $\zeta>0$, \Lem~\ref{lem:Peeling_on_Trees} ensures that
  \begin{align}\label{eq_lem_noexcess2}
    \pr\brk{\max_{1\leq i\leq L}\fn_\root(1,\TT[i])\geq\Lambda}&\leq O(n^{-2}).
  \end{align}
  Combining~\eqref{eq_lem_noexcess1} and~\eqref{eq_lem_noexcess2} completes the proof.
\end{proof}

For later reference we make a note of the following immediate consequence of the coupling from the proof of \Lem~\ref{lem_noexcess}.
For two rooted Boolean formulas $\phi,\phi'$ we write $\phi\ism\phi'$ if there is an isomorphism of $\phi$ and $\phi'$ that preserves the root variable.
We consider the random formula $\vec\phi'_{\ell,1}$ rooted at $x_1$.

\begin{corollary}\label{cor_lcwk}
  For every $\ell \ge0$ and any fixed tree $T$ we have $\left|\Pr\brk{\TT^{(\ell)}\ism T}- \Pr\brk{\vec\phi'_{\ell,1}\ism T}\right| = o(1).$
\end{corollary}

{\em From here on we set $\Lambda=\lceil c_5\log\log n\rceil$ for a large enough $c_5=c_5(d,k)>0$.}
We obtain the following bound on the second moment of $|\bar\cL|$ on the event that the excess equals $-L$.

\begin{corollary}\label{lem:coup}
  For any $0<d<\duniq(k)$ and any $1\leq L\leq\log^2n$ we have $\ex[\vecone\{\vX_{\Lambda,L}=-L\}|\bar\cL|^2]=O(1)$.
\end{corollary}
\begin{proof}
  Since $|\bar\cL|\leq 2n$ deterministically, this is an immediate consequence of \Cor~\ref{lem:SMSizeGivenHeight} and \Lem~\ref{lem_noexcess}.
\end{proof}

As a next step we deal with the case that the excess equals $1-L$.
More precisely, with $c_6=c_6(d,k)\gg c_5$ a large enough constant let $\Lambda^+=c_6\log\log n$.
We are going to bound $|\bar\cL|$ on the event that $\vX_{\Lambda,L}=\vX_{\Lambda^+,L}=1-L$.
The proof combines the bound on the probability of this event from \Lem~\ref{lem_excess} with a crude bound on $|\bar\cL|$.
To elaborate, since \Lem~\ref{lem_excess} shows that the event $\vX_{\Lambda,L}=\vX_{\Lambda^+,L}=1-L$ has probability $\tilde O(n^{-1})$, we can essentially get away with simply bounding $|\bar\cL|$ by the total number of variables within a $2\Lambda^+$ radius around the start variables $\cL$.
Indeed, as \Lem~\ref{lem_excess} shows, this number of variables is very likely polylogarithmic in $n$.
Working out the details, we obtain the following.

\begin{lemma}\label{lem_unicyc}
  Let $0<d<\duniq(k)$ and let $1\leq L\leq\log^2n$.
  Then $\ex\brk{\vecone\{\vX_{\Lambda,L}=\vX_{\Lambda^+,L}=1-L\}|\bar\cL|^{3/2}}=o(1).$
\end{lemma}
\begin{proof}
  Let $\cL^+=V(\vec\phi'_{\Lambda,L})\setminus V(\vec\phi'_{\Lambda-1,L})$ and obtain $\vec\phi^-$ from $\PHI'$ by deleting all variables from $V(\vec\phi'_{\Lambda-1,L})$ and all clauses from $F(\vec\phi'_{\Lambda,L})$. 
  Further, let $\Lambda^-=\Lambda^+-\Lambda$ and let $\vec\phi^+$ be the sub-formula of $\vec\phi^-$ comprising all clauses and variables of $\vec\phi^-$ with distance at most $2\Lambda^-$ from $\cL^+$.
  If $\vX_{\Lambda,L}=\vX_{\Lambda^+,L}=1-L$ then
  \begin{align}\label{eqlem_unicyc_1}
    |V(\vec\phi'_{\Lambda,L})|+|F(\vec\phi'_{\Lambda,L})|-|E(\vec\phi'_{\Lambda,L})|&=1-L,\\
    |V(\vec\phi^+)|+|F(\vec\phi^+)|-|E(\vec\phi^+)|&=-|\cL^+|.\label{eqlem_unicyc_2}
  \end{align}
  Moreover, \Lem~\ref{lem_excess} shows that for suitable $c_5'=c_5'(d,k,c_5),c_6'=c_6'(d,k,c_6)>0$ we have
  \begin{align}\label{eqlem_unicyc_3}
    \pr\brk{|V(\vec\phi'_{\Lambda,L})|+|F(\vec\phi'_{\Lambda,L})|>\log^{c_5'}n}&= O(n^{-2}),\\
    \label{eqlem_unicyc_4}
    \pr\brk{|V(\vec\phi'_{\Lambda^+,L})|+|F(\vec\phi'_{\Lambda^+,L})|>\log^{c_6'}n}&= O(n^{-2}).
  \end{align}

  Let $\hat\cL\subset\bar\cL$ be the set of literals $l$ that were added to the output set $\bar\cL$ by Step~7 of \pulp\ by way of clauses $a\in F(\vec\phi'_{\Lambda,L})$, i.e., at distance less than $2\Lambda$ from the initial set $\cL$.
  Let $\cL^-=\{|l|:l\in\hat\cL\}\cap\cL^+$ be the set of all variables at distance $2L$ from $\cL$ in $\PHI'$ that underlie a literal from $\hat\cL$.
  If $\vX_{\Lambda,L}=1-L$, the variables and clauses at distance at most $\Lambda$ from $\cL$ do not cause \pulp\ to run into a contradiction, because each clause contains $k\geq3$ literals.
  Therefore, there does not exist a variable $x$ such that both $x$ and $\neg x$ belong to $\hat\cL$.
  Hence, because the signs of $\PHI'$ are uniformly random and \pulp\ proceeds in a BFS order, we may assume without loss that $\hat\cL$ contains positive literals only.
  Thus,
  \begin{align}\label{eqlem_unicyc_10}
    \cL^-=\hat\cL\cap\cL^+\subset\cL^+.
  \end{align}

  We now apply \Lem~\ref{lem_noexcess} to the random formula $\vec\phi^-$.
  Specifically, let $\bar\cL^+$ be the output of \pulp\ on the formula $\vec\phi^-$ with the start set $\cL^+$.
  Further, let $\fE$ be the event that $|V(\vec\phi'_{\Lambda,L})|+|F(\vec\phi'_{\Lambda,L})|\leq\log^{c_5'}n$  and  let
  $$\vX^+=|V(\vec\phi^+)|+|F(\vec\phi^+)|-|E(\vec\phi^+)|$$
  be the excess of $\vec\phi^+$.
  Since $0<d<\duniq(k)$, given $\fE$ the formula $\vec\phi^-$ has the same distribution as a random $k$-CNF with $n^-=n-O(\log^cn)$ variables and $\vm^-\disteq\Po(d^-n^-/k)$ random clauses, with $0<d^-=d+o(1)<\duniq(k)$.
  Hence, assuming that $c_6=c_6(d,k)> c_5'$ is sufficiently large, \Lem~\ref{lem_noexcess} shows that
  \begin{align}\label{eqlem_unicyc_5}
    \pr\brk{\vecone\fE\cap\{\vX^+=-|\cL^+|\}\cdot|\bar\cL^+|>u}&\leq\pr\brk{\sum_{1\leq i\leq\log^{c_5'}n}|\overline{\{r\}}_{\TT[i]}|>u}+O(n^{-2})&&(u>0).
  \end{align}
  Combining~\eqref{eqlem_unicyc_5} with \Lem~\ref{lem:SMSizeGivenHeight}, we conclude that for a large enough $c_7=c_7(d,k) > c_6'$,
  \begin{align}\label{eqlem_unicyc_6}
    \pr\brk{\vecone\fE\cap\{\vX^+=-|\cL^+|\}\cdot|\bar\cL^+|>\log^{c_7}n}&=O(n^{-2}).
  \end{align}
  Finally, combining~\eqref{eqlem_unicyc_1}--\eqref{eqlem_unicyc_10} with \eqref{eqlem_unicyc_6} completes the proof.
\end{proof}

\begin{proof}[Proof of \Lem~\ref{lem_EIchi}]
  The assertion is immediate from \Cor~\ref{lem:coup}, \Lem~\ref{lem_unicyc}, \Lem~\ref{lem_excess} and the deterministic bound $|\bar\cL|\leq 2n$.
\end{proof}





\section{Proof of \Prop~\ref{prop_arnab}}\label{sec_prop_arnab}


\noindent
Let $\pi^{(\ell)}_{d,k}=\BP_{d,k}^{\ell}(\delta_{1/2})$ be the distribution obtained after $\ell$ iterations of $\BP_{d,k}(\cdot)$, with the convention $\pi^{(0)}_{d,k}=\delta_{1/2}$.
We recall $(\MU_{\pi,i,j})_{i,j\geq1}$ signify independent random variables with distribution $\pi$.

\begin{fact}\label{prop_identical}
For all $\ell \geq 0$ the random variables $\MU_{\pi^{(\ell)}_{d,k},1,1}$ and $1-\MU_{\pi^{(\ell)}_{d,k},1,1}$ are identically distributed.
\end{fact}

\begin{proof}
This is an immediate consequence of the fact that the random variables $\vd^+,\vd^-$ from the definition~\eqref{eqBPop}--\eqref{eqhat} are identically distributed.
\end{proof}

While the following is a direct consequence of the fact that Belief Propagation is `exact on trees' (see~\cite[\Chap~14]{MM} for precise statements), we carry out a detailed proof for the sake of completeness.
Following the conventions from \Sec~\ref{sec_results_num_sol}, we continue to denote by $\TAU^{(\ell)}$ a random satisfying assignment of the $k$-CNF $\TT^{(\ell)}=\TT^{(\ell)}_{d,k}$.

\begin{fact}\label{fac_BPexact}
For all $\ell\ge 0$, $d>0$ we have $\pr\brk{\TAU^{(\ell)}(r)=1\mid\TT}\disteq\pi^{(\ell)}_{d,k}\enspace.$
\end{fact}
\begin{proof}
We proceed by induction on $\ell$.
As $\pi^{(0)}_{d,k}=\delta_{1/2}$, for $\ell=0$ there is nothing to show.
To go from $\ell-1$ to $\ell\geq1$, for a clause $a\in\partial_\TT r$ and a variable $y\in\partial_\TT a\setminus\cbc\root$ let $\TT_{y\to a}$ be the component of the forest $\TT-a$ obtained by removing clause $a$ that contains variable $y$.
We consider $y$ the root of $\TT_{y\to a}$.
Further, obtain $\TT_{y\to a}^{(\ell-1)}$ from $\TT_{y\to a}$ by deleting all clauses and variables at a distance greater than $2(\ell-1)$ from $y$.
Additionally, for $s\in\PM$ let
\begin{align}\label{eq_fac_BPexact_0}
\vZ^{(\ell)}(s)&=\abs{\cbc{\sigma\in S(\TT^{(\ell)}):\sigma(\root)=s}},&
\vZ_{y\to a}^{(\ell-1)}(s)&=\abs{\cbc{\sigma\in S(\TT_{y\to a}^{(\ell-1)}):\sigma(y)=s}}.
\end{align}
In words, $\vZ^{(\ell)}(s)$ is the number of satisfying assignments of $\TT^{(\ell)}$ that set $\root$ to $s$, and $\vZ_{y\to a}^{(\ell-1)}(s)$ is the corresponding quantity for the sub-tree $\TT^{(\ell-1)}_{y\to a}$.

Clearly, setting $\root$ to $s\in\PM$ immediately satisfies all clauses $a\in\partial_\TT^s\root$.
By contrast, once $\root$ is assigned the value $+1$ each clause $a\in\partial_\TT^{-s}\root$ needs to be satisfied by setting some other variable $y\in\partial_\TT a\setminus\cbc\root$ to the value $\sign(y,a)$.
Hence,
\begin{align}\label{eq_fac_BPexact_1}
\vZ^{(\ell)}(s)&=\brk{\prod_{a\in\partial^+_{\TT}\root}\prod_{y\in\partial_{\TT}a\setminus\cbc\root}\sum_{t\in\PM}\vZ^{(\ell-1)}_{y\to a}\bc t}\cdot\brk{\prod_{a\in\partial^-_\TT\root} \bc{\prod_{y\in\partial_{\TT}a\setminus\cbc\root}\sum_{t\in\PM}\vZ^{(\ell-1)}_{y\to a}\bc t-\prod_{y\in\partial_{\TT}a\setminus\cbc\root}\vZ^{(\ell-1)}_{y\to a}\bc{-\sign(y,a)}}}.
\end{align}
Furthermore, the definition of the Galton-Watson tree $\TT$ ensures that the sub-trees $\TT_{y\to a}^{(\ell-1)}$ are independent copies of $\TT^{(\ell-1)}$.
Hence, by induction we have
\begin{align}\label{eq_fac_BPexact_2}
\frac{\vZ_{y\to a}^{(\ell-1)}(1)}{\sum_{s\in\PM}\vZ_{y\to a}^{(\ell-1)}(s)}&\disteq\pi_{d,k}^{(\ell-1)}&&\mbox{for all }a\in\partial_{\TT}\root,\,y\in\partial_{\TT}a\setminus\cbc\root,
\end{align}
and the random variables $\vZ_{y\to a}^{(\ell-1)}(1)/\sum_{s\in\PM}\vZ_{y\to a}^{(\ell-1)}(s)$ are mutually independent.
Combining~\eqref{eq_fac_BPexact_1}--\eqref{eq_fac_BPexact_2} with Fact~\ref{prop_identical}, we finally obtain
\begin{align*}
\pr\brk{\TAU^{(\ell)}(\root)=1\mid\TT}&=\frac{\vZ^{(\ell)}(1)}{\sum_{s\in\PM}\vZ^{(\ell)}(s)}\disteq\frac{\prod_{i=1}^{\vd^-}\brk{1-\prod_{j=1}^{k-1}\MU_{\pi_{d,k}^{(\ell-1)},2i-1,j}}}{\prod_{i=1}^{\vd^-}\brk{1-\prod_{j=1}^{k-1}\MU_{\pi_{d,k}^{(\ell-1)},2i-1,j}}+\prod_{i=1}^{\vd^+}\brk{1-\prod_{j=1}^{k-1}\MU_{\pi_{d,k}^{(\ell-1)},2i,j}}}\disteq\pi_{d,k}^{(\ell)},
\end{align*}
thereby completing the induction.
\end{proof}

Combining the combinatorial interpretation of the distributions $\pi_{d,k}^{(\ell)}$ with the Gibbs uniqueness property, we proceed to show that the sequence $(\pi_{d,k}^{(\ell)})_\ell$ converges in the weak topology.
To this end, it suffices to show that the sequence is Cauchy with respect to the Wasserstein $W_1$ metric.

\begin{lemma}\label{lem_weak_pi}
If $d < \duniq(k)$ then $(\pi^{(\ell)}_{d,k})_{\ell\geq0}$ is a $W_1$-Cauchy sequence.
\end{lemma}
\begin{proof}
If $d<\duniq(k)$ then the random tree $\TT=\TT_{d,k}$ enjoys the Gibbs uniqueness property; hence, ~\eqref{eqTreeUniq} is satisfied.
Consequently, given $0<\eps<1$ we can choose $\ell_0=\ell_0(d,k,\eps)>0$ large enough so that the event
\begin{align*}
\fU_{\eps,\ell}=\cbc{\max_{\tau\in S(\TT^{(\ell)})}\abs{\pr\brk{\TAU^{(\ell)}(\root)=1\mid\TT}-\pr\brk{\TAU^{(\ell)}(\root)=1\mid\TT,\,\forall x\in\partial^{2\ell}\root:\TAU^{(\ell)}(x)=\tau(x)} }>\eps}
\end{align*}
has probability
\begin{align}\label{eq_lem_weak_pi_1}
\pr\brk{\fU_{\eps,\ell}}&<\eps \enspace,&&\mbox{for all }\ell\geq\ell_0.
\end{align}

Now suppose that $\ell_0\leq\ell<\ell'$.
Let $\TAU^{(\ell)},\TAU^{(\ell')}$ be independent uniformly random satisfying assignments of $\TT^{(\ell)}$ and $\TT^{(\ell')}$, respectively.
We claim that
\begin{align}\label{eq_lem_weak_pi_2}
\pr\brk{\abs{\pr\brk{\TAU^{(\ell)}(\root)=1\mid\TT}-\pr\brk{\TAU^{(\ell')}(\root)=1\mid\TT}}>\eps}&<\eps.
\end{align}
To see this, let $\TAU^{(\ell,\ell')}=(\TAU^{(\ell')}(x))_{x\in\partial^{2\ell}_{\TT}\root}$ comprise the truth values that $\TAU^{(\ell')}$ assigns to the variables at distance exactly $2\ell$ from $\root$.
Then
\begin{align*}
\pr\brk{\TAU^{(\ell')}(\root)=1\mid\TT}&=
\ex\brk{\pr\brk{\TAU^{(\ell')}(\root)=1\mid\TT,\TAU^{(\ell,\ell')}}\mid\TT}\\&=
\ex\brk{\pr\brk{\TAU^{(\ell)}(\root)=1\mid\TT,\TAU^{(\ell,\ell')},\,\forall x\in\partial^{2\ell}\root:\TAU^{(\ell)}(x)=\TAU^{(\ell,\ell')}_x} \mid\TT}.
\end{align*}
Hence, for every $T \in \fU_{\eps,\ell}$ we have
\begin{align}\label{eq_lem_weak_pi_3}
\abs{\pr\brk{\TAU^{(\ell')}(\root)=1\mid\TT = T}-\pr\brk{\TAU^{(\ell)}(\root)=1\mid\TT = T}}&\leq\eps.
\end{align}
Thus, \eqref{eq_lem_weak_pi_2} follows from~\eqref{eq_lem_weak_pi_1} and~\eqref{eq_lem_weak_pi_3}.

Finally, since Fact~\ref{fac_BPexact} demonstrates that $\pr\brk{\TAU^{(\ell)}(\root)=1\mid\TT = T}\disteq\pi_{d,k}^{(\ell)}$ and 
$\pr\brk{\TAU^{(\ell')}(\root)=1\mid\TT = T}\disteq\pi_{d,k}^{(\ell')}$, \eqref{eq_lem_weak_pi_2} shows that
\begin{align*}
W_1\bc{\pi_{d,k}^{(\ell)},\pi_{d,k}^{(\ell')}}&<2\eps&&\mbox{	for all $\ell_0\leq\ell<\ell'$.}
\end{align*}
Hence, the sequence $(\pi_{d,k}^{(\ell)})_\ell$ is Cauchy.
\end{proof}


We are left to bound the lower tail of the limiting distribution $\pi_{d,k}=\lim_{\ell \to \infty}\pi^{(\ell)}_{d,k}$.


\begin{lemma}\label{lem_secmu}
If $d<\duniq(k)$ then $\ex\log^2\MU_{\pi_{d,k},1,1} < \infty$ .
\end{lemma}
\begin{proof}
We are going to bound $\ex\log^2\MU_{\pi_{d,k}^{(\ell)},1,1}$ and subsequently invoke the monotone convergence theorem to complete the proof.
Let $\cL=\cbc\root$.
Then for all $\ell \ge 0$ we have
\begin{align*}
\ex\log^2\MU_{\pi^{(\ell)}_{d,k},1,1} &= \ex\log^2\frac{Z(\TT^{(\ell)}, \cL)}{Z(\TT^{(\ell)})}&&\mbox{[by \Fact~\ref{fac_BPexact}]}\\
&\le \Erw \brk{|\bar\cL(1,\TT)|^2}&&\mbox{[by \Lem~\ref{lem_Ichi}]}\\
&<\infty&&\mbox{[by \Cor~\ref{cor_c3}]}.
\end{align*}
Since $\pi_{d,k}$ is the weak limit of $(\pi_{d,k}^{(\ell)})_\ell$, we conclude that for any $N\in\NN$,
\begin{align}\label{eq_lem_secmu_1}
\ex\brk{ N \wedge \log^2\MU_{\pi_{d,k},1,1} } = \lim_{\ell \to \infty} \ex\brk{N \wedge \log^2\MU_{\pi^{(\ell)}_{d,k},1,1} } \le\Erw \brk{|\bar\cL(1,\TT)|^2}<\infty.
\end{align}
Finally,  applying the monotone convergence theorem to the limit $N\to\infty$, we see that the uniform bound~\eqref{eq_lem_secmu_1} implies the assertion.
\end{proof}

\begin{proof}[Proof of \Prop~\ref{prop_arnab}]
In light of Fact~\ref{prop_identical} and \Lem s~\ref{lem_weak_pi} and \ref{lem_secmu}, it only remains to show that
\begin{align*}
\ex\left|\log\bc{\prod_{i=1}^{\vd^-}\MU_{\pi_{d,k},2i}+\prod_{i=1}^{\vd^+}\MU_{\pi_{d,k},2i-1}}\right| < \infty
&&\text{ and }&&
\ex\left|\log\bc{1-\prod_{j=1}^k\MU_{\pi_{d,k},1,j}}\right| < \infty
\enspace.
\end{align*}
Recall the definition of $\MU_{\pi_{d,k},i}$ from \eqref{eqhat}. Using \Fact~\ref{prop_identical} and \Lem~\ref{lem_secmu}, we obtain
\begin{align*}
\ex\left|\log\bc{\prod_{i=1}^{\vd^-}\MU_{\pi_{d,k},2i}+\prod_{i=1}^{\vd^+}\MU_{\pi_{d,k},2i-1}}\right|
\le \log(2) +   \ex\left|\log{\prod_{i=1}^{\vd^-}\MU_{\pi_{d,k},2i}}\right| 
&\le  \log(2) +  \frac{d}{2} \ex\left|\log \MU_{\pi_{d,k},1}\right|\\
&\le  \log(2) +  \frac{d}{2} \sqrt{ \ex\left|\log^2 {\MU_{\pi_{d,k},1,1}}\right|} < \infty
\enspace,
\end{align*}
yielding the first inequality. Similarly, invoking \Fact~\ref{prop_identical} and \Lem~\ref{lem_secmu} for the second l.h.s. above gives
\begin{align*}
\ex\left|\log\bc{1-\prod_{j=1}^k\MU_{\pi_{d,k},1,j}}\right| 
\le \ex\left|\log\bc{1-\MU_{\pi_{d,k},1,1}}\right|
= \ex\left|\log\bc{\MU_{\pi_{d,k},1,1}}\right|
\le \sqrt{\ex\left|\log^2{\MU_{\pi_{d,k},1,1}}\right|}< \infty
\enspace,
\end{align*}
thereby completing the proof.
\end{proof}


\section{Proof of \Cor~\ref{cor_interpolation}}\label{sec_prop_interpolation}

\noindent
In order to turn the estimate of the expectation of $\log 1\vee Z(\PHI)$ provided by \Prop~\ref{prop_aizenman} into a `with high probability' statement, we harness a `soft' version of the $k$-SAT problem where violated clauses are discouraged but not strictly forbidden.
To be precise, for a $k$-CNF $\Phi$ and a real $\beta>0$ define
\begin{align}\label{eqZbeta_exp}
Z_\beta(\Phi)&=\sum_{\sigma\in\PM^{V(\Phi)}}\prod_{a\in F(\Phi)}\exp(-\beta\vecone\{\sigma\not\models a\}).
\end{align}
Thus, each satisfying assignment contributes one to the sum on the r.h.s.\ of~\eqref{eqZbeta_exp},
while the contribution of assignments that violate a number $M$ of clauses equals $\exp(-\beta M)$.
The value $Z_\beta(\PHI)$, called the {\em partition function of the random $k$-SAT model at inverse temperature $\beta$}, has received a considerable
amount of attention in the mathematical physics literature (see, e.g.,~\cite{PanchenkoBook}).
Crucially, by means of an interpolation argument~\cite{FranzLeone,Guerra} it is possible to prove the following.

\begin{theorem}[{\cite[\Thm~1]{PanchenkoTalagrand}}]\label{thm_interp}
For any $k\geq 3$, any $\beta>0$ and any probability measure $\pi$ on $[0,1]$ we have
\begin{align}\label{eqthm_interp}
\frac1n\ex\brk{\log Z_\beta(\PHI)}&\leq
\ex\brk{\log\bc{\prod_{i=1}^{\vd^-}\MU_{\beta, \pi,2i}+\prod_{i=1}^{\vd^+}\MU_{\beta, \pi,2i-1}}
-\frac{d(k-1)}{k}\log\bc{1-\bc{1- e^{-\beta}}\prod_{j=1}^k\MU_{\pi,1,j}}},&&\mbox{where}\\
\MU_{\beta,\pi,i}&=1-(1-\exp(-\beta))\prod_{j=1}^{k-1}\MU_{\pi,i,j}&&\mbox{ for $i\geq1$}.\nonumber
\end{align}
\end{theorem}

\noindent
We emphasise that the bound~\eqref{eqthm_interp} holds for any $n\geq k$ {\em without} an error term.
We also notice that by the monotone convergence theorem for the measure $\pi=\pi_{d,k}$ from \Thm~\ref{thm_main} we have
\begin{align}\nonumber
\lim_{\beta\to\infty}&
\ex\brk{\log\bc{\prod_{i=1}^{\vd^-}\MU_{\beta, \pi_{d,k},2i}+\prod_{i=1}^{\vd^+}\MU_{\beta, \pi_{d,k},2i-1}}
-\frac{d(k-1)}{k}\log\bc{1-\bc{1- e^{-\beta}}\prod_{j=1}^k\MU_{\pi_{d,k},1,j}}}\\
&= \ex\brk{\log\bc{\prod_{i=1}^{\vd^-}\MU_{ \pi_{d,k},2i}+\prod_{i=1}^{\vd^+}\MU_{ \pi_{d,k},2i-1}}
-\frac{d(k-1)}{k}\log\bc{1-\prod_{j=1}^k\MU_{\pi_{d,k},1,j}}}
\enspace.
\label{eq_dom}
\end{align}

The reason why we proceed by way of the `soft' model with $\beta<\infty$ is that for this model a routine application of Azuma-Hoeffding
implies the following concentration bound.

\begin{lemma}\label{lem_AH}
For any fixed $\beta>0$ we have $\pr\brk{\abs{\log Z_\beta(\PHI)-\ex\log Z_\beta(\PHI)}>\sqrt n\log n}=o(1/n).$
\end{lemma}
\begin{proof}
The clauses of the random formula $\PHI$ are drawn independently, and adding or removing a single clause can alter the value of $\log Z_\beta(\nix)$
by no more than $\pm\beta$.
\end{proof}

\begin{proof}[Proof of \Cor~\ref{cor_interpolation}]
The definition~\eqref{eqZbeta_exp} of the partition function ensures that $Z_\beta(\PHI)\geq Z(\PHI)$ for all $\beta>0$.
Furthermore, \Thm~\ref{thm_interp} and \Lem~\ref{lem_AH} demonstrate that for any fixed $\beta>0$, and any measure $\pi$, we have
\begin{align}\nonumber
\frac1n\log Z(\PHI)\leq
\frac1n\log Z_\beta(\PHI)&\leq
\ex\brk{\log\bc{\prod_{i=1}^{\vd^-}\MU_{\beta, \pi,2i}+\prod_{i=1}^{\vd^+}\MU_{\beta, \pi,2i-1}}
-\frac{d(k-1)}{k}\log\bc{1-\bc{1- e^{-\beta}}\prod_{j=1}^k\MU_{\pi,1,j}}}
+o(1)&&\mbox\whp
\end{align}
Hence, taking $\beta\to\infty$, $\pi=\pi_{d,k}$, and invoking \eqref{eq_dom}, we conclude that
\begin{align}\nonumber%\label{eq_fin_upperBoundCor}
\frac1n\log Z(\PHI)\leq
\ex\brk{\log\bc{\prod_{i=1}^{\vd^-}\MU_{\beta, \pi_{d,k},2i}+\prod_{i=1}^{\vd^+}\MU_{\beta, \pi_{d,k},2i-1}}
-\frac{d(k-1)}{k}\log\bc{1-\prod_{j=1}^k\MU_{\pi_{d,k},1,j}}}
+o(1)&&\mbox\whp
\enspace,
\end{align}
as desired.
\end{proof}


\section{Proof of \Prop~\ref{prop_aizenman}}\label{sec_prop_aizenman}

\noindent
In this section we prove \Prop s~\ref{lem_PHI''} and \ref{lem_PHI'''}, which in light of \Fact~\ref{fact_coupling},
imply \Prop~\ref{prop_aizenman}.
Both proofs follow a similar structure and make use of \Prop s~\ref{prop_bad} and~\ref{prop_benign}, which we therefore prove first.

\subsection{Proof of \Prop~\ref{prop_bad}}\label{sec_prop_bad}

We show that both terms of \eqref{eq_prop_bad} have finite expectation.
Let us begin with the first one.

\begin{lemma}\label{lem_bad''}
If $d<\duniq(k)$ then $\ex\brk{\left|\log\frac{Z(\PHI'')\vee 1}{Z(\PHI')\vee 1}\right|^{3/2}}=O(1)$.
\end{lemma}
\begin{proof}
Since $\PHI''$ is obtained from $\PHI'$ by adding clauses, we have
\begin{align}\label{eq_lem_PHI''_1_1}
0\leq Z(\PHI'')\leq Z(\PHI')\leq 2^n.
\end{align}
Hence,
\begin{align}\label{eq_lem_bad''_1}
\log\frac{Z(\PHI'')\vee 1}{Z(\PHI')\vee 1}=0&&\mbox{ if }Z(\PHI')=0.
\end{align}
Therefore, we may assume from now on that $\PHI'$ is satisfiable.

The number $\vDelta''\disteq\Po(d(k-1)/k)$ of new clauses is a Poisson variable with bounded mean.
Therefore, Bennett's inequality shows that $\pr\brk{\vDelta''>\log n}=O(n^{-2})$.
Since~\eqref{eq_lem_PHI''_1_1} shows that $|\log((Z(\PHI'')\vee 1)/(Z(\PHI')\vee 1))|^{3/2}\leq n^{3/2}$, we conclude that
\begin{align}\label{eq_lem_PHI''_1_4}
\ex\brk{\vecone\cbc{\vDelta''>\log n}\cdot \left|\log\frac{Z(\PHI'')\vee 1}{Z(\PHI')\vee 1}\right|^{3/2}}&=o(1).
\end{align}

Further, let $c_1,\ldots,c_{\vDelta''}$ be the new clauses added by {\bf CPL2}.
Let $\vx_{1,1},\ldots,\vx_{1,k},\ldots,\vx_{\vDelta'',1},\ldots,\vx_{\vDelta'',k}$ be their constituent variables and let $\cX=\{\vx_{1,1},\ldots,\vx_{1,k},\ldots,\vx_{\vDelta'',1},\ldots,\vx_{\vDelta'',k}\}$.
Since the clauses $c_1,\ldots,c_{\vDelta''}$ are chosen uniformly and independently, a routine balls-into-bins consideration shows that
\begin{align}\label{eq_lem_PHI''_1_2}
\pr\brk{|\cX|\leq k(\vDelta''-1)\mid\vDelta''\leq\log n}&=\tilde O(n^{-2}).
\end{align}

Now, consider the `good' event
\begin{align*}
\fG&=\cbc{Z(\PHI')>0,\,\vDelta''\leq\log n,\,|\cX|> k(\vDelta''-1)}.
\end{align*}
Combining~\eqref{eq_lem_PHI''_1_1}--\eqref{eq_lem_PHI''_1_2}, we see that
\begin{align}\label{eq_lem_PHI''_1_3}
\ex\brk{(1-\vecone\fG)\cdot\left|\log\frac{Z(\PHI'')\vee 1}{Z(\PHI')\vee 1}\right|^{3/2}}&=o(1).
\end{align}
Hence, we are left to bound $\ex[\vecone\fG\cdot|\log((Z(\PHI'')\vee 1)/(Z(\PHI')\vee1))|^{3/2}]$.
If $\fG$ occurs and thus $|\cX|>k(\vDelta''-1)$, then there exists a set of literals $\cL\subset\cbc{\vx_{1,1},\neg\vx_{1,1},\ldots,\vx_{1,k},\neg\vx_{1,k},\ldots,\vx_{\vDelta'',1},\neg\vx_{\vDelta'',1},\ldots,\vx_{\vDelta'',k},\neg \vx_{\vDelta'',k}}$ such that
\begin{itemize}
\item every clause $c_i$ contains a literal from $\cL$ ($1\leq i\leq\vDelta''$), and
\item there does not exist $x\in\cX$ such that $x\in\cL$ and $\neg x\in\cL$.
\end{itemize}
Moreover, on $\fG$ we have $|\cL|\leq|\cX|\leq k\log n$.
Let $\bar\cL=\bar\cL_{\PHI'}$ be the output of \pulp\ on $(\PHI',\cL)$.
Then \Lem~\ref{lem_Ichi} shows that
\begin{align}\label{eq_lem_PHI''_1_3a}
\ex\brk{\vecone\fG\cdot\left|\log\frac{Z(\PHI'')\vee 1}{Z(\PHI')\vee 1}\right|^{3/2}}&\leq\ex\brk{\vecone\fG\cdot\abs{\bar\cL}^{3/2}}.
\end{align}
Furthermore, since by {\bf CPL2} the new clauses $c_1,\ldots,c_{\vDelta''}$ are chosen independently of the formula $\PHI'$, \Lem~\ref{lem_EIchi} implies that there exists $C=C(d,k)>0$ such that
\begin{align}\label{eq_lem_PHI''_1_3b}
\ex\brk{\vecone\fG\cdot\abs{\bar\cL}^{3/2}\mid\vDelta''}&\leq C\cdot\bc{\vDelta''}^{3/2}.
\end{align}
Combining~\eqref{eq_lem_PHI''_1_3a}--\eqref{eq_lem_PHI''_1_3b} and recalling that $\vDelta''\disteq\Po(d(k-1)/k)$, we obtain
\begin{align}\label{eq_lem_PHI''_1_3c}
\ex\brk{\vecone\fG\cdot\left|\log\frac{Z(\PHI'')\vee 1}{Z(\PHI')\vee 1}\right|^{3/2}}&=O(1).
\end{align}
Finally, the assertion follows from~\eqref{eq_lem_PHI''_1_3} and \eqref{eq_lem_PHI''_1_3c}.
\end{proof}

We move on to the second term of \eqref{eq_prop_bad}.

\begin{lemma}\label{lem_bad'''}
If $d<\duniq(k)$ then $\ex\brk{\left|\log\frac{Z(\PHI''')\vee 1}{Z(\PHI')\vee 1}\right|^{3/2}}=O(1)$.
\end{lemma}
\begin{proof}
We proceed similarly as in the proof of \Lem~\ref{lem_bad''}.
The construction in {\bf CPL3} ensures that $\PHI'''$ contains one additional variable $x_{n+1}$ and $\vDelta'''\disteq\Po(d)$ new clauses $b_1,\ldots,b_{\vDelta'''}$ that each contain $x_{n+1}$ and $k-1$ other variables.
Let $\vx_{1,1},\ldots,\vx_{1,k-1},\ldots,\vx_{\vDelta''',1},\ldots,\vx_{\vDelta''',k-1}\in\{x_1,\ldots,x_n\}$ be the variables among $x_1,\ldots,x_n$ that appear in $b_1,\ldots,b_{\vDelta'''}$ and let $\cX=\{\vx_{1,1},\ldots,\vx_{\vDelta''',k-1}\}$.
Then
\begin{align}\label{eq_lem_PHI'''_1_1}
0\leq Z(\PHI'')\leq 2Z(\PHI')\leq 2^{n+1}.
\end{align}
Hence, if $\PHI'$ is unsatisfiable, then so is $\PHI'''$ and thus
\begin{align}\label{eq_lem_PHI'''_1_1a}
\log\frac{Z(\PHI''')\vee 1}{Z(\PHI')\vee1}&=0&&\mbox{ if }Z(\PHI')=0.
\end{align}
Furthermore, since $\vDelta'''\disteq\Po(d)$, Bennett's inequality shows that $\pr\brk{\vDelta'''>\log n}=O(n^{-2})$.
Therefore, \eqref{eq_lem_PHI'''_1_1} shows that
\begin{align}\label{eq_lem_PHI'''_1_2}
\ex\brk{\vecone\cbc{\vDelta'''>\log n}\cdot \left|\log\frac{Z(\PHI''')\vee 1}{Z(\PHI')\vee1}\right|^{3/2}}&=o(1).
\end{align}
Moreover, since the $k-1$ variables among $x_1,\ldots,x_n$ that appear in the clauses $b_1,\ldots,b_{\Delta'''}$ are chosen uniformly and independently, a simple balls-into-bins argument shows that
\begin{align}\label{eq_lem_PHI'''_1_2_a}
\pr\brk{|\cX|\leq(k-1)(\vDelta''-1)\mid\vDelta''\leq\log n}&=\tilde O(n^{-2}).
\end{align}

Hence, consider the event
\begin{align*}
\fG&=\cbc{Z(\PHI')>0,\,\vDelta'''\leq\log n,\,|\cX|>(k-1)(\vDelta''-1)}.
\end{align*}
Combining~\eqref{eq_lem_PHI'''_1_1}--\eqref{eq_lem_PHI'''_1_2_a}, we obtain
\begin{align}\label{eq_lem_PHI'''_1_2_b}
\ex\brk{(1-\vecone\fG)\cdot \left|\log\frac{Z(\PHI''')\vee 1}{Z(\PHI')\vee1}\right|^{3/2}}&=o(1).
\end{align}
Furthermore, if the event $\fG$ occurs, then there exists a set $\cL\subseteq\{x,\neg x:x\in\cX\}$ of literals such that each clause $b_i$, $1\leq i\leq\vDelta'''$, contains a literal $l\in\cL$ and such that $\{x,\neg x\}\not\subseteq\cL$ for all $x\in\cX$.
Hence, with $\bar\cL=\bar\cL_{\PHI'}$ the output of \pulp\ on $(\PHI',\cL)$, \Lem~\ref{lem_Ichi} shows that
\begin{align}\label{eq_lem_PHI'''_1_2_c}
\ex\brk{\vecone\fG\cdot \left|\log\frac{Z(\PHI''')\vee 1}{Z(\PHI')\vee1}\right|^{3/2}}&\leq\ex\brk{\vecone\fG\cdot|\bar\cL|^{3/2}}.
\end{align}
Furthermore, since the clauses $b_1,\ldots,b_{\vDelta'''}$ are drawn independently of $\PHI'''$, \Lem~\ref{lem_EIchi} shows that there exists $C=C(d,k)>0$ such that
\begin{align}\label{eq_lem_PHI'''_1_2_d}
\ex\brk{\vecone\fG\cdot|\bar\cL|^{3/2}\mid\vDelta'''}&\leq C\cdot(\vDelta''')^{3/2}.
\end{align}
Finally, since $\vDelta'''\disteq\Po(d)$, the assertion follows from~\eqref{eq_lem_PHI'''_1_2_b}, \eqref{eq_lem_PHI'''_1_2_c} and~\eqref{eq_lem_PHI'''_1_2_d}.
\end{proof}


\begin{proof}[Proof of \Prop~\ref{prop_bad}]
The proposition follows immediately from \Lem s~\ref{lem_bad''}--\ref{lem_bad'''}.
\end{proof}


\subsection{Proof of \Prop~\ref{prop_benign}}\label{sec_prop_benign}

Let $\pi_{d,k}^{(\ell)}=\BP_{d,k}^\ell(\delta_{1/2})$ be the result of an $\ell$-fold application of the operator $\BP_{d,k}$ from~\eqref{eqBPop} to the point mass at $1/2$.
Also recall from~\eqref{eqempirical} that $\vec\pi_n'$ denotes the empirical distribution %of the marginals $\pr\brk{\SIGMA_{\PHI'}(x_1, \ldots, x_n)=1\mid\PHI'}$.
of the marginals $(\pr[\SIGMA_{\PHI'}(x_i)=1\mid\PHI'])_{1\leq i\leq n}$.

\begin{lemma}\label{lem_benign}
Suppose that $d<\duniq(k)$.
For any $\eps>0$ there exists $\ell_0=\ell_0(d,k,\eps)>0$ such that for all $\ell\geq\ell_0$ we have $$\ex[W_1(\vec\pi_n',\pi_{d,k}^{(\ell)})\mid Z(\PHI')>0]<\eps+o(1).$$
\end{lemma}
\begin{proof}
Assume that $\ell\geq\ell_0$ for a large enough $\ell_0=\ell_0(d,k,\eps)>0$.
Since $d<\duniq(k)$ and since $\TT=\TT_{d,k}$ is a Galton-Watson tree in which every variable node has $\Po(d)$ clause nodes as offspring and the offspring of every clause node is $k-1$ variable nodes, there exists a finite set $\cT_\ell$ of trees such that the following conditions hold:
\begin{description}
\item[T0] for every $T\in\cT_\ell$ we have $\pr\brk{\TT^{(\ell)}=T}>0$.
\item[T1] $\pr\brk{\TT^{(\ell)}\in\cT_\ell}>1-\eps$.
\item[T2] given $\TT^{(\ell)}\in\cT_\ell$ we have
\begin{align*}
\max_{\tau\in S(\TT^{(\ell)})}\abs{\pr\brk{\TAU^{(\ell)}(r)=1\mid\TT^{(\ell)}} -\pr\brk{\TAU^{(\ell)}(r)=1\mid\TT^{(\ell)},\,\forall x\in\partial^{2\ell}r:\TAU^{(\ell)}(x)=\tau(x)} }&<\eps.
\end{align*}
\end{description}

For a variable node $x_i$ of $\PHI'$ obtain $\vec\phi'_{\ell}(x_i)$ from $\PHI'$ by deleting all variables and clauses at distance greater than $2\ell$ from $x_i$.
We consider $x_i$ the root of $\vec\phi'_{\ell}(x_i)$.
Moreover, for a tree $T\in\cT_\ell$ let $\cV_T$ be the set of variable nodes $x_i$, $1\leq i\leq n$, such that $\vec\phi'_{\ell}(x_i)\ism T$; thus, there is an isomorphism of the CNFs $T$ and $\vec\phi'_\ell(x_i)$ that maps the root $\root$ of $T$ to $x_i$.
Consider the event
\begin{align}\label{eq_lem_benign_100}
\fT_\ell&=\cbc{\sum_{T\in\cT_\ell}\abs{\pr\brk{\TT^{(\ell)}\ism T}-|\cV_T|/n}<\eps}.
\end{align}
Then \Cor~\ref{cor_lcwk} implies that
\begin{align}\label{eq_lem_benign_1}
\pr\brk{\fT_\ell}&=1-o(1)&&\mbox{for every }\ell\geq0.
\end{align}

We now claim that
\begin{align}\label{eq_lem_benign_4}
\abs{\pr\brk{\TAU^{(\ell)}(r)=1\mid\TT^{(\ell)}=T}-\pr\brk{\SIGMA_{\PHI'}(x_i)=1\mid \PHI'}}<\eps&&\mbox{ for all }T\in\cT_\ell,\,x_i\in\cV_T.
\end{align}
To see this, let $S_\ell(\PHI',x_i)$ be the set of all assignments $\sigma\in\PM^{\partial^{2\ell}x_i}$ of the variables at distance $2\ell$ from $x_i$ in $\PHI'$ such that there exists a satisfying assignment $\sigma'\in S(\PHI')$ with $\sigma'(y)=\sigma(y)$ for all $y\in\partial^{2\ell}x_i$.
Then the law of total probability shows that
\begin{align}\label{eq_lem_benign_2}
\pr\brk{\SIGMA_{\PHI'}(x_i)=1\mid \PHI'}&=\sum_{\sigma\in S_\ell(\PHI',x_i)}\pr\brk{\SIGMA_{\PHI'}(x_i)=1\mid \PHI',\,\forall y\in \partial^{2\ell}x_i : \SIGMA_{\PHI'}(y)=\sigma(y)}\pr\brk{\forall y\in \partial^{2\ell}x_i : \SIGMA_{\PHI'}(y)=\sigma(y)\mid\PHI'}.
\end{align}
Further, since for $T\in\cT_\ell$ and $x_i\in\cV_T$ we have $\vec\phi_\ell'(x_i)\ism T$, condition {\bf T2} implies that
\begin{align}\label{eq_lem_benign_3}
\abs{\pr\brk{\SIGMA_{\PHI'}(x_i)=1\mid \PHI',\,\forall y\in \partial^{2\ell}x_i : \SIGMA_{\PHI'}(y)=\sigma(y)}-\pr\brk{\TAU^{(\ell)}(r)=1\mid \TT^{(\ell)}=T}}&<\eps.
\end{align}
Combining~\eqref{eq_lem_benign_2} and~\eqref{eq_lem_benign_3}, we obtain~\eqref{eq_lem_benign_4}.

To complete the proof, we recall from Fact~\ref{fac_BPexact} that $\pi_{d,k}^{(\ell)}$ is precisely the distribution of $\pr\brk{\TAU^{(\ell)}(r)=1\mid\TT^{(\ell)}}$.
Therefore, on the event $\fT_\ell$ we have
\begin{align*}
W_1(\vec\pi_n',\pi_{d,k}^{(\ell)})&\leq\pr\brk{\TT^{(\ell)}\not\in\cT_\ell}+\frac1n\sum_{T\in\cT_\ell}\sum_{x\in\cV_t}\abs{\pr\brk{\TAU^{(\ell)}(r)=1\mid\TT^{(\ell)}=T}-\pr\brk{\SIGMA_{\PHI'}(x_i)=1\mid \PHI'}}+\eps&&\mbox{[by~\eqref{eq_lem_benign_100}]}\\
&\leq3\eps&&\mbox{[by {\bf T1} and \eqref{eq_lem_benign_4}].}
\end{align*}
Combining this bound with~\eqref{eq_lem_benign_1} completes the proof.
\end{proof}


\begin{proof}[Proof of \Prop~\ref{prop_benign}]
The assertion follows from \Prop~\ref{prop_arnab}, \Lem~\ref{lem_benign} and the triangle inequality.
\end{proof}



\subsection{Proof of Proposition~\ref{lem_PHI''}}\label{sec_lem_PHI''}

As in the proof of \Lem~\ref{lem_bad''} let $c_1,\ldots,c_{\vDelta''}$ be the new clauses added by {\bf CPL2} and let $\vx_{1,1},\ldots,\vx_{1,k},\ldots,\vx_{\vDelta'',1},\ldots,\vx_{\vDelta'',k}$ be their constituent variables.
Let $\cX=\{\vx_{1,1},\ldots,\vx_{1,k},\ldots,\vx_{\vDelta'',1},\ldots,\vx_{\vDelta'',k}\}$.
For $\eps > 0$ and $z \in \RR$ define $\lambda_\eps(z) = \log(z\vee\eps)$.
Finally, let $(\vs_i)_{i\geq0}$ be a sequence of uniformly random $\pm1$-valued random variables, mutually independent and independent of all other randomness.


\begin{lemma}\label{lem_PHI''_2}
Assume that $d<\duniq(k)$.
There exists $B=B(d,k)>0$ such that for all $0<\eps<1$ we have
\begin{align*}
\limsup_{n\to\infty}\ex\brk{\bc{\sum_{i=1}^{\vDelta''}\lambda_\eps\bc{1-\prod_{j=1}^k
\pr\brk{\SIGMA(\vx_{i,j})\neq\sign(\vx_{i,j},c_i)\mid\PHI'}}}^2\mid Z(\PHI')>0}\leq B.
\end{align*}
\end{lemma}
\begin{proof}
Given $Z(\PHI')>0$ we have
\begin{align}\label{eq_lem_PHI''_2_2}
0&\geq\lambda_\eps\bc{1-\prod_{j=1}^k
\pr\brk{\SIGMA(\vx_{1,j})\neq\sign(\vx_{1,j}, c_1)\mid\PHI'}
}\geq
\lambda_\eps\bc{1-\pr\brk{\SIGMA(\vx_{1,1})\neq\sign(\vx_{1,1}, c_1)\mid\PHI'}}.
\end{align}
Recalling that $\vDelta''\disteq\Po(d(k-1)/k)$, we combine~\eqref{eq_lem_PHI''_2_2} with Cauchy-Schwarz to obtain $B'=B'(d,k)>0$ such that
\begin{align}\nonumber
\ex&\brk{\bc{\sum_{i=1}^{\vDelta''}\lambda_\eps\bc{1-\prod_{j=1}^k\pr\brk{\SIGMA(\vx_{i,j})\neq\sign(\vx_{i,j}, c_i)\mid\PHI'}}}^2\mid Z(\PHI')>0}\\
&\leq B'\cdot \ex\brk{\lambda_\eps\bc{1-\pr\brk{\SIGMA(\vx_{1,1})\neq\sign(\vx_{1,1}, c_1)\mid\PHI'}}^2\mid Z(\PHI')>0}\label{eq_lem_PHI''_2_1}.
\end{align}
Further, since the function $\lambda_\eps$ is bounded and continuous for every $\eps>0$ and since $\sign(\vx_{1,1}, c_1)$ is chosen independently of $\PHI'$, \Prop~\ref{prop_benign} shows that for any $\eps>0$,
\begin{align}\nonumber
\ex\brk{\lambda_\eps\bc{1-\pr\brk{\SIGMA(\vx_{1,1})\neq\sign(\vx_{1,1}, c_1)\mid\PHI'}}^2\mid Z(\PHI')>0}&= \ex\brk{\lambda_\eps\bc{\MU_{\pi_{d,k},1,1}}^2}+o(1) \\
&\leq\ex\brk{\log\bc{\MU_{\pi_{d,k},1,1}}^2}+o(1).\label{eq_lem_PHI''_2_3}
\end{align}
Since \Prop~\ref{prop_arnab} shows that $\ex\brk{\log\bc{\MU_{\pi_{d,k},1,1}}^2}=O(1)$, the assertion follows from \eqref{eq_lem_PHI''_2_1} and \eqref{eq_lem_PHI''_2_3}.
\end{proof}

\begin{lemma}\label{lem_PHI''_3}
Assume that $d<\duniq(k)$.
For any $\delta>0$ there exists $\eps_0>0$ such that for all $\eps_0>\eps>0$ we have
\begin{align*}
\limsup_{n\to\infty}\abs{\ex\brk{\log\frac{Z(\PHI'')\vee 1}{Z(\PHI')\vee 1}}-\frac{d(k-1)}k\ex\brk{\lambda_\eps\bc{1-\prod_{j=1}^k\pr\brk{\SIGMA(x_j)=\vs_j\mid\PHI'}}\mid Z(\PHI')>0}}<\delta.
\end{align*}
\end{lemma}
\begin{proof}
We choose small enough $\xi=\xi(d,k,\delta)>\zeta(\xi)>\eta=\eta(\zeta)>\eps_0=\eps_0(\eta)>0$, let $0<\eps<\eps_0$ and assume that $n\ge n_0(\eps)$ is large enough.
Also let $\gamma=\gamma(n)=o(1)$ be a sequence that tends to zero sufficiently slowly.
Additionally, let $\fE$ be the event that all of the following conditions occur.
\begin{description}
\item[E1] $Z(\PHI')>0.$
\item[E2] $\vDelta''\leq\zeta^{-1}.$
\item[E3] $|\cX|=k\vDelta''.$
\item[E4] $\max_{x\in\cX,s\in\PM}\pr[\SIGMA(x)=s\mid\PHI']\leq1-\eta.$
\item[E5] $\sum_{\tau\in\PM^{\cX}}\abs{\pr[\forall x\in\cX:\SIGMA(x)=\tau(x)\mid\PHI']-\prod_{x\in\cX}\pr[\SIGMA(x)=\tau(x)\mid\PHI']}<\gamma.$
\end{description}

We claim that
\begin{align}\label{eqlem_PHI''_3_1}
\pr\brk{\fE}&\geq1-2\xi+o(1).
\end{align}
Indeed, since $0<d < \duniq(k) <\dsat(k)$, we have that $\pr\brk{Z(\PHI')>0}=1-o(1)$.
Moreover, since $\vDelta^{\prime \prime}\disteq\Po(d(k-1)/k)$, Markov's inequality shows that $\pr\brk{\vDelta''>\zeta^{-1}}\leq\zeta d <\xi$.
Further, since the new clauses $c_1,\ldots,c_{\vDelta''}$ are chosen independently, we have $\pr\brk{|\cX|=k\vDelta''\mid\vDelta''\leq\zeta^{-1}}=1-O(1/n)$.
Similarly, \Prop~\ref{prop_benign} shows together with \eqref{eq_prop_arnab_bound} that
\begin{align*}
\pr\brk{\max_{x\in\cX,s\in\PM}\pr[\SIGMA(x)=s\mid\PHI']\leq1-\eta\mid\vDelta''\leq\zeta^{-1},\,Z(\PHI')>0}\geq1-\xi,
\end{align*}
provided that $\eta$ is chosen small enough.
Similarly, \Prop~\ref{prop_benign} shows together with Markov's inequality that
\begin{align*}
\pr\brk{\mbox{{\bf E5} occurs}\mid\vDelta'',\,Z(\PHI')>0}=1-o(1)
\enspace ,
\end{align*}
provided that $\gamma\to\infty$ sufficiently slowly.
Thus, we obtain \eqref{eqlem_PHI''_3_1}.

Furthermore, \eqref{eqlem_PHI''_3_1} implies together with
\Prop~\ref{prop_bad}
and H\"older's inequality that
\begin{align}\label{eqlem_PHI''_3_2}
\ex\abs{(1-\vecone\fE)\cdot\log\frac{Z(\PHI'')}{Z(\PHI')}}&\leq\delta/3+o(1),
\end{align}
provided that $\xi=\xi(d,k,\delta)>0$ is small enough.
Analogously, \eqref{eqlem_PHI''_3_1}, \Lem~\ref{lem_PHI''_2} and Cauchy-Schwarz yield
\begin{align}\label{eqlem_PHI''_3_3}
\ex\abs{(1-\vecone\fE)\lambda_\eps\bc{1-\prod_{j=1}^k\pr\brk{\SIGMA(x_j)=\vs_j\mid\PHI'}}}&\leq\delta/3+o(1).
\end{align}

Thus, we confine ourselves to the event $\fE$, on which we have $Z(\PHI'),Z(\PHI'')>0$ due to {\bf E1}, {\bf E3}, {\bf E4} and {\bf E5}.
Hence,
\begin{align}\nonumber
\log\frac{Z(\PHI'')\vee1}{Z(\PHI')\vee1}&=\log\frac{Z(\PHI'')}{Z(\PHI')}=
\log\sum_{\tau\in\PM^{\cX}}\vecone\cbc{\tau\models c_1,\ldots,c_{\vDelta''}}\pr[\forall x\in\cX:\SIGMA(x)=\tau(x)\mid\PHI']\\
&=\log\sum_{\tau\in\PM^{\cX}}\vecone\cbc{\tau\models c_1,\ldots,c_{\vDelta''}}\prod_{x\in\cX}\pr[\SIGMA(x)=\tau(x)\mid\PHI']+o(1)&&\mbox{[by {\bf E4, E5}]}\nonumber\\
&=\sum_{i=1}^{\vDelta''}\log\brk{1-\prod_{j=1}^k\pr\brk{\SIGMA(\vx_{i,j})\neq\sign(\vx_{i,j},c_i)\mid\PHI'}} +o(1)	&&\mbox{[by {\bf E3}].}
\label{eqlem_PHI''_3_4}
\end{align}
Further, {\bf E4} ensures that for any $1\leq i\leq\Delta''$,
\begin{align}
\abs{\log\brk{1-\prod_{j=1}^k\pr\brk{\SIGMA(\vx_{i,j})\neq\sign(\vx_{i,j},c_i)\mid\PHI'}}-\lambda_\eps\brk{1-\prod_{j=1}^k\pr\brk{\SIGMA(\vx_{i,j})\neq\sign(\vx_{i,j}, c_i)\mid\PHI'}}}<\xi.
\label{eqlem_PHI''_3_5}
\end{align}
Thus, combining \eqref{eqlem_PHI''_3_4} and~\eqref{eqlem_PHI''_3_5}, we obtain
\begin{align}
\ex\abs{\vecone\fE\bc{\log\frac{Z(\PHI'')\vee1}{Z(\PHI')\vee1}-\sum_{i=1}^{\vDelta''}\lambda_\eps\bc{1-\prod_{j=1}^k\pr\brk{\SIGMA(\vx_{i,j})\neq\sign(\vx_{i,j}, c_i)\mid\PHI'}}}}&<\delta/3+o(1).
\label{eqlem_PHI''_3_6}
\end{align}
Further, combining \eqref{eqlem_PHI''_3_2} and \eqref{eqlem_PHI''_3_6} with \Lem~\ref{lem_PHI''_2}, we obtain
\begin{align}\label{eqlem_PHI''_3_7}
\abs{\ex\brk{\log\frac{Z(\PHI'')\vee1}{Z(\PHI')\vee1}}-\ex\brk{\sum_{i=1}^{\vDelta''}\lambda_\eps\bc{1-\prod_{j=1}^k\pr\brk{\SIGMA(\vx_{i,j})\neq\sign(\vx_{i,j},c_i)\mid\PHI'}}\mid Z(\PHI')>0}}&<\delta+o(1).
\end{align}
Finally, since the clauses $c_1,\ldots,c_{\vDelta''}$ are drawn uniformly and independently and since the distribution of $\PHI'$ is invariant under permutation of the variable nodes, we find
\begin{align}\nonumber
\ex&\brk{\sum_{i=1}^{\vDelta''}\lambda_\eps\bc{1-\prod_{j=1}^k\pr\brk{\SIGMA(\vx_{i,j})\neq\sign(\vx_{i,j},c_i)\mid\PHI'}\mid Z(\PHI')>0}}\\
&=\frac{d(k-1)}{k}\ex\brk{\lambda_\eps\bc{1-\prod_{j=1}^k\pr\brk{\SIGMA(x_j)=\vs_j}\mid\PHI'}\mid Z(\PHI')>0}.\label{eqlem_PHI''_3_8}
\end{align}
Combining~\eqref{eqlem_PHI''_3_7} and~\eqref{eqlem_PHI''_3_8} completes the proof.
\end{proof}

\begin{proof}[Proof of \Prop~\ref{lem_PHI''}]
\Prop~\ref{prop_benign} shows together with \Lem~\ref{lem_PHI''_3} that
\begin{align}\label{eq_lem_PHI''_A}
\ex\brk{\log\frac{Z(\PHI'')\vee 1}{Z(\PHI')\vee 1}}&=\frac{d(k-1)}k\ex\brk{\lambda_\eps\bc{1-\prod_{j=1}^k\MU_{\pi_{d,k},1,j}}}+o_\eps(1),
\end{align}
with $o_\eps(1)$ hiding a term that vanishes in the limit $\eps\to0$.
Furthermore, in light of~\eqref{eq_prop_arnab_bound} the monotone convergence theorem yields
\begin{align}\label{eq_lem_PHI''_B}
\ex\brk{\log\bc{1-\prod_{j=1}^k\MU_{\pi_{d,k},1,j}}}&=\lim_{\eps\to0}\ex\brk{\lambda_\eps\bc{1-\prod_{j=1}^k\MU_{\pi_{d,k},1,j}}}.
\end{align}
The assertion follows from~\eqref{eq_lem_PHI''_A} and~\eqref{eq_lem_PHI''_B}.
\end{proof}

\subsection{Proof of \Prop~\ref{lem_PHI'''}}\label{sec_lem_PHI'''}
We adapt the steps from \Sec~\ref{sec_lem_PHI''} to the coupling of $\PHI'$, $\PHI'''$.
Recall that the latter is obtained by adding to $\PHI'$ a single variable $x_{n+1}$ along with $\vDelta'''$ clauses $b_1,\ldots,b_{\vDelta'''}$ that each contain $x_{n+1}$ and $k-1$ other variables.
Thus, let $\vx_{1,1},\ldots,\vx_{1,k-1},\ldots,\vx_{\vDelta''',1},\ldots,\vx_{\vDelta''',k-1}\in\{x_1,\ldots,x_n\}$ be the variables other than $x_{n+1}$ that appear in $b_1,\ldots,b_{\vDelta'''}$ and let $\cX=\{\vx_{1,1},\ldots,\vx_{\vDelta''',k-1}\}$ be the set comprising all these variables.


\begin{lemma}\label{lem_PHI'''_2}
Assume that $0<d<\duniq(k)$.
There exists $B=B(d,k)>0$ such that for all $0<\eps<1$ we have
\begin{align*}
\limsup_{n\to\infty}\ex\brk{ \lambda_\eps\bc{\sum_{s\in\PM}\prod_{i=1}^{\vDelta'''}1-\vecone\{\sign(x_{n+1},b_i)\neq s\}\prod_{j=1}^{k-1}\pr[\SIGMA(\vx_{i,j})\neq\sign(\vx_{i,j}, b_i)\mid\PHI']}^2 \mid Z(\PHI')>0}&\leq B.
\end{align*}
\end{lemma}
\begin{proof}
Given that $\PHI'$ is satisfiable we have
\begin{align*}
0\wedge\lambda_\eps&\bc{\sum_{s\in\PM}\prod_{i=1}^{\vDelta'''}1-\vecone\{\sign(x_{n+1},b_i)\neq s\}\prod_{j=1}^{k-1}\pr[\SIGMA(\vx_{i,j})\neq\sign(\vx_{i,j}, b_i)\mid\PHI']}\\
&\geq \lambda_\eps\bc{\prod_{i=1}^{\vDelta'''}\pr[\SIGMA(\vx_{i,1})=\sign(\vx_{i,1}, b_i)\mid\PHI']}\geq\sum_{i=1}^{\vDelta'''}\lambda_\eps(\pr[\SIGMA(\vx_{i,1})=\sign(\vx_{i,1}, b_i)\mid\PHI']).
\end{align*}
Since $\vDelta'''\disteq\Po(d)$ and the clauses $b_i$ are uniformly random and independent, we therefore obtain
\begin{align}
\ex&\brk{ \lambda_\eps\bc{\sum_{s\in\PM}\prod_{i=1}^{\vDelta'''}1-\vecone\{\sign(x_{n+1},b_i)\neq s\}\prod_{j=1}^{k-1}\pr[\SIGMA(\vx_{i,j})\neq\sign(\vx_{i,j},b_i)\mid\PHI']}^2 \mid Z(\PHI')>0}\nonumber\\
&\leq\ex\brk{\bc{\sum_{i=1}^{\vDelta'''}(1+\lambda_\eps(\pr[\SIGMA(\vx_{i,1})=\sign(\vx_{i,1}, b_i)\mid\PHI'])}^2\mid Z(\PHI')>0}\nonumber\\
&\leq d(d+1)\ex\brk{\bc{1+\lambda_\eps(\pr[\SIGMA(\vx_{1,1})=\sign(\vx_{1,1}, b_1)\mid\PHI'])}^2\mid Z(\PHI')>0}\nonumber\\
&\leq4d(d+1)\bc{1+\ex\brk{\lambda_\eps(\pr[\SIGMA(\vx_{1,1})=\sign(\vx_{1,1}, b_1)\mid\PHI'])^2\mid Z(\PHI')>0}}.
\label{eq_lem_PHI'''_2_2}
\end{align}
Further, \Prop~\ref{prop_benign} implies that for any $\eps>0$,
\begin{align}
\ex\brk{\lambda_\eps(\pr[\SIGMA(\vx_{1,1})=\sign(\vx_{1,1}, b_1)\mid\PHI'])^2\mid Z(\PHI')>0}&= \ex\brk{\lambda_\eps(\MU_{\pi_{d,k},1,1})^2}+o(1)\leq \ex\brk{\log^2\MU_{\pi_{d,k},1,1}}+o(1).
\label{eq_lem_PHI'''_2_3}
\end{align}
Finally, the assertion follows from \eqref{eq_lem_PHI'''_2_2} and~\eqref{eq_lem_PHI'''_2_3}.
\end{proof}

\begin{lemma}\label{lem_PHI'''_3}
Assume that $0<d<\duniq(k)$.
For any $\delta>0$ there exists $\eps_0>0$ such that for all $\eps_0>\eps>0$ we have
\begin{align*}
\limsup_{n\to\infty}&\Bigg|\ex\brk{\log\frac{Z(\PHI''')\vee 1}{Z(\PHI')\vee 1}}\\&-\ex\brk{\lambda_\eps\bc{\sum_{s\in\PM}\prod_{i=1}^{\vDelta'''}1-\vecone\{\sign(x_{n+1},b_i)\neq s\}\prod_{j=1}^{k-1}\pr[\SIGMA(\vx_{i,j})\neq\sign(\vx_{i,j}, b_i)\mid\PHI']}^2 \mid Z(\PHI')>0}\Bigg|<\delta.
\end{align*}
\end{lemma}
\begin{proof}
Choose small enough $\xi=\xi(d,k,\delta)>\zeta(\xi)>\eta=\eta(\zeta)>\eps_0=\eps_0(\eta)>0$, let $0<\eps<\eps_0$, suppose that $n>n_0(\eps)$ is sufficiently large and let $0<\gamma=\gamma(n)=o(1)$ be a sequence that converges to zero slowly.
Let $\fE$ be the event that the following conditions occur.
\begin{description}
\item[E1] $Z(\PHI')>0$.
\item[E2] $\vDelta'''\leq\zeta^{-1}$.
\item[E3] $|\cX|=(k-1)\vDelta'''$.
\item[E4] $\max_{x\in\cX,s\in\PM}\pr[\SIGMA(x)=s\mid\PHI']\leq1-\eta$.
\item[E5] $\sum_{\tau\in\PM^{\cX}}\abs{\pr[\forall x\in\cX:\SIGMA(x)=\tau(x)\mid\PHI']-\prod_{x\in\cX}\pr[\SIGMA(x)=\tau(x)\mid\PHI']}<\gamma$
\end{description}
As in the proof of \Lem~\ref{lem_PHI''_3} we find that
\begin{align}\label{eqlem_PHI'''_3_1}
\pr\brk{\fE}&\geq1-2\xi+o(1).
\end{align}

Let
\begin{align*}
\vL_\eps&= \lambda_\eps\bc{\sum_{s\in\PM}\prod_{i=1}^{\vDelta'''}1-\vecone\{\sign(x_{n+1}, b_i)\neq s\}\prod_{j=1}^{k-1}\pr[\SIGMA(\vx_{i,j})\neq\sign(\vx_{i,j}, b_i)\mid\PHI']}
\end{align*}
for brevity.
Combining \Prop~\ref{prop_bad}, \Lem~\ref{lem_PHI'''_2} and \eqref{eqlem_PHI'''_3_1} and using H\"older's inequality, we obtain
\begin{align}\label{eqlem_PHI'''_3_2}
\ex\abs{(1-\vecone\fE)\log\frac{Z(\PHI'')}{Z(\PHI')}}&\leq\delta/3+o(1),&
\ex\abs{(1-\vecone\fE)\vL_\eps\mid Z(\PHI')>0}&\leq\delta/3+o(1).
\end{align}

Hence, we are left to compare $\ex\abs{\vecone\fE\cdot\log\frac{Z(\PHI'')}{Z(\PHI')}}$ and $\ex\abs{\vecone\fE\cdot\vL_\eps\mid Z(\PHI')>0}$.
On the event $\fE$ we have $Z(\PHI'),Z(\PHI''')>0$.
Consequently,
\begin{align}\nonumber
\log\frac{Z(\PHI''')\vee1}{Z(\PHI')\vee1}&=\log\frac{Z(\PHI''')}{Z(\PHI')}=
\log\sum_{\tau\in\PM^{\cX\cup\{x_{n+1}\}}}\vecone\cbc{\tau\models b_1,\ldots,b_{\vDelta'''}}\pr[\forall x\in\cX:\SIGMA(x)=\tau(x)\mid\PHI']\\
&=\log\sum_{\tau\in\PM^{\cX\cup\{x_{n+1}\}}}\vecone\cbc{\tau\models b_1,\ldots,b_{\vDelta'''}}\prod_{x\in\cX}\pr[\SIGMA(x)=\tau(x)\mid\PHI']+o(1)&&\mbox{[by {\bf E4, E5}]}\nonumber\\
&=\log\brk{\sum_{s\in\PM}\prod_{i=1}^{\vDelta'''}1-\vecone\cbc{\sign(x_{n+1}, b_i)\neq s}\prod_{j=1}^{k-1}\pr\brk{\SIGMA(\vx_{i,j})\neq\sign(\vx_{i,j},c_i)\mid\PHI'}} +o(1)	&&\mbox{[by {\bf E3}].}
\label{eqlem_PHI'''_3_4}
\end{align}
Now, {\bf E4} guarantees that
\begin{align}
\log\brk{\sum_{s\in\PM}\prod_{i=1}^{\vDelta'''}1-\vecone\cbc{\sign(x_{n+1},b_i)\neq s}\prod_{j=1}^{k-1}\pr\brk{\SIGMA(\vx_{i,j})\neq\sign(\vx_{i,j}, c_i)\mid\PHI'}}&=\vL_\eps.
\label{eqlem_PHI'''_3_5}
\end{align}
Therefore, we combine \eqref{eqlem_PHI'''_3_4} and~\eqref{eqlem_PHI'''_3_5} to obtain
\begin{align}
\ex\abs{\vecone\fE\bc{\log\frac{Z(\PHI''')\vee1}{Z(\PHI')\vee1}-\vL_\eps}}&<\delta/3+o(1).
\label{eqlem_PHI'''_3_6}
\end{align}
Finally, the assertion follows from \eqref{eqlem_PHI'''_3_2} and \eqref{eqlem_PHI'''_3_6}.
\end{proof}

\begin{proof}[Proof of \Prop~\ref{lem_PHI'''}]
Following similar steps as in the proof of \Prop~\ref{lem_PHI''}, we see that the assertion follows from \Lem~\ref{lem_PHI'''_3}, \Prop~\ref{prop_aizenman} and the dominated convergence theorem.
\end{proof}

\begin{proof}[Proof of \Prop~\ref{prop_aizenman}]
Immediate from Fact~\ref{fact_coupling}, \Prop~\ref{lem_PHI''} and \Prop~\ref{lem_PHI'''}.
\end{proof}


