\subsection{Proof of \Lem~\ref{lem:ExtremalBnd}}
The proof is by induction on the height of the tree.
The following claim summarises the main step of the induction.

\begin{claim}\label{Lemma_Noela}
For all $\ell\geq0$, all variables $x$ of ${\TT}^{(\ell)}$ and all
satisfying assignments $\tau\in S({\TT}^{(\ell)})$ we have
\begin{align}\label{eqLemma_Noela1}
\frac{Z({\TT}_x^{(\ell)},\tau,\TAU^+(x))}{Z(\TT_x^{(\ell)},\tau)}
&\leq\frac{Z({\TT}_x^{(\ell)},\TAU^+,\TAU^+(x))}{Z(\TT_x^{(\ell)},\TAU^+)}.
\end{align}
\end{claim}

\begin{proof}
For boundary variables $x\in\partial^{\ell} \root$ there is nothing to show
because the r.h.s.\ of \eqref{eqLemma_Noela1} equals one.
Hence, consider a variable $x\in\partial^{2q}\root$ for some $q<\ell$.
If $Z({\TT}_x^{(\ell)},\tau,\TAU^+(x))=0$, then \eqref{eqLemma_Noela1} is
trivially satisfied. Hence, assume that
$Z({\TT}_x^{(\ell)},\tau,\TAU^+(x))>0$.

Let $a_1^+,\ldots,a_g^+$ be the children (clauses) of $x$ with
$\sign(x,a_i^+)=\TAU^+(x)$. Also let
$y_{11},\ldots,y_{1(k-1)}, \ldots, y_{g1}, \ldots, y_{g(k-1)}$ be
the children (variables) of $a_1^+,\ldots,a_g^+$.
Similarly, let $a_1^-,\ldots,a_h^-$ be the children of $x$ with
$\sign(x,a_i^-)=-\TAU^+(x)$ and let
$z_{11},\ldots,z_{1(k-1)}, \ldots, z_{h1}, \ldots, z_{h(k-1)}$ be their
children.
We claim that for all $\tau\in S({\TT}^{(\ell)})$,
\begin{align}%\label{eqLemma_Noela2}
Z({\TT}_x^{(\ell)},\tau,\TAU^+(x))
&=
\left(
\prod_{i=1}^g
\prod_{t=1}^{k-1}
Z({\TT}_{y_{it}}^{(\ell)},\tau)
\right)
\cdot
\prod_{j=1}^h
\left(
\prod_{t=1}^{k-1}
Z({\TT}_{z_{jt}}^{(\ell)},\tau)
-
\prod_{t=1}^{k-1}
Z({\TT}_{z_{jt}}^{(\ell)},\tau,-\TAU^+(z_{jt}))
\right)
\label{eq:SplusMax}
\enspace,
\\
Z({\TT}_x^{(\ell)},\tau,-\TAU^+(x))
&=
\prod_{i=1}^g
\left(
\prod_{t=1}^{k-1}
Z({\TT}_{y_{it}}^{(\ell)},\tau)
-
\prod_{t=1}^{k-1}
Z({\TT}_{y_{it}}^{(\ell)},\tau, \TAU^+_{y_{it}})
\right)
\cdot
\left(
\prod_{j=1}^h
\prod_{t=1}^{k-1}
Z({\TT}_{z_{jt}}^{(\ell)},\tau)
\right)
\label{eq:SminusMax}
\enspace.
\end{align}
For setting $x$ to $\TAU^+(x)$ satisfies $a_1^+,\ldots,a_g^+$; hence,
arbitrary satisfying assignments of the sub-trees ${\TT}_{y_it}^{(\ell)}$
can be combined, which explains the first product in \eqref{eq:SplusMax}.
By contrast, upon assigning $x$ the value $\TAU^+(x)$ we need to ensure
that each of the clauses $a_1^-,\ldots,a_g^-$ are satisfied by at least
one variable other than $x$. This explains the second factor of
\eqref{eq:SplusMax}.
A similar argument yields \eqref{eq:SminusMax}.
Dividing \eqref{eq:SminusMax} by \eqref{eq:SplusMax} and invoking the
induction hypothesis (for $q+1$), we obtain
\begin{align*}
\frac{Z({\TT}_x^{(\ell)},\tau,-\TAU^+(x))}{Z(\TT_x^{(\ell)},\tau,\TAU^+(x))}
&=
\prod_{i=1}^g
\left(1-\prod_{t=1}^{k-1}
\frac{Z({\TT}_{y_{it}}^{(\ell)},\tau,\TAU^+(y_{it}))}
{Z({\TT}_{y_{it}}^{(\ell)},\tau)}
\right)
\cdot
\prod_{j=1}^h
\left(
1-
\prod_{t=1}^{k-1}
\frac{Z({\TT}_{z_{jt}}^{(\ell)},\tau, -\TAU^+(z_i))}
{Z({\TT}_{z_{jt}}^{(\ell)},\tau)}
\right)^{-1}
\\
&\ge
\prod_{i=1}^g
\left(1-\prod_{t=1}^{k-1}
\frac{Z({\TT}_{y_{it}}^{(\ell)},\TAU^+,\TAU^+(y_{it}))}
{Z({\TT}_{y_{it}}^{(\ell)},\TAU^+)}
\right)
\cdot
\prod_{j=1}^h
\left(
1-
\prod_{t=1}^{k-1}
\frac{Z({\TT}_{z_{jt}}^{(\ell)},\TAU^+, -\TAU^+(z_i))}
{Z({\TT}_{z_{jt}}^{(\ell)},\TAU^+)}
\right)^{-1}
=\frac{Z({\TT}_x^{(\ell)},\TAU^+,-\TAU^+(x))}
{Z({\TT}_x^{(\ell)},\TAU^+,\TAU^+(x))} \enspace ,
\end{align*}
completing the induction.
\end{proof}


\begin{proof}[Proof of \Lem~\ref{lem:ExtremalBnd}]
Applying Claim~\ref{Lemma_Noela} to $x=\root$ completes the proof of \Lem~\ref{lem:ExtremalBnd}.
\end{proof}



\subsection{Proof of Lemma \ref{lem_SmallOnTop}}\label{sec:lem:SmallOnTop}
We employ the {\pulp} algorithm introduced in \Sec~\ref{sec_pulp} and its analysis on the random tree from \Sec~\ref{sec_treepulp}.
Recall that given an initial set of literals $\cL$, {\pulp} returns a superset $\bar\cL$ with the property that the partial assignment obtained from setting all literals of  $\bar\cL$ to true, leaves no clause with only unsatisfying literals.
Let us write $\vN_{x,s}$ for the size of of the output set $\bar\cL$ of {\pulp} initialized with the literal set $\cL =\{s \cdot x\}$.

\begin{claim}\label{cor_from_Ichi}
Let $0\leq t<\ell$ and assume that $x\in \partial^{2t}_\TT\root$ satisfies $\vN_{x,s} < \ell - t$.
Then for all $\tau\in S(\TT^{(\ell)})$ and $s \in \{\pm 1\}$,
\begin{align}
Z({\TT}_x^{(\ell)},\tau)\leq 2^{\vN_{x,s}}\cdot Z(\TT_x^{(\ell)},\tau,s)
\enspace.
\end{align}
\end{claim}
\begin{proof}
Notice that under our assumption on the size of $\vN_{x,s}$, the assignment $\tau$ does not clash with the one imposed by {\pulp}.
The assertion therefore follows immediately from %\Cor~\ref{cor_from_Ichi}.
the same argument as in the proof of \Lem~\ref{lem_Ichi}.
\end{proof}



\begin{claim}\label{cl_size_t_GWtree}
We have $\lim_{t \to \infty} \Pr\brk{ |\partial_{\TT}^{2t} \root |>(200d\cdot (k-1))^{t}} = 0$.
\end{claim}
\begin{proof}
This is an immediate consequence of \Lem~\ref{lem_crude}.
\end{proof}


\begin{proof}[Proof of \Lem~\ref{lem_SmallOnTop}]
Assume that $\ell>ct^c$ for a large enough $c=c(d,k)>0$ and that $t>t_0=t_0(d,k)$ is sufficiently large.
Then \Cor~\ref{lem:SMSizeGivenHeight} shows that
\begin{align}\label{eq_tail_Nct}
\Pr\brk{\vN_{\root, \pm 1} \ge t^c} \le \exp(-t^2) \enspace.
\end{align}
Combining \Cl~\ref{cl_size_t_GWtree} with \eqref{eq_tail_Nct} and using the union bound, we obtain a sequence $\varepsilon_t \to 0$ such that
\begin{align}\label{eq_UnOnN}
\Pr \brk{ \forall x \in \partial^{2t}_\TT\root: \vN_{x, \pm 1} < t^c} \ge 1-\eps_t
\enspace.
\end{align}
If $x \in \partial_\TT^{2t}\root$ satisfies $\vN_{x, \pm 1} < t^c$ and $\ell > ct^c$, then Claim~\ref{cor_from_Ichi} yields that for all $x\in \partial^{2t}\root$
\begin{align}\label{eq_Inter_diffN}
\left|\ETA^{(\ell)}_x\right| \le \log \frac{Z(\TT^{(\ell)}_x, \SIGMA^+)}{Z(\TT^{(\ell)}_x, \SIGMA^+, +1)} +
\log \frac{Z(\TT^{(\ell)}_x, \SIGMA^+)}{Z(\TT^{(\ell)}_x, \SIGMA^+, -1)}
\le \vN_{x, +1} + \vN_{x, -1}\le 2t^c \enspace.
\end{align}
The result now follows from \eqref{eq_UnOnN} and \eqref{eq_Inter_diffN}.
\end{proof}


\subsection{Proof of \Prop~\ref{prop_BPPureLit}}\label{sec_prop_BPPureLit}


We focus on the operator $\LDELitS{{k},d}$ introduced in \Sec~\ref{sec_uniq_outline}.
Let $\rho = \left(\rho_{\AllKid}, \rho_{\PureP}, \rho_{\PureM} \right)$, and
${\rho'} = \left({\rho}'_{\AllKid}, {\rho}'_{\PureP}, {\rho}'_{\PureM}\right)$
be two arbitrary triplets in
$\cP (-\infty,\infty] \times \cP (0, +\infty] \times \cP(-\infty, 0] $, and write
$\hat\rho = \left(\hat\rho_{\AllKid}\hat\rho_{\PureP}, \hat\rho_{\PureM} \right)$ and 
$\hat\rho' = \left(\hat\rho'_{\AllKid}\hat\rho'_{\PureP}, \hat\rho'_{\PureM} \right)$ for the 
images $\LDELitS{{k},d}(\rho)$ and $\LDELitS{{k},d}(\rho')$, respectively.
We wish to bound $\dist_{d}\left(\hat\rho, \hat\rho'\right)$ in terms of $\dist_{d}\left(\rho, \rho'\right)$.

To this end, we begin with bounding the $W_1$-distance separately for each of the coordinates $(\hat\rho_{\PureP}, \hat\rho'_{\PureP}),
(\hat\rho_{\PureM}, \hat\rho'_{\PureM})$ and $(\hat\rho_{\AllKid}, \hat\rho'_{\AllKid})$. Observe that  
it is sufficient to consider only $W_1(\hat\rho_{\PureP}, \hat\rho'_{\PureP})$ and $W_1(\hat\rho_{\PureM}, \hat\rho'_{\PureM})$, 
as the triangle inequality implies that $W_1(\hat\rho_{\AllKid}, \hat\rho'_{\AllKid}) \le 
W_1(\hat\rho_{\PureP}, \hat\rho'_{\PureP})+ W_1(\hat\rho_{\PureM}, \hat\rho'_{\PureM})$.

To spell out our bounds, we need to introduce some additional notation. Recall that for 
$i,j \ge 1$ the random variables $\ETA_{\AllKid,i,j}$, $\ETA_{\PureP,i,j}$, $\ETA_{\PureM,i,j}$ follow the law of 
$\rho_{\AllKid}$, $\rho_{\PureP}$, $\rho_{\PureM}$, respectively. Similarly, let $\ETA'_{\AllKid,i,j}$, $\ETA'_{\PureP,i,j}$, $\ETA'_{\PureM,i,j}$ 
be random variables with law $\rho'_{\AllKid}, \rho'_{\PureP}$ and $\rho'_{\PureM}$,
respectively.
We denote with $\ETA^{\wedge}_{\AllKid,i,j}$ the random variable $\ETA_{\AllKid,i,j} \wedge \ETA'_{\AllKid,i,j}$,  and with $\ETA^{\vee}_{\AllKid,i,j}$ 
the random variable $\ETA_{\AllKid,i,j} \vee \ETA'_{\AllKid,i,j}$. Similarly, we write  
$\ETA^{\wedge}_{\PureP,i,j} = \ETA_{\PureP,i,j}\wedge \ETA'_{\PureP,i,j}$
and $\ETA^{\vee}_{\PureP,i,j} = \ETA_{\PureP,i,j} \vee \ETA'_{\PureP,i,j}$, and also write 
$\ETA^{\wedge}_{\PureM,i,j} = \ETA_{\PureM,i,j} \wedge \ETA'_{\PureM,i,j}$ and 
$\ETA^{\vee}_{\PureM,i,j} = \ETA_{\PureM,i,j}, \ETA'_{\PureM,i,j}$.



Moreover, for a sign $\varepsilon \in \{\pm 1\}$ and a vector $r=(r_{\AllKid}, r_{\PureP}, r_{\PureM}, r_{\NoKid})$ of non-negative integers with 
$r_{\AllKid} + r_{\PureP} + r_{\PureM} + r_{\NoKid} = {k-1}$ and $1 \le i \le r_{\AllKid}$, $1 \le j \le r_{\PureP}$, $1 \le \ell \le r_{\PureM}$, we let
\begin{align*}
\diffr^{\AllKid}_{i}&(z, r; \varepsilon)\\
&= 
\left|
\frac{\partial}
{\partial z}
\log{
{\left(
1 -  \frac{1}{2^{\vec{r}_{\NoKid}}}
\Pfun\left(
\varepsilon  (\ETA_{\AllKid,1,1}, \ldots,\ETA_{\AllKid,1,i-1}, z, \ETA'_{\AllKid,1,i+1}, \ldots
\ETA'_{\AllKid,1,r_{\AllKid}})
\right)
\Pfun\left(
\varepsilon(\ETA'_{\PureP,1,1}, \ldots, \ETA'_{\PureP,1,r_{\PureP}})
\right)
\Pfun\left(
\varepsilon(\ETA'_{\PureM,1,1}, \ldots, \ETA'_{\PureM,1,r_{\PureM}})
\right)
\right)
}
}\right|
.
\end{align*}
Analogously, we define
\begin{align*}
\diffr^{\PureP}_{j}&(z, r; \varepsilon)\\
&=
\left|
\frac{\partial}
{\partial z}
\log{
{\left(
1 -  \frac{1}{2^{\vec{r}_{\NoKid}}} 
\Pfun\left(
\varepsilon  (\ETA_{\AllKid,1,1}, \ldots
\ETA_{\AllKid,1,r_{\AllKid}})
\right)
\Pfun\left(
\varepsilon  (\ETA_{\PureP,1,1}, \ldots, \ETA_{\PureP,1,j-1}, z, \ETA'_{\PureP,1,j+1},
\ldots, \ETA'_{\PureP,1,r_{\PureP}})
\right)
\Pfun\left(
\varepsilon  (\ETA'_{\PureM,1,1}, \ldots
\ETA'_{\PureM,1,r_{\PureM}})
\right)
\right)
}
}\right|,
\end{align*}
\begin{align*}
\diffr^{\PureM}_{\ell}&(z, r; \varepsilon) \\
&=
\left|
\frac{\partial}
{\partial z}
\log{
{\left(
1 -  \frac{1}{2^{\vec{r}_{\NoKid}}} 
\Pfun\left(
\varepsilon  (\ETA_{\AllKid,1,1}, \ldots
\ETA_{\AllKid,1,r_{\AllKid}})
\right)
\Pfun\left(
\varepsilon(\ETA_{\PureP,1,1}, \ldots, \ETA_{\PureP,1,r_{\PureP}})
\right)
\Pfun\left(
\varepsilon  (\ETA_{\PureM,1,1}, \ldots, \ETA_{\PureM,1,\ell-1}, z, \ETA'_{\PureM,1,\ell+1},
\ldots, \ETA'_{\PureP,1,r_{\PureM}})
\right)
\right)
}
}\right|.
\end{align*}

With the above notation in place, we are now ready to bound $W_1(\hat\rho_{\PureP}, \hat{\rho}'_{\PureP})$. 
For each of the pairs of distributions $(\rho_{\AllKid},\rho'_{\AllKid})$, 
$(\rho_{\PureP},\rho'_{\PureP})$, and 
$(\rho_{\PureM},\rho'_{\PureM})$, fix an arbitrary coupling among its coordinates. 

\begin{lemma}\label{lem_BoundW1P}
$W_1(\hat\rho_{\PureP}, \hat{\rho}'_{\PureP})$ is upper bounded by
\begin{align}\label{eq:FinalBoundForW1P}
\frac{d/2}{1-e^{-\frac{d}{2}}}
\cdot
\Erw\Biggl[
\sum_{i=1}^{\vec{r}_{\AllKid,1}}
\int_{{\ETA}^\wedge_{\AllKid, 1, i}}^{{\ETA}^\vee_{\AllKid, 1, i}}\!
\diffr^{\AllKid}_{i}(w_i, \vr_1; +1)
\dd w_i
+
\sum_{j=1}^{\vec{r}_{\PureP,1}}
\!
\int_{{\ETA}^\wedge_{\PureP, 1, j}}^{{\ETA}^\vee_{\PureP, 1, j}}\!
\diffr^{\PureP}_{j}(y_j, \vr_1; +1)
\dd y_j
+
\sum_{\ell=1}^{\vec{r}_{\PureM,1}}
\int_{{\ETA}^\wedge_{\PureM, 1, \ell}}^{{\ETA}^\vee_{\PureM, 1, \ell}}
\!
\diffr^{\PureM}_{\ell}(z_\ell, \vr_1; +1)
\dd z_\ell
\Biggr]
\enspace.
\end{align}
\end{lemma}

\begin{proof}
Let us write $\LArg_{i,j}'(\eps,r)$ for the expression 
in the r.h.s. of \eqref{eq:defOfXI} where distribution $\rho'$ is used instead of $\rho$, i.e.,
\begin{align}\label{eq:defOfprimeXI}
\LArg_{i,j}'(\eps,r)=  1 -  \frac{1}{2^{{r}_{\NoKid}}} 
\Pfun
\left(\eps \bigl( {\ETA'_{\AllKid,4i+j,1}},\ldots,{\ETA'_{\AllKid,4i+j,r_{\AllKid}}}\bigr) \right)
\Pfun
\left(\eps\bigl( {\ETA'_{\PureP,4i+j,1}},\ldots,{\ETA'_{\PureP,4i+j,r_{\PureP}}}\bigr) \right)
\Pfun\left(\eps
\bigl( {\ETA'_{\PureM,4i+j,1}},\ldots,{\ETA'_{\PureM,4i+j,r_{\PureM}}}\bigr)
\right)
.
\end{align}

By identically coupling the number of clauses and the types of the children variables of each clause in $\hat\rho_{\PureP}, \hat\rho'_{\PureP}$, 
we see that by the definition of the $W_1$ norm, 
\begin{align*}
W_1(\hat\rho_{\PureP}, \hat{\rho}'_{\PureP})
&\leq
\Erw{
        \brk
        {\left| -\sum_{i=1}^{\vdpc}
\log{\LArg_{i,3}(+1, \vr_{4i+3})
\over
\LArg'_{i,3}(+1, \vr_{4i+3})}
\right|}
}
\enspace.
\end{align*}
Applying Wald's lemma, we further obtain 
\begin{align}\label{eq:WaldsOnlyP}
W_1(\hat\rho_{\PureP}, \hat{\rho}'_{\PureP})
\le	
\frac{d/2}{1- e^{-d/2}}
\cdot
\Erw{
\brk
{\left| 
\log{\LArg_{1,3}(+1, \vr_{7})
\over
\LArg'_{1,3}(+1, \vr_{7})}
\right|}
}
=
\frac{d/2}{1- e^{-d/2}}
\cdot
\Erw{
\brk
{\left| 
\log{\LArg_{0,1}(+1, \vr_{1})
\over
\LArg'_{0,1}(+1, \vr_{1})}
\right|}
}
\enspace.
\end{align}
Let us now focus on the expectation in the r.h.s. of
\eqref{eq:WaldsOnlyP}. Recalling the definition of $\; \LArg$ in \eqref{eq:defOfXI}, and the definition of $\; \LArg'$ in \eqref{eq:defOfprimeXI},
we expand  
\begin{align}\label{eq:RecallXI}
\log{\LArg_{0,1}(+1, \vr_{1})
\over
\LArg'_{0,1}(+1, \vr_{1})}
=
\log{
\frac{
1 -  {2^{-{r}_{\NoKid}}} \cdot
\Pfun
\left( {\ETA_{\AllKid,1,1}},\ldots,{\ETA_{\AllKid,1,\vr_{\AllKid, 1}}} \right)
\cdot
\Pfun
\left( {\ETA_{\PureP,1,1}},\ldots,{\ETA_{\PureP,1,\vr_{\PureP,1}}} \right)
\cdot
\Pfun\left(
{\ETA_{\PureM,1,1}},\ldots,{\ETA_{\PureM,1,\vr_{\PureM,1}}}
\right)
}
{
1 -  {2^{-{r}_{\NoKid}}} \cdot
\Pfun
\left( {\ETA'_{\AllKid,1,1}},\ldots,{\ETA'_{\AllKid,1,\vr_{\AllKid,1}}} \right)
\cdot
\Pfun
\left( {\ETA'_{\PureP,1,1}},\ldots,{\ETA'_{\PureP,1,\vr_{\PureP,1}}} \right)
\cdot
\Pfun\left( {\ETA'_{\PureM,1,1}},\ldots,{\ETA'_{\PureM,1,\vr_{\PureM,1}}}  \right)
}
}.
\end{align}
Telescoping over the arguments of the functions $\Pfun$ in the r.h.s of
\eqref{eq:RecallXI}, invoking the fundamental theorem of calculus for
each term, and applying the triangle inequality we further obtain
\begin{align*}%\label{eq:AfterTelesc}
\left|\log{\LArg_{0,1}(+1, \vr_{1})
\over
\LArg'_{0,1}(+1, \vr_{1})}
\right|
\le
\sum_{i=1}^{\vec{r}_{\AllKid,1}}
\left|
\int_{{\ETA}'_{\AllKid,1,i}}^{\ETA_{\AllKid,1,i}}
\diffr^{\AllKid}_{i}(w_i, \vec{r}_1; +1)
\dd w_i
\right|
+
\sum_{j=1}^{\vec{r}_{\PureP,1}}
\left|
\int_{{\ETA}'_{\PureP,1,j}}^{\ETA_{\PureP,1,j}}
\diffr^{\PureP}_{j}(y_j, \vec{r}_1; +{1})
\dd y_j
\right|
+
\sum_{\ell=1}^{\vec{r}_{\PureM,1}}
\left|
\int_{{\ETA}'_{\PureM,1,\ell}}^{\ETA_{\PureM,1,\ell}}
\diffr^{\PureM}_{\ell}(z_\ell, \vec{r}_1; +{1})
\dd z_\ell
\right|.
\end{align*}
Plugging the above into \eqref{eq:WaldsOnlyP} gives the result.
\end{proof}

Following the same steps as above, but replacing `$+1$' with `$-1$', yields the corresponding bound for $W_1(\hat\rho_{\PureM},\hat{\rho}'_{\PureM})$.

\begin{lemma}\label{lem_BoundW1M}
$W_1(\hat\rho_{\PureM},\hat{\rho}'_{\PureM})$ is upper bounded by
\begin{align}\label{eq:FinalBoundForW1M}
\frac{d/2}{1-e^{-\frac{d}{2}}}
\cdot
\Erw\Biggl[
\sum_{i=1}^{\vec{r}_{\AllKid,1}}
\int_{{\ETA}^\wedge_{\AllKid, 1, i}}^{{\ETA}^\vee_{\AllKid, 1, i}}\!
\diffr^{\AllKid}_{i}(w_i, \vr_1; -1)
\dd w_i
+
\sum_{j=1}^{\vec{r}_{\PureP,1}}
\!
\int_{{\ETA}^\wedge_{\PureP, 1, j}}^{{\ETA}^\vee_{\PureP, 1, j}}\!
\diffr^{\PureP}_{j}(y_j, \vr_1; -1)
\dd y_j
+
\sum_{\ell=1}^{\vec{r}_{\PureM,1}}
\int_{{\ETA}^\wedge_{\PureM, 1, \ell}}^{{\ETA}^\vee_{\PureM, 1, \ell}}
\!
\diffr^{\PureM}_{\ell}(z_\ell, \vr_1; -1)
\dd z_\ell
\Biggr]
\enspace.
\end{align}
\end{lemma}

Exploiting the signs of the variables with types $\rPureP$ and $\rPureM$, we obtain the following bounds for each of the $\diffr$-functions.
For $\lambda \in (0,1]$, we define the real function $\fun_\lambda : [0,1] \to \RR$ as
\begin{align}
\fun_\lambda \left(w\right)	=  \frac{\lambda\cdot w}{1-\lambda\cdot w} \cdot(1-w)
\enspace.
\label{eq:DefofPsi}
\end{align}
It is easy to check that $\fun_{\lambda'}(w) \le \fun_{\lambda}(w)$, for every $\lambda' \le \lambda$.
\begin{claim}\label{cl_Dbound}
For every
$r = \left({r}_{\AllKid},
{r}_{\PureP}, {r}_{\PureM}, {r}_{\NoKid}\right)$, and
$i\in [r_{\AllKid}]$ we have that
\begin{align}\label{eq:BoundOfDiffAllKid}
\diffr^{{\AllKid}}_{i}
\left(w_i, r ;+ 1
\right)
\le
\fun_{2^{-r_{\NoKid}-r_{\PureM}}}
\left(\frac{1 + \tanh({w_i}/{2})}{2}\right)
\enspace
&& \text{ and } &&
\diffr^{{\AllKid}}_{i}
\left(w_i, r ;- {1}
\right)
&\le
\fun_{2^{-r_{\NoKid}-r_{\PureP}}}
\left(\frac{1 - \tanh({w_i}/{2})}{2}\right)
\enspace.
\end{align}
Similarly, we also have that for $j \in [r_{\PureP}]$,
\begin{align}\label{eq:BoundOfDiffPureP}
\diffr^{{\PureP}}_{j}
\left(y_j, r ;+ {1}
\right)
\le
\fun_{2^{-r_{\NoKid}-r_{\PureM}}}
\left(\frac{1 + \tanh({y_j}/{2})}{2}\right)
\enspace
&& \text{ and } &&
\diffr^{{\PureP}}_{j}
\left(y_j, r ;- {1}
\right)
&\le
\fun_{2^{-r_{\NoKid}-(r_{\PureP}-1)}}
\left(\frac{1 - \tanh({y_j}/{2})}{2}\right)
\enspace,
\end{align}
and for $\ell \in [r_{\PureM}]$
\begin{align}\label{eq:BoundOfDiffPureM}
\diffr^{{\PureM}}_{\ell}
\left(z_\ell, r ;+ {1}
\right)
\le
\fun_{2^{-r_{\NoKid}-(r_{\PureM}-1)}}
\left(\frac{1 + \tanh({z_\ell}/{2})}{2}\right)
\enspace
&& \text{ and } &&
\diffr^{{\PureM}}_{\ell}
\left(z_\ell, r ;- {1}
\right)
&\le
\fun_{2^{-r_{\NoKid}-r_{\PureP}}}
\left(\frac{1 - \tanh({z_\ell}/{2})}{2}\right)
\enspace.
\end{align}
\end{claim}

\begin{proof}
We only prove the first inequality of \eqref{eq:BoundOfDiffAllKid} as the rest of them follow in a similar manner.  
A straightforward calculation shows that for $\rvec{z} \in \RR^q, \varepsilon \in \PM$, and $i \in [q]$ we have
\begin{align}\label{eq_derOfG}
\frac{\partial}{\partial z_i}
\Pfun \left(\varepsilon\cdot\rvec{z}\right)
&=
{\varepsilon}
\cdot
\frac{1-\tanh(\varepsilon\cdot{z_i}/2)}{2}
\cdot
\Pfun \left(\varepsilon \cdot \rvec{z}\right)
\enspace.
\end{align}
Writing 
$K =  {2^{-{r}_{\NoKid}}}
\Pfun\left(
\ETA_{\AllKid,1,1}, \ldots,\ETA_{\AllKid,1,i-1}, \ETA'_{\AllKid,1,i+1}, \ldots
\ETA'_{\AllKid,1,r_{\AllKid}}
\right)
\Pfun\left(
\ETA'_{\PureP,1,1}, \ldots, \ETA'_{\PureP,1,r_{\PureP}}
\right)
\Pfun\left(
\ETA'_{\PureM,1,1}, \ldots, \ETA'_{\PureM,1,r_{\PureM}}
\right)$, 
applying the chain rule, and using \eqref{eq_derOfG}, we see that
\begin{align}
\diffr^{{\AllKid}}_{i}\left(w_i, r ;+ 1\right) 
=
\fun_K \bc{\frac{1 + \tanh({w_i}/{2})}{2}}\enspace.
\end{align}
Using the fact that $\rho'_{\PureM}$ is supported in $(-\infty, 0]$, and that $\Pfun \le 1$, we obtain $K \le 2^{-r_{\AllKid}-r_{\PureM}}$. The
monotonicity of $\fun_\lambda$ with respect to the parameter $\lambda$ concludes the proof. 
\end{proof}

Using \Cl~\ref{cl_Dbound}, and maximising each of the functions $\fun_\lambda$ appearing in \eqref{eq:BoundOfDiffAllKid}--\eqref{eq:BoundOfDiffPureM}, we can recover
the bounds of~\cite{MM}. To obtain sharper bounds, a natural idea is to optimise groups of summands, instead of optimising each $\diffr$-summand of
$W_1(\hat\rho_{\PureP},\hat{\rho}'_{\PureP}) + W_1(\hat\rho_{\PureM},\hat{\rho}'_{\PureM})$ in isolation. In particular, 
it is tempting to pair terms of the form $\diffr(\cdot,-1)$ with corresponding terms of the form $\diffr(\cdot,+1)$, as \Lem~\ref{lem:OptimizeAntipodal} suggests.
\begin{lemma}
\label{lem:OptimizeAntipodal}
Let $ \sfun_\lambda : [0,1] \to \RR$ to be the function
$\sfun_\lambda(w) =
\fun_\lambda(w) + \fun_\lambda(1-w)
$.
For every $\lambda \in (0,1]$, we have that  $\sfun_\lambda(w) \le \sfun_\lambda(1/2) = \frac{\lambda/2}{1-\lambda/2}$, for all $w\in [0,1]$.
\end{lemma}

\begin{proof}
For $\lambda = 1$, we have that $\fun_\lambda(w) = w$ implying $\sfun_\lambda(w) = 1$, and thus, the result holds trivially. Let now $\lambda \in (0,1)$. 
Differentiating $\fun_\lambda$ gives
\begin{align*}
\fun^\prime_\lambda(w)
=
\frac{\lambda^{2} w^{2} - 2 \lambda w + \lambda}{\lambda^{2} w^{2} - 2 \, \lambda w + 1}
=
1 - \frac{ 1 - \lambda }{(1-\lambda w)^2}
\enspace.
\end{align*}
Therefore,
\begin{align*}
\sfun^\prime_\lambda(w)
=
1 - \frac{ 1 - \lambda }{(1-\lambda w)^2}
-\left(1 - \frac{ 1 - \lambda }{(1-\lambda (1-w))^2}\right)
=
\frac{ 1 - \lambda }{(1-\lambda (1-w))^2}
- \frac{ 1 - \lambda }{(1-\lambda w)^2}
\enspace.
\end{align*}
It is straightforward to check that the above expression has only one root at $w=1/2$, being non-negative for $w \in [0, 1/2)$, and non-positive for $w \in (1/2, 1]$. Therefore, $\sfun_\lambda(1/2) = \frac{\lambda/2}{1-\lambda/2}$ is the maximum value of $\sfun_\lambda$.
\end{proof}

However, directly applying \Lem~\ref{lem:OptimizeAntipodal} to 
$W_1(\hat\rho_{\PureP},\hat{\rho}'_{\PureP}) + W_1(\hat\rho_{\PureM},\hat{\rho}'_{\PureM})$
seems hopeless, since in the bounds supplied by \Cl~\ref{cl_Dbound}, the parameters of the functions $\fun$ bounding 
$\diffr(\cdot,r,+1)$-terms in $W_1\left(\hat\rho_{\PureP},\hat{\rho}'_{\PureP}\right)$
are quite different from the parameters of the functions $\fun$ bounding the corresponding $\diffr(\cdot,r,-1)$-terms in
$W_1\left(\hat\rho_{\PureM},\hat{\rho}'_{\PureM}\right)$.


The following lemma reveals, a somewhat unexpected, symmetry between $W_1(\hat\rho_{\PureP},\hat{\rho}'_{\PureP})$
and $W_1(\hat\rho_{\PureM},\hat{\rho}'_{\PureM})$, that facilitates our pairing strategy. 

Some additional notation is in order. We denote with $\cR(k)$ for the set of all vectors $r = (r_{\AllKid}, r_{\PureP}, r_{\PureM}, r_{\NoKid})$ of 
non-negative integer entries which sum to $k-1$. For every $r \in \cR(k)$ we use the shorthand %
\begin{align*}
P({r})
= \frac{(k-1)!}
{{r}_{\AllKid}! {r}_{\PureP}!{r}_{\PureM}! {r}_{\NoKid}!}
\cdot
p_{\AllKid}^{{r}_{\AllKid}}
p_{\PureP}^{{r}_{\PureP}}
p_{\PureM}^{{r}_{\PureM}}
p_{\NoKid}^{{r}_{\NoKid}}
\enspace,
\end{align*}
where $p_{\AllKid}, p_{\PureP}, p_{\PureM}, p_{\NoKid}$ are the probabilities defined in \eqref{eq_def_multipr}. Finally, we define
\begin{align}
\Ex{\AllKid}
&=
\sum_{\substack{r \in \cR(k) \\ r_{\AllKid}\ge 1}}
P({r})
\cdot
{r}_{\AllKid}
\cdot
\Erw
\left[
\int_{{\ETA}^\wedge_{\AllKid, 1, 1}}^{{\ETA}^\vee_{\AllKid, 1, 1}}
\sfun_{2^{-r_{\NoKid}-r_{\PureM}}} \left(\frac{1+\tanh(w/2)}{2}\right)
\;
\dd w
\right]
\enspace,
\label{eq:ExpAllKid}
\\
\Ex{\PureP}
&=
\sum_{\substack{r \in \cR(k) \\ r_{\PureP}\ge 1}}
P({r})
\cdot
{r}_{\PureP}
\cdot
\Erw
\left[
\int_{{\ETA}^\wedge_{\PureP, 1, 1}}^{{\ETA}^\vee_{\PureP, 1, 1}}
\sfun_{2^{-r_{\NoKid}-r_{\PureM}}}
\left(\frac{1 + \tanh({y}/{2})}{2}\right)
\;
\dd y
\right]
\enspace,
\label{eq:ExpPureP}
\\
\Ex{\PureM}
&=
\sum_{\substack{r \in \cR(k) \\ r_{\PureM}\ge 1}}	P({r})
\cdot
{r}_{\PureM}
\cdot
\Erw
\left[ 
\int_{{\ETA}^\wedge_{\PureM, 1, 1}}^{{\ETA}^\vee_{\PureM, 1, 1}}
\sfun_{2^{-r_{\NoKid}-r_{\PureP}}}
\left(\frac{1 + \tanh({z}/{2})}{2}\right)
\;
\dd z
\right]
\label{eq:ExpPureM}
\enspace.
\end{align}


\begin{lemma}\label{lem_PairingE}
We have that
\begin{align}
W_1(\hat\rho_{\PureP},\hat{\rho}'_{\PureP})
+
W_1(\hat{\rho}_{\PureM},\hat{\rho}'_{\PureM})
\le
\frac{d/2}{1-e^{-d/2}}
\left(
\Ex{\AllKid}
+
\Ex{\PureP}
+
\Ex{\PureM}
\right)
\enspace.
\label{eq:ExpBreak3}
\end{align}
\end{lemma}

\begin{proof}
Expanding the expectation in \eqref{eq:FinalBoundForW1P} with respect
to $\vec{r}=\left(\vec{r}_{\AllKid}, \vec{r}_{\PureP},
\vec{r}_{\PureM}, \vec{r}_{\NoKid}\right)$ , and using the shorthand
\begin{align*}
E^{\pm}_{\AllKid}(r) &=  \ex\brk{
\int_{{\ETA}^\wedge_{\AllKid, 1, 1}}^{{\ETA}^\vee_{\AllKid, 1, 1}}
\diffr^{\AllKid}_{1}
\left(w, r; \pm{1}
\right) \dd w
} ,\enspace 
E^{\pm}_{\PureP}(r) =  \ex\brk{
\int_{{\ETA}^\wedge_{\PureP, 1, 1}}^{{\ETA}^\vee_{\PureP, 1, 1}}
\diffr^{\PureP}_{1}
\left(y, r; \pm{1}
\right) \dd y} 
, \enspace 
E^{\pm}_{\PureM}(r) =  \ex\brk{
\int_{{\ETA}^\wedge_{\PureM, 1, 1}}^{{\ETA}^\vee_{\PureM, 1, 1}}
\diffr^{\PureM}_{1}
\left(z, r; \pm\vec{1}
\right) \dd z},
\end{align*}
we see that
\begin{align}\label{eq_W1Pb}
W_1(\hat\rho_{\PureP},\hat\rho'_{\PureP})
&\le \frac{d/2}{1-e^{-d/2}}
\bc{
\sum_{r \in \cR(k)} P(r) \cdot r_{\AllKid} \cdot E^{+}_{\AllKid}(r) +
\sum_{r \in \cR(k)} P(r) \cdot r_{\PureP} \cdot E^{+}_{\PureP}(r) +
\sum_{r \in \cR(k)} P(r) \cdot r_{\PureM} \cdot E^{+}_{\PureM}(r)
}\nonumber\\
&= \frac{d/2}{1-e^{-d/2}}
\bc{
\sum_{\substack{r \in \cR(k) \\ r_{\AllKid}\ge1}} P(r) \cdot r_{\AllKid} \cdot E^{+}_{\AllKid}(r) +
\sum_{\substack{r \in \cR(k) \\ r_{\PureP}\ge1}} P(r) \cdot r_{\PureP} \cdot E^{+}_{\PureP}(r) +
\sum_{\substack{r \in \cR(k) \\ r_{\PureM}\ge1}} P(r) \cdot r_{\PureM} \cdot E^{+}_{\PureM}(r)
}
\enspace.
\end{align}
In a similar manner, we derive
\begin{align}\label{eq_W1Mb}
W_1(\hat\rho_{\PureM},\hat\rho'_{\PureM})
\le \frac{d/2}{1-e^{-d/2}}
\bc{
\sum_{\substack{r \in \cR(k) \\ r_{\AllKid}\ge1}} P(r) \cdot r_{\AllKid} \cdot E^{-}_{\AllKid}(r) +
\sum_{\substack{r \in \cR(k) \\ r_{\PureP}\ge1}} P(r) \cdot r_{\PureP} \cdot E^{-}_{\PureP}(r) +
\sum_{\substack{r \in \cR(k) \\ r_{\PureM}\ge1}} P(r) \cdot r_{\PureM} \cdot E^{-}_{\PureM}(r)
}\enspace.
\end{align}

Let us now consider the bound on the sum $W_1(\hat\rho_{\PureP},\hat\rho'_{\PureP}) + W_1(\hat\rho_{\PureM},\hat\rho'_{\PureM})$ obtained by summing 
\eqref{eq_W1Pb}, \eqref{eq_W1Mb}. We next group each of the three sums in \eqref{eq_W1Pb} with the corresponding sum in \eqref{eq_W1Mb}, carefully pairing their terms.
Specifically, for the $\rAllKid$--sums we match  the term of $\sum_{r} P(r) \cdot r_{\AllKid} \cdot E^{+}_{\AllKid}(r)$ corresponding to
$r = ({r}_{\AllKid}, {r}_{\PureP},
{r}_{\PureM}, {r}_{\NoKid})$ with the term of $\sum_{r'} P(r') \cdot r'_{\AllKid} \cdot E^{+}_{\AllKid}(r')$ that corresponds to
$r' = ({r}_{\AllKid}, {r}_{\PureM}, {r}_{\PureP}, {r}_{\NoKid})$. Since $r \mapsto r'$ is a bijection of
$\mathcal{R}(k) \cap \{r: r_{\AllKid}\ge1\}$, and $r'_{\AllKid}= r_{\AllKid}$, and $P(r') = P(r)$ we see that
\begin{align}\label{eq_MatchAllKid}
\sum_{\substack{r \in \cR(k)\\ r_{\AllKid \ge 1}}} P(r)\cdot r_{\AllKid} \bc{E^{+}_{\AllKid}(r) + E^{-}_{\AllKid}(r)}
= \sum_{\substack{r \in \cR(k)\\ r_{\AllKid \ge 1}}} P(r)\cdot r_{\AllKid} \bc{E^{+}_{\AllKid}(r) + E^{-}_{\AllKid}(r')} \enspace.
\end{align}
Invoking the bounds \eqref{eq:BoundOfDiffAllKid} of \Cl~\ref{cl_Dbound}, and recalling the definitions of $\sfun$, $\Ex{\AllKid}$, we upper bound the r.h.s. of
\eqref{eq_MatchAllKid}~by
\begin{align}\label{eq_SumEA}
\sum_{\substack{r \in \cR(k)\\ r_{\AllKid \ge 1}}} P(r)r_{\AllKid} \bc{\Erw
\brk{
\int_{{\ETA}^\wedge_{\AllKid, 1, 1}}^{{\ETA}^\vee_{\AllKid, 1, 1}}
\fun_{2^{-r_{\NoKid}-r_{\PureM}}} \left(\frac{1+\tanh(w/2)}{2}\right)
\; \dd w}
+
\Erw\brk{
\int_{{\ETA}^\wedge_{\AllKid, 1, 1}}^{{\ETA}^\vee_{\AllKid, 1, 1}}
\fun_{2^{-r_{\NoKid}-r_{\PureM}}} \left(\frac{1-\tanh(w/2)}{2}\right)
\;\dd w
}}	
= \Ex{\AllKid}
\enspace.
\end{align}
The matchings between the terms for the $\rPureP, \rPureM$--sums of \eqref{eq_W1Pb}, \eqref{eq_W1Mb} are more delicate.
In particular, for the $\rPureP$--sum it turns out that we can pull off the same trick as above by pairing the term of
$\sum_{r} P(r) \cdot r_{\PureP} \cdot E^{+}_{\PureP}(r)$ corresponding to the vector $r = ({r}_{\AllKid}, {r}_{\PureP},
{r}_{\PureM}, {r}_{\NoKid})$ with the term of $\sum_{r''} P(r'') \cdot r''_{\PureP} \cdot E^{-}_{\PureP}(r'')$ that corresponds to 
$r'' = ({r}_{\AllKid}, {r}_{\PureM}+1, {r}_{\PureP}-1, {r}_{\NoKid})$. To see this, note that the mapping $r \mapsto r''$ is a bijection of
$\mathcal{R}(k) \cap \{r: r_{\PureP}\ge1\}$, leaving the quantity $P(r)\cdot r_{\PureP}$ invariant as  
\begin{align*}
P(r) \cdot r_{\PureP} =
\frac{(k-1)!}
{{r}_{\AllKid}! ({r}_{\PureP}-1)!{r}_{\PureM}! {r}_{\NoKid}!}
\cdot
p_{\AllKid}^{{r}_{\AllKid}}
p_{\PureP}^{{r}_{\PureP}}
p_{\PureM}^{{r}_{\PureM}}
p_{\NoKid}^{{r}_{\NoKid}} =
\frac{(k-1)!}
{{r}_{\AllKid}! ({r}_{\PureM}+1)!({r}_{\PureP}-1)! {r}_{\NoKid}!}
\cdot
p_{\AllKid}^{{r}_{\AllKid}}
p_{\PureP}^{{r}_{\PureP}}
p_{\PureM}^{{r}_{\PureM}}
p_{\NoKid}^{{r}_{\NoKid}}
\cdot
(r_{\PureM}+1)=
P(r'') \cdot r''_{\PureP}
\enspace.
\end{align*}
Invoking the bounds \eqref{eq:BoundOfDiffPureP} of \Cl~\ref{cl_Dbound}, recalling the definitions of $\sfun$, $\Ex{\PureP}$, and arguing as above, 
we obtain
\begin{align}\label{eq_SumEP}
\sum_{\substack{r \in \cR(k)\\ r_{\PureP}\ge1}} P(r)\cdot r_{\PureP} \bc{E^{+}_{\PureP}(r) + E^{-}_{\PureP}(r'')} \le \Ex{\PureP}\enspace.
\end{align}
Similarly, using the mapping $r\mapsto r'''$, with $r'''\! = (r_{\AllKid}, r_{\PureM} - 1, r_{\PureP}+1, r_{\NoKid})$, and following the same steps as above, we get
\begin{align}\label{eq_SumEM}
\sum_{\substack{r \in \cR(k)\\ r_{\PureM}\ge1}} P(r)\cdot r_{\PureM} \bc{E^{+}_{\PureM}(r) + E^{-}_{\PureM}(r''')} \le \Ex{\PureM}\enspace.
\end{align}
Summing \eqref{eq_SumEA}--\eqref{eq_SumEM} concludes the proof.
\end{proof}


In light of the above, we are now ready to finish the proof of \Prop~\ref{prop_BPPureLit}.

\begin{proof}[Proof of \Prop~\ref{prop_BPPureLit}]
Applying \Lem~\ref{lem:OptimizeAntipodal} on the function $\sfun$ in the r.h.s. of \eqref{eq:ExpAllKid} gives
\begin{align}
\sfun_{2^{-r_{\NoKid}-r_{\PureM}}} \left(\frac{1+\tanh(w/2)}{2}\right)
\le
\frac{2^{-\vec{r}_{\PureM}- \vec{r}_{\NoKid}-1}}{1 - 2^{-\vec{r}_{\PureM}- \vec{r}_{\NoKid}-1}}
\le
\left(\frac{1}{2}\right)^{\vec{r}_{\PureM} + \vec{r}_{\NoKid}} \enspace.
\label{eq:SfunAllKidBound}
\end{align}
Plugging the above into  \eqref{eq:ExpAllKid} and applying the binomial theorem, further yields 
\begin{align}
\Ex{\AllKid} \le (k-1) \cdot p_{\AllKid} \bc{1 - \frac{e^{-\frac{d}{2}}}{2}}^{k-2} \ex\brk{|\ETA_{\AllKid, 1,1 }-\ETA'_{\AllKid, 1,1 }|}
\enspace.
\label{eq:ExpAllKidFin}
\end{align}
Working in a similar manner, we obtain 
\begin{align}
\Ex{\PureP}
\le
(k-1)\cdot p_{\PureP}
\left(1-\frac{e^{-\frac{d}{2}}}{2}\right)^{k-2}
\!\!
\ex\brk{|\ETA_{\PureP, 1,1 }-\ETA'_{\PureP, 1,1 }|},
&&
\text{and}
&&
\Ex{\PureM}
\le
(k-1)\cdot p_{\PureM}
\left(1-\frac{e^{-\frac{d}{2}}}{2}\right)^{k-2}
\!\!
\ex\brk{|\ETA_{\PureM, 1,1 }-\ETA'_{\PureM, 1,1 }|}
\label{eq:ExpPureMFin}
\enspace.
\end{align}
Finally, plugging the bounds \eqref{eq:ExpAllKidFin},
and \eqref{eq:ExpPureMFin} into \eqref{eq:ExpBreak3} we see that 
$ W_1(\hat\rho_{\PureP},\hat\rho'_{\PureP})
+
W_1(\hat\rho_{\PureM},\hat\rho'_{\PureM})$
is upper bounded by 
\begin{align}
\frac{d\cdot (k-1)}{2}
\cdot
\left(1-\frac{e^{-\frac{d}{2}}}{2}\right)^{k-2}
\!\! 
\left[
\left(1-e^{-\frac{d}{2}}\right)
\ex\brk{|\ETA_{\AllKid, 1,1 }-\ETA'_{\AllKid, 1,1 }|}
+
e^{-\frac{d}{2}}
\ex\brk{|\ETA_{\PureP, 1,1 }-\ETA'_{\PureP, 1,1 }|}
+
e^{-\frac{d}{2}}
\ex\brk{|\ETA_{\PureM, 1,1 }-\ETA'_{\PureM, 1,1 }|}
\right]
\enspace.
\label{eq:ExpBound3}
\end{align}
Recall that we established \eqref{eq:ExpBound3} assuming an arbitrary coupling between the coordinates of each pair of distributions $(\rho_{\AllKid},\rho'_{\AllKid})$, 
$(\rho_{\PureP},\rho'_{\PureP})$, and $(\rho_{\PureM},\rho'_{\PureM})$. Therefore, the definition of $W_1$ norm and \eqref{eq:ExpBound3}, imply the first inequality
below, while \eqref{eq:ExpBound4} follows by the definition \eqref{eq:DistDef} of $\dist_d$  
\begin{align}
W_1(\hat\rho_{\PureP},\hat\rho'_{\PureP})+W_1(\hat\rho_{\PureM},\hat\rho'_{\PureM}) 	
&\le
\frac{d (k-1)}{2}
\left(1-\frac{e^{-\frac{d}{2}}}{2}\right)^{k-2}
\left[
\left(1-e^{-\frac{d}{2}}\right)
W_1(\rho_{\AllKid}, \rho'_{\AllKid})
+
e^{-\frac{d}{2}}
W_1(\rho_{\PureP}, \rho'_{\PureP})
+
e^{-\frac{d}{2}}
W_1(\rho_{\PureM}, \rho'_{\PureM})
\right]
\nonumber\\
&\le
\frac{d (k-1)}{2}
\left(1-\frac{e^{-\frac{d}{2}}}{2}\right)^{k-2}
\dist_d(\rho, \rho') \enspace.
\label{eq:ExpBound4}
\end{align}
Moreover, as per the triangle inequality we see that
\begin{align}
W_1(\hat\rho_{\AllKid},\hat\rho'_{\AllKid}) \le W_1(\hat\rho_{\PureP},\hat\rho'_{\PureP})+ W_1(\hat\rho_{\PureM},\hat\rho'_{\PureM})
\le\frac{d (k-1)}{2}
\left(1-\frac{e^{-\frac{d}{2}}}{2}\right)^{k-2}
\dist_d(\rho, \rho')
\enspace.  
\label{eq_AllBTri}
\end{align}
Plugging the bounds \eqref{eq:ExpBound4} and \eqref{eq_AllBTri} into the expression of $\dist_{d} \bc{\hat\rho, \hat\rho'}$ yields
\begin{align*}
\dist_{d} \bc{\hat\rho, \hat\rho'} 
&= 
(1-e^{-d/2})
\cdot
W_1(\hat\rho_{\AllKid}, \hat{\rho}_{\AllKid}')
+
e^{-d/2}
\bc{
W_1(\hat\rho_{\PureP}, \hat{\rho}_{\PureP}')
+
W_1(\hat\rho_{\PureM}, \hat{\rho}_{\PureM}')}
\le
\frac{d (k-1)}{2}
\left(1-\frac{e^{-\frac{d}{2}}}{2}\right)^{k-2}
\dist_d(\rho, \rho') \enspace.
\end{align*}
Recalling the definition of ${\dours}$, we see that for $d<\dours(k)$, the operator $\LDELitS{k,d}$
contracts with respect to the metric $\dist_{d}$, as desired.
\end{proof}



















\subsection{Proof of \Prop~\ref{prop:condMarg}}
To get a handle on the $\ETA_{x}^{(\ell)}$ from \eqref{eta}, we show that these quantities
can be calculated by propagating the extremal boundary condition $\SIGMA^+$
bottom-up toward the root of the tree. Specifically, we consider the operator
\begin{align*}
\LDEP_{{\TT}^{(\ell)}}
&:
(-\infty,\infty]^{V({\TT}^{(\ell)})}
\to
(-\infty,\infty]^{V({\TT}^{(\ell)})}
\enspace,&
\eta&\mapsto\hat\eta=\LDEP_{{\TT}^{(\ell)}}(\eta)
\enspace,
\end{align*}
defined as follows. 
For all $x\in\partial^{2\ell}\root$ we set $\hat\eta_x=\infty$. 
Moreover, for a variable $x\in\partial^{2q}\root$ with $q<\ell$ having children clauses $a_1,\ldots,a_t$, and grandchildren variables $y_{1,1}, \ldots, y_{1,(k-1)}, \ldots, y_{t,1}, \ldots, y_{t,(k-1)}$ we define
\begin{align}\label{eqhatetax}
\hat\eta_x &= -\sum_{i=1}^{t} {\TAU^+(x)}\sign(x,a_i)
\cdot
\log\left(
1-
{\Pfun\left({\TAU^+(x)}\sign(x,a_i)\cdot
(
\eta_{y_{i,1}}, \ldots, \eta_{y_{1,(k-1)}}
)
\right)}
\right)
\enspace.
\end{align}
It may not be apparent that the sum above is well-defined as $-\infty$ summands may manifest. 
The following lemma rules out such possibility and shows that the $\ell$-fold iteration of $\LDEP_{{\TT}^{(\ell)}}$, initiated all-$(+\infty)$ yields $\ETA^{(\ell)}=(\ETA^{(\ell)}_x)_{x \in V({\TT}^{(\ell)})}$.

\begin{lemma}\label{lem:upthetree}
The operator $\LDEP_{{\TT}^{(\ell)}}$ is well-defined and
$\mathrm{LL}^{+\, (t)}_{{\TT}^{(\ell)}}(+\infty,\ldots,+\infty)= \ETA^{(\ell)}$
for every $t \ge \ell$.
\end{lemma}

\begin{proof}
To show that $\LDEP_{{\TT}^{(\ell)}}$ is well defined we verify that, in the notation of \eqref{eqhatetax},
$\hat\eta_x\in(-\infty,\infty]$ for all $x$. Indeed, in the expression on the r.h.s.\ of \eqref{eqhatetax} a
$\pm\infty$ summand can arise only from variables $y_{i,j}$ with $\eta_{y_{i,j}}=\infty$. But the definition of
$\TAU^+$ ensures that such $y_{i,j}$ either render a zero summand if $\TAU^+(x)\sign(x,a_i)=-1$, or a $+\infty$ summand if $\TAU^+(x)\sign(x,a_i)=1$.
Thus, the sum is well-defined and $\hat\eta_x\in(-\infty,\infty]$.

Further, to verify the identity $\ETA^{(\ell)}=\LDEPl_{{\TT}^{(\ell)}}(\infty,\ldots,\infty)$, consider a variable $x$ of $\TT^{(\ell)}$.
Let $a_1^+,\ldots,a_g^+$ be the children (clauses) of $x$ with $\sign(x,a_i^+)=\TAU^+(x)$. Also let $y_{11},\ldots,y_{1(k-1)}, \ldots,
y_{g1}, \ldots, y_{g(k-1)}$ be the children of $a_1^+,\ldots,a_g^+$. 
Similarly, let $a_1^-,\ldots,a_h^-$ be the children of $x$ with
$\sign(x,a_i^-)=-\TAU^+(x)$ and let
$z_{11},\ldots,z_{1(k-1)}, \ldots, z_{h1}, \ldots, z_{h(k-1)}$ be their
children. Then \eqref{eq:SplusMax}, and \eqref{eq:SminusMax}  yield
\begin{align}\nonumber
\ETA_x^{(\ell)}
&=-
\sum_{i=1}^g
\log\left(1-\prod_{q=1}^{k-1}
\frac{Z({\TT}_{y_{iq}}^{(\ell)},\TAU^+,\TAU^+({y_{iq}}))}
{Z({\TT}_{y_{iq}}^{(\ell)},\TAU^+)}
\right)
+\sum_{j=1}^h\log
\left(
1-
\prod_{q=1}^{k-1}
\frac{Z({\TT}_{z_{jq}}^{(\ell)},\TAU^+, -\TAU^+({z_{jq}}))}
{Z({\TT}_{z_{jq}}^{(\ell)},\TAU^+)}
\right)
\\
& =-\sum_{i=1}^g\log
\left(1- \Pfun\left(\sign(x,a_i^+)\TAU^+(x)\cdot\left(\ETA^{(\ell)}_{y_{i1}}, \ldots, \ETA^{(\ell)}_{y_{i(k-1)}}\right) \right)\right)
+\sum_{j=1}^h \log
\left(1- \Pfun\left( \sign(x,a_i^-)\TAU^+(x)\cdot\left(\ETA^{(\ell)}_{z_{j1}}, \ldots, \ETA^{(\ell)}_{z_{j(k-1)}}\right)\right)\right)
\enspace.
\end{align}
The assertion follows because $\sign(x,a_i^+)\TAU^+(x)=1$ and $\sign(x,a_i^-)\TAU^+(x)=-1$.
\end{proof}


The next aim is to approximate the $\ell$-fold iteration of $\LDEP_{{\TT}^{(\ell)}}$, and more specifically the distribution of $\ETA_\root^{(\ell)}$, using a non-random operator.
To this end, we need to cope with the $\pm\infty$-entries of the vector $\ETA^{(\ell)}$. 
This is addressed by \Lem~\ref{lem_SmallOnTop}, proven in \Sec~\ref{sec:lem:SmallOnTop}, which provides a bound on $\ETA^{(\ell)}_x$ for variables $x$ near the root of the tree.

In the following we continue to write $c$ and $(\varepsilon_t)_t$ for the number and the sequence supplied by Lemma~\ref{lem_SmallOnTop}.
Guided by Lemma \ref{lem_SmallOnTop} we consider the vector $\bar\ETA^{(\ell,t)}$ of truncated log-likelihood ratios
\begin{align}\label{eq:truncEta}
\bar\ETA^{(\ell,t)}_x
&=
\begin{cases}-2t^c&\mbox{ if $x\in\partial^{2t}\root$ and } \ETA_{x}^{(\ell)}<-2t^c \enspace, \\
2t^c&\mbox{ if $x\in\partial^{2t}\root$ and } \ETA_{x}^{(\ell)}>2t^c \enspace,\\
\ETA_{x}^{(\ell)}&\mbox{ otherwise} \enspace.
\end{cases}
\end{align}
Further, let
$
\ETA^{(\ell,t)}
$
be the result of $t$ iterations of $\LDEP_{{\TT}^{(\ell)}}(\nix)$ starting from $\bar\ETA^{(\ell,t)}$.
The following corollary is a direct consequence of \Lem~\ref{lem:upthetree} and  \Lem~\ref{lem_SmallOnTop}.

\begin{corollary}\label{Cor_boundary}
For any $\ell>ct^c$ we have $\Pr[\ETA^{(\ell,t)}_\root \neq \ETA^{(\ell)}_\root]<\eps_t.$
\end{corollary}

\begin{proof}
Due to Lemma~\ref{lem_SmallOnTop}, the truncation in \eqref{eq:truncEta} is
inconsequential with probability at least $1-\varepsilon_t$, in which case
\begin{align*}
\ETA^{(\ell,t)}
=
\LDE^{+ (t)}_{{\TT}^{(\ell)}}(\bar\ETA^{(\ell,t)})
=
\LDE^{+ (t)}_{{\TT}^{(\ell)}}(\ETA^{(\ell)})
=
\LDE^{+ (\ell+ t)}_{{\TT}^{(\ell)}}(+\infty, \ldots, +\infty)
=
\ETA^{(\ell)}
\enspace,
\end{align*}
where the last equality follows from Lemma~\ref{lem:upthetree}.
\end{proof}

Recall that we defined the non-random operator $\LDELitS{{k},d}$ from~\eqref{eqLDELitS}, mimicking $\LDE^{+}_{{\TT}^{(\ell)}}$.
To make the connection between the
random operator $\LDE^{+}_{{\TT}^{(\ell)}}$ and $\LDELitS{{k},d}$ precise, we introduce the
following concepts. 
Given a tree formula $T$ we write $V_{\AllKid}(T)$, for the set of $x$ variables of $T$ that appear both as positive and negative literals in the sub-tree $T_x$ comprising $x$ and its the progeny. 
We define  $V_{\NoKid}(T), V_{\PureP}(T)$, and $V_{\PureM}(T)$ similarly.
Note that the above sets constitute a partition of $V(T)$. 
We use $\type: V(T) \to \{\AllKid, \PureP, \PureM, \NoKid\}$ to indicate the part vertex belongs to.
We denote with $\TT^{(\ell)}_{\AllKid}$ the random Galton-Watson formula $\TT$ conditioned on the root $\type(\root)=\AllKid$. 
We define $\TT^{(\ell)}_{\PureP}$, and $\TT^{(\ell)}_{\PureM}$ analogously. 
Degenerately, we also write $\TT^{(\ell)}_{\NoKid}$ for the formula comprised by a single variable $\root$.
Let us denote with $\rho^{(\ell, t)}_{\AllKid}$ the distribution of $\bar\ETA_\root^{(\ell,t)}$ in $\TT^{(\ell)}_{\AllKid}$. 
Moreover, let $\bar\rho^{(\ell-t)}_{\AllKid}$ be the distribution of
\begin{align*}
\ETA_{\root}^{(\ell-t)} \cdot\Ind\left\{|\ETA_{\root}^{(\ell-t)}| \le 2t^c\right\}  + 2t^c \cdot\Ind\left\{\ETA_{\root}^{(\ell-t)} > 2t^c\right\}
-2t^c \cdot\Ind\left\{\ETA_{\root}^{(\ell-t)} < -2t^c\right\}
\enspace,
\end{align*}
i.e., the truncation of $\ETA_{\root}^{(\ell-t)}$ in
$\TT^{(\ell)}_{\AllKid}$.
Analogously we define the distributions $ \rho^{(\ell, t)}_{\PureP}, \rho^{(\ell, t)}_{\PureM}$, and
$\bar\rho^{(\ell-t)}_{\PureP}, \bar\rho^{(\ell- t)}_{\PureM}$. Notice that, degenerately,
$\rho^{(\ell- t)}_{\NoKid} = \bar\rho^{(\ell-t)}_{\NoKid} = \delta_{0}$.


\begin{lemma}\label{lem_NoR_R_OP}
For $\ell > ct^c$ we have that
$ \left(\rho^{(\ell, t)}_{\AllKid}, \rho^{(\ell, t)}_{\PureP}, \rho^{(\ell, t)}_{\PureM}\right)
= \LDELitS{k,d} \left(\bar\rho^{(\ell- t)}_{\AllKid}, \bar\rho^{(\ell- t)}_{\PureP}, \bar\rho^{(\ell- t)}_{\PureM}\right).
$
\end{lemma}

\begin{proof}
We use induction on $t$. Specifically, let $\nu = \left(\nu_{\AllKid}, \nu_{\PureP}, \nu_{\PureM}\right)$ be any triplet in
$\cP(-\infty, \infty] \times \cP[0, +\infty] \times \cP[-\infty,0]$, and $\nu^{(t)} =\LDELit^{\star (t)}_{k,d}(\nu)$ be the outcome
of the $t$-fold application of $\LDELitS{k,d}$. Moreover, let $(\ETA_x)_{x\in V(\TT^{(t)})}$ be a vector of independent samples
with  $\ETA_x \disteq \nu_{\type(x)}$.
We claim that root value $\ETA^{(t)}_\root$ of the random operator $\LDE^{+ (t)}_{{\TT^{(t)}}}$,  coincides with $\nu_{\type(\root)}$. Indeed, for
$t=1$ the claim follows readily from the definitions. For the inductive step, we notice that the $t$-fold application of $\LDELitS{k,d}$ is
obtained by applying $\LDELitS{k,d}$ to the $(t-1)$-fold application. 
Per the induction hypothesis
\begin{align}
\bc{\LDE^{+ (t-1)}_{\TT^{(t-1)}}(\ETA_x)_{x}}_{\root} \disteq \nu^{(t-1)}_{\type(\root)}
\enspace.
\end{align}
Applying $\LDELitS{k,d}$ to $\nu^{(t-1)}$ implies the result as the first layer of $\TT^{(t)}$ is independent of the subtrees rooted at the
grandchildren $\partial^2 \root$ of the root, which are distributed as i.i.d.\ copies of $\TT^{(t-1)}$. 
The lemma follows from applying the above identity to
$\nu = \left(\bar\rho^{(\ell- t)}_{\AllKid}, \bar\rho^{(\ell- t)}_{\PureP}, \bar\rho^{(\ell- t)}_{\PureM}\right)$.
\end{proof}

Refining the definition of the $\BP_{d,k}$ operator in \eqref{eqBPop}, we write  $\BP_{d,k}^{\AllKid}$ for the operator obtained from
$\BP_{d,k}$ upon conditioning on $\vd^+,\vd^- \ge 1$. Similarly $\BP_{d,k}^{\PureP}$ and $\BP_{d,k}^{\PureM}$ are obtained from
$\BP_{d,k}$ upon conditioning on $\vd^+\ge 1,\vd^- = 0$, and $\vd^+ = 0 ,\vd^- \ge 1$, respectively.
We define
\begin{align*}
\pi^{\AllKid}_{d,k}=\BP_{d,k}^{\AllKid} \left(\pi_{d,k}\right),\enspace
\pi^{\PureP}_{d,k}=\BP_{d,k}^{\PureP} \left(\pi_{d,k}\right),\enspace
\pi^{\PureM}_{d,k}=\BP_{d,k}^{\PureM} \left(\pi_{d,k}\right)\enspace.
\end{align*}
Let us write $\fratio, \fprop$ for the continuous and mutually inverse real functions
\begin{align}
\fratio: \RR \to (0,1), \enspace z \mapsto (1 + \tanh(z/2))/2, &&
\fprop: (0,1) \to \RR, \enspace p \mapsto \log (p/(1-p))
\enspace.
\end{align}
Let $\rho^{\AllKid}_{d,k}=\fprop(\pi_{d,k}^{\AllKid})$,  and define $\rho^{\PureP}_{d,k}, \rho^{\PureM}_{d,k}$ similarly.


\begin{claim}\label{cl_FixedPoints_LL}
The vector $\bc{\rho^{\AllKid}_{d,k}, \rho^{\PureP}_{d,k}, \rho^{\PureM}_{d,k}}$ is a fixed point of the operator $\LDELitS{d,k}$.
\end{claim}

\begin{proof}
Let $\rho_{d,k}=\fprop\bigl(\pi_{d,k}\bigr)$.
First, we claim that
\begin{align}\label{eq_dixq}
\LDELitS{d,k}\bc{\rho_{d,k}, \rho_{d,k}, \rho_{d,k}} = \bc{\rho^{\AllKid}_{d,k}, \rho^{\PureP}_{d,k}, \rho^{\PureM}_{d,k}}
\enspace.
\end{align}
Indeed, since all input distributions are the same, by \Prop~\ref{prop_arnab}, the two summands in %\eqref{eq:AllKidRecGUnqBak}
the left term of \eqref{eq:AllKidRecGUnq} corresponding to $\vdpc$ and $\vdmc$ are identically distributed, and also identically distributed to the sums that appear in the other two terms.
Therefore,
\eqref{eq_dixq} follows directly from the definitions of $\BP_{d,k}^{\AllKid}, \BP_{d,k}^{\PureP}$, and $ \BP_{d,k}^{\PureM}$.
The claim now follows from \eqref{eq_dixq}, the definition of the operator $\LDELitS{d,k}$, and the law of total probability.
\end{proof}


Let $\rho^{(\ell)}$ be the distribution of the log-likelihood ratio $\ETA^{(\ell)}_\root$.

\begin{corollary}\label{cor_wk_prp}
For $d < \dours(k)$ the sequence $\bc{\fratio\bc{\rho^{(\ell)}}}_{\ell}$ converges weakly to $\pi_{d,k}$.
\end{corollary}

\begin{proof}
The result follows by combining \Cor~\ref{Cor_boundary}, \Lem~\ref{lem_NoR_R_OP}, \Prop~\ref{prop_BPPureLit}, \Cl~\ref{cl_FixedPoints_LL},
and applying the continuous mapping theorem and the law of total probability.
\end{proof}


\begin{proof}[Proof of \Prop~\ref{prop:condMarg}]
Recall that we write $\LDE_{\TT^{(\ell)}}^{+(\ell)}$ for the $\ell$-fold iteration of the operator $\LDEP_{{\TT}^{(\ell)}}$.
Let $\THETA^{(\ell)}_\root = \bigl(\LDE^{+(\ell)}_{\TT^{(\ell)}}(0, \ldots, 0)\bigr)_\root$.
Using arguments similar to \Fact~\ref{fac_BPexact}, we can show that  $\THETA^{(\ell)}_\root$ is nothing but the distribution of the random variable
$\fprop(\pr\brk{\TAU^{(\ell)}(\root)=1\mid\TT})$. Therefore,
\begin{align*}
{\pr[\TAU^{(\ell)}(\root)=1\mid\TT]}\disteq
\fratio(\THETA^{(\ell)}_\root) \enspace, &&
\text{ and }
&&
{\pr[\TAU^{(\ell)}(\root)=1 \mid \forall y\in\partial^{2\ell}\root: \TAU^{(\ell)}(y) = \TAU^+(y),\TT]} \disteq \fratio(\ETA^{(\ell)}_{\root})
\enspace.
\end{align*}
Due to \Lem~\ref{lem:ExtremalBnd}, $0 \le \fratio(\THETA^{(\ell)}_\root) \le \fratio(\ETA^{(\ell)}_\root) \le 1$. 
Moreover, from \Lem~\ref{lem_NoR_R_OP}, \Prop~\ref{prop_BPPureLit}, and \Cl~\ref{cl_FixedPoints_LL}, we see that for $d < \dours(k)$ the sequence $\bigl(\fratio(\THETA^{(\ell)}_\root)\bigr)_\ell$ converges weakly to $\pi_{d,k}$. 
Finally, \Cor~\ref{cor_wk_prp} implies that $\bigl(\fratio(\ETA^{(\ell)}_\root)\bigr)_\ell$ also converges weakly to $\pi_{d,k}$, and thus,
\begin{align*}
\lim_{\ell \to \infty} \Erw \left|\fratio(\THETA^{(\ell)}_\root)- \fratio(\ETA^{(\ell)}_\root)\right|
=
\lim_{\ell \to \infty} \left|\Erw\brk{\fratio(\THETA^{(\ell)}_\root)} - \Erw\brk{\fratio(\ETA^{(\ell)}_\root)}\right| = 0 \enspace,
\end{align*}
implying the assertion.
\end{proof}







