%We will be particularly interested in the categories $Rel_{inj}(\tau), Rel_{inj}(\tau, \tau')$ and $ Rel_{inj}^{cov}(\tau, \tau')$, where morphisms are injective homomorphisms, and the set of objects is $Rel(\tau), Rel(\tau,\tau')$ and the subset of $Rel(\tau,\tau')$, where every element is in exactly one relation from $\tau'$.

%Let $\mathcal F'$ be a finite set of structures in the category $\mathcal C$ (one of the above categories with structures from $Rel(\tau,\tau')$).
%By ${\rm Forb}(\mathcal F')$ we denote the class of all structures ${\bf
%A}' \in {\mathcal C}$ satisfying ${\bf F}' \not\longrightarrow \bf A'$ for every ${\bf F}' \in \mathcal F'$. %(This class is sometimes,
%and perhaps more efficiently, denoted by ${\mathcal F'} \not\rightarrow$.)
%So the class $\Phi({\rm Forb}(\mathcal F'))$ is the class of all structures $\bf{A}$ which have a lift $\bf{A}'$ in the class ${\rm Forb}(\mathcal F')$. These are typical classes investigated here.


%Similarly (well, dually), for the finite set of structures $\mathcal D'$ in $\mathcal C$ we denote by $CSP(\mathcal D')$ the class of all structures ${\bf A}' \in \mathcal C$ satisfying ${\bf A}' \longrightarrow {\bf D}'$ for some ${\bf D}' \in \mathcal{D}'$.

$MMSNP$ languages in $Rel(\tau)$ are introduced in  \cite{FV}.  In the setting of this paper they can be defined as languages $\Phi(Forb(\mathcal{F'})) \subset Rel^{cov}(\tau, \tau')$ for a suitable type $\tau'$ consisting of monadic symbols and finite set $\mathcal{F'}$ of $\tau'$-lifted structures of type $\tau$. An $MMSNP$ language is equal to a finite $CSP$ language iff it can defined by a minimal set $\mathcal{F'}$ of lifted structures whose cores are trees. For other results on $MMSNP$ and its connection to $CSP$ see Bodirsky, Madeleine and Mottet \cite{BMM}, and Bienvenu, ten Cate, Lutz and Wolter \cite{BCLW}.

\begin{remark} \label{pattern2CSP}
If every structure in $\Phi(\mathcal{F'})$ consists of a single non-degenerate relational tuple then $\Phi(Forb(\mathcal{F'}))$ is a $CSP$ language. This is easy to see: the base set of the $CSP$ language is $\tau'$ and a tuple is in relation $R \in \tau$ iff the corresponding $\tau'$-lift of the tuple is not in $\mathcal{F'}$.
\end{remark}

The following theorem works for an infinite $\tau'$ as well. We apply it in two cases: when $\tau'$ is finite and when $\tau'$ corresponds to $\mathbb{Q}$.

A set $\mathcal{F}' \subset Rel_{inj}(\tau, \tau')$ is called {\it normal}, if
$\tau'$ contains only unary relations, and if
for any ${\bf F_1', F_2'} \in \mathcal{F'}$ if
$\Phi({\bf F_1'})$ is isomorphic to a substructure of $\Phi({\bf F_2'})$
then $\mathcal{F'}$ contains every lift of $\Phi({\bf F_2'})$ extending the lift
of the isomorphic copy of $\Phi({\bf F_1'})$. Note that every language $\Phi({\rm Forb}_{inj}(\mathcal{F'}))$ is equal to one defined by a normal set of patterns (we simply add  patterns to the original set if necessary).

\begin{theorem} \label{theCSP}
Consider a pair of finite relational types $\tau$ and $\tau'$, where $\tau'$ contains only unary relational symbols, and a normal set $\mathcal{F'} \subset Rel_{inj}(\tau, \tau')$ such that $\Phi(\mathcal{F}')$ is finite and
every lift  ${\bf F'} \in \mathcal{F'}$ is biconnected. Set
$g=max_{{\bf F}' \in \mathcal{F}'}|{F}'|$. Let $\beta$ be the finite relational type consisting of the $|F|$-ary relational symbols $R_{\bf F}$ for isomorphism types ${\bf F} \in \Phi(Forb(\mathcal{F}')$. Let ${\bf T}$ be
the relational structure  of type $\beta$ with base set $T=\tau'$ defined as follows: an $|F|$-tuple is in $R_{\bf F}({\bf T})$ iff the corresponding lift is not in $\mathcal{F}'$.
(Alternatively, we can view  $R_{\bf F}({\bf T}) \subset T^{|F|}$, by identifying $F$
and $[|F|]$, elements of $T^{|F|}$, as mappings in $T^F$, or, rather
a structure in $Rel_{inj}(\tau, \tau')$ with shadow ${\bf F}$.)

Then the following holds for ${\bf T}$.

\begin{enumerate}

\item
{For every finite ${\bf A} \in Rel(\tau)$ there exists ${\bf B} \in Rel(\beta)$ with $B=A$ that the set of homomorphisms ${\bf B} \longrightarrow {\bf T}$ is exactly the set of mappings inducing a lift
${\bf A}' \in Forb(\mathcal{F}')$. Moreover, ${\bf B}$ can be calculated in polynomial time (of $|A|$).}

\item
{For every finite ${\bf B} \in Rel(\beta)$ with girth greater than $g$ there exists ${\bf A} \in Rel(\tau)$ with $A=B$ that the set homomorphisms ${\bf B} \longrightarrow {\bf T}$ is exactly the set of mappings inducing a lift
${\bf A}' \in Forb(\mathcal{F}')$. Moreover, ${\bf A}$ can be calculated in polynomial time (of $|B|$).}

\end{enumerate}

\end{theorem}


\begin{proof}
%We will construct the CSP language following the proof of Feder-Vardi...
%First, we determine the type of the relational structures in this language.
%For every isomorphism class in $\Phi(\mathcal{F'})$ we choose one structure ${\bf F}$ in this class. We  assume that the base set of the representative ${\bf F}$ is $\{1, \dots ,|F| \}$. We introduce the relational symbol $R_{\bf F}$ of arity  $|F|$ (the size of the structure). Denote by $\beta$ the type that consists of these relational symbols $R_{{\bf F}}$. This will be the type of our CSP language.

We define the following functors $\Psi$ and $\Theta$. The functor $\Psi: Rel(\tau) \rightarrow Rel(\beta)$ assigns to a structure ${\bf A}$ a structure $\Psi({\bf A})$ on the same base set. The relations of $\Psi({\bf A})$ are defined as follows:

$R_{\bf F}(\Psi({\bf A}))= \{(f_1,...,f_{|F|}\}:  f: {\bf F} \hookrightarrow {\bf A}\}$, shortly $\{ f : f: {\bf F} \hookrightarrow {\bf A} \}$
($f$ is a injective homomorphism in $Rel_{inj}(\tau)$).
In other words, a tuple of elements is in relation
$R_{\bf F}$ if it is the injective homomorphic image of ${\bf F}$.

The functor $\Theta$ maps a
structure ${\bf B} \in Rel(\beta)$ to the following structure in $Rel(\tau)$ again on the
same base set:

$\Theta({\bf B})= \cup \{ f({\bf F}): {\bf F} \in \Phi(\mathcal{F'}),
f \in R_{\bf F}({\bf B})\}$,
where  $f({\bf F}) \text{ is the injective }$ $\text{ homomorphic image of the structure } {\bf F} \}.$

The mappings $\Psi$ and $\Theta$ are both functorial. Consider the
induced functors $\Psi': Rel(\beta,\tau') \rightarrow
Rel(\tau,\tau')$ and $\Theta': Rel(\tau,\tau') \rightarrow
Rel(\beta, \tau')$. We will use the following (easy to check) properties of these
functors.

\vspace{2mm}

(i) $\Theta \circ \Psi = id_{Rel(\tau)}$ and $\Theta' \circ \Psi'= id_{Rel(\tau,\tau')}$

(ii) For every ${\bf U} \in Rel(\beta)$ (${\bf U'} \in
Rel(\beta,\tau')$) and relational symbol $T \in \beta$ the
following inclusions hold:

$R(\Psi \circ \Theta ({\bf U})) \supseteq R({\bf U})$ and

$R(\Psi' \circ \Theta' ({\bf U'})) \supseteq R({\bf U'})$.

\vspace{2mm}

We define a finite set of structures
$\mathcal{S'} \subset Rel(\beta, \tau')$ as follows. We put ${\bf S'} \in \mathcal{S'}$ if
${\bf S}$ has one single relational tuple, and
$\Theta'({\bf S'})$ is isomorphic to a structure in $\mathcal{F'}$.
Since $\Phi(\mathcal{S'})$ consists of single relational tuples the language $\Phi(Forb(\mathcal{S'}))$ it is a $CSP$ language:
in fact, is $CSP({\bf T})$ as Remark \ref{pattern2CSP} shows.
We prove that $CSP({\bf T})=\Phi(Forb(\mathcal{S'}))$ satisfies to the conditions of the theorem.
Observe the following  consequences of the
construction of $\mathcal{S'}$:

\vspace{2mm}

(iii) If ${\bf A'} \notin Forb(\mathcal{F'})$ then $\Psi({\bf A'})
\notin Forb(\mathcal{S'})$ holds for every ${\bf A'} \in
Rel(\tau,\tau')$, since ${\bf A'} \in \mathcal{F'}
\Longrightarrow \Psi({\bf A'}) \in \mathcal{S'}$.

(iv) If ${\bf U'} \notin Forb(\mathcal{S'})$ then $\Theta({\bf U'})
\notin Forb(\mathcal{F'})$ holds for every ${\bf U'} \in
Rel(\beta,\tau')$, since ${\bf U'} \in \mathcal{S'}
\Longrightarrow \Theta({\bf U'}) \in \mathcal{F'}$.

\vspace{2mm}

First, we will show that for a structure ${\bf A} \in Rel(\tau)$ the equivalence
${\bf A} \in \Phi(Forb(\mathcal{F'})\iff \Psi({\bf A}) \in \Phi(Forb(\mathcal{S'}))$ holds. This is implied by the equivalence in the lifted category as the same $\tau'$ relations prove the membership in both
languages: If ${\bf A'} \in Forb(\mathcal{F'})$ then $\Psi'({\bf
A'}) \in Forb(\mathcal{S'})$ by (i) and (iv). On the other hand,
(iii) implies that if ${\bf A'} \notin Forb(\mathcal{F'})$ then
$\Psi'({\bf A'}) \notin Forb(\mathcal{S'})$.

We will prove that for every ${\bf B} \in
Rel(\beta)$ with girth greater than $g$ the equivalence ${\bf B} \in
\Phi(Forb(\mathcal{S'})) \iff \Theta({\bf B}) \in \Phi(Forb(\mathcal{F'})$ holds. We
prove the equivalence again in the lifted categories. If
$\Theta'({\bf B'}) \in Forb(\mathcal{F'})$ then $\Psi'(\Theta'({\bf B'})) \in Forb(\mathcal{S'})$, as we have seen earlier. (The structure ${\bf B'}$ contains less relations than $\Psi'(\Theta'({\bf B'}))$ by (ii), hence ${\bf B'} \in Forb(\mathcal{S'})$.)

If $\Theta'({\bf B'}) \notin Forb(\mathcal{F'})$ then there exists a structure ${\bf F'} \in \mathcal{F'}$ and an injective homomorphism $\varphi:{\bf F'} \rightarrow \Theta'({\bf B'})$. Since the image $\varphi({\bf F'})$ is biconnected, the girth condition implies that it should be contained by the image of a single relational tuple of ${\bf B}$ under $\Theta$. The image of this tuple of ${\bf B}$ is isomorphic to a particular structure ${\bf F_0} \in \Phi(\mathcal{F'})$. Since $\mathcal{F'}$ is normal, there exists an ${\bf F_0'} \in \mathcal{F'}$ containing
$\varphi({\bf F'})$ as a substructure. Hence $\Psi({\bf F_0'})$ witnesses that ${\bf B'} \in Forb(\mathcal{S'})$.

Finally, $(1)$ follows by choosing ${\bf B}=\Theta({\bf A})$, while for $(2)$ we set ${\bf A}=\Psi(B)$.

\end{proof}

The following  result is the dichotomy theorem for colored biconnected patterns.

\begin{theorem} \label{inj2con}
For any pair of finite relational types $\tau$ and $\tau'$,
where $\tau'$ contains only unary relational symbols, and a finite set $\mathcal{F'} \subset Rel_{inj}^{cov}(\tau, \tau')$,
if every lift  ${\bf F'} \in {\rm Forb}_{inj}(\mathcal{F'})$ is biconnected then
$\Phi({\rm Forb}_{inj}(\mathcal{F'}))$
is either tractable or $NP$-complete.
\end{theorem}


\begin{proof}
We apply Theorem \ref{theCSP} and we get a finite relational structure ${\bf T}$ of (probably different) finite type and $g>0$ such that
$\Phi({\rm Forb}_{inj}(\mathcal{F'}))$ can be reduced to $CSP({\bf T})$ and
$CSP({\bf T})$ restricted to structures with girth greater than $g$ has a reduction to $\Phi({\rm Forb}_{inj}(\mathcal{F'}))$. We know from \cite{K} that $CSP({\bf T})$ is polynomially equivalent to its restriction to structures with girth greater than $g$. Hence $\Phi({\rm Forb}_{inj}(\mathcal{F'}))$ and $CSP({\bf T})$ are polynomially equivalent. The dichotomy theorem for finite $CSP$'s implies the theorem.
\end{proof}

\begin{proposition} \label{precise}
Consider a relational type $\tau$ and a finite set of finite ordered relational structures $\mathcal{F}^<$ of type $\tau$. Let $\tau'$ be the relational type with countably infinite unary relational symbols labeled by the rational numbers.
Set $\underline{\mathcal{F}'} \subseteq Rel^{cov}_{inj}(\tau,\tau')$ as follows.

\begin{itemize}

\item
{For every ordered structure ${\bf F}^< \in \mathcal{F}^<$ we add to $\underline{\mathcal{F}}'$ every $\tau'$-lift of ${\bf F}$ if any two elements get the same color.}

\item
{For every ordered structure ${\bf F}^< \in \mathcal{F}^<$ we add to $\underline{\mathcal{F}}'$ every $\tau'$-lift of ${\bf F}$ if the order of the rationals corresponding to the unary relations in $\tau'$ agrees with the ordering of ${\bf F}^<$.}

\end{itemize}

Then the $\mathcal{F}^<$-ordering problem and $\Phi(Forb_{inj}(\underline{\mathcal{F}}'))$ are the same languages.
\end{proposition}

\begin{proof}
Given a relational structure with a witness ordering ${\bf S}^<$ for the $\mathcal{F}^<$-ordering problem consider an
${\bf S}' \in Rel^{cov}_{inj}(\tau, \tau')$, where the order of the rationals corresponding to the relational symbols in $\tau'$ is the same as the ordering ${\bf S}^<$. Clearly ${\bf S}' \in Forb_{inj}(\underline{\mathcal{F}}')$.

On the other hand, consider ${\bf S}' \in Rel^{cov}_{inj}(\tau, \tau')$. Every element in $S$ is in a different unary relation of $\tau'$, else a two-element pattern of the first type could be embedded into ${\bf S}'$. Consider the ordering
${\bf S}^<$ induced by the ordering of the corresponding rationals, this is a good witness for the ordering problem.
%If there are elements in the same $\tau'$ relation then these can not be in the same relational tuple. Thus, we can perturb the corresponding rationals without changing the order on any relational tuple in a $\tau$-relation. The corresponding unary relations in $\tau'$ still give a good witness, and since they are all different, they induce a good ordering.
\end{proof}

We will use the following technical lemma in the proof of Theorem \ref{main2}.

\begin{lemma} \label{param}
The $\mathcal{F}^<$-ordering problem is polynomially equivalent to the $\mathcal{F}^<$-ordering problem, where we only consider orderings extending the prescribed ordering of a subset of constant size.
\end{lemma}

\begin{proof}
Given the elements $x_1, \dots ,x_k$ with a prescribed ordering, consider a relational structure ${\bf U} \in Rel(\tau)$ with $k$ distinguished elements, to which we refer as roots, such that for any $k$-tuple $y \in \mathbb{Q}^k$ if there is an injective homomorphism ${\bf U} \longrightarrow {\bf T}$ mapping the roots to $y_1, \dots ,y_k$ (in the same order) then there is an automorphism $\alpha=\alpha_y$ of $(\mathbb{Q},<)$ such that $\alpha(y_i)=x_i$ for every $i$.

The reduction of the ordering problem with the ordering prescribed on $k$ elements to the original ordering problem assigns to a structure ${\bf S}$ the structure ${\bf W}$ obtained by adding a copy of ${\bf U}$ on the elements with prescribed order.
If this has a good ordering then we represent it by an injective mapping $\iota$ to the rationals. Now $\alpha \circ \iota$, where $\alpha$ is the
above authomorphism corresponding to the tuple
$(\iota(x_1), \dots ,\iota(x_k))$, gives a good mapping preserving the prescribed order on $\{ x_1, \dots ,x_k \}$.
\end{proof}

\begin{proof}(of Theorem \ref{main2})
Consider the signature $\tau'$ of unary relational symbols, we identify these with the set of rational numbers $\mathbb{Q}$.

And consider the set of finite structures $\underline{\mathcal{F}'}$ defined in Proposition \ref{precise}. We know that the $\mathcal{F}^<$-ordering problem and $\Phi(Forb_{inj}(\underline{\mathcal{F}}'))$ are the same languages, which we denote by $L$.

We apply Theorem \ref{theCSP} to $\underline{\mathcal{F}}' \subseteq Rel^{cov}_{inj}(\tau, \tau')$ in order to get a relational structure ${\bf T}$ and $g>0$ such that
$L$ can be reduced to $CSP({\bf T})$ and
$CSP({\bf T})$ restricted to structures with girth greater than $g$ has a reduction to $L$. Moreover, we know that $CSP({\bf T})$ is a simple temporal $CSP$, and Bodirsky and K\'ara \cite{BK} proved dichotomy for temporal constraint languages.
(See Section \ref{secpoly}, where their theorem and its consequences are discussed in greater details.)

If $CSP({\bf T})$ is tractable then the ordering problem is also tractable.

If $CSP({\bf T})$ is not tractable then Corollary \ref{useful} shows that there exists a $D>0$ and finitely many rational numbers that if we add those to the signature as unary symbols and also add them to ${\bf T}$ as constant relations then for the resulting type $\tau_+$ and structure ${\bf T}_+$ of type $\tau_+$ the problem $CSP({\bf T}_+)$ is $NP$-complete, when restricted to structures with maximum degree at most $D$.
%The Sparse Incomparability Lemma \ref{ordered} implies that $CSP({\bf T})_+$ restricted to structures with girth greater than $g$ is $NP$-complete.
%Consider the relational type $\tau_+$ consisting of the relational symbols of $\tau$ plus a unary symbol for every parameter added it to ${\bf T}_+$.
Enlarge $\underline{\mathcal{F}}' \subseteq Rel^{cov}_{inj}(\tau, \tau')$ by adding for every extra unary symbol in $\tau_+ \setminus \tau$ the one-element structures in $Rel^{cov}_{inj}(\tau_+, \tau')$, where the element is in the unary relation in $\tau_+$ corresponding to the rational number the symbol is assigned to, but also in a unary relation from $\tau'$ corresponding to a different rational number (for every pair in $(\tau_+ \setminus \tau) \times \tau'$ but those pairs corresponding to the same rational number).
Make this normal in order to obtain $\underline{\mathcal{F}}'_+ \subseteq Rel^{cov}_{inj}(\tau_+, \tau')$. Observe that $(2)$ of Theorem \ref{theCSP}, Corollary \ref{useful} and the Sparse Incomparability Lemma \ref{ordered} provide a polynomial time reduction of $CSP({\bf T}_+)$ to $\Phi(\underline{\mathcal{F}}'_+)$. And $\Phi(\underline{\mathcal{F}}'_+)$ is equivalent to the $\mathcal{F}^<$-ordering problem with prescribed ordering on a set of constant size by Proposition \ref{precise}. Lemma \ref{param} implies that this is equivalent to the $\mathcal{F}^<$-ordering problem, hence that is also $NP$-complete.

