    \centering
    \includegraphics{approx-cov.pdf}
    \caption{Illustration of how the path starting in cell $i$ from the global group of the coverage of $e[s,t]$ is dominated by the proxy coverage of $e[s,t]$ and $\rev{e[s,t]}$ if $i$ is bad for $e[s,t]$ and hence good for $\rev{e[s,t]}$. Importantly $[l_i(s),r_j(t)]\subset[l_i(t),r_i(s)]\cup[\hat{l}_i(s),r_j(t)]$.
    }
    \label{fig:approx-cov}
\end{figure}

\begin{lemma}\label{lem:proxyapprox}
    The proxy coverage approximates the coverage. That is
    \[\Cov_{A_S}(e[s,t])\subset\proxyCov_{A_S}(e[s,t])\cup \proxyCov_{A_S}(\rev{e[s,t]}).\]
\end{lemma}
\begin{proof}
    If $i$ is in $\localG(e[s,t])\setminus\bad(e[s,t])$, then $[l_i(s),r_i(t)]\subset \proxyCov_{A_S}(e[s,t])$. If instead $i$ is in $\localG(e[s,t])\cap\bad(e[s,t])$ then by \Cref{lem:revprob} it follows that $[l_i(s),r_i(t)]\subset [l_i(t),r_i(s)]\subset \proxyCov_{A_S}(\rev{e[s,t]})$. 

    Let now instead $(i,j)\in\redGlobG(e[s,t])$. We show that $[l_i(s),r_i(s)]\cup[r_i(s),l_j(t)]\cup[l_j(t),r_j(t)]\subset \proxyCov_{A_S}(e[s,t])\cup \proxyCov_{A_S}(\rev{e[s,t]})$. First observe that $[r_i(s),l_j(t)]\subset \proxyCov_{A_S}(e[s,t])$. Assume $i$ is bad, as otherwise $[l_i(s),r_i(s)]\subset [l_i(s),l_j(t)]\subset \proxyCov_{A_S}(e[s,t])$. But then by \Cref{lem:revprob} $[l_i(s),r_i(s)]\subset [l_i(t),r_i(s)]\subset \proxyCov_{A_S}(\rev{e[s,t]})$ (refer to \Cref{fig:approx-cov}). Similarly $[l_j(t),r_j(t)]\subset \proxyCov_{A_S}(e[s,t])\cup \proxyCov_{A_S}(\rev{e[s,t]})$ implying the claim.
\end{proof}

\begin{theorem}\label{thm:16setsystem}
    Let $P$ be a polygonal curve, and let $S$ be a simplification of $P$. 
    Then for any curve $\pi\in\curvespace{\ell}$ there is a set $S_\pi\subset \ConcreteCandidates{S}(P)$ of size at most $16$ such that 
    \[\Cov_P(\pi,\Delta)\subset\bigcup_{s\in S_\pi}\proxyCov_{P}(s).\]
\end{theorem}
\begin{proof}
    This follows from the definition of the proxy coverage, \Cref{lem:proxyapprox} and \Cref{lem:supersetfreespace}.
\end{proof}

\begin{algorithm}
\caption{Maintenance of the reduced global group}\label{alg:main}
\begin{algorithmic}[1]
\Procedure{Maintain}{$e$, $A_e$, sweep-sequence $\sweepseq=\{(s_1,t_1),\ldots,(s_m,t_m)\}$ of $\extremal{}(A_e)$}
    \State for every $i$ compute $B_i=\{(s,t)\in S\mid \text{$i$ is bad for $e[s,t]$}\}$ \Comment{\Cref{lem:badsets}}
    \State Compute coverage $\Cov_{A_e}(e[s_m,t_m])$ represented as $\O(n)$ disjoint intervals
    \State Compute $\localG(e[s_m,t_m])$ and $\globalG(e[s_m,t_m])$ from $\Cov_{A_e}(e[s_m,t_m])$ 
    \State $\unifyG,\localG,\globalG,(s,t)\gets \localG(e[s_m,t_m])\cup \globalG(e[s_m,t_m]),\localG(e[s_m,t_m]),\globalG(e[s_m,t_m]),(s_m,t_m)$
    \State Compute $\bad(e[s,t])$ from $B_i$ and with it $\redGlobG\gets \redGlobG(e[s_m,t_m])$
    \For{$(s',t')$ in \textsc{Reversed}(S)}\label{line:forloop}\Comment{sweeping-window events}
        \If{ $s'\neq s$}
            \State  Compute $\bad(e[s',t])\setminus\bad(e[s,t])$ and $\bad(e[s,t])\setminus\bad(e[s',t])$ via the intervals $B_i$
            \State Update $\unifyG, \localG, \globalG$ and $\redGlobG$ via $\textsc{AdvanceStart}(s,s',t)$
            \State Update $\bad(e[s,t])$ to $\bad(e[s',t])$ via the intervals $B_i$
            \State $s\gets s'$
        \EndIf
        \If{$t'\neq t$}
            \State  Compute $\bad(e[s,t'])\setminus\bad(e[s,t])$ and $\bad(e[s,t])\setminus\bad(e[s,t'])$ via the intervals $B_i$
            \State Update $\unifyG, \localG, \globalG$ and $ \redGlobG$ via $\textsc{AdvanceEnd}(s,t,t')$
            \State Update $\bad(e[s,t])$ to $\bad(e[s',t])$ via the intervals $B_i$
            \State $t\gets t'$ 
        \EndIf
    \EndFor
\EndProcedure
\end{algorithmic}
\end{algorithm}

\subsection{Maintaining the proxy coverage along a sweep-sequence}\label{sec:symbolicRepresentation}

In this section we show that during a sweep-sequence one can correctly maintain a symbolic representation of $\proxyCov_{A_S}(e[s,t])$ in (roughly) logarithmic time per element in the sweep-sequence. To this end we show that one can correctly maintain $\redGlobG(e[s,t])$, $\localG(e[s,t])\setminus\bad(e[s,t])$ and $\bad(e[s,t])$. For this we define the set $\unifyG(e[s,t])$ of inclusion-wise maximal index-pairs $(i,j)$ such that either $i=j$ and $l_i(s)\neq\infty$ or there is a path from cell $i$ at height $s$ to cell $j$ at some height $\hat{t}\leq t$, which helps us maintain $\redGlobG(e[s,t])$, $\localG(e[s,t])\setminus\bad(e[s,t])$.


\begin{lemma}\label{lem:badsets}
    Let $\sweepseq\in\edgeseqs{e}$ be a sweep-sequence. The set $B_i=\{(s,t)\in \sweepseq|\text{$i$ is bad for $e[s,t]$}\}$ is a contiguous subset of $\sweepseq$. They can be computed in total time $\O(n\log n)$
\end{lemma}
\begin{proof}
    This is an immediate consequence of the fact that for the right-most top-most point at $x$-coordinate $x_\mathrm{top}$ the set $\{(s,t)\in \sweepseq|l_i(s)\neq\infty,\ l_i(s)\geq x_\mathrm{top}\}$ is contiguous. So is the set $\{(s,t)\in \sweepseq|r_i(t)\neq\infty,\ r_i(t)\leq x_\mathrm{bottom}\}$, where $x_\mathrm{bottom}$ is the $x$-coordinate of the left-most bottom-most point. $B_i$ is simply the intersection of these two sets. The boundaries of this contiguous set can be computed via binary search over $\sweepseq$.
\end{proof}

Next we show how to maintain $\redGlobG(e[s,t])$. The algorithm is described in \Cref{alg:main}. This algorithm involves maintaining $\globalG(e[s,t])$ which in turn involves maintaining a set $\unifyG(e[s,t])$ consisting of index-pairs $(i,j)$ representing either inclusionwise-maximal paths that end at some height less than $t$, or if $i=j$. To maintain these sets we introduce two data-structures.

\begin{lemma}[\textsc{AdvanceStart} of $\globalG$]\label{lem:advanceStartG}
    Let $s'\leq s\leq t\in \extremal{}(A_e)$ be given. with $s'$ and $s$ consecutive. Let $(i,j)\in\globalG(e[s',t])$. Then one of the following hold:
    \begin{compactenum}
        \item $(i,j)\in\globalG(e[s,t])$,
        \item $(i',j)\in\globalG(e[s,t])$, $s'$ corresponds to the top-most point of the left free space interval of cell $i'$, and $i$ is the smallest index such that $l_{\hat{i}}(s)$ lies in the free space interval of cell $\hat{i}$ for all $i<\hat{i}\leq i'$, or
        \item $(i',j)\in\globalG(e[s,t])$, $s$ corresponds to the lowest point in cell $i'$ and $i$ is the smallest index $i'<i$ such that $l_i(s)\neq\infty$.
    \end{compactenum}
\end{lemma}
\begin{proof}
    Let $(i,j)\in\globalG(e[s',t])$ but $(i,j)\not\in\globalG(e[s,t])$. 

    Assume first that there is a path from cell $i$ at height $s$ to cell $j$ at height $t$. This implies that there is an index-pair $(i',j')$ in $\globalG(e[s,t])$ with $i'\leq i< j\leq j'$. Observe that $j'=j$, otherwise there is a path from cell $i$ at height $s'$ to cell $j'$ at height $t$ contradicting the fact that $(i,j)\in\globalG(e[s',t])$. Further observe, that $s'$ must correspond to the lowest point of the cell $i'$ as otherwise $(i',j)\in\globalG(e[s',t])$, contradicting the fact that $(i,j)\in\globalG(e[s',t])$. But then $i$ coincides with the smallest index $i'<\hat{i}$ such that $l_i(s)\neq\infty$, as otherwise $(i,j)$ is dominated by $(\hat{i},j)$.

    Now assume that there is no path from cell $i$ at height $s$ to cell $j$ at height $t$. This in turn implies that there is also no $(i',j')\in\globalG(e[s,t])$ with $i'\leq i < j\leq j'$. But then $s$ must correspond to some top-most point in a free space interval of some cell $i<i'<j$, as otherwise $(i,j)\in\globalG(e[s,t])$. Further clearly $(i',j)\in \globalG(e[s,t])$. This concludes the proof.
\end{proof}

\begin{algorithm}[htp]
\caption{Advancing the start point of the sweep-window}\label{alg:advstart}
\begin{algorithmic}[1]
\Procedure{AdvanceStart}{$s$,$s'$,$t$}
    \State Get $A_e$, $\unifyG$, $\localG$, $\globalG$, $\redGlobG$, $\bad(e[s,t])$, $\bad(e[s',t])\setminus\bad(e[s,t])$ and $\bad(e[s,t])\setminus\bad(e[s',t])$ from \textsc{Maintain}
    \If{$s$ is induced by a lowest point in cell $i$ of $A_e$}
        \State Identify smallest $j>i$ such that $l_j(s)\neq \infty$ \Comment{\Cref{lem:jumpright}}
        \State Update index-pairs in $\unifyG$ and in $\globalG$ starting at $i$ to start at $j$
    \EndIf
    \If{$s'$ is induced by a upper boundary of free space interval of cell $i$ of $A_e$}
        \State Identify largest $j<i$ such that $l_j(s)$ is in the interior of cell $j$ \Comment{\Cref{lem:shootleft}}
        \State Update index-pairs in $\unifyG$ and in $\globalG$ starting at $i$ to start at $j$
    \EndIf
    \If{$s'$ is induced by a highest point in cell $i$ of $A_e$}
        \State Add $(i,i)$ to $\unifyG$
    \EndIf
    \For{changed index-pair $(i,j)$ in $\unifyG$ and $\globalG$}
        \State If $i\neq j$ and $r_j(t)\neq\infty$ move index-pair to $\globalG$, else move it to $\unifyG$
        \State Remove any dominated index-pairs involving $(i,j)$ from $\globalG$ and $\unifyG$
    \EndFor
    \State Update $\redGlobG$ from $\globalG$ after merging overlapping intervals via $\bad(e[s,t])$ and $\bad(e[s',t])$
    \State Update $\localG$ via the changes to $\unifyG$, $\bad(e[s,t])$ and $\bad(e[s,t'])$ \Comment{\Cref{obs:UtoL}}
\EndProcedure
\end{algorithmic}
\end{algorithm}


\begin{lemma}[\textsc{AdvanceStart} of $\unifyG$]\label{lem:advanceStartU}
    Let $s'\leq s\leq t\in \extremal{}(A_e)$ be given. with $s'$ and $s$ consecutive. Let $(i,j)\in\unifyG(e[s',t])$. Then one of the following hold:
    \begin{compactenum}
        \item $(i,j)\in\unifyG(e[s,t])$,
        \item $(i',j)\in\unifyG(e[s,t])$, $s'$ corresponds to the top-most point of the left free space interval of cell $i'$, and $i$ is the smallest index such that $l_{\hat{i}}(s)$ lies in the free space interval of cell $\hat{i}$ for all $i<\hat{i}\leq i'$, or
        \item $(i',j)\in\unifyG(e[s,t])$, $s$ corresponds to the lowest point in cell $i'$ and $i$ is the smallest index $i'<i$ such that $l_i(s)\neq\infty$.
        \item $s'$ corresponds to the highest point in cell $i$ and $i=j$.
    \end{compactenum}
\end{lemma}
\begin{proof}
    Let $(i,j)\in\unifyG(e[s',t])$ but $(i,j)\not\in\unifyG(e[s,t])$. 

    Assume first that there is a path from cell $i$ at height $s$ to cell $j$ at height at most $t$. This implies that there is an index-pair $(i',j')$ in $\unifyG(e[s,t])$ with $i'\leq i< j\leq j'$. Observe that $j'=j$, otherwise there is a path from cell $i$ at height $s'$ to cell $j'$ at height at most $t$ contradicting the fact that $(i,j)\in\unifyG(e[s',t])$. Further observe, that $s'$ must correspond to the lowest point of the cell $i'$ as otherwise $(i',j)\in\unifyG(e[s',t])$, contradicting the fact that $(i,j)\in\unifyG(e[s',t])$. But then $i$ coincides with the smallest index $i'<\hat{i}$ such that $l_i(s)\neq\infty$, as otherwise $(i,j)$ is dominated by $(\hat{i},j)$.

    Now assume that there is no path from cell $i$ at height $s$ to cell $j$ at height at most $t$. If $l_i(s)=\infty$ then as $l_i(s')\neq \infty$ we observe that $i=j$ as by symbolic perturbation every highest-most point is above all right-most points and as such there is no monotone path exiting cell $i$.
    If $l_i(s)\neq\infty$ the fact that there is no path from cell $i$ at height $s$ to cell $j$ at height at most $t$ there is no $(i',j')\in\unifyG(e[s,t])$ with $i'\leq i < j\leq j'$. But then $s$ must correspond to some top-most point in a free space interval of some cell $i<i'<j$, as otherwise $(i,j)\in\unifyG(e[s,t])$. Further clearly $(i',j)\in \unifyG(e[s,t])$. This concludes the proof.
\end{proof}



\begin{algorithm}
\caption{Advancing the end point of the sweep-window}\label{alg:advend}
\begin{algorithmic}[1]
\Procedure{AdvanceEnd}{$s$,$t$,$t'$}
    \State Get $A_e$, $\unifyG$, $\localG$, $\globalG$, $\redGlobG$, $\bad(e[s,t])$, $\bad(e[s,t'])\setminus\bad(e[s,t])$ and $\bad(e[s,t])\setminus\bad(e[s,t'])$ from \textsc{Maintain}
    \If{$t$ is induced by a lower boundary of free space interval of cell $i$ of $A_e$}
        \State Identify smallest $j>i$ such that $l_j(s)\neq \infty$ \Comment{\Cref{lem:jumpright}}
        \State Replace index-pairs $(a,b)$ in $\unifyG$ and in $\globalG$ with $a<i\leq b$ with $(a,i)$ and $(j,b)$
    \EndIf
    \If{$t'$ is induced by highest point in cell $j$ of $A_e$}
        \State Add $(i,j)$ to $\globalG$ where $i$ is the minimal index such that $(i,j)\in\unifyG$\Comment{\Cref{lem:UtoG}}
    \EndIf
    \For{changed index-pair $(i,j)$ in $\unifyG$ and $\globalG$}
        \State If $i\neq j$ and $r_j(t)\neq\infty$ move index-pair to $\globalG$, else move it to $\unifyG$
        \State Remove any dominated index-pairs involving $(i,j)$ from $\globalG$ and $\unifyG$
    \EndFor
    \State Update $\redGlobG$ from $\globalG$ after merging overlapping intervals via $\bad(e[s,t])$ and $\bad(e[s,t'])$
    \State Update $\localG$ via the changes to $\unifyG$, $\bad(e[s,t])$ and $\bad(e[s,t'])$ \Comment{\Cref{obs:UtoL}}
\EndProcedure
\end{algorithmic}
\end{algorithm}

\begin{lemma}[\textsc{AdvanceEnd} of $\globalG$]\label{lem:advanceEndG}
    Let $s\leq t'\leq t\in\extremal{}(A_e)$ be given, with $t'$ and $t$ consecutive. Let $(i,j)\in\globalG(e[s,t'])$. Then one of the following holds:
    \begin{compactenum}
        \item $(i,j)\in\globalG(e[s,t])$,
        \item $t'$ corresponds to the highest point of cell $j$, and $i<j$ is the smallest index such that there is a monotone path from cell $i$ starting at height $s$ ending in cell $j$.
        \item $(i,j')\in\globalG(e[s,t])$ and $j'>j$ and $t$ is the lowest-most point in the left free space interval of cell $j+1$
        \item $(i',j)\in\globalG(e[s,t])$ and $i'<i$ and $t$ is the lowest-most point in cell $\hat{i}$ with $i'<\hat{i}<i$ and $i$ is the smallest index $\hat{i}<i$ such that $l_i(s)\neq\infty$.
    \end{compactenum}
\end{lemma}
\begin{proof}
    Let $(i,j)\in\globalG(e[s,t'])$ but $(i,j)\not\in\globalG(e[s,t])$.

    Assume first that there is a path from cell $i$ at height $s$ to cell $j$ at height $t$. This implies that there is an index-pair $(i',j')$ in $\globalG(e[s,t])$ with $i'\leq i< j\leq j'$. But then $t$ must correspond to the lowest point of the left free space interval of some cell $i'<\hat{i}\leq j'$. Further $\hat{i}\leq i$ and $j+1<\hat{i}$, as otherwise $(i,j)\not\in \globalG(e[s,t'])$. But then $i'=i$ or $j=j'$ as otherwise $(i,j)$ is dominated by $(i',\hat{i}-1)$ or $(\hat{i},j')$. If $i'=i$, then $j=\hat{i}$. If $j'=j$, then $i$ is the smallest index $\hat{i}<i$ such that $l_i(s)\neq\infty$.

    Now assume that there is no path from cell $i$ at height $s$ to cell $j$ at height $t$. But then $t$ corresponds to the highest point of cell $j$, and $i$ corresponds to the smallest index $i$ such that there is a monotone path from cell $i$ at height $s$ into cell $j$ concluding the proof.
\end{proof}

\begin{lemma}[\textsc{AdvanceEnd} of $\unifyG$]\label{lem:advanceEndU}
    Let $s\leq t'\leq t\in \extremal{}(A_e)$ be given. with $t'$ and $t$ consecutive. Let $(i,j)\in\unifyG(e[s,t'])$. Then one of the following hold:
    \begin{compactenum}
        \item $(i,j)\in\unifyG(e[s,t])$,
        \item $(i,j')\in\unifyG(e[s,t])$ and $j'>j$ and $t$ is the lowest-most point in the left free space interval of cell $j+1$
        \item $(i',j)\in\unifyG(e[s,t])$ and $i'<i$ and $t$ is the lowest-most point in left free space interval of cell $\hat{i}$ with $i'<\hat{i}<i$ and $i$ is the smallest index $\hat{i}<i$ such that $l_i(s)\neq\infty$.
    \end{compactenum}
\end{lemma}
\begin{proof}
    Let $(i,j)\in\unifyG(e[s,t'])$ but $(i,j)\not\in\unifyG(e[s,t])$.

    Observe that as $t'<t$ the fact that $(i,j)\in\unifyG(e[s,t'])$ implies that there is a path from cell $i$ at height $s$ to cell $j$ at height at most $t$. As $(i,j)\not\in\unifyG(e[s,t])$ there is an index-pair $(i',j')$ in $\unifyG(e[s,t])$ with $i'\leq i< j\leq j'$. But then $t$ must correspond to the lowest point of the left free space interval of some cell $i'<\hat{i}\leq j'$. Further $\hat{i}\leq i$ and $j+1<\hat{i}$, as otherwise $(i,j)\not\in \unifyG(e[s,t'])$. But then $i'=i$ or $j=j'$ as otherwise $(i,j)$ is dominated by $(i',\hat{i}-1)$ or $(\hat{i},j')$. If $i'=i$, then $j=\hat{i}$. If $j'=j$, then $i$ is the smallest index $\hat{i}<i$ such that $l_i(s)\neq\infty$.
\end{proof}

\begin{lemma}\label{lem:symdiff}
    Let $s'\leq s\leq t'\leq t\in \extremal{}(A_e)$ be given. with $s'$ and $s$ consecutive and $t'$ and $t$ consecutive. Then for the symmetric difference $\triangle$ it holds that
    \begin{compactenum}
        \item $|\globalG(e[s,t])\ \triangle\ \globalG(e[s,t'])|=\O(1)$,
        \item $|\globalG(e[s,t])\ \triangle\ \globalG(e[s',t])|=\O(1)$,
        \item $|\unifyG(e[s,t])\ \triangle\ \unifyG(e[s,t'])|=\O(1)$ and
        \item $|\unifyG(e[s,t])\ \triangle\ \unifyG(e[s',t])|=\O(1)$.
    \end{compactenum}
\end{lemma}
\begin{proof}
    It suffices to show that if $t$ is the lowest-most point in cell $\hat{i}$, then there is only one index-pair $(i,j)\in\unifyG(e[s,t])$ such that $i<\hat{i}\leq j$. This however is an immediate consequence of the fact that if $i<\hat{i}\leq j$ and $(i',j')\in\unifyG(e[s,t])$ with $i'<\hat{i}\leq j'$, then both paths go through the bottom-most point of the free space interval of cell $\hat{i}$, and thus $j=j'$. Further $i$ is the minimal index such that there is a monotone path to the bottom-most point of the free space interval of cell $\hat{i}$, and so is $i'$, and thus $i=i'$. This argument also carries over for $\globalG$.

    Lastly, by inclusion-wise maximality of index-pairs in $\globalG(e[s,t])$ and $\unifyG(e[s,t])$ any index $i$ occurs at most $\O(1)$ times among all index-pairs in $\globalG(e[s,t])$ and $\unifyG(e[s,t])$. Then \Cref{lem:advanceStartG}, \Cref{lem:advanceStartU}, \Cref{lem:advanceEndG} and \Cref{lem:advanceEndU} conclude the proof.
\end{proof}

\begin{lemma}\label{lem:UtoG}
    Given $\unifyG(e[s,t])$ and index $j$, one can compute the minimal index $i<j$, such that there is a path from cell $i$ at height $s$ to cell $j$ at height $t$ or decide that this index does not exist in time $\O(\log n)$.
\end{lemma}
\begin{proof}
    The index $i$ is precisely the smallest index $i$ such that $(i,j')\in\unifyG(e[s,t])$ such that $i<j\leq j'$. This index $i$ can be computed via binary search over the index-pairs stored in $\unifyG(e[s,t])$.
\end{proof}

 \begin{observation}\label{obs:UtoL}
     $\localG(e[s,t])=\{(i,j)\in\unifyG(e[s,t])\mid i=j \text{, $r_j(t)\neq\infty$ and } i\not\in\bad(e[s,t])\}$.
 \end{observation}

\begin{lemma}[Shoot-left data-structure]\label{lem:shootleft}
    Let $I=\{i_1,\ldots,i_n\}$ be a list of intervals in $\bR$. One can build in $O(n\log n)$ time a data-structure that allows queries with input $i\leq n$ and $x\in\bR$ correctly outputting the smallest index $j\leq i$ such that $x\in\bigcap_{j\leq s\leq i}i_s$ or determining that there is no such $j$.
\end{lemma}
\begin{proof}
    Store the intervals in a balanced binary tree, where every parent stores the intersection of the intervals stored in its children nodes. This construction takes $\O(n\log n)$ time. Thus if the query point $x$ lies in the interval stored at some node $r$ of the tree, then it also lies in the intersection of all intervals stored in the leaves of the tree rooted at $r$.

    Let now $i$ and $x$ be given. If $x\not \in i_i$, return that there is not such $j$. Otherwise we temporarily modify the tree as follows: Traverse the tree upwards starting at the node of $i_i$ removing all children of nodes that represent trees of intervals whose index is strictly bigger than $i$, updating the intervals along the way. This modification takes $\O(\log n)$ time and results in a tree of height $\log n$ whose leaves are all intervals $\{i_1,\ldots,i_i\}$ such that every every node stores the intersection of all intervals of the leaves on its subtree. Next we traverse the tree starting at the root, checking whether $x$ lies in the stored interval at the root. If it we can output $1$. Otherwise assume there is an interval $i_j$ which is the interval with the largest index that does not contain $x$. We now recursively check both children. If the interval of the right child (towards $i$) does not contain $x$, we next traverse in this child. If instead the interval of the right child does not contain $x$, then the left child must not contain $x$, hence we traverse right. In the end we correctly identified the leaf $j$.
\end{proof}

\begin{lemma}[Jump-right data-structure]\label{lem:jumpright}
    Let $A=\{a_1,\ldots,a_n\}$ be a list of values. One can build in $\O(n\log n)$ time a data-structure that allows queries with input $i$ correctly outputting the smallest index $j>i$ such that $a_i>a_j$ or determining that there is no such $j$ in $\O(1)$ time.
\end{lemma}
\begin{proof}
    First sort the indices $\{1,\ldots,n\}$ with the values $\{a_1,\ldots,a_n\}$ as keys in time $\O(n\log n)$. The resulting list of indices is then iteratively inserted into a sorted list (this time by index). Each insertion takes $\O(\log n)$ time. Further, when some index $i$ is inserted at position $k$, the smallest index $j>i$ such that $a_i>a_j$ (if it exists) is at position $k+1$. Hence, when inserting this index $i$, look up the index at position $k+1$ and store it as the answer to the query with index $i$.
\end{proof}

\begin{figure}
    \centering
    \includegraphics[width=\linewidth]{sweepline.pdf}
    \caption{Shoot-left, and jump-right update to $\globalG(e[s,t])$.}
    \label{fig:shoot-left}
\end{figure}

\begin{theorem}\label{thm:maintainSymbolic}
    At the beginning and end of the loop in Line $7$ of \textsc{Maintain} of \Cref{alg:main}, the set of index-pairs $\redGlobG$ coincides with $\redGlobG(e[s,t])$ and $\localG$ coincides with $\localG(e[s,t])\setminus\bad(e[s,t])$. Further, executing \textsc{Maintain} takes $\O(n\log n)$ time.
\end{theorem}
\begin{proof}

    Observe that initially $\bad(e[s,t])=\emptyset$ and $\unifyG(e[s,t])=\unifyG(e[s,s])=\globalG(e[s,s])\cup\localG(e[s,t])$ which is correctly computed.

    Observe that by \Cref{lem:advanceStartG}, \Cref{lem:advanceStartU}, \Cref{lem:advanceEndG}, \Cref{lem:advanceEndU}, \Cref{lem:UtoG} and \Cref{obs:UtoL} the sets $\unifyG=\unifyG(e[s,t])$, $\localG=\localG(e[s,t])\setminus\bad(e[s,t])$ and $\globalG = \globalG(e[s,t])$ are correctly updated by \textsc{AdvanceStart} and \textsc{AdvanceEnd}.

    By \Cref{lem:symdiff}, throughout the entirety of the algorithm there are $\O(n)$ updates to $\globalG$ that can be described as a total of $\O(n)$ insertions and removals of index-pairs, where at any point no index-pair is contained in another index-pair. Under these assumptions $\redGlobG$ can be maintained as $\bad(e[s,t])$ is given, and at every (sorted) insertion and removal only its two neighboring index-pairs need to be considered for additional updates to $\redGlobG$. Maintaining $\redGlobG$ thus takes total time $\O(n\log n)$.
\end{proof}

\begin{corollary}\label{cor:intervalset}
    Let $\sweepseq\in\edgeseqs{e}$ be a sweep-sequence. There are $m=\O(n)$ index-pairs $p_1=(i_1,j_1),\ldots,p_m=(i_m,j_m)$ together with $m$ contiguous subsets $I_i=\{(s_{a_i},t_{a_i}),\ldots,(s_{b_i},t_{b_i})\}\subset S$, such that for every $(s,t)\in \sweepseq$ it holds that
    \[\redGlobG(e[s,t])\cup(\localG(e[s,t])\setminus\bad(e[s,t]))=\bigcup_{1\leq i\leq m, (s,t)\in I_i}\{p_i\}.\]
    Further for $p_k=(i_k,j_k)$ the index $i_k$ is either always good or always bad for $e[s,t]$ for $(s,t)\in I_k$, and the index $j_k$ is either always good or always bad for $e[s,t]$ for $(s,t)\in I_k$.
    The index-pair $p_i$ as well as the values $a_i$ and $b_i$ can be computed for all $i$ in total time $\O(n\log n)$.
\end{corollary}
\begin{proof}
    This is an immediate consequence of \Cref{thm:maintainSymbolic}, as throughout \Cref{alg:main} $\redGlobG(e[s,t])\cup(\localG(e[s,t])\setminus\bad(e[s,t]))$ is correctly maintained along $\sweepseq$ in $\O(n)$ updates to $\O(n)$ initial index-pairs. We store any index-pair in $\redGlobG(e[s,t])\cup(\localG(e[s,t])\setminus\bad(e[s,t]))$ whenever it gets added, removed, modified or either of its entries changes from good to bad proving the claim.
\end{proof}

Thus, overall, we are able to maintain a symbolic representation of $\proxyCov(\cdot)$ during a sweep-sequence in total time $\O(\log n)$.

Next, we show how to use this maintained set $\redGlobG(\cdot)$ and $\localG(\cdot)\setminus\bad(\cdot)$ for batch point-queries.

\begin{theorem}\label{thm:pointQuery}
    Let $\sweepseq\in\edgeseqs{e}$, and let $Q\subset[0,1]$ together with $w_Q:Q\rightarrow\bN$ be a weighted point-set. Let for any $Q'\subset Q$ its weight $w_Q(Q')$ be defined as $\sum_{q\in Q'}w_q(q)$. There is an algorithm which computes $w_Q(Q\cap \proxyCov_{A_S}(e[s,t]))$
    for every $(s,t)\in \sweepseq$ in $\O(|Q|\log|Q| + n\log n)$ time.
\end{theorem}
\begin{proof}
    Define following values for all $i$, $j$ along the sweep-sequence $\mathfrak{s}$ where for $(s,t)\in\sweepseq$:
    \begin{multicols}{2}
\vspace*{-3em}
  \begin{equation*}
    L_i((s,t))=\hspace{-2em}\sum_{\substack{q\in Q,\ q\text{ in cell $i$}\\\hat{l}_{i,e[s,t]}(s)\neq\infty,\ \hat{l}_{i,e[s,t]}(s)\leq q}}\hspace{-2em}w_Q(q),
  \end{equation*}\nolinenumbers\break
\vspace*{-3em}
  \begin{equation*}
    R_j((s,t))=\hspace{-2em}\sum_{\substack{q\in Q,\ q\text{ in cell $j$}\\\hat{r}_{j,e[s,t]}(t)\neq\infty,\ q\leq \hat{r}_{j,e[s,t]}(t)}}\hspace{-2em}w_Q(q),
  \end{equation*}
\end{multicols}

\begin{multicols}{2}
\vspace*{-3em}
  \begin{equation*}
    M_i((s,t))=\hspace{-3em}\sum_{\substack{q\in Q,\ i\not\in\bad(e[s,t]),\ q\text{ in cell $i$}\\l_i(s)\neq\infty,\ r_i(t)\neq\infty,\ l_i(s)\leq q\leq r_i(t)}}\hspace{-4em}w_Q(q),
  \end{equation*}\nolinenumbers\break
\vspace*{-3em}
  \begin{equation*}
    D(i,j)=\hspace{-1.5em}\sum_{\substack{q\in Q,\ q\text{ in cell $m$}\\i\leq m\leq j}}\hspace{-1.5em}w_Q(q).
  \end{equation*}
\end{multicols}
The value $L_i(s,t)$ corresponds to the weight of points in cell $i$ that lie right of $\hat{l}_{i,e[s,t]}(s)$. Similarly $R_i(s,t)$ corresponds to the weight of points in cell $i$ that lie left of $\hat{r}_{i,e[s,t]}(t)$. The value $M_i(s,t)$ corresponds to the weight of points in cell $i$ that lie in between $\hat{l}_{i,e[s,t]}(s)$ and $\hat{r}_{i,e[s,t]}(t)$ if $i$ is good for $e[s,t]$. Lastly $D(i,j)$ corresponds to the total weight of points that lie on edge $i,\ldots,j$. Then for any $(s,t)\in\sweepseq$ and any $(i,i)\in\localG(e[s,t])\setminus\bad(e[s,t])$ it holds that \(M_i((s,t)) = w_Q(Q\cap[l_i(s),r_i(t)])\). Similarly, for any $(i,j)\in\redGlobG(e[s,t])$ it holds that \(L_i((s,t)) + D(i+1,j-1) + R_j((s,t))\) equals \(w_Q(Q\cap[\hat{l}_{i,e[s,t]}(s),r_{i,e[s,t]}(t)])\).
Hence
\begin{align*}
    &w_Q(Q\cap\proxyCov_{A_S}(e[s,t]))=\\
    &=\left(\sum_{i \in\localG(e[s,t])\setminus\bad(e[s,t])}\hspace{-1.5em}w_Q(Q\cap[l_i(s),r_i(t)])\right) +\left(\sum_{(i,j)\in\redGlobG(e[s,t])}\hspace{-1em}w_Q(Q\cap[\hat{l}_{i,e[s,t]}(s),\hat{r}_{j,e[s,t]}(t)])\right)\\
    &=\left(\sum_{i \in\localG(e[s,t])\setminus\bad(e[s,t])}\hspace{-1.5em}M_i((s,t))\right)+\left(\sum_{(i,j)\in\redGlobG(e[s,t])}\hspace{-1em}L_i((s,t)) + D(i+1,j-1) + R_j((s,t))\right).
\end{align*}

Observe that $D(i,j)$ can be provided via a data-structure that first computes $d_i=\sum_{q\in Q,q\text{ in cell $i$}}w_Q(q)$ for every $i$ in total time $\O(|Q|\log n)$ and stores them in a balanced binary tree as leaves, where every inner node stores the sum of the values of its children. For every $i\leq j$ the value $D(i,j)=\sum_{i\leq m\leq j}d_m$ can then be returned in $\O(\log n)$ time by identifying in $\O(\log n)$ time all $\O(\log n)$ maximal subtrees whose children lie in the interval $[i,j]$ and then returning the sum of the stored values in the root of each maximal subtree.

\begin{figure}
    \centering
    \includegraphics{Iq.pdf}
    \caption{Construction of the set $I_q$ encoding when $\hat{l}_{i,e[s,t]}(s)\leq q$ from Proof of \Cref{thm:pointQuery} via the sets $L_q$ and $R_q$ encoding when $l_i(s)\leq q$ and $r_i(s)\geq q$ and the set $B_i$ for all $(s,t)\in\sweepseq$.}
    \label{fig:Iq}
\end{figure}

Next we show that $L_i(\cdot)$ (resp. $R_j(\cdot)$ and $M_i(\cdot)$) can correctly be maintained when performing the sweep of $\sweepseq$. To this end let \[I_{q}=\{(s,t)\in \sweepseq\mid\text{$q$ is in cell $i$ and } \hat{l}_{i,e[s,t]}(s)\neq\infty,\hat{l}_{i,e[s,t]}\leq q\}.\] 
Refer to \Cref{fig:Iq}. As the free space in every cell is convex, throughout $\sweepseq$ the first indices are monotone and the $y$-coordinates of the left-most and right-most points are stored in $\extremal{}(A_e)$, for every $q\in Q$ the contiguous subsets \[L_{q}=\{(s,t)\in\sweepseq\mid\text{$q$ is in cell $i$ and } l_{i}(s)\neq\infty,l_i(s)\leq q\}\text{ and }\]\[R_{q}=\{(s,t)\in\sweepseq\mid \text{$q$ is in cell $i$ and } l_{i}(s)\neq\infty,r_i(s)\geq q\}\] can be computed in $\O(\log n)$ time. Similarly the set $B_i=\{(s,t)\in\sweepseq\mid \text{$i$ is bad for $e[s,t]$}\}$ is also a contiguous subset of $\sweepseq$ and all $B_i$ can be computed in $\O(\log n)$ time. Let $Q_i$ denote all $q\in Q$ that lie in the $i$th edge of $P$. Then for any $q\in Q_i$
\[I_q = (L_q\cap(\sweepseq\setminus B_i)) \cup ((\sweepseq\setminus R_q) \cap B_i),\]
and thus $I_q$ consists of $\O(1)$ contiguous disjoint subsets of $\sweepseq$. Thus all sets $I_q$ (represented as $\O(1)$ contiguous subsets of $\sweepseq$) can be computed in time $\O(|Q|\log n + n\log n)$. Further,
\[L_i((s,t)) = \sum_{q\in Q_i}\mathbbm{1}_{q\in I_q}w_Q(q),\]
and hence $L_i(\cdot)$ can be maintained in total time $\O(|Q| + n\log n)$ after one initial computation of all $I_{q}$, by adding $w_Q(q)$ for $q\in Q_i$ whenever $(s,t)$ enters the $\O(1)$ contiguous disjoint subsets of $I_q$, and subtracting $w_Q(q)$ for $q\in Q_i$ whenever $(s,t)$ exits the $\O(1)$ contiguous disjoint subsets of $I_q$. Sorting the boundaries of all $I_q$ preparing them for the maintenance of $L_i(\cdot)$ takes $\O(|Q|\log|Q|)$ time. Similarly $M_i(\cdot)$ and $R_j(\cdot)$ can be maintained.


Overall, the values $L_i(\cdot)$, $R_j(\cdot)$, $M_i(\cdot)$ and $D(i,j)$ are correctly maintained in total time $\O(|Q|\log|Q|)$ time such that they can be evaluated in $\O(\log n)$. By \Cref{cor:intervalset} there are only $\O(n)$ total updates to $\redGlobG(\cdot)$ and $\localG(\cdot)\setminus\bad(\cdot)$. Hence, $w(\cdot)$ can be correctly maintained along $\sweepseq$ by updating it whenever $L_i(\cdot)$, $R_j(\cdot)$, $M_i(\cdot)$, $\redGlobG(\cdot)$, $\localG(\cdot)\setminus\bad(\cdot)$ or $\bad(\cdot)$ change. Thus computing $w(e[s,t])$ for all $(s,t)\in S$ takes $\O(|Q|\log|Q| +n\log n)$ time.
\end{proof}

\section{Cubic Subtrajectory Covering}\label{sec:cubicClusterin}

In this section we focus on the SC problem. The goal of this section is the following theorem.


\begin{restatable}{theorem}{thmMainClustering}
\label{thm:mainClustering}
    Let $P$ be a polygonal curve of complexity $n$ and let $\Delta>0$ and $\ell\leq n$ be given. Let $\kopt$ be the size of the smallest set $\mathcal{C}^*\subset\curvespace{\ell}$ such that $\bigcup_{c\in\mathcal{C}^*}\Cov_P(c,\Delta)=[0,1]$. There is an algorithm that given $P$, $\Delta$ and $\ell$ computes a set $\mathcal{C}\subset\curvespace{\ell}$ of size $\O(\kopt\log n)$ such that $\bigcup_{c\in\mathcal{C}}\Cov_P(c,4\Delta)=[0,1]$. Further, it does so in $\O(n^3\log ^2 n + kn^2\log^3 n)$ time using $\O(n^3\log n)$ space.
\end{restatable}

Throughout this section let $S$ be a simplification of $P$ and set $\alpha=1$, that is, the approximate free spaces $A_e$ and $A_S$ are exactly the $4\Delta$-free space of $e$ and $P$, and $S$ and $P$, respectively. We further set $\extremal{}(A_S)$ to be precisely all extremal points of the $4\Delta$-free space of $S$ and $P$.

\subsection{Atomic intervals}
\begin{definition}[Atomic intervals]
    Let $P$ be a polygonal curve, and let $\Delta>0$ and $\ell$ be given. Let $S$ be a simplification of $P$. Let $G$ be the set of all intersection-points of horizontal lines at height $y$ for $y\in\extremal{}(A_S)$ with the boundary of the free space $\mathcal{D}_{4\Delta}(S,P)$. From this, define the set of atomic intervals $\atomic{}(S,P)$ as the set of intervals describing the arrangement of $[0,1]$ defined by the set $\{x\in[0,1]\mid \exists y\in[0,1]: (x,y)\in G\}$ (\Cref{fig:extremal-molecular}).
\end{definition}

\begin{observation}\label{obs:atomicnumber}
    As $|\extremal{}(A_S)|\leq 8n^2$, and each horizontal line intersects at most $n$ cells, and the free space in every cell is convex it follows, the set of all midpoints of atomic intervals $\atomic{}(S,P)$ is a point set $A\subset[0,1]$ of size $16n^3$ such that for any $C\subset\ConcreteCandidates{S}(P)$ it holds that 
    \[\proxyCov_{P}(C) = [0,1]\iff A \subset \proxyCov_{P}(C).\]
\end{observation}

\begin{theorem}\label{thm:reduction}
    Let $P$ be curve of complexity $n$, let $\Delta$ and $\ell$ be given. Let $S$ be a simplification of $P$. Let $A\subset[0,1]$ be a finite set. Any algorithm that iteratively adds the curve $c$ among $\ConcreteCandidates{S}(P)$ to $R$ maximizing
    \[\left|\left\{a\in A\middle|a\in\left(\proxyCov_P(c,4\Delta)\setminus\left(\bigcup_{r\in R}\proxyCov_P(r,4\Delta)\right)\right)\right\}\right|,\]
    terminates after $16(\ln |A| + 1)\kopt$ iterations where $\kopt$ is the size of the smallest set $\mathcal{C}^*\subset\curvespace{\ell}$ such that $\bigcup_{c\in\mathcal{C}^*}\Cov_P(c,\Delta)=[0,1]$. Furthermore for the resulting set $R\subset\bX_\ell^d$ it holds that
    \(\Cov_P(R,4\Delta)=[0,1]\).
\end{theorem}
\begin{proof}
    By \Cref{thm:16setsystem} there is a set $C_1$ of size $16\kopt$ in $\ConcreteCandidates{S}(P)$ such that $\proxyCov_{A_S}(C_1)=[0,1]$. Hence, by standard greedy \textsc{SetCover} arguments, the algorithm thus terminates after $(\ln|A|+1)16\kopt$ iterations, returning a set $C\subset\ConcreteCandidates{S}(P)$ of size $(\ln |A|+1)16\kopt$ such that $\proxyCov_{A_S}(C)=[0,1]$. As $\proxyCov_{A_S}(\cdot)\subset\Cov_P(\cdot,4\Delta)$ it follows that $\Cov_P(C,4\Delta)=[0,1]$.
\end{proof}

We define the weight of any subcurve $S[s,t]$ in $\ConcreteCandidates{S}(P)$ with respect to the point-set $A\subset[0,1]$ as
\(\candW{A}(S[s,t]):=\left|A\cap\proxyCov_{A_S}(S[s,t])\right|\).
By \Cref{thm:reduction} it suffices to show that given a set of curves $R\subset \ConcreteCandidates{S}(P)$ in we can evaluate $\candW{A\setminus \proxyCov_{A_S}(R)}(\pi)$ for every $\pi\in\ConcreteCandidates{S}(P)$. 

\subsection{\boldmath Maintaining a partial solution and Type $(I)$-curves}

The greedy-algorithm operates in rounds: given a partial solution $R\subset\ConcreteCandidates{S}(P)$, which initially is empty, it identifies a subcurve $\pi\in\ConcreteCandidates{S}(P)$ which maximizes $\candW{A}(\pi,R)$. Let $I_R$ be the $\O(|R|n)\leq \O(\kopt n\log n )$ disjoint intervals describing $\bigcup_{r\in R}\Cov_P(r,4\Delta)$. During the greedy set cover algorithm the exact information on $R$ is less important, more so $I_R$, and accessing and updating this union of intervals quickly throughout the algorithm, as by definition
\[\candW{A\setminus\proxyCov_{A_S}(R)}(\pi)=\left|\left\{a\in A\middle|a\subset\left(\proxyCov_{A_S}(\pi)\setminus\left(\bigcup_{i\in I_R}i\right)\right)\right\}\right|.\]

\begin{lemma}\label{lem:solution_datastructure}
    Let $I$ be a set of $n$ pairwise disjoint intervals defined by interval boundaries of $\atomic{}(S,P)$. There is a data-structure that allows computing

\[\left|\left\{a\in A\middle|a\subset\left([l,r]\setminus\left(\bigcup_{i\in I_R}i\right)\right)\right\}\right|\]

    in $\O(\log n)$ time for $[l,r]$ defined by boundaries of $\atomic{}(S,P)$. Further we can either remove an interval from $I$, or if $[l,r]\cap \left(\bigcup_{i\in I}i\right)=\emptyset$, then $[l,r]$ can be added to $I$ correctly updating the data-structure $\O(\log n)$ time.
\end{lemma}
\begin{proof}
    Simply store the disjoint intervals $I_R$ in an interval-tree and for every interval store the number of intervals from $\atomic{}(S,P)$ that lie inside it. This number can be computed in $\O(\log n)$ time.
\end{proof}

Throughout the $\O(\kopt \log n)$ iterations of the algorithm $I$ will have complexity at most $\O(n\kopt \log n)$, and maintaining it takes at most $\O(n\kopt \log^2 n)$ time, as any interval is added and removed exactly once to maintain disjointedness. 
\begin{observation}
    Trivially $\kopt \leq\lceil n/\ell\rceil=\O(n)$.
\end{observation}

\begin{lemma}[\cite{vanderhoog2024fasterdeterministicsubtrajectoryclustering}]\label{lem:evalType1}
    In $\O(n^2\ell\log\ell\log n)$ one can compute $\Cov_{P}(S[s,t],4\Delta)=\proxyCov_{A_S}(S[s,t])$ for every Type $(I)$-subcurve $S[s,t]$ of $S$.
\end{lemma}

Given $\O(n)$ disjoint intervals describing some $\proxyCov_{A_S}(\pi)$ and the data structure from \Cref{lem:solution_datastructure} storing a partial solution consisting of at most $\O(n^2\log n)$ disjoint intervals. Then we can compute $\candW{A}(\pi,R)$ in time $\O(n\log n)$. Thus the following theorem follows.

\begin{theorem}\label{thm:type1}
    Let $S$ and $P$ be polygonal curves of complexity $n$. After $\O(n^2\ell\log^2 n)$ preprocessing time one can answer queries with a set $I_R$ of intersection-free intervals together with the data-structure from \Cref{lem:solution_datastructure} representing the coverage of a set $R\subset\ConcreteCandidates{S}(P)$ of size $\O(k\log n)$ identifying the Type $(I)$ subcurve $c$ of $S$ maximizing $\candW{A}(c,I)$ in $\O(n^2\log n\log \ell)$ time.
\end{theorem}
\begin{proof}
    This is an immediate consequence of \Cref{lem:evalType1} and \Cref{lem:solution_datastructure}. We compute and store the $\O(n)$ intervals representing the coverage for every Type $(I)$ subcurve in total time $\O(n^2\ell\log^2n)$.
\end{proof}


\subsection{\boldmath Type $(II)$- and $(III)$-subcurves}

This leaves us with computing the weight of subcurves in the sweep-sequences, both of which are subedges.

\begin{observation}
    For any edge $e$ of $S$ it holds that $\extremal{}(A_e)\subset\extremal{}(A_S)$ and as such the atomic intervals of $e$ and $P$ partition the atomic intervals of $S$ and $P$, where each atomic interval of $e$ and $P$ can be described as a contiguous subset of atomic intervals of $S$ and $P$.
\end{observation}

\begin{figure}
    \centering
    \includegraphics[width=\linewidth]{atomic_molecular.pdf}
    \caption{Illustration of extremal points $\extremal{}(S,P)$ in the $4\Delta$-freespace of $S$ and $P$, as well as the atomic intervals $\atomic{}(S,P)$. On the right in red molecular intervals $\atomic{}(e,P)$ for the second edge $e$ of $S$ are illustrated. Their weights w.r.t. the midpoints of atomic intervals $\atomic{}(S,P)$ are shown if they are not equal to $1$.}
    \label{fig:extremal-molecular}
\end{figure}

To clarify the difference of atomic intervals $\atomic{}(S,P)$ and atomic intervals $\atomic{}(e,P)$ we will call the latter \emph{molecular intervals} (\Cref{fig:extremal-molecular}) and denote them by $\molecular{}(e,P)$.


A molecular interval $m\in\molecular{}(e,P)$ is additionally endowed with a weight \(\molW{A}(m)=\left|A\cap m\right|\).

\begin{lemma}\label{lem:molecularPQ}
    Let $A\subset[0,1]$ be a set of $\O(n^3)$ points. Let $e$ be an edge of $S$. Let $W_e=\{(s,t)\in\molecular{}(e,P)\mid w_A(e[s,t])\neq 0\}$ together with $w_A(m)$ and the midpoint of $m$ for every $m\in W_e$ be given. Let $\sweepseq\in\edgeseqs{e}$ be a sweep-sequence. Then $\candW{A}(e[s,t])$ can be computed for every $(s,t)\in\sweepseq$ in total time $\O(|W_e|\log n + n\log n)$.
\end{lemma}
\begin{proof}
    This is an immediate consequence of \Cref{thm:pointQuery} together with the fact that 
    \begin{align*}
        \candW{A}(e[s,t])&=|A\cap\proxyCov_{A_S}(e[s,t])|=\sum_{[a,b]\in\molecular{}(e,P)}\mathbbm{1}_{[a,b]\subset\proxyCov_{A_S}(e[s,t])}|A\cap[a,b]|\\
        &= \sum_{[a,b]\in\molecular{}(e,P)}\mathbbm{1}_{[a,b]\subset\proxyCov_{A_S}(e[s,t])}\molW{A}([a,b]).\qedhere
    \end{align*}
\end{proof}

\begin{lemma}\label{lem:theDestroyer}
    Let $A$ be a set of size $\O(n^3)$ stored in a tree. Let $W_e=\{m\in\molecular{}(e,P)\mid \molW{A}(m)\neq 0\}$ be stored together with their weights $\molW{A}(\cdot)$ in a self-balancing tree where $m$ is left of $m'$ in the tree, if $m$ lies to the left of $m'$ in $[0,1]$. Let $r$ together with its proxy coverage $\proxyCov_{A_S}(r)$ be given. Let $\widetilde{W}_e=\{m\in\molecular{}(e,P)\mid \molW{A\setminus \proxyCov_{A_S}(r)}(m)\neq 0\}\subset W_e$.
    \begin{compactenum}
        \item In time $\O(|W_e\setminus \widetilde{W}_e|+n\log n)$ one can compute and output $W'=\{m\in\molecular{}(e,P)\mid \molW{A\cap \proxyCov_{A_S}(r)}(m)\neq 0\}\subset W_e$ together with its weights $\molW{A\cap \proxyCov_{A_S}(r)}(\cdot)$.
        \item In total time $\O(|W_e\setminus \widetilde{W}_e|+n\log n)$ one can update the tree storing $W_e$ and its weights $\molW{A}(\cdot)$ to instead store $\widetilde{W}_e$ and its weights $\molW{A\setminus \proxyCov_{A_S}(r)}(\cdot)$.
        \item In time $\O(|A\cap\proxyCov_{A_S}(r)|\log n + n\log n)$ one can compute a tree storing $A\cap\proxyCov_{A_S}(r)$.
        \item In time $\O(|A\cap\proxyCov_{A_S}(r)| + n\log n)$ one can update the tree storing $A$ to store $A\setminus\proxyCov_{A_S}(r)$ instead.
    \end{compactenum}
\end{lemma}
\begin{proof}
    Let $[a_1,b_1],\ldots$ be the $\O(n)$ disjoint intervals of atomic intervals representing $\proxyCov_{A_S}(r)$. Let $m\in W_e$. If $m\subset [a_i,b_i]$ then $\molW{A\cap \proxyCov_{A_S}(r)}(m) = \molW{A}(m)$ and hence $m\in W'$ and $m\not\in\widetilde{W}_e$. If $m\subset [0,1]\setminus\bigcup_i[a_i,b_i]$ then $\molW{A\cap \proxyCov_{A_S}(r)}(m) = 0$ and as such $m\not \in W'$ and $m\in\widetilde{W}_e$. Lastly there are $\O(n)$ molecular intervals that contain some interval boundary $a_i$ or $b_i$.

    \textbf{1:} To compute and output $W'$ output all $m$ and their weight $\molW{A}(\cdot)$ that lie in some interval $[a_i,b_i]$ in $\O(|W_e\setminus \widetilde{W}_e|+n\log n)$ time via the tree storing $W_e$. Further determine the $\O(n)$ intervals that contain some interval boundary $a_i$ or $b_i$ and for them compute $\molW{A\cap\proxyCov_{A_S}(r)}(\cdot)$ via the tree storing $A$ in total time $\O(n\log n)$.

    \textbf{2:} To update the tree to store $\widetilde{W}_e$ remove all molecular intervals from the tree that are contained in some interval $[a_i,b_i]$ in total time $\O(|W_e\setminus \widetilde{W}_e|+n\log n)$. Lastly for the $\O(n)$ intervals that contain some interval boundary $a_i$ or $b_i$ compute and store their weight $\molW{A\setminus \proxyCov_{A_S}(r)}(\cdot)$. If this weight is zero, also remove them from the tree. Handling these $\O(n)$ intervals takes $\O(n\log n)$ time. 

    \textbf{4:} Simply compute all points from the tree storing $A$ that are contained in some $[a_i,b_i]$ and output a tree storing them.

    \textbf{4:} Simply remove all points from the tree storing $A$ that are contained in some $[a_i,b_i]$.
\end{proof}

\begin{lemma}\label{lem:numberOfAtomic}
    Let $e$ be an edge of $S$. Let $A$ be a set of $\O(n^3)$ points in $[0,1]$ that is stored in a tree. There are $\O(n^2)$ molecular intervals $\molecular{}$ of $e$ and $P$, and they as well as their initial weights $\molW{A}(m)=\molW{A}(m)$ can be computed in $\O(n^2\log n)$ time.
\end{lemma}
\begin{proof}
    Straight forward, as for any interval $[a,b]$ the value $|A\cap[a,b]|$ can be computed in $\O(\log n)$ time.
\end{proof}

\begin{algorithm}[htp]
\caption{Covering a finite subset of $[0,1]$}\label{alg:covera}
\begin{algorithmic}[1]
\Procedure{CoverA}{$A_S$, $A\subset[0,1]$, $\{\edgeseqs{e}\mid e\text{ of }S\}$,$\{W_{e}\mid e\text{ of }S, \molW{A}(m)\neq 0\}$}
    \State Compute all Type $(I)$-curves and their proxy coverage $\proxyCov_{A_S}(\cdot)$
    \State For every $e$ compute $\molW{A}(m)$ and the midpoint of $m$ for every $m\in W_e$
    \State $R\gets\emptyset$
    \For{$e$ of $S$}
        \For{$\sweepseq\in\edgeseqs{e}$}
            \State Compute $\candW{A}(e[s,t])=|A\cap \proxyCov_{A_S}(e[s,t])|$ via $\molW{A}((s,t))$ for $(s,t)\in W_e$
        \EndFor
    \EndFor
    \While{$A\neq\emptyset$}
        \State For every Type $(I)$-curve $\pi$ compute $\candW{A}(\pi)=|A\cap \proxyCov_{A_S}(\pi)|$
        \State Add $r\in\ConcreteCandidates{S}(P)$ maximizing $\candW{A}(r)=|A\cap \proxyCov_{A_S}(r)|$ to $R$
        \State $A'\gets A \cap \proxyCov_{A_S}(r)$
        \For{$e$ of $S$}
            \State For every $m\in W_e$ compute $\molW{A'}(m)$ and $W'_e=\{m\in W_e\mid \molW{A'}(m)\neq 0\}$
            \State Remove $m$ from $W_e$ if $\molW{A\setminus A'}(m)=\molW{A}(m)-\molW{A'}(m)=0$
            \For{$\sweepseq\in\edgeseqs{e}$}
                \State Compute $\candW{A'}(e[s,t])$ via $\molW{A'}((s,t))$ for every $(s,t)\in\sweepseq$
                \State Update $\candW{A}(e[s,t],\emptyset)\gets \candW{A}(e[s,t],\emptyset) - \candW{A'}(e[s,t],\emptyset)$ for every $(s,t)\in\sweepseq$
            \EndFor
        \EndFor
        \State $A\gets A\setminus A'$
    \EndWhile
    \State \Return $R$
\EndProcedure
\end{algorithmic}
\end{algorithm}

\subsection{Putting everything together}\label{sec:cubic}

\begin{lemma}\label{lem:finalCosts}
    Let $P$ be a polygonal curve of complexity $n$ and let $\Delta>0$ and $\ell\leq n$ be given. Let $S$ be a simplification of $P$. Let $A_S$ be the $4\Delta$-free space of $S$ and $P$. Let $A\subset[0,1]$ be a set of $\O(n^3)$ points. For every edge $e$ of $S$ let $\edgeseqs{e}$ be $\O(\log n)$ sweep-sequences, each of length $\O(n)$, together containing all $\O(n\log n)$ Type $(II)$- and $(III)$-subedges of $e$, and let $W_e$ be the set of molecular intervals $m$ such that $\molW{A}(m)\neq 0$. Let $\kopt$ be the size of the smallest set $\mathcal{C}^*\subset\curvespace{\ell}$ such that $\bigcup_{c\in\mathcal{C}^*}\Cov_P(c,\Delta)=[0,1]$. The algorithm \textsc{CoverA} from \Cref{alg:covera} computes a set $\mathcal{C}\subset\curvespace{\ell}$ of size $(48\ln(n)+64)\kopt$ such that $A\subset\proxyCov_{A_S}(C)$. Further, it does so in time
    \[\O(n^2\ell\log n^2 + |A|\log n + \kopt n^2\log^3n + \log n\sum_e|W_e|).\]

\end{lemma}
\begin{proof}

    Observe that at the beginning of the \textbf{while}-Loop $A$ coincides with the set $A\setminus\proxyCov_{A_S}(R)$. Hence by \Cref{thm:reduction} it suffices to show that during the \textbf{while}-Loop the element $r\in\ConcreteCandidates{S}(P)$ maximizing $\candW{A}(r)$ is correctly identified.

    By \Cref{thm:type1}, computing all Type $(I)$-curves and their proxy coverage takes a total of $\O(n^2\ell\log n\log \ell)$ time. As $A$ is stored in a tree, computing $\molW{A}(m)$ and the midpoint of $m$ for every $m\in W_e$ takes $\O(|W_e|\log n)$ time. By \Cref{thm:pointQuery} computing and storing $\candW{A}(e[s,t])$ for every $(s,t)\in\sweepseq$ for every $\sweepseq\in\edgeseqs{e}$ for an edge $e$ of $S$ takes a total of $\O(|W_e|\log n+n^2\log^2 n)$ time. Thus the precomputation steps before the \textbf{while}-Loop take a total of $\O(n^2\ell\log n\log \ell + \sum_e(|W_e|\log n+n\log n))$ time.

    Now let for the $i$th iteration of the \textbf{while}-Loop $R_i$ denote the set stored in $R$ and let $A_i$ denote the set stored in $A$ coinciding with $A\setminus\proxyCov_{A_S}(R_i)$. Let further $W_{e,i}$ denote the set of molecular intervals stored in $W_e$, and similarly $W'_{e,i}$ be the set of molecular intervals stored in $W'_e$.
    Assume for now that $\candW{A_i}(e[s,t])$ is stored correctly for every Type $(II)$- and $(III)$-subcurve. Then $r$ is identified correctly. Observe that for $i=0$ this is indeed the case.

    Observe that $W_{e_i}=\{m\in\molecular{}(e,P)\mid \molW{A_i}(m)\neq 0\}$ and $W'_{e_i}=\{m\in\molecular{}(e,P)\mid \molW{A_i\cap\proxyCov_{A_S}(r)}(m)\neq 0\}$. By \Cref{lem:theDestroyer} $W'_{e,i}$ and its weights can be computed in time $\O(|W_{e_i}\setminus W_{e,{i+1}}| + n\log n)$. Similarly $W_{e,i}$ is afterwards updated to store $W_{e,i+1}=\{m\in\molecular{}(e,P)\mid \molW{A_i\setminus \proxyCov_{A_S}(r)}(m)=\molW{A_{i+1}}(m)\neq 0\}$. By \Cref{lem:theDestroyer} this update takes $\O(|W_{e,i}\setminus W_{e,{i+1}}| + n\log n)$. Lastly by \Cref{thm:pointQuery} computing $\candW{A_i\setminus A_{i+1}}(e[s,t])$ for every $(s,t)\in\sweepseq$ for an $\sweepseq\in \edgeseqs{e}$ for an edge $e$ takes time $\O(|A_{i}\setminus A_{i+1}|\log n + n\log n|)$. Afterwards $\candW{A_{i+1}}(e[s,t])$ is stored for all Type $(II)$- and $(III)$-subcurves as by definition $\candW{A_{i+1}}(\cdot)=\candW{{A_i}}(\cdot)-\candW{{A_i \setminus A_{i+1}}}(\cdot)$ and ${A_i \setminus A_{i+1}}=A_i\cap\proxyCov_{A_S}(r)$. Updating $A_i$ takes total time $\O(|A_i\setminus A_{i+1}| + n\log n)$. 

    Throughout the entirety of $k$ rounds the \textbf{while}-Loop without the computation of $\candW{A}$ of Type $(I)$-subcurves takes 
    \begin{align*}
        &\O\left(\sum_{i=0}^{k}\left(|A_i\setminus A_{i+1}|\log n +n\log n +\left( \sum_e\sum_{\sweepseq\in\edgeseqs{e}}\left( |W_{e,i}\setminus W_{e,i+1}| + n\log n \right) \right)\right)\right)\\
        =\;\;&\O\left(|A|\log n +kn\log n +\sum_{i=0}^{k}\left(\log n \sum_e\left( |W_{e,i}\setminus W_{e,i+1}| + n\log n \right) \right)\right)\\
        =\;\;&\O\left(|A|\log n +kn\log n + kn^2\log^2 n+\log n \sum_e\sum_{i=0}^{k}\left( |W_{e,i}\setminus W_{e,i+1}|\right) \right)\\
        =\;\;&\O\left(|A|\log n + kn^2\log^2 n+\log n \sum_e|W_e| \right).
    \end{align*}
    Thus by \Cref{thm:reduction} the algorithm terminates after $\O(n^2\ell\log n^2 + |A|\log n + \kopt n^2\log^3n + \log n\sum_e|W_e|)$ time, concluding the proof.
\end{proof}

