For an edge-coloured graph $H$, an \emph{automorphism} of $H$ is a bijective homomorphism from $H$ to itself. Let $\aut(H)$ be the number of automorphisms of $H$. For each $J_\ell$, the number of indices $j\in\{1,\dots,512\}$ such that $J_\ell$ is isomorphic to $H_j$ is precisely $\frac{2\cdot 3!\cdot 3!}{\aut(J_\ell)} = \frac{72}{\aut(J_\ell)}$. Therefore, if we let $d(J_\ell,G):=\frac{72}{\aut(J_\ell)}t_{\inj}(J_\ell,G)$ for each $1\leq \ell\leq 26$, then \eqref{eq:sumToOne} can be rewritten as
\begin{equation}
\label{eq:sumToOne2}
    \sum_{\ell=1}^{26}d(J_\ell,G) = 1.
\end{equation}
A \emph{homomorphism} between two graphs without edge colours is simply a map from the vertex set of the first graph to the vertex set of the second with the property that adjacent pairs of vertices are mapped to adjacent pairs of vertices. We view the graph $C_6$ and the edge-coloured graph $C_6^A$ as having the same vertex set. For each $1\leq i\leq 26$, let $t_{\bip}(C_6^A,J_\ell)$ be the probability that a uniformly random injective homomorphism $f$ from $C_6$ to $K_{3,3}$ is a homomorphism from $C_6^A$ to $J_\ell$; we define $t_{\bip}(C_6^A,H_i)$ analogously for $0\leq i\leq 512$. The next proposition relates $t_{\inj}(C_6^A,G)$ to the quantities $t_{\bip}(C_6^A,J_\ell)$ and $d(J_\ell,G)$ for $1\leq \ell\leq 26$. 

\begin{prop}
\label{prop:doubleCount}
For any edge-coloured clique $G$,
\[t_{\inj}(C_6^A,G)=\sum_{\ell=1}^{26}t_{\bip}(C_6^A,J_\ell)\cdot d(J_\ell,G).\]
\end{prop}

\begin{proof}
If $v(G)<6$, then both sides of the equation in the proposition are zero and so we may assume that $v(G)\geq6$. Let $f:V(K_{3,3})\to V(G)$ be a uniformly random injective function and let $g:V(C_6)\to V(K_{3,3})$ be a uniformly random injective homomorphism from $C_6$ to $K_{3,3}$. Then $f\circ g$ is nothing more than a uniformly random injective function from $V(C_6^A)$ to $V(G)$. Let $E$ be the event that $f\circ g$ is a homomorphism from $C_6^A$ to $G$ and, for each $1\leq i\leq 512$, let $F_i$ be the event that $f$ is a homomorphism from $H_i$ to $G$. By definition, we have $t_{\inj}(C_6^A,G)=\mathbb{P}(E)$. Also, since $G$ is an edge-coloured clique, the events $F_1,\dots,F_{512}$ are disjoint and satisfy $\sum_{i=1}^{512}\mathbb{P}(F_i)=1$. Therefore, 
\[t_{\inj}(C_6^A,G)=\sum_{i=1}^{512}\mathbb{P}(E\cap F_i)=\sum_{i=1}^{512}\mathbb{P}(E\mid F_i)\mathbb{P}(F_i) = \sum_{i=1}^{512}t_{\bip}(C_6^A,H_i)\cdot t_{\inj}(H_i,G).\]
The result follows by collecting terms based on isomorphism classes. 
\end{proof}

The quantities $t_{\bip}(C_6^A,J_\ell)$ for $1\leq \ell\leq 26$ can all be easily computed. As it turns out, 
\[t_{\bip}(C_6^A,J_4)=\frac{12}{72},\qquad t_{\bip}(C_6^A,J_9)=\frac{6}{72},\qquad t_{\bip}(C_6^A,J_{11})=\frac{6}{72},\qquad t_{\bip}(C_6^A,J_{12})=\frac{12}{72}\]
and $t_{\bip}(C_6^A,J_\ell)=0$ for all other indices $\ell$. Thus, by Proposition~\ref{prop:doubleCount},
\begin{equation}
\label{eq:doubleCount}
t_{\inj}(C_6^A,G)=\frac{1}{6}d(J_4,G) + \frac{1}{12}d(J_9,G) +\frac{1}{12}d(J_{11},G) +\frac{1}{6}d(J_{12},G).
\end{equation}

