\subsection{Achievability Proof of the Fixed-Length Test (Theorem \ref{theo:fl})}
\label{proof:fl:test}

Recall the definition of $g(\cdot)$ in \eqref{def:gn}. Fix any $l\in[T_K]$ and any tuple of distributions $(P^{M_1},Q^{M_2})\in\calP_l^K$. Recall that $\bbP_l^K$ denotes the joint distribution of sequences $(\bX^{\xi_N},\bY^{\chi_N})$. Define the set $[T_K]_{\setminus l}:=\{t\in[T_K]:~t\neq l\}$. Similarly to \eqref{use:prob:typeclass} to \eqref{use:num:types}, it follows from the definition of the mismatch probability in \eqref{def:mismatch} and the test design in \eqref{test:fl} that
\begin{align}
\nn&\beta(\Phi|P^{M_1},Q^{M_2})\\*
&=\bbP_l^K\Big\{\exists~t\in[T_K]_{\setminus l},~\rmS_t^K(\bX^{\xi_N},\bY^{\chi_N})\leq \rmS_l^K(\bX^{\xi_N},\bY^{\chi_N})\Big\}\\
&\leq \sum_{t\in[T_K]_{\setminus l}}\bbP_l^K\big\{\rmS_t^K(\bX^{\xi_N},\bY^{\chi_N})\leq \rmS_l^K(\bX^{\xi_N},\bY^{\chi_N})\big\}\\
&=\sum_{t\in[T_K]_{\setminus l}}\sum_{\substack{(\bx^{\xi_N},\by^{\chi_N}):\\\rmS_t^K(\bx^{\xi_N},\by^{\chi_N})\leq \rmS_l^K(\bx^{\xi_N},\by^{\chi_N})}}\Big(\prod_{i\in[M_1]}P_i^{\xi_N}(x_i^{\xi_N})\Big)\Big(\prod_{j\in[M_2]}Q_j^{\chi_N}(y_j^{\chi_N})\Big)\\
&=\sum_{t\in[T_K]_{\setminus l}}\sum_{\substack{(\Omega^{M_1},\Psi^{M_2})\in(\calP^{\xi_n}(\calX))^{M_1}\times(\calP^{\chi_n}(\calX))^{M_2}:\\ \rmG_t^K(\Omega^{M_1},\Psi^{M_2},\alpha,\beta)\leq \rmG_l^K(\Omega^{M_1},\Psi^{M_2},\alpha,\beta)
}}\Big(\prod_{i\in[M_1]}P_i^{\xi_n}(\calT_{\Omega_i}^{\xi_n})\Big)\Big(\prod_{j\in[M_2]}Q_j^{\chi_n}(\calT_{\Psi_j}^{\chi_n})\Big)\\
&\leq \sum_{t\in[T_K]_{\setminus l}}\sum_{\substack{(\Omega^{M_1},\Psi^{M_2})\in(\calP^{\xi_n}(\calX))^{M_1}\times(\calP^{\chi_n}(\calX))^{M_2}:\\ \rmG_t^K(\Omega^{M_1},\Psi^{M_2},\alpha,\beta)\leq \rmG_l^K(\Omega^{M_1},\Psi^{M_2},\alpha,\beta)
}}\exp\bigg(-\Big(\sum_{i\in[M_1]}\xi_nD(\Omega_i\|P_i)+\sum_{j\in[M_2]}\chi_nD(\Psi_j\|Q_j)\Big)\bigg)\\
&\leq \sum_{t\in[T_K]_{\setminus l}}\sum_{\substack{(\Omega^{M_1},\Psi^{M_2})\in(\calP^{\xi_n}(\calX))^{M_1}\times(\calP^{\chi_n}(\calX))^{M_2}:\\ \rmG_t^K(\Omega^{M_1},\Psi^{M_2},\alpha,\beta)\leq \rmG_l^K(\Omega^{M_1},\Psi^{M_2},\alpha,\beta)
}}\exp\bigg(-n\Big(\sum_{i\in[M_1]}\alpha D(\Omega_i\|P_i)+\sum_{j\in[M_2]}\beta D(\Psi_j\|Q_j)\Big)\bigg)\\
&\leq \sum_{t\in[T_K]_{\setminus l}}\sum_{\substack{(\Omega^{M_1},\Psi^{M_2})\in(\calP(\calX))^{M_1+M_2}:\\ \rmG_t^K(\Omega^{M_1},\Psi^{M_2},\alpha,\beta)\leq \rmG_l^K(\Omega^{M_1},\Psi^{M_2},\alpha,\beta)
}}\exp\big(-n E(P^{M_1},Q^{M_2},\Omega^{M_1},\Psi^{M_2})\big)\label{useegain}\\
&\leq \sum_{t\in[T_K]_{\setminus l}}\sum_{\substack{(\Omega^{M_1},\Psi^{M_2})\in(\calP(\calX))^{M_1+M_2}:\\ \rmG_t^K(\Omega^{M_1},\Psi^{M_2},\alpha,\beta)\leq \rmG_l^K(\Omega^{M_1},\Psi^{M_2},\alpha,\beta)
}}\exp\big(-n E_\rmf(l,K,P^{M_1},Q^{M_2})\big)\label{use:e:fl}\\
&\leq T_K\exp\Big(-n\Big(E_\rmf(l,K,P^{M_1},Q^{M_2})-g(N,M_1,M_2)\Big)\Big)\label{use:g:fl},
\end{align}
where \eqref{useegain} follows from the definition of $E(\cdot)$ in \eqref{def:epqop}, \eqref{use:e:fl} follows from the definition of $E_\rmf(\cdot)$ in \eqref{def:exponent:fl}, and \eqref{use:g:fl} follows from the upper bound on the number of types and the definition of $g(\cdot)$ in \eqref{def:gn}.

Thus, the mismatch exponent of the fixed-length test satisfies
\begin{align}
\liminf_{N\to\infty}\frac{-\log \beta(\Phi|P^{M_1},Q^{M_2})}{n}\geq E_\rmf(l,K,P^{M_1},Q^{M_2}).
\end{align}

\subsection{Justification of \eqref{eqn:67}}
\label{just:eqn:67}
Consider any $(P^{M_1},Q^{M_2})\in\calP_0$ (cf. \eqref{def:calP:r}). For any $(h,t)\in\calM$, it follows that
\begin{align}
\sum_{(i,j)\in\calM_t^h}\mathrm{GJS}(P_i,Q_j,\alpha,\beta) \geq \min_{(i,j)\in[M_1]\times[M_2]}\mathrm{GJS}(P_i,Q_j,\alpha,\beta).
\end{align}
As a result, 
\begin{align}
\min_{(h,t)\in\calM}\sum_{(i,j)\in\calM_t^h}\mathrm{GJS}(P_i,Q_j,\alpha,\beta) \geq \min_{(i,j)\in[M_1]\times[M_2]}\mathrm{GJS}(P_i,Q_j,\alpha,\beta).  \label{eqn:lowerbou}
\end{align}
On the other hand, consider any pair
\begin{align}
(i_0,j_0)\in \argmin_{(i,j)\in[M_1]\times[M_2]}  \mathrm{GJS}(P_i,Q_j,\alpha,\beta).
\end{align}
Assume that $h_0=1$. Consider hypothesis $\calM_{h_0}^{t_0}$ such that $\calM_{t_0}^{h_0}=\{ (i_0,j_0) \}$. It follows that 
\begin{align}
\min_{(h,t)\in\calM}\sum_{(i,j)\in\calM_t^h}\mathrm{GJS}(P_i,Q_j,\alpha,\beta)
&\leq \sum_{(i,j)\in\calM_{t_0}^{h_0}}\mathrm{GJS}(P_i,Q_j,\alpha,\beta)\\
&= \mathrm{GJS}(P_{i_0},Q_{j_0},\alpha,\beta)\\
&=\min_{(i,j)\in[M_1]\times[M_2]}\mathrm{GJS}(P_i,Q_j,\alpha,\beta)\label{eqn:upperbou}.
\end{align} 
The justification of \eqref{eqn:67} is completed by combining \eqref{eqn:lowerbou} and \eqref{eqn:upperbou}.

\subsection{Achievability Proof for Another Fixed-Length Test (Theorem \ref{theo:fl:one-step})}
\label{proof:fl:one-step}

Recall the definitions of $E_\rmr(\lambda_1,P^{M_1},Q^{M_2})$ in \eqref{def:er} and $g(\cdot)$ in \eqref{def:gn}. Fix any $(P^{M_1},Q^{M_2})\in\calP_0$ (cf. \eqref{def:calP:r}). Recall that $\bbP_\rmr$ denotes the joint distribution of all sequences of two databases. It follows from \eqref{def:etar} that the false alarm probability satisfies
\begin{align}
\eta(\Phi_{\rm{FL}}^{\rm{uk}}|P^{M_1},Q^{M_2})
&=\bbP_\rmr\Big\{\Phi_{\rm{FL}}^{\rm{uk}}(\bX^{\xi_N},\bY^{\chi_N})\neq \rmH_\rmr\Big\}\\
&=\bbP_\rmr\bigg\{\exists~(\barh,\bart)\in\calM,~\calB_{\barh,\bart}^N\bigcap_{(h,t)\in\calM_{\setminus \bart}^{\setminus \barh}}(\calB_{h,t}^n)^\rmc\bigg\}\\
&\leq \sum_{(\barh,\bart)\in\calM}\bbP_\rmr\Big\{\calB_{\barh,\bart}^N\Big\}\\
&\leq \sum_{(\barh,\bart)\in\calM}\bbP_\rmr\Big\{\rmS_{\barh}^{\bart}(\bX^{\xi_N},\bY^{\chi_N})\leq \lambda_1\Big\}\label{use:calA2:omit}\\
&\leq T\exp\Big(-N\big(E_\rmr(\lambda_1,P^{M_1},Q^{M_2})-g(N,M_1,M_2)\big)\Big)\label{use:usegn:fl:uk},
\end{align}
where \eqref{use:calA2:omit} follows from the definition of $\calB_{2,h,t}$ in \eqref{def:calBht} and \eqref{use:usegn:fl:uk} follows from the result \eqref{usegn} by replacing $n$ with $N$ and ignoring the outer summation over $n$. Thus, the false alarm exponent satisfies
\begin{align}
\liminf_{N\to\infty}\frac{-\log \eta(\Phi_{\rm{FL}}^{\rm{uk}}|P^{M_1},Q^{M_2})}{N}\geq E_\rmr(\lambda_1,P^{M_1},Q^{M_2}).
\end{align}

Next consider non-null hypotheses. Fix $(K,l)\in\calM$ and $(P^{M_1},Q^{M_2})\in\calP_l^K$ (cf. \eqref{def:calp:lk}). Recall that $\bbP_l^K$ denotes the joint distribution of all sequences of the two databases. It follows from \eqref{def:mismatch:unknown} that the mismatch probability satisfies
\begin{align}
\beta(\Phi_{\rm{FL}}^{\rm{uk}}|P^{M_1},Q^{M_2})
&=\bbP_l^K\Big\{\Phi_{\rm{FL}}^{\rm{uk}}(\bX^{\xi_N},\bY^{\chi_N})\notin\{\rmH_l^K,\rmH_\rmr\}\Big\}\\
&\leq \bbP_l^K\bigg\{\exists~(\barh,\bart)\in\calM_{\setminus l}^{\setminus K},~\calB_{\barh,\bart}^N\bigcap_{(h,t)\in\calM_{\setminus \bart}^{\setminus \barh}}(\calB_{h,t}^n)^\rmc\bigg\}\\
&\leq \bbP_l^K\Big\{\exists~(\barh,\bart)\in\calM_{\setminus l}^{\setminus K},~\calB_{\barh,\bart}^N\Big\}\\
&\leq \sum_{(\barh,\bart)\in\calM_{\setminus l}^{\setminus K}}\bbP_l^K\{\calB_{\barh,\bart}^N\}\\
&\leq T_K\exp\Big(-N\big(\lambda_2-g(N,M_1,M_2)\big)\Big)+T\exp\Big(-N\big(\lambda_2-g(N,h,h)\big)\Big)\\*
&\qquad+T\exp\Big(-N\big(G(\lambda_1,P^{M_1},Q^{M_2})-g(N,M_1,M_2)\big)\Big)
\label{use2:use:gn:hlk},
\end{align}
where \eqref{use2:use:gn:hlk} follows from the results in \eqref{p:mis:step2}, \eqref{p:mis:step3}, and \eqref{p:mis:step4} with $n$ replaced by $N$. Thus, the mismatch exponent satisfies
\begin{align}
\liminf_{N\to\infty}\frac{-\log \beta(\Phi_{\rm{FL}}^{\rm{uk}}|P^{M_1},Q^{M_2})}{N}\geq \min\Big\{G(\lambda_1,P^{M_1},Q^{M_2}),\lambda_2\Big\}.
\end{align}

It follows from \eqref{def:freject} that the false reject probability satisfies
\begin{align}
\zeta(\Phi_{\rm{FL}}^{\rm{uk}}|P^{M_1},Q^{M_2})
&=\bbP_l^K\Big\{\Phi_{\rm{FL}}^{\rm{uk}}(\bX^{\xi_N},\bY^{\chi_N})=\rmH_\rmr\Big\}\\
&\leq\bbP_l^K\Big\{\big(\calB_{K,l}^N\big)^\rmc\bigcup_{(h,t)\in\calM_{\setminus l}^{\setminus K}}\calB_{h,t}^n\Big\}\\
&\leq \bbP_l^K\big\{(\calB_{K,l}^N)^\rmc\big\}+\sum_{(h,t)\in\calM_{\setminus l}^{\setminus K}}\bbP_l^K\big\{\calB_{h,t}^n\big\}
\label{fl:uk:fr:step1}.
\end{align}

Recall the definition of $F(\lambda_2,P^{M_1},Q^{M_2})$ in \eqref{def:exponent:nonnull}. It follows from \eqref{etau:hlk:step2:0}, \eqref{etau:hlk:step2}, \eqref{use:gn:hlk} and \eqref{use:eth} that the first term in \eqref{fl:uk:fr:step1} satisfies
\begin{align}
\bbP_l^K\big\{(\calB_{K,l}^N)^\rmc\big\}
&\leq \exp\Big(-n\big(\lambda_1-g(n,K,K)\big)\Big)+T_K\exp\Big(-n\big(F(\lambda_2,P^{M_1},Q^{M_2})-g(n,M_1,M_2)\big)\Big)\label{fl:uk:fr:step2}.
\end{align}
Recall the definition of $G(\lambda,P^{M_1},Q^{M_2})$ in \eqref{def:g:exponent}. The second term in \eqref{fl:uk:fr:step1} has been bounded in \eqref{use2:use:gn:hlk}.

Therefore, combining \eqref{use2:use:gn:hlk}, \eqref{fl:uk:fr:step1}, and \eqref{fl:uk:fr:step2}, the false reject exponent satisfies
\begin{align}
\liminf_{N\to\infty}\frac{-\log\zeta(\Phi_{\rm{FL}}^{\rm{uk}}|P^{M_1},Q^{M_2})}{N}
\geq \min\Big\{\lambda_1,\lambda_2,G(\lambda_1,P^{M_1},Q^{M_2}),F(\lambda_2,P^{M_1},Q^{M_2})\Big\}.
\end{align}


