(H(t))_{0,k} = \frac{\B{\tilde{u}}_b(t, x_0, y_k)}{x_1 - x_0}, \quad
(H(t))_{N_x,k} = -\frac{\B{\tilde{u}}_b(t, x_{N_x}, y_k)}{x_{N_x} - x_{N_x-1}}, \quad k = 1, \ldots, N_y-1,
$$
$$
(H(t))_{j,k} = 0, \quad j = 1, \ldots, N_x-1, \quad k = 1, \ldots, N_y-1,
$$
$$
(H(t))_{0,k} = -\frac{\B{\tilde{u}}_b(t, x_1, y_k) - \B{\tilde{u}}_b(t, x_0, y_k)}{x_1 - x_0}, \quad k \in \{0, N_y\},
$$
$$
(H(t))_{N_x,k} = -\frac{\B{\tilde{u}}_b(t, x_{N_x}, y_k) - \B{\tilde{u}}_b(t, x_{N_x-1}, y_k)}{x_{N_x} - x_{N_x-1}}, \quad k \in \{0, N_y\},
$$
$$
(H(t))_{j,k} = -\frac{\B{\tilde{u}}_b(t, x_{j+1}, y_k) - \B{\tilde{u}}_b(t, x_{j-1}, y_k)}{x_{N_x+1} - x_{N_x-1}}, \quad j = 1, \ldots, N_x-1, \quad k \in \{0, N_y\}.
$$
The case $\B{F} = (0, f)^T$ can be considered similarly.
