To this moment, we did not control that $H(t)$ belongs to $Q_h$, i. e. \mbox{$\int \tilde{\B{u}}_b \cdot \B{n} ds = 0$} is satisfied in the discrete sense. The easiest way to enforce this is to correct the mapping $\Pi$ in \eqref{eq_def_ub} so that $Div\, u_b(t) \equiv 0$.

Let $L$ be the operator taking $f \in Q_h$ to $Lf \in Q_h$ as
\begin{equation}
\begin{gathered}
(Lf)_{j,k} = \varphi_{\langle j,k \rangle, \langle j+1,k \rangle} (\Delta x)_j^{-1}\frac{f_{j+1,k} - f_{j,k}}{x_{j+1}-x_j} - \varphi_{\langle j,k \rangle, \langle j-1,k \rangle} (\Delta x)_j^{-1}\frac{f_{j,k} - f_{j-1,k}}{x_j-x_{j-1}} +
\\
+ \varphi_{\langle j,k \rangle, \langle j,k+1 \rangle} (\Delta y)_k^{-1}  \frac{f_{j,k+1} - f_{j,k}}{y_{j+1}-y_j} - \varphi_{\langle j,k \rangle, \langle j,k-1 \rangle} (\Delta y)_k^{-1} \frac{f_{j,k} - f_{j,k-1}}{y_{j}-y_{j-1}}
\end{gathered}
\label{eq_FD2_L1}
\end{equation}
where 
\begin{equation}
\varphi_{\langle j,k \rangle, \langle j',k' \rangle} = \left\{\begin{array}{ll}
1, & \langle j,k \rangle, \langle j',k' \rangle \in \mathcal{N};  \\
1/2, & \langle j,k \rangle \in \mathcal{N}, \langle j',k' \rangle \in \mathcal{N}_b;  \\
1/2, & \langle j,k \rangle \in \mathcal{N}_b, \langle j',k' \rangle \in \mathcal{N};  \\
0, & \langle j,k \rangle, \langle j',k' \rangle \in \mathcal{N}_b;
\\
0, & \langle j,k \rangle \not\in \bar{\mathcal{N}} \ \mathrm{or}\  \langle j',k' \rangle \not\in \bar{\mathcal{N}}.
\end{array}\right.
\label{eq_FD2_L2}
\end{equation}
%If an index of a node is out of range, then the corresponding fraction is dropped. 

%$S f = 0$ holds if and only if $f$ is a linear function. This is the reason to introduce $\varphi_{\alpha,\beta}$.
\begin{lemma}
For $f \in Q_h$, $\B{g} \in V_h$, there holds $[f, D\B{g}] = -[\B{g}, Gf]$.
\label{th:lemma3}
\end{lemma}
\begin{proof}
First assume that $\B{g} = (g, 0)^T$. By definition,
\begin{equation*}
\begin{gathered}
  \left[f, D\B{g}\right] = 
\frac{1}{2}\sum\limits_{k=0}^{N_y}(\Delta y)_k \Bigl(g_{1,k} f_{0,k} + (g_{2,k} - g_{0,k}) f_{1,k} + \ldots
\\
 + (g_{N_x,k} - g_{N_x-2,k}) f_{N_x-1,k} - g_{N_x-1,k} f_{N_x,k}\Bigr).
\end{gathered}
\end{equation*}
Note that $g_{0,k} = g_{N_x,k}=0$ because $\B{g} \in V_h$. By reordering,
$$
\left[f, D\B{g}\right] =
-\frac{1}{2}\sum\limits_{k=0}^{N_y}(\Delta y)_k \Bigl(g_{1,k} (f_{2,k} - f_{0,k}) + \ldots 
 + g_{N_x-1,k} (f_{N_x,k}-f_{N_x-2,k})\Bigr) = [-Gf, \B{g}].
$$
The proof for $\B{g} = (0,g)^T$ is similar, and the general case is by linearity.
\end{proof}

\begin{proposition}
Operators $G$, $D$, $L$ defined by \eqref{eq_FD2_G}--\eqref{eq_FD2_L2} satisfy \eqref{eq_gen_assumptions}. Furthermore, $S f = 0$ holds if and only if $f$ is a linear function, i. e. $f_{j,k} = \alpha x_j + \beta y_k$ for some $\alpha, \beta \in \mathbb{R}$.
\end{proposition}
\begin{proof}
The identity $D = -G^*$ is by Lemma~\ref{th:lemma3}. For each $f, g \in Q_h$ there holds
\begin{equation}
\begin{gathered}
\ [Lf, g] = -\sum\limits_{k=1}^{N_y-1}  (\Delta y)_k  \sum\limits_{j=0}^{N_x-1} \varphi_{\langle j,k \rangle, \langle j+1,k \rangle} \frac{(f_{j+1,k} - f_{j,k})(g_{j+1,k} - g_{j,k})}{x_{j+1}-x_j}
\\
-\sum\limits_{j=1}^{N_x-1}  (\Delta x)_j  \sum\limits_{k=0}^{N_y-1} \varphi_{\langle j,k \rangle, \langle j,k+1 \rangle} \frac{(f_{j,k+1} - f_{j,k})(g_{j,k+1} - g_{j,k})}{y_{k+1}-y_k}.
\end{gathered}
\label{eq_aux_FD2_L}
\end{equation}
Thus, $L = L^* \le 0$. Furthermore, let $f \in Q_h$ and $[Lf, f] = 0$. Then for each pair of neighboring nodes with $\phi_{\langle j,k\rangle, \langle j',k'\rangle} \ne 0$ there holds $f_{j,k} = f_{j',k'}$. By the choice of $Q_h$, we have $f = 0$. This proves that $L < 0$.

Since $D = -G^*$, we have
$$
-[f, DGf] = \sum\limits_{\langle j, k \rangle \in \mathcal{N}} (\Delta x)_j (\Delta y)_k |(Gf)_{\langle j, k \rangle}|^2 = \Sigma_x + \Sigma_y
$$
where
$$
\Sigma_x = \frac{1}{4} \sum\limits_{k=1}^{N_y-1}  (\Delta y)_k  \sum\limits_{j=1}^{N_x-1}  (\Delta x)_j^{-1}(f_{j+1,k} - f_{j-1,k})^2,
$$
$$
\Sigma_y =\frac{1}{4}\sum\limits_{j=1}^{N_x-1}  (\Delta x)_j \sum\limits_{k=1}^{N_y-1}  (\Delta y)_k^{-1}  (f_{j,k+1}-f_{j,k-1})^2.
$$
After a simple transformation,
$$
\Sigma_x = \frac{1}{2} \sum\limits_{k=1}^{N_y-1}  (\Delta y)_k  \sum\limits_{j=1}^{N_x-1} \left[\frac{(f_{j+1,k}-f_{j,k})^2}{x_{j+1}-x_j} +   \frac{(f_{j,k}-f_{j-1,k})^2}{x_{j}-x_{j-1}}\right] - 
$$
$$
 - \frac{1}{2} \sum\limits_{k=1}^{N_y-1}  (\Delta y)_k  \sum\limits_{j=1}^{N_x-1}\frac{(x_{j+1}-x_j)(x_j - x_{j-1})}{x_{j+1}-x_{j-1}} \left(\frac{f_{j+1,k}-f_{j,k}}{x_{j+1}-x_j} - \frac{f_{j,k}-f_{j-1,k}}{x_j - x_{j-1}}\right)^2.
$$
By \eqref{eq_aux_FD2_L}, $[Lf,f] = \tilde{\Sigma}_x + \tilde{\Sigma}_y$ where
$$
\tilde{\Sigma}_x = -\sum\limits_{k=1}^{N_y-1}  (\Delta y)_k  \sum\limits_{j=0}^{N_x-1} \varphi_{\langle j,k \rangle, \langle j+1,k \rangle} \frac{(f_{j+1,k} - f_{j,k})^2}{x_{j+1}-x_j},
$$
$$
\tilde{\Sigma}_y = -\sum\limits_{j=1}^{N_x-1}  (\Delta x)_j  \sum\limits_{k=0}^{N_y-1} \varphi_{\langle j,k \rangle, \langle j,k+1 \rangle} \frac{(f_{j,k+1} - f_{j,k})^2}{y_{k+1}-y_k}.
$$
We see that $-\tilde{\Sigma}_x$ coincides with the first term on the right-hand side of the expression for $\Sigma_x$. Thus, $f^T S f = -(\Sigma_x + \Sigma_y + \tilde{\Sigma}_x + \tilde{\Sigma}_y)\ge 0$ and $S$ vanishes on linear functions.
\end{proof}

{\it Remark.} Taking the standard approximation of the Laplace operator ($\phi_{\langle j,k\rangle, \langle j',k'\rangle} = 1$ for $\langle j,k\rangle, \langle j',k'\rangle \in \bar{\mathcal{N}}$) would preserve  \eqref{eq_gen_assumptions} but the stabilization term would no longer be zero on linear functions, causing a large solution error near boundaries.

{\it Remark.} Due to the constraint $[f, 1]=0$ in the definition of $Q_h$, a direct matrix representation of operator $L$ with a local portrait is not possible. Instead, to efficiently solve a system of the form $Lx = y$, $x, y \in Q_h$, the following well-known procedure may be used:
\begin{enumerate}
\item Let $L' : \mathbb{R}^{\bar{\mathcal{N}}} \to \mathbb{R}^{\bar{\mathcal{N}}}$ be defined by \eqref{eq_FD2_L1}--\eqref{eq_FD2_L2}. Let $\mathrm{L}'$ be its matrix representation in the standard basis (which is defined by $(\phi_{\langle j,k \rangle})_{\langle l,m \rangle} = \delta_{jl}\delta_{km}$, $\langle j,k \rangle, \langle l,m \rangle \in \bar{\mathcal{N}}$). Consider the system $\mathrm{L}' x' = y$ for $x' \in \mathbb{R}^{\bar{\mathcal{N}}}$.
\item Pin the values at corner nodes: for each ${\langle j,k \rangle} \in \mathcal{N}_c$, replace the line corresponding to node $j$ by $x'_{\langle j,k \rangle} = 0$.
\item Pin the value at one non-corner node: replace the line corresponding to one (arbitrary chosen) node ${\langle j,k \rangle} \in \bar{\mathcal{N}} \setminus \mathcal{N}_c$ by $x'_{\langle j,k \rangle} = 0$.
\item The resulting system has a non-degenerate matrix. Solve it for $x' \in \mathbb{R}^{\bar{\mathcal{N}}}$ using an algebraic multigrid method. By construction, $x'_{\langle j,k \rangle} = 0$ for ${\langle j,k \rangle} \in \mathcal{N}_c$.
\item Put $x_{\langle j,k \rangle} = x'_{\langle j,k \rangle} - [x', 1]$ for each ${\langle j,k \rangle} \in \bar{\mathcal{N}}$. Now $x \in Q_h$.
\end{enumerate}


\subsection{Galerkin methods}
\label{sect:Gal}

We begin with the case of periodic boundary conditions. Let $\Omega$ be the unit cube. Let $L^2_{per}(\mathbb{R}^d)$ and $H^1_{per}(\mathbb{R}^d)$ be the spaces of 1-periodic functions from $L^2_{loc}(\mathbb{R}^d)$ and $H^1_{loc}(\mathbb{R}^d)$, correspondingly. Let $V_h$ be a finite-dimensional subspace of $(H^1_{per}(\mathbb{R}^d))^d$ equipped with the scalar product $(\B{f},\B{g}) = \int_{\Omega} \B{f}\cdot\B{g}dr$. Let $Q$ be the space of functions from $H^1_{per}(\mathbb{R}^d)$ with zero average. Let $Q_h$ be a finite-dimensional subspace of $Q$ equipped with the scalar product from $L^2(\Omega)$. Let $Gf$, $f \in Q_h$, be defined as the orthogonal projection of $\nabla f$ on $V_h$:
\begin{equation}
(G f, \B{g}) = \int\limits_{\Omega} \B{g}(\B{r}) \cdot \nabla f(\B{r}) dV, \quad f \in Q_h, \quad \B{g} \in V_h.
\label{eq_def_FE_G}
\end{equation}
Then $D = -G^*$ is given by
\begin{equation}
(D \B{f}, g) = \int\limits_{\Omega} g(\B{r}) \nabla \cdot \B{f}(\B{r}) dV, \quad \B{f} \in V_h, \quad g \in Q_h.
\label{eq_def_FE_D}
\end{equation}
Let $L$ be defined by
\begin{equation}
(L f, g) = -\int\limits_{\Omega} \nabla {f}(\B{r}) \cdot \nabla {g}(\B{r}) dV, \quad f, g \in Q_h.
\label{eq_def_FE_L}
\end{equation}

{\it Remark.} In bases $\{\phi_j \in V_h\}$ and $\{\psi_j \in Q_h\}$, the operators $G$, $D$, and $L$ take the form $M_{\psi}^{-1} \tilde{G}$, $M_{\phi}^{-1} \tilde{G}^T$, $M_{\phi}^{-1} \tilde{L}$ where $M_{\psi}$ and $M_{\phi}$ are the mass matrices, $\tilde{L}$ is the stiffness matrix, and $\tilde{G} = \{\int \phi_j \nabla \psi_k dV\}$. For $f = \sum f_j \phi_j$ and $g = \sum g_j \phi_j$ the scalar product is $(f, g) = (f_1, \ldots, f_{dim \,Q_h})^T M_{\phi} (g_1, \ldots, g_{dim\, Q_h})$.



\begin{proposition}
The operators $G$, $D$, $L$ defined above satisfy \eqref{eq_gen_assumptions}.
\end{proposition}
The proof may be found in \cite{Codina1998} (Sect. 4.1). We give its short form.

\begin{proof}
The conditions $D = -G^*$ and $L = L^* < 0$ are by construction. Let $\|\ \cdot\ \|$ be the square norm of the vector with the components from $L^2(\Omega)$. Then $(-Lf, f) = \|\nabla f\|^2$. We also have $(DGf, f) = -(Gf, Gf) = -\|Gf\|^2$.
Since $Gf$ is the orthogonal projection of $\nabla f$ on $V_h$, then $\|Gf\| \le \|\nabla f\|$, and $(S f, f) = \|\nabla f\|^2 - \|G f\|^2 \ge 0$.
\end{proof}

We utilized the Galerkin method to construct operators $G$, $D$, $L$ for use in \eqref{eq_momentun_base}, \eqref{eq_continuity_base}. What we obtained, can be transformed back to a weak formulation, which is conventional for finite-element methods. For the steady Stokes problem, this is done in \cite{Codina1997}, and accuracy estimates were proved.

{\it Remark.} For methods that do not satisfy the inf-sup condition, pressure stabilization is a stability requirement. If the inf-sup condition holds, instead of \eqref{eq_def_FE_L} one can put $L = DG$ and thus $S = 0$. However, for finite element methods, the matrix representation of $L = DG$ is nonlocal (unless the mass lumping is used), and one finds themselves in a position so solve a Darcy-type problem instead of a scalar elliptic equation (see Remark~3.1 in \cite{Colomes2015}). If one wants to have the stiffness matrix in the pressure equation, they naturally get $S \ne 0$ even for an inf-sup-stable method.\\

Now we move to the case that $\Omega$ is a bounded domain in $\mathbb{R}^d$, and the homogeneous Dirichet boundary conditions are applied on $\D \Omega$. Here the choice of finite element spaces is controversial. It seems natural to take $V_h$ as a subspace of $(H^1_0(\Omega))^d$. However, this has a major drawback. On the boundary, $\nabla p$ is generally nonzero while \mbox{$Gp \in V_h$} is always zero. Therefore, one can expect that $(S p, p) = \|\nabla p\|^2 - \|Gp\|^2$ is bounded from below by $O(h)$. For the Stokes problem, this restricts the  convergence rate in $L_2$ by $O(h^{3/2})$ for the velocity and $O(h^{1/2})$ for the pressure gradient (see Theorem~3 in \cite{Codina1997}). %See also Remarks~3.1 and~3.2 in \cite{Guermond2006}.

One may ignore the Dirichlet boundary conditions when choosing $V_h$ and enforce them by a proper discretization of the flux terms. However, this setup is counterintuitive.  First, if $G$ is given by \eqref{eq_def_FE_G}, then $D = -G^*$ is defined by
$$
(D \B{f}, g) = \int\limits_{\Omega} g(\B{r}) \nabla \cdot \B{f}(\B{r}) dV - \int\limits_{\D \Omega} g(\B{r}) \B{f}(\B{r}) \cdot \B{n} dS, \quad \B{f} \in V_h, \quad g \in Q_h.
$$
Second, the simplified system $\nabla \cdot \tilde{\B{u}}=0$, $\tilde{\B{u}}_t + \nabla \tilde{p} = 0$  requires a slip boundary condition, but there are no flux terms where these boundary conditions may be imposed. Therefore, it is hardly possible to construct a robust numerical method, especially for convection-dominant flows.

% As noted in \cite{Karniadakis1991}, the assumption that velocities have zero normal component on boundaries, is natural for the analysis of time integration methods.

An intermediate approach is to take $V_h$ as a subspace of $(H^1(\Omega))^d$ such that for each $\B{f} \in V_h$ there holds
$$
\int\limits_{\D \Omega} \B{f}(\B{r}) \cdot \B{n}\ g(\B{r}) dS = 0, \quad g \in Q_h.
$$
Then $\tilde{\B{u}} \cdot \B{n} = 0$ is imposed by the choice of the finite element space, while \mbox{$\tilde{\B{u}} \cdot \B{n}^{\perp} = 0$} should be imposed by the discretization of the viscous term.  If \mbox{$\D p/\D n \ne 0$} on $\D \Omega$, then we get a numerical boundary layer and a low order convergence. However, if $\D p/\D n$ is small, then this error may be not so crucial. We use this approach in Section~\ref{sect:turbchannel} for the turbulent flow in a channel.

{\it Remark.} It is well-known that projection-based methods (except explicit ones) in the standard formulation generate a numerical boundary layer, see \cite{Guermond2006}. Here we have a numerical boundary layer of a different origin. It results from the difference between $-G^*G$ and $L$, and does not vanish for explicit methods.

%Note that the assumption that the velocity field satisfies $\tilde{\B{u}} \cdot \B{n} = 0$ is natural for the analysis of time integration methods (see, for instance, \cite{Karniadakis1991}).

\iffalse
Another idea is to compensate the error within the operator $L$. Let $\hat{V}_h \subset (H^1(\Omega))^d$ and $V_h \subset (H^1_0(\Omega))^d \cap \hat{V}_h$. Let $\hat{G}$ be the orthogonal projection of $(L^2(\Omega))^d$ on $\hat{V}_h$. Then $L$ may be defined as
\begin{equation*}
(L f, g) = -\int\limits_{\Omega} \nabla f \cdot \nabla g  dV + (\hat{G}f, \hat{G}g) - (Gf, Gg).
%\label{eq_def_FE_L}
\end{equation*}
