\subsection{Mass-lumped P1-Galerkin method}

As we saw in Section~\ref{sect:FD2}, the basic 1-exact central difference scheme naturally admits the strong enforcement of the Dirichlet condition. Here we show that the same holds for the mass-lumped P1-Galerkin method, which may be considered as a generalization of the central difference scheme to unstructured meshes.

If the basis functions are nonnegative, then the mass-lumped Galerkin method gives operators that satisfy \eqref{eq_gen_assumptions}. For a general Galerkin method, mass lumping results in the loss of high order convergence. High-order mass-lumped methods are designed in \cite{Mulder2001, Cohen2001} (see also references therein) but the basis functions are not nonnegative. Thus, although we do not rely on a specific form of basis functions, what we discuss here is mainly designed for the mass-lumped P1-Galerkin method.

Let $\mathcal{N}$ and $\mathcal{N}_0 \subset \mathcal{N}$ be finite non-empty sets. Let $\{\phi_j \in H^1(\Omega), j \in \mathcal{N}\}$ be a linearly independent system of functions used to approximate one velocity component. Assume that $v_j := \int \phi_j dV > 0$ for each $j \in \mathcal{N}$, and $\phi_j(\B{r})=0$ on $\D \Omega$ for $j \in \mathcal{N} \setminus \mathcal{N}_0$. For 
$$
f = \sum\limits_{k \in \mathcal{N}} f_k \phi_k, \quad g = \sum\limits_{k \in \mathcal{N}} g_k \phi_k
$$
denote
$$
[f,g] = \sum\limits_{j \in \mathcal{N}} v_j f_j g_j.
$$

Define $\hat{V}_h = (span\{\phi_j, j \in \mathcal{N}\})^d$ and equip it with the scalar product $[\B{f}, \B{g}] = [f^x, g^x] + [f^y, g^y]$ (for $d=2$) or similar for other dimensions. Let $V_h \subset \hat{V}_h$ be the set of functions with zero coefficients for $j \in \mathcal{N} \setminus \mathcal{N}_0$. Let $Q_h$ be a finite-dimensional subspace of $Q$ where $Q$ is the space of functions from $H^1(\Omega)$ with zero average.  The choice of the scalar product in $Q_h$ does not matter because we only need the combination $L^{-1}D$.

%The latter issue vanishes when the mass lumping in the velocity space is used. Assume that $\hat{V}_h = (\hat{V}_h^1)^d$, $V_h = (V_h^1)^d$. Let $\{\phi_j, j = 1, \ldots, \hat{N}\}$ be a basis in $\hat{V}_h^1$, $\{\phi_j, j = 1, \ldots, N\}$ be a basis in $V_h^1$, and $[f,g]$ be the lumped scalar product in $\hat{V}_h$:
%$$[f,g] = \sum f_j g_j \int \phi_j(\B{r}) dV, \quad f = \sum f_k \phi_k, \quad g = \sum g_k \phi_k.$$

For $f \in Q_h$, define $\hat{G} f \in V_h$ by
\begin{equation}
[\hat{G} f, \B{g}] = \int\limits_{\Omega} \B{g}(\B{r}) \cdot \nabla f(\B{r}) dV,  \quad \B{g} \in \hat{V}_h.
\label{eq_def_FE_G_lumped}
\end{equation}
Or, equivalently,
\begin{equation}
(\hat{G} f)(\B{r}) = \sum\limits_{j \in \mathcal{N}} (\hat{G} f)_j \phi_j(\B{r}), 
\quad 
(\hat{G} f)_j = v_j^{-1} \int\limits_{\Omega} \phi_j(\B{r}) \nabla f(\B{r}) dV, \quad f \in Q_h.
\label{eq_def_FE_G_lumped2}
\end{equation}
Then $Gf$ can be obtained from $\hat{G}f$ by nullifying the coefficients at $\phi_j$, $j \in \mathcal{N} \setminus \mathcal{N}_0$, and $D = -G^*$ is defined by \eqref{eq_def_FE_D}. Finally, put
\begin{equation}
(L f, g) = -\int\limits_{\Omega} \nabla f \cdot \nabla g  dV + \sum\limits_{j \in \mathcal{N} \setminus \mathcal{N}_0} v_j (\hat{G}f)_j \cdot (\hat{G}g)_j.
\label{eq_def_FE_L_lumped}
\end{equation}

\begin{proposition}
Assume that $\phi_j(\B{r}) \ge 0$ and $\sum_k \phi_k(\B{r}) \le 1$ for each $j \in \mathcal{N}$ and $\B{r} \in \Omega$. Then operators $G$, $D$, $L$ defined above satisfy \eqref{eq_gen_assumptions}.
\end{proposition}

\begin{proof}
First we claim that for each $w \in \hat{V}_h$ there holds $\int |w|^2 dV \le [w,w]$. Indeed,
\begin{equation*}
\begin{gathered}
\int |w|^2 dV = \int \sum\limits_{j,k} w_j \cdot w_k \phi_j \phi_k dV \le 
\int \sum\limits_{j,k} \frac{|w_j|^2 + |w_k|^2}{2} \phi_j \phi_k dV 
= \\
=
\int \sum\limits_{j} |w_j|^2 \phi_j \sum\limits_{k} \phi_k dV 
\le 
\sum\limits_{j} |w_j|^2 \int \phi_j dV = [w,w].
\end{gathered}
\end{equation*}
Using this fact for $w = \hat{G} f$, $f \in Q_h$, and by the Schwarz inequality we obtain
\begin{equation}
\begin{gathered}
\left[\hat{G} f, \hat{G}f\right] = \int (\hat{G} f) \cdot \nabla f dV \le
\left(\int |\hat{G} f|^2 dV\right)^{1/2}
\left(\int |\nabla f|^2 dV\right)^{1/2} 
\le 
\\
\le
\left([\hat{G} f, \hat{G} f]\right)^{1/2}
\left(\int |\nabla f|^2 dV\right)^{1/2}.
\end{gathered}
\label{eq_Schrartz}
\end{equation}
Thus, $[\hat{G} f, \hat{G}f] \le \int |\nabla f|^2 dV$. The condition $D = -G^*$ is by construction. Therefore,
$$
(S f, f) = - [G f, G f] - (L f, f) = \int |\nabla f|^2 dV - [\hat{G} f, \hat{G}f] \ge 0.
$$
Thus, $S \ge 0$ and $L \le 0$. 

It remains to prove that $(Lf, f) < 0$ for each $f \in Q_h$, $f \ne 0$. If $(S f, f) > 0$, then $(Lf, f) \le -(S f, f) < 0$. If $(S f, f)=0$, then both inequalities in \eqref{eq_Schrartz} turn to equalities. The first one does if $(\hat{G}f)_j=(\hat{G}f)_k$ for each $j, k \in \mathcal{N}$. Therefore, $f$ is a sum of a linear function and a vector from $\mathrm{Ker}\,\hat{G}$. The second one does if $\hat{G}f = c\nabla f$, hence, $f$ can be either a linear function ($c=1$) or a vector from $\mathrm{Ker}\,\hat{G}$ ($c=0$). In the first case, we have $(Lf, f) = - |\nabla f|^2 \sum v_j$ where the sum is over $j \in \mathcal{N}_0$. In the second case, we have $(Lf, f) = -\int |\nabla f|^2 dV < 0$. Thus, $L < 0$.
\end{proof}



