\section{Overview of the Proposed Approach}
\label{sec:algorithm}
Algorithm \ref{alg:overall} describes the overall approach, which aims to sample a batch of \( K \) items for a user \( u \), maximizing both diversity and relevance in a sequential way setting over \( T \) rounds taking into account his history of seen or interacted with items. The input consists of the user embedding \( \psi_u \), item embeddings \( \mathbf{E}^I \), and sampling parameters. The output is a batch of items selected based on a reward function combining Volume and Ridge Leverage Score (RLS) gains.

The set of selected items for the user, \( \mathcal{H}_u \), is initialized to be empty. Each item \( i \in \{1, \dots, n\} \) is initialized with \( \text{count}_i = 0 \) to save how many times this item has been recommended, Thompson Sampling parameters \( \alpha_i = 1 \), \( \beta_i = 1 \), and an initial ratio gains \( \theta_i^{(t)} = 0 \) for all time steps \( t \in \{1, \dots, T\} \). Two variables, \( \text{Old}_{\text{Volume}} \) and \( \text{Old}_{\text{RLS}} \), are initialized to zero to track the reward changes across rounds.

At each round \( t = 1, \dots, T \), the algorithm calls the Batch Selection procedure defined in algorithm \ref{alg:pareto_selection} to return a candidate subset \( \mathcal{PF} \) of items balancing diversity and/or relevance—depending on the chosen policy—according to the current values of \( \theta, \alpha, \beta, \text{count} \), the user history \( \mathcal{H}_u \), \( \mathbf{E}^I \), and \( \psi_u \).

For each item \( i \in \mathcal{PF} \), the Ridge Leverage Score is computed with respect to the context (the selected subset) \( \mathcal{H}_u \), and the logarithm of each RLS value, % related to the selected subset,
is accumulated into \( \text{RLS}_\mathcal{PF} \). %A user feedback probability \( p_i \) is clipped to a valid range, and feedback is simulated by sampling a Bernoulli outcome. If the feedback is positive (i.e., \( \text{feedback}_i = 1 \)), the item is added to the user history \( \mathcal{H}_u \).

Once all items in the Batch have been evaluated, the algorithm computes the Volume score as the determinant of the kernel matrix modulated by the user embedding \( L_{\mathcal{PF}} \), denoted \( \text{Volume}_{\mathcal{PF}} \). The change in volume \( \Delta^{\text{Volume}}_{\mathcal{PF}} \) is computed relative to the previous round. Likewise, the change in RLS is given by \( \Delta^{\text{RLS}}_{\mathcal{PF}} = \text{RLS}_{\mathcal{PF}} - \text{Old}_{\text{RLS}} \).

The reward for the current round is defined as the product of the RLS and Volume gains:
\(
\text{reward}^t = \Delta^{\text{RLS}}_{\mathcal{PF}} \cdot \Delta^{\text{Volume}}_{\mathcal{PF}}.
\)
The Thompson Sampling parameters are subsequently updated based on the computed reward. For all items \( i \in \mathcal{PF} \), the updates are performed as follows:
if the reward is positive, then \( \alpha_i \gets \alpha_i + \mathbb{1}_{\{ \text{reward}^t > 0 \}} \); otherwise, \( \beta_i \gets \beta_i + \mathbb{1}_{\{ \text{reward}^t \leq 0 \}} \).
Here, \( \mathbb{1}_{\{\cdot\}} \) denotes the indicator function, which returns 1 when the condition is true, and 0 otherwise.

This process is repeated over \( T \) rounds, where at each step the system refines its selection by balancing exploration (serendipity) and the trade-off between relevance and diversity, thereby assisting the user with increasingly tailored suggestions each time a search is launched.


\begin{algorithm}%[H]
\caption{Contextual Diversity-aware sequential Sampling}\label{alg:overall}
\begin{algorithmic}[1]
\STATE \textbf{Input:} batch size $K$, user $u$, user embeddings $\psi$, item embeddings $\mathbf{E}^I$, 
\STATE \textbf{Output:} A batch of items achieving the highest rewards
\STATE Initialize $\mathcal{H}_u \gets \emptyset$ \COMMENT{Set of selected items}
\STATE Initialize \( \text{count}_i \gets 0 \quad \forall i \in \{1, \dots, n\} \).
\STATE Initialize \( \alpha_i \gets 1 \), \( \beta_i \gets 1 \quad \forall i \in \{1, \dots, n\} \)
\STATE Initialize \( \theta_i^{(t)} \gets 0 \quad \forall i \in \{1, \dots, n\},\; \forall t \in \{1, \dots, T\} \)
\STATE $Old_{Volume} \gets 0$
\STATE $Old_{RLS} \gets 0$
\FOR{$t = 1$ to $T$}
    \STATE $\mathcal{PF} \gets \text{Batch\_Selection}(K, t, \theta, \alpha, \beta, count, \mathcal{H}_u, \mathbf{E}^I, \psi_u)$ %\COMMENT{Compute Pareto front}

    \STATE $\text{RLS}_\mathcal{PF} \gets 0$
    \FORALL{$i \in \mathcal{PF}$}
        \STATE Compute $\text{RLS}_i \gets \text{Ridge\_Leverage\_Score}(i,\mathcal{H}_u)$
        \STATE Compute $\text{RLS}_\mathcal{PF} \gets \text{RLS}_\mathcal{PF} + \log(\text{RLS}_i)$

%        \STATE $p_i \gets \text{clip}(\text{Feedback\_Utilisateur})$ \COMMENT{Clip user feedback to valid range}
        %\IF{$\text{random.random()} \leq p_i$}
         %   \STATE $\text{feedback}_i \gets 1$
            \STATE $\mathcal{H}_u \gets \mathcal{H}_u \cup \{i\}$
       % \ELSE
       %     \STATE $\text{feedback}_i \gets 0$
        %\ENDIF

    \ENDFOR
    \STATE Compute $\text{Volume}_\mathcal{PF} \gets \det \left(L_{\mathcal{PF}}\right)$
    \STATE $\Delta^{Volume}_\mathcal{PF} \gets \text{Volume}_\mathcal{PF} - Old_{Volume}$
    \STATE $Old_{Volume} \gets \text{Volume}_\mathcal{PF}$
    \STATE $\Delta^{RLS}_{\mathcal{PF}} \gets \text{RLS}_\mathcal{PF} - Old_{RLS}$
    \STATE $Old_{RLS} \gets \text{RLS}_\mathcal{PF}$
    \STATE Update $\text{reward}^t \gets \Delta^{RLS}_{\mathcal{PF}} * \Delta^{Volume}_\mathcal{PF}$
    %\STATE Update \(\alpha_i \leftarrow \alpha_i + \max(0, \text{reward}^t) \quad \forall i \in \mathcal{PF} \)
    \STATE Update \( \alpha_i \gets \alpha_i + \mathbb{1}_{\{\text{reward}^t > 0\}} \quad \forall i \in \mathcal{PF} \)
\STATE Update \( \beta_i \gets \beta_i + \mathbb{1}_{\{\text{reward}^t \leq 0\}} \quad \forall i \in \mathcal{PF} \)

\ENDFOR
\end{algorithmic}
\end{algorithm}

%\noindent \textbf
%\subsection*{Batch Selection Procedure}
\paragraph{Batch Selection Procedure.}
Algorithm~\ref{alg:pareto_selection} selects a batch of items that jointly optimize relevance and diversity under various strategies, including mono-objective and multi-objective. It takes as input the batch size \( K \), the current time step \( t \), Thompson sampling parameters \( \theta, \alpha, \beta \), the item selection counts, the user's interaction history \( \mathcal{H}_u \), item embeddings \( \phi \), and the user embedding \( \psi_u \).

For each item \( i = 1, \dots, n \), the algorithm first samples a parameter \( \theta_i^{(t)} \) from a Beta distribution using Thompson Sampling based on \( \alpha_i \) and \( \beta_i \). It then computes a gain estimate \( b_i \) as the change in \( \theta_i \) between time steps \( t \) and \( t-1 \), normalized by the number of times the item has been selected.

Using this gain \( b_i \), a diversity score is computed as \( \text{div}_i = b_i \cdot \text{diss}(\phi_i, \mathcal{H}_u) \), where \( \text{diss}(\cdot) \) denotes the dissimilarity between the item's embedding and the user history. Similarly, a relevance score is computed as \( \text{rel}_i = b_i \cdot \text{sim}(\phi_i, \psi_u) \), where \( \text{sim}(\cdot) \) measures similarity to the user embedding.

Multiple scoring objectives are derived in the selection process. The aggregated score for each item \( i \) is defined as 
\( \text{Agg\_obj}_i = b_i \cdot (1 + \text{div}_i - \text{rel}_i) \), which combines both diversity and relevance signals. 
A single-objective relevance score is computed as 
\( \text{Sin\_obj}_i = b_i \cdot \text{rel}_i \). 
Additionally, a multi-objective formulation is considered as a tuple 
\( (b_i \cdot \text{rel}_i, \, b_i \cdot \text{div}_i) \), 
allowing both objectives to be treated simultaneously. 


%  \item A Gaussian-based score: \( \text{Gauss\_obj}_i = b_i \cdot \text{pred}_i \), where \( \text{pred}_i \) denotes a predicted utility

Next, to enable a vectorized treatment of both objectives, two kernel matrices are computed to obtain vectorized representations. The \emph{diversity matrix} is defined as 
\( \mathbf{D} = \mathcal{H}_u \left( \operatorname{diag}(\mathbf{b}) \, \mathbf{E}^I \right)^\top \), 
where \( \mathcal{H}_u \) denotes the user's history and \( \mathbf{E}^I \) the item embeddings. The \emph{relevance matrix} is given by 
\( \mathbf{R} = \left( \operatorname{diag}(\mathbf{b}) \, \mathbf{E}^I \right) \odot \boldsymbol{\psi}_u \), 
with \( \boldsymbol{\psi}_u \) representing the user embedding and \( \odot \) denoting the Hadamard (element-wise) product.
From these, \( k \)-DPP-based item selection probabilities are computed following the procedure detailed in Algorithm~\ref{alg:kDPP_Proba}:  
\(
\pi_{\text{div}} = \text{k\_DPP\_probabilities}(\mathbf{D}, K), \quad \pi_{\text{rel}} = \text{k\_DPP\_probabilities}(\mathbf{R}, K)
\).

Therefore, the returned batch of items is selected based on the specified strategy, which falls into one of two categories: dominance-based ranking or Top-$K$ selection.
\vspace{0.5cm}

\textit{Dominance-based ranking:}
\begin{itemize}
  \item \textbf{Vectorized Multi-Objective (VMo):} Items are ranked using dominance-based ranking over the vectorized scores \( \pi_{\text{div}} \) and \( \pi_{\text{rel}} \).
  \item \textbf{Non-Linear Multi-Objective (MO):} Dominance-based ranking is applied to the scalar scores \( \text{div}_i \) and \( \text{rel}_i \).
\end{itemize}

\textit{Top-$K$-based (argmax) ranking:}
\begin{itemize}
  \item \textbf{Aggregation (Lin):} Items are ranked and selected based on \( \text{Agg\_obj} \), which aggregates \( \text{div}_i \) and \( \text{rel}_i \).
  \item \textbf{Single Objective (SO):} Items are ranked by the relevance scores \( \text{rel}_i \).
  \item \textbf{Vectorized Mono-Objective (VMN):} Items are selected based on the vectorized diversity scores \( \pi_{\text{div}} \).
\end{itemize}

\begin{algorithm}[H]
\caption{Batch Selection}\label{alg:pareto_selection}
\begin{algorithmic}[1]
\STATE \textbf{Input:} $K$, $t$, $\theta$, $\alpha$, $\beta$, $count$, history $\mathcal{H}_u$, item embeddings $\mathbf{E}^I$, user embedding $\psi_u$
\STATE \textbf{Output:} Batch of size $K$
\FOR{$i = 1$ to $n$}
    \STATE $\theta_i^{(t)} \gets \text{ThompsonSampling}(\alpha_i, \beta_i)$
    \STATE $b_i \gets \frac{\theta_i^{(t)} -\theta_i^{(t-1)}}{\text{count}_i}$
    \STATE $\text{div}_i \gets b_i \cdot \text{diss}(\phi_i, \mathcal{H}_u)$
    \STATE $\text{rel}_i \gets b_i \cdot \text{sim}(\phi_i, \psi_u)$
    \STATE $Agg\_obj_i = b_i * (1 + div_i - rel_i)$
    %\STATE $Sin\_obj_i = b_i * \text{rel}_i$
%    \STATE $Gauss\_obj_i = b_i * pred_i$
\ENDFOR
\STATE $\mathbf{D} = \mathcal{H}_u \left( \operatorname{diag}(\mathbf{b}) \, \mathbf{E}^I \right)^\top$
\STATE $\mathbf{R} = \left( \operatorname{diag}(\mathbf{b}) \, \mathbf{E}^I \right) \odot \boldsymbol{\psi}_u$
\STATE $\pi_{div} \gets \text{k-DPP\_probabilities}(D, K)$
\STATE $\pi_{rel} \gets \text{k-DPP\_probabilities}(R, K)$

\IF{way == "Vectorized Multi-Objective"}
    \STATE \textbf{return} $\text{Dominance\_ranking}(\pi_{div}, \pi_{rel})$
\ELSIF{way == "Multi-Objective"}
    \STATE \textbf{return} $\text{Dominance\_ranking}(div_i, rel_i)$
\ELSIF{way == "Aggregation"}
    \STATE \textbf{return} $\text{argsort(Agg\_obj)}$
\ELSIF{way == "Single objective"}
    \STATE \textbf{return} \text{argsort($\text{rel}_i$)}
\ELSIF{way == "Vectorized Mono-Objective"}
    \STATE \textbf{return} 
    \text{argsort($\pi_{div}$)}
\ENDIF


\end{algorithmic}
\end{algorithm}


