\section{Derivation of Friis' total noise factor formula} 
\label{secA1}

According to Friis \cite{bib25}, the stage-wise noise factors of a cascade network is expressed as,  

\begin{equation}
\label{Appendix_A_eqn_1}
F_x^{\text{Friis}} = 1+\frac{N_{\text{ext}(x)}}{N_\text{i}G_x}
\end{equation}


Therefore, Friis' total noise factor formula for a cascade network in terms of its stage-wise noise factors (neglecting the stage-wise internal noise powers ($N_{\text{int}(x)}$)) is given by, 

\begin{equation}
\label{Appendix_A_eqn_2}
\begin{aligned}
F_{\text{T}_n}^{\text{Friis}} &= \frac{\text{SNR}_\text{i}}{\text{SNR}_\text{o}} = \frac{\left({S_\text{i}}/{N_\text{i}}\right)}{\left({S_\text{o}}/{N_\text{o}}\right)} \\
&= \underbrace{1+\frac{N_{\text{ext}(1)}}{N_\text{i}G_1}}_{\text{$=F_1^{\text{Friis}}$}}+\underbrace{\frac{N_{\text{ext}(2)}}{N_\text{i}G_1G_2}}_{\text{$=\left(F_2^{\text{Friis}}-1\middle)\middle/\middle(G_1\right)$}} \\ 
&~+...+\underbrace{\frac{N_{\text{ext}(n)}}{N_\text{i}G_1G_2...G_n}}_{\text{$=\left(F_n^{\text{Friis}}-1\middle)\middle/\middle(\prod_{x=1}^{(n-1)}G_x\right)$}} \\ 
&= F_1^{\text{Friis}}+\sum_{x=2}^{n}\left(\frac{F_x^{\text{Friis}}-1}{\prod_{y=1}^{(x-1)}G_y}\right)
\end{aligned}
\end{equation} 



\section{Derivation of our new total noise factor formula} 
\label{secB1}

Our new expression for a cascade network's stage-wise noise factors is given by, 

\begin{equation}
\label{Appendix_B_eqn_1}
\begin{aligned}
F_x^{\text{Bang}} = 1+\frac{\left(N_{\text{int}(x)}+N_{\text{ext}(x)}\right)}{N_{\text{i}(x)}G_x} 
\end{aligned}
\end{equation}

Rewriting the stage-wise noise factor at the $x$-th stage of a cascade network in terms of its previous stages' stage-wise noise factors, 

\begin{equation}
\label{Appendix_B_eqn_2}
F_x^{\text{Bang}} = 1+\frac{\left(N_{\text{int}(x)}+N_{\text{ext}(x)}\right)}{N_\text{i}\prod_{j=1}^{x}G_j\prod_{k=1}^{(x-1)}F_k^{\text{Bang}}}; \forall x\geq2 
\end{equation}


Therefore, rearranging equation~\eqref{Appendix_B_eqn_2} and substituting it in equation~\eqref{Appendix_B_eqn_3}, the new total noise factor formula for a cascade network in terms of its stage-wise noise factors (including the stage-wise internal noise powers ($N_{\text{int}(x)}$)) is given by, 

\begin{equation}
\label{Appendix_B_eqn_3}
\begin{aligned}
F_{\text{T}_n}^{\text{Bang}} &= \frac{\text{SNR}_\text{i}}{\text{SNR}_\text{o}} = \frac{\left({S_\text{i}}/{N_\text{i}}\right)}{\left({S_\text{o}}/{N_\text{o}}\right)} \\ 
=& \underbrace{1+\frac{\left(N_{\text{int}(1)}+N_{\text{ext}(1)}\right)}{N_\text{i}G_1}}_{\text{$=F_1^{\text{Bang}}$}}+\underbrace{\frac{\left(N_{\text{int}(2)}+N_{\text{ext}(2)}\right)}{N_\text{i}G_1G_2}}_{\text{$=\left(F_2^{\text{Bang}}-1\right)F_1^{\text{Bang}}$}}\\
&+...+\underbrace{\frac{\left(N_{\text{int}(n)}+N_{\text{ext}(n)}\right)}{N_\text{i}G_1G_2...G_n}}_{\text{$=\left(F_n^{\text{Bang}}-1\right)\prod_{x=1}^{n-1}F_x^{\text{Bang}}$}} \\ 
&= \prod_{x=1}^{n}F_x^{\text{Bang}}\neq\Bigl(F_{\text{T}_n}^{\text{Friis}}\Bigr) 
\end{aligned}
\end{equation}


\section{Illustration to prove the inequality in Friis' and ours stage-wise noise factor formulas, for higher stages (neglecting internally generated stage-wise noises)} 
\label{secC1}

The noise factor a single-stage network or the stage-wise noise factor at the 1-st stage of a cascade network is given by, 

\begin{equation}
\label{Appendix_C_eqn_1}
\begin{aligned}
F_1^{\text{Bang}} &= \frac{\text{SNR}_{\text{i}(1)}}{\text{SNR}_{\text{o}(1)}} = \frac{\text{SNR}_{\text{i}}}{\text{SNR}_{\text{o}(1)}} \\
&=\frac{N_{\text{o}(1)}}{N_{\text{i}(1)}G_1} = 1 + \frac{N_{\text{ext}(1)}}{N_\text{i}G_1} \\ 
&=\left(F_1^{\text{Friis}}=1+\frac{N_{\text{ext}(1)}}{N_\text{i}G_1}\right) 
\end{aligned}
\end{equation}



However, considering the noise factor at the 2-nd stage of a network,

\begin{equation}
\label{Appendix_C_eqn_2}
\begin{aligned}
F_2^{\text{Bang}} &= \frac{\text{SNR}_{\text{i}(2)}}{\text{SNR}_{\text{o}(2)}} = \frac{\text{SNR}_{\text{o}(1)}}{\text{SNR}_{\text{o}(2)}} \\
&=\frac{N_{\text{o}(2)}}{N_{\text{i}(2)}G_2} = 1 + \frac{N_{\text{ext}(2)}}{\left(N_\text{i}G_1+N_{\text{ext}(1)}\right)G_2} \\ 
&\neq\left(F_2^{\text{Friis}}=1+\frac{N_{\text{ext}(2)}}{N_\text{i}G_2}\right) 
\end{aligned}
\end{equation}


From equation~\eqref{Appendix_C_eqn_2}, it is observed that $N_\text{i} \neq N_{\text{i}(2)} \left(=N_\text{i}G_1+N_{\text{ext}(1)}\right)$. This inequality shown in equation~\eqref{Appendix_C_eqn_2} applies to all higher stages.






