\lseq ...,\, \Gamma_{r0 \& (array\_size-1)} \land \Gamma_{toleak} = \bot\land \Gamma_{publicarray[r0 \& (array\_size-1)]} = \bot\rseq\\
	r1 := array\_size; \\
\lseq ...,\, \Gamma_{r0 \& (r1-1)} \land \Gamma_{toleak} = \bot\land \Gamma_{publicarray[r0 \& (r1-1)]} = \bot\rseq\\
	r0 := r0 ~\&~ (r1-1);\\
\lseq ...,\, \Gamma_{r0} \land \Gamma_{toleak} = \bot\land \Gamma_{publicarray[r0]} = \bot\rseq\\
	\leak r0;\\
\lseq ...,\, \Gamma_{toleak} = \bot\land \Gamma_{publicarray[r0]} = \bot\rseq\\
	r1 := publicarray[r0];\\
\lseq ...,\, \Gamma_{toleak} = \bot\land \Gamma_{r1} = \bot\rseq\\
	toleak\_ret := r1;\\
\lseq true,\, \Gamma_{toleak} = \bot\land \Gamma_{toleak\_ret} = \bot\rseq\\
	\fence;\\
\lseq \Gamma_{toleak} = \bot \land \Gamma_{toleak\_ret} = \bot,\, \Gamma_{toleak} = \bot\land \Gamma_{toleak\_ret} = \bot\rseq\\
	r0 := toleak\_ret;// \mbox{ if $\neg\df{toleak\_ret}$ then $toleak\_ret=toleak\_ret^\base$ since $toleak\_ret$ local}\\
\lseq \Gamma_{toleak} = \bot \land \Gamma_{r0} = \bot,\, \Gamma_{toleak} = \bot\land \Gamma_{r0} = \bot\rseq\\
	toleak := r0;\t1 // \mbox{This store may be bypassed}\\
\lseq \Gamma_{toleak} = \bot,\, \Gamma_{toleak} = \bot\rseq\\
	r1:= toleak;\t1 // \mbox{ if $\neg\df{toleak}$ then $toleak=toleak^\base$ since $toleak$ is local}\\
\lseq \Gamma_{r1} = \bot,\, \Gamma_{r1} = \bot\rseq\\
	\leak r1;\zbreak
\lseq true,\, true\rseq\\
	r2 := publicarray[r1*512];\\
\lseq true,\, true\rseq
\]

\subsection*{Case 12}

The code is secure since there is no store to bypass. 

\[\lseq \M ...,\, true\O\rseq\\	
	r0 := idx;\\
\lseq \M ...,\, \Gamma_{r0 \& (array\_size-1)}=\bot \land \Gamma_{publicarray[r0 \& (array\_size-1)]} = \bot\O\rseq\\
	r1 := array\_size; \\
\lseq \M ...,\, \Gamma_{r0 \& (r1-1)}=\bot \land \Gamma_{publicarray[r0 \& (r1-1)]} = \bot\O\rseq\\
	r0\_ret := r0 ~\&~ (r1-1);\\
\lseq \M ...,\, \Gamma_{r0\_ret}=\bot \land \Gamma_{publicarray[r0\_ret]} = \bot\O\rseq\\
	\fence;\\
\lseq \M ...,\, \Gamma_{r0\_ret}=\bot \land \Gamma_{publicarray[r0\_ret]} = \bot\O\rseq\\
	r0 := r0\_ret;\\
\lseq \M ...,\, \Gamma_{r0}=\bot \land \Gamma_{publicarray[r0]} = \bot\O\rseq\\
	\leak r0;\\
\lseq \M ...,\, \Gamma_{publicarray[r0]} = \bot\O\rseq\\
	r1:= publicarray[r0];\\
\lseq \Gamma_{r1} = \bot,\, \Gamma_{r1} = \bot\rseq\\
	\leak r1;\\
\lseq ...,\, true\rseq\\
	r2 := publicarray2[r1*512];\\
\lseq true,\, true\rseq
\]

\subsection*{Case 13}

The code is secure since the only store is followed by a fence (and hence cannot be bypassed).

\[\lseq \M ...,\, true\O\rseq\\	
	r0 := idx;\\
\lseq \M ...,\, \Gamma_{r0 \& (array\_size-1)}=\bot \land \Gamma_{publicarray[r0 \& (array\_size-1)]} = \bot\O\rseq\\
	r1 := array\_size; \\
\lseq ...,\, \Gamma_{r0 \& (r1-1)}=\bot\land \Gamma_{publicarray[r0 \& (r1-1)]} = \bot\rseq\\
	r0 := r0 ~\&~ (r1-1);\\
\lseq ...,\, \Gamma_{r0}=\bot\land \Gamma_{publicarray[r0]} = \bot\rseq\\
	\leak r0;\\
\lseq ...,\, \Gamma_{publicarray[r0]} = \bot\rseq\\
	r1 := publicarray[r0];\\
\lseq ...,\, \Gamma_{r1} = \bot\rseq\\
	toleak\_ret := r1;\zbreak
\lseq true,\, \Gamma_{toleak\_ret} = \bot\rseq\\
	\fence;\\
\lseq \Gamma_{toleak\_ret} = \bot,\, \Gamma_{toleak\_ret} = \bot\rseq\\
	r1 := toleak\_ret;\t1 // \mbox{ if $\neg\df{toleak}$ then $toleak\_ret=toleak\_ret^\base$ since $toleak\_ret$ local}\\
\lseq \Gamma_{r1} = \bot,\, \Gamma_{r1} = \bot\rseq\\
	\leak r1;\\
\lseq true,\, true\rseq\\
	r2 := publicarray2[r1*512];\\
\lseq true,\, true\rseq
\]

\section{Combination of Spectre-PHT and Spectre-STL}

Below we apply our logic to Listing~1 from Fabian et al.\ \cite{fab22} which involves a vulnerability arising from a combination of Spectre-PHT and Spectre-STL. The tests are reexpressed in the language from Section~\ref{sec:wp}. In the test, $secret$ is a pointer to a sensitive value, and $public$ a pointer to a non-sensitive value. $p$ is a local variable and $A$ a publicly accessible array.

The speculative precondition is elided whenever there are no points where speculation can start (stores or branches) earlier in the code.\\

\noindent To express this test in our simple programming language, pointers are modelled as arrays of length 1.

 The code is insecure since it requires that the value at $secret$ is non-sensitive. 

\[\lseq ...,\, \Gamma_{public[0]} = \bot \land \Gamma_{secret[0]} = \bot \land \Gamma_{p[0]}=\bot\rseq\\
	r0 := 0;\\
\lseq ...,\, \Gamma_{public[0]} = \bot \land \Gamma_{secret[0]} = \bot \land \Gamma_{r0}=\bot \land \Gamma_{p[0]}=\bot\rseq\\
	r1 := secret;\\
\lseq ...,\, \Gamma_{public[0]} = \bot \land \Gamma_{r1[0]} = \bot \land \Gamma_{r0}=\bot \land \Gamma_{p[0]}=\bot\rseq\\
	p := r1;\\
\lseq \M(\df{p[0]} \implies \Gamma_{p[0]} = \bot) \land (\lnot\df{p[0]} \implies \Gamma_{p[0]^{\base}} = \bot) \land \Gamma_{public[0]} = \bot,\,\\
\Gamma_{public[0]} = \bot \land \Gamma_{p[0]} = \bot \land \Gamma_{r0}=\bot\rseq\O\\
	r1 := public; \t1 // \mbox{ if $\neg\df{public}$ then $public=public^\base$ since $public$ is local}\\
\lseq \M(\df{p[0]} \implies \Gamma_{p[0]} = \bot) \land (\lnot\df{p[0]} \implies \Gamma_{p[0]^{\base}} = \bot) \land \Gamma_{r1} = \bot,\,\\
\Gamma_{r1[0]} = \bot \land \Gamma_{p[0]} = \bot \land \Gamma_{r0}=\bot\rseq\O\\
	p := r1;   \t1 //  \mbox{ This store may be bypassed}\\
\lseq \M (\df{p[0]} \implies \Gamma_{p[0]} = \bot) \land (\lnot\df{p[0]} \implies \Gamma_{p[0]^{\base}} = \bot),\, \Gamma_{p[0]} = \bot \land \Gamma_{r0}=\bot)\rseq\\
	\ifc (r0 != 0)\\ 
\t1 \M \lseq (\df{p} \implies \Gamma_{p[0]} = \bot) \land (\lnot\df{p} \implies \Gamma_{p[0]^{\base}} = \bot),\, \Gamma_{p[0]} = \bot\rseq\\
	r1 := p[0];\\
\lseq \Gamma_{r1} = \bot,\, \Gamma_{r1} = \bot\rseq\\
	\leak r1;\\
\lseq true,\, true\rseq\\
	  r2 := A[r1*512];\\
\lseq true,\, true\rseq\O\\
\lseq true,\, true\rseq
\]


